INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('intent-integrity-chain/kit/iikit-08-taskstoissues', 'iikit-08-taskstoissues', 'intent-integrity-chain', 'kit', 'community', 'iikit-08-taskstoissues intent-integrity-chain kit community The iikit-08-taskstoissues skill converts existing tasks into dependency-ordered GitHub issues for project tracking, benefiting developers and project managers. It utilizes bash scripts and JSON data for seamless integration. iikit-08-taskstoissues是一个将任务转换为依赖排序的GitHub问题的工具，用于项目跟踪 iikit-08-taskstoissuesは、タスクを依存関係順のGitHub Issueに変換するツールで、プロジェクトの追跡に使用されます iikit-08-taskstoissues는 태스크를 의존성 순서의 GitHub 이슈로 변환하는 도구로 프로젝트 추적에 사용됩니다 iikit-08-taskstoissues es una herramienta que convierte tareas en problemas de GitHub para un seguimiento de proyectos más eficaz iikit-08-taskstoissues est un outil qui convertit des tâches en problèmes GitHub pour un suivi de projets plus efficace iikit-08-taskstoissues ist ein Tool, das Aufgaben in GitHub-Probleme umwandelt, um die Projektnachverfolgung zu verbessern O iikit-08-taskstoissues é uma ferramenta que converte tarefas em problemas do GitHub, utilizando scripts Bash e JSON para otimizar o rastreamento de projetos. ИИ Агент iikit-08-taskstoissues преобразует задачи в проблемы GitHub, используя скрипты Bash и JSON для оптимизации отслеживания проектов أداة iikit-08-taskstoissues تحول المهام إلى قضايا GitHub، باستخدام脚本ات Bash و JSON لتحسين تتبع المشاريع how to use iikit-08-taskstoissues iikit-08-taskstoissues setup guide iikit-08-taskstoissues alternative github issue converter bash script for project tracking json data format for integration iikit-08-taskstoissues install project management with github issues dependency-ordered issue tracking AI工具 任务转换 GitHub问题 依赖排序 bash脚本 环境检查 CLI JSON 项目跟踪 Converts existing tasks into dependency-ordered GitHub issues Utilizes bash scripts for prerequisites checking Supports JSON data format for seamless integration Runs on GitHub for project tracking and management Executes prerequisites check using `check-prerequisites.sh` script Compatible with Windows using `pwsh` command iikit-08-taskstoissues is a skill that converts tasks into GitHub issues, utilizing bash scripts and JSON data for efficient project tracking and management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dermatologist/crisp-t/crisp-mcp', 'community', 'dermatologist', 'crisp-t', 'dermatologist/crisp-t', 'crisp-mcp', 8, 0, 50, '2026-02-26T22:06:45Z', '2026-03-06T06:49:05.563Z', 'fcb7d601db4a386ea6e1520042c43c9d27111b990bdc518bbf37564c4e3c4ba2', '{"id":"dermatologist/crisp-t/crisp-mcp","name":"crisp-mcp","description":{"en":"The crisp-mcp skill enables developers to perform AI-assisted qualitative research with vibe analytics, linking textual narratives and numeric data. It benefits researchers and data analysts working with machine learning and NLP.","zh":"CRISP-T MCP 服务器提供文本编码和数值分析工具，支持计算三角测量和基于扎根理论的编码","ja":"CRISP-T MCP サーバーはテキストコーディングと数値分析ツールを提供し、計算三角測量と根拠に基づくコード化をサポートします","ko":"CRISP-T MCP 서버는 텍스트 코딩과 수치 분석 도구를 제공하며 계산 삼각 측정을 통해 근거에 기반한 코딩을 지원합니다","es":"crisp-mcp es un servidor de investigación cualitativa que utiliza aprendizaje automático y análisis de vibraciones para triangular datos computacionales y teoría fundamentada","fr":"crisp-mcp est un serveur de recherche qualitative qui utilise le machine learning et l''analyse de vibrations pour la triangulation de données computationnelles et la théorie ancrée","de":"crisp-mcp ist ein Server für qualitative Forschung, der Machine Learning und Vibrationen-Analytics verwendet, um computergestützte Daten und Grounded Theory zu verbinden","pt":"O CRISP-MCP é uma ferramenta de análise qualitativa que utiliza vibração analítica e triangulação computacional para ligar narrativas textuais e dados numéricos","ru":"CRISP-MCP - это инструмент качественного анализа, который использует вибрационную аналитику и компьютерную триангуляцию для соединения текстовых нарративов и числовых данных","ar":"CRISP-MCP هو أداة تحليل نوعية تستخدم تحليل التأرجح وثلاثية الحوسبة لربط السرد النصي والبيانات الرقمية"},"seo":{"title":{"en":"crisp-mcp: AI Assisted Qualitative Research Setu