INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dermatologist/crisp-t/crisp-mcp', 'crisp-mcp', 'dermatologist', 'crisp-t', 'community', 'crisp-mcp dermatologist crisp-t community hacktoberfest machine-learning nlp qualitative-research The crisp-mcp skill enables developers to perform AI-assisted qualitative research with vibe analytics, linking textual narratives and numeric data. It benefits researchers and data analysts working with machine learning and NLP. CRISP-T MCP 服务器提供文本编码和数值分析工具，支持计算三角测量和基于扎根理论的编码 CRISP-T MCP サーバーはテキストコーディングと数値分析ツールを提供し、計算三角測量と根拠に基づくコード化をサポートします CRISP-T MCP 서버는 텍스트 코딩과 수치 분석 도구를 제공하며 계산 삼각 측정을 통해 근거에 기반한 코딩을 지원합니다 crisp-mcp es un servidor de investigación cualitativa que utiliza aprendizaje automático y análisis de vibraciones para triangular datos computacionales y teoría fundamentada crisp-mcp est un serveur de recherche qualitative qui utilise le machine learning et l''analyse de vibrations pour la triangulation de données computationnelles et la théorie ancrée crisp-mcp ist ein Server für qualitative Forschung, der Machine Learning und Vibrationen-Analytics verwendet, um computergestützte Daten und Grounded Theory zu verbinden O CRISP-MCP é uma ferramenta de análise qualitativa que utiliza vibração analítica e triangulação computacional para ligar narrativas textuais e dados numéricos CRISP-MCP - это инструмент качественного анализа, который использует вибрационную аналитику и компьютерную триангуляцию для соединения текстовых нарративов и числовых данных CRISP-MCP هو أداة تحليل نوعية تستخدم تحليل التأرجح وثلاثية الحوسبة لربط السرد النصي والبيانات الرقمية how to use crisp-mcp crisp-mcp setup guide crisp-mcp alternative crisp-mcp vs machine learning what is crisp-mcp crisp-mcp install crisp-mcp qualitative research crisp-mcp NLP analysis crisp-mcp Hacktoberfest CRISP-T MCP 服务器 AI 辅助质性研究 计算三角测量 基于扎根理论的编码 文本编码 数值分析 质性研究工具 AI 研究工具 Utilizes the CRISP-T MCP server for qualitative analysis Supports computational triangulation for data validation Employs grounded theory-inspired coding for text analysis Provides tools for corpus management and text coding Exposes several tools for numeric analysis Falls back to crisp-cli skill if CRISP-T MCP server is unavailable crisp-mcp is a skill that utilizes the CRISP-T MCP server for qualitative research, providing tools for corpus management, text coding, and numeric analysis.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sanity-io/plugins/turborepo', 'community', 'sanity-io', 'plugins', 'sanity-io/plugins', 'turborepo', 8, 3, 50, '2026-02-27T09:48:56Z', '2026-03-06T13:04:11.998Z', 'd7e4295a4ce6a5de509742e501a20c9989e55592d532347459b441be890f6ef1', '{"id":"sanity-io/plugins/turborepo","name":"turborepo","description":{"en":"Turborepo is a build system for JavaScript/TypeScript monorepos, providing a centralized place for developing, testing, and publishing plugins. It benefits developers by caching task outputs and running tasks in parallel based on dependency graphs.","zh":"Turborepo 是一个 JavaScript/TypeScript 项目的构建系统，能够缓存任务输出并基于依赖图运行任务。","ja":"Turborepo は JavaScript/TypeScript プロジェクトのビルドシステムであり、タスクの出力をキャッシュし、依存関係グラフに基づいてタスクを実行します。","ko":"Turborepo는 JavaScript/TypeScript 프로젝트의 빌드 시스템으로, 태스크 출력을 캐시하고 의존성 그래프를 기반으로 태스크를 실행합니다.","es":"Turborepo es un sistema de compilación para monorepos de JavaScript/TypeScript que almacena en caché las salidas de las tareas y ejecuta tareas en paralelo según el grafo de dependencias.","fr":"Turborepo est un système de construction pour les monorepos JavaScript/TypeScript qui met en cache les sorties des tâches et exécute les tâches en parallèle en fonction du graphique de dépendances.","de":"Turborepo ist ein Build-System für JavaScript/TypeScript-Monorepos, das Task-Ausgaben zwischenspeichert und Tasks parallel basierend auf der Abhängigkeitsgraph ausführt.","pt":"O Turborepo é um sistema de construção para monorepos JavaScript/TypeScript que melhora a eficiência ao armazenar em cache as saídas das tarefas e executar tarefas em paralelo com base no gráfico de dependências","ru":"Turborepo — это система сборки для монорепозиториев JavaScript/TypeScript, которая улучшает эффективность путем кэширования выходных данных задач и запуска задач параллельно на основе графа зависимостей","ar":"Turborepo هو نظام بناء لمونوريبوزиторي جافاسكريبت/تايبسكريبت الذي يحسن الكفاءة من خلال تخزين النتائج المؤقتة للمهام وتنفيذ المهام بالتوازي بناءً على مخطط الاعتماديات"},"seo":{"title":{"en":"Turborepo: Setup Guide for JavaScript Monorepos | AI Agen...","zh":"Turborepo_SETUP GUIDE - JavaScript/TypeScript Monorepo 构建系统","ja":"Turborepo セットアップガイド - JavaScript/TypeScript モノレポビルドシステム","ko":"Turborepo 설정 가이드 - JavaScript/TypeScript 모노리포 빌드 시스템","es":"Guía de configuración de Turborepo para monorepos de Java...","fr":"Guide d''installation de Turborepo pour les monorepos Java...","de":"Turborepo-Setup-Anleitung für JavaScript/TypeScript-Monor...","pt":"Guia de Configuração do Turborepo: Otimização de Monorepo...","ru":"ИИ Агенты: Руководство по настройке Turborepo для оптимиз...","ar":"دليل إعداد Turborepo: تحسين أداء مونوريبوزиторي جافاسكريب..."},"description":{"en":"Unlock efficient development with Turborepo. Learn how to cache task outputs, run tasks in parallel, and optimize your workflow. Get started now!","zh":"了解 Turborepo 的优势，实现 JavaScript/TypeScript 项目的高效构建和部署，AIエージェント","ja":"Turborepo の機能を活用して、JavaScript/TypeScript プロジェクトのビルドとデプロイを効率化する、AIエージェント","ko":"Turborepo의 장점을 이해하고 JavaScript/TypeScript 프로젝트의 효율적인 빌드와 배포를 구현해보세요, AI 도구","es":"Aprende a utilizar Turborepo para gestionar tus monorepos de JavaScript/TypeScript de manera eficiente","fr":"Découvrez comment utiliser Turborepo pour gérer vos monorepos JavaScript/TypeScript de manière efficace","de":"Erfahren Sie, wie Sie Turborepo verwenden können, um Ihre JavaScript/TypeScript-Monorepos effizient zu verwalten","pt":"Aprenda a configurar o Turborepo para melhorar a eficiência do seu monorepo JavaScript/TypeScript. Descubra como otimizar tarefas e dependências","ru":"Узнайте, как настроить Turborepo для оптимизации вашего монорепозитория JavaScript/TypeScript. Откройте для себя, как ускорить задачи и зависимости","ar":"تعلم كيفية إعداد Turborepo لتحسين كفاءة مونوريبوزиторي جافاسكريبت/تايبسكريبت. اكتشف كيفية تحسين المهام والاعتماديات"},"definition":{"en":"Turborepo is a build system for JavaScript/TypeScript monorepos that caches task outputs and runs tasks in parallel based on dependency graphs.","zh":"Turborepo 是一个用于 JavaScript/TypeScript 项目的构建系统，提供缓存和并行任务执行的功能。","ja":"Turborepo は、JavaScript/TypeScript プロジェクト用のビルドシステムであり、キャッシュと並列タスク実行の機能を提供します。","ko":"Turborepo는 JavaScript/TypeScript 프로젝트용 빌드 시스템으로, 캐시 및 병렬 태스크 실행 기능을 제공합니다.","es":"Turborepo es un sistema de compilación para monorepos que almacena en caché las salidas de las tareas y ejecuta tareas en paralelo","fr":"Turborepo est un système de construction pour les monorepos qui met en cache les sorties des tâches et exécute les tâches en parallèle","de":"Turborepo ist ein Build-System für Monorepos, das Task-Ausgaben zwischenspeichert und Tasks parallel ausführt","pt":"O que é Turborepo? É um sistema de construção para monorepos JavaScript/TypeScript que melhora a eficiência","ru":"Что такое Turborepo? Это система сборки для монорепозиториев JavaScript/TypeScript, которая улучшает эффективность","ar":"ما هو Turborepo؟ هو نظام بناء لمونوريبوزиторي جافاسكريبت/تايبسكريبت الذي يحسن الكفاءة"},"features":{"en":["Caches task outputs for improved performance","Runs tasks in parallel based on dependency graphs","Supports package tasks via `package.json` files","Registers tasks in root `turbo.json` file","Delegates tasks via `turbo run <task>` command","Optimizes workflow by avoiding root tasks"],"zh":["缓存任务输出","基于依赖图运行任务","支持 JavaScript/TypeScript 项目","并行任务执行","根任务委托","包任务注册"],"ja":["タスクの出力をキャッシュ","依存関係グラフに基づいてタスクを実行","JavaScript/TypeScript プロジェクトをサポート","並列タスク実行","ルート タスクの委托","パッケージ タスクの登録"],"ko":["태스크 출력 캐시","의존성 그래프를 기반으로 태스크 실행","JavaScript/TypeScript 프로젝트 지원","병렬 태스크 실행","루트 태스크委托","패키지 태스크 등록"],"es":["Almacena en caché las salidas de las tareas para reducir el tiempo de compilación","Ejecuta tareas en paralelo según el grafo de dependencias","Requiere la creación de tareas de paquete en lugar de tareas de raíz","Soporta la registración de tareas en el archivo turbo.json","Permite la delegación de tareas en el archivo package.json de raíz"],"fr":["Met en cache les sorties des tâches pour réduire le temps de construction","Exécute les tâches en parallèle en fonction du graphique de dépendances","Requiert la création de tâches de package au lieu de tâches de racine","Prend en charge l''enregistrement de tâches dans le fichier turbo.json","Permet la délégation de tâches dans le fichier package.json de racine"],"de":["Speichert Task-Ausgaben zwischenspeichert, um die Build-Zeit zu reduzieren","Führt Tasks parallel basierend auf der Abhängigkeitsgraph aus","Erfordert die Erstellung von Task-Paketen anstelle von Root-Tasks","Unterstützt die Registrierung von Tasks in der Datei turbo.json","Ermöglicht die Delegation von Tasks in der Datei package.json von Root"],"pt":["Armazenamento em cache de saídas de tarefas","Execução de tarefas em paralelo com base no gráfico de dependências","Otimização de monorepos JavaScript/TypeScript","Suporte a criação de tarefas em pacotes individuais","Registro de tarefas no arquivo turbo.json","Delegação de tarefas via comando turbo run"],"ru":["Кэширование выходных данных задач","Параллельный запуск задач на основе графа зависимостей","Оптимизация монорепозиториев JavaScript/TypeScript","Поддержка создания задач в отдельных пакетах","Регистрация задач в файле turbo.json","Делегирование задач через команду turbo run"],"ar":["تخزين النتائج المؤقتة للمهام","تنفيذ المهام بالتوازي بناءً على مخطط الاعتماديات","تحسين أداء مونوريبوزиторي جافاسكريبت/تايبسكريبت","دعم إنشاء مهام في حزم فردية","تسجيل المهام في ملف turbo.json","تفويض المهام عبر أمر turbo run"]},"keywords":{"en":["how to use turborepo","turborepo setup guide","turborepo vs lerna","turborepo install","what is turborepo","turborepo alternative","turborepo tutorial","turborepo best practices","turborepo for developers"],"zh":["Turborepo","JavaScript","TypeScript","monorepo","构建系统","AIエージェント","缓存任务输出","并行任务执行"],"ja":["Turborepo","JavaScript","TypeScript","monorepo","ビルドシステム","AIエージェント","タスクの出力をキャッシュ","並列タスク実行"],"ko":["Turborepo","JavaScript","TypeScript","monorepo","빌드 시스템","AI 도구","태스크 출력 캐시","병렬 태스크 실행"],"es":["turborepo","monorepo","javascript","typescript","sistema de compilación","caché de tareas","tareas en paralelo","grafo de dependencias","herramientas de desarrollo"],"fr":["turborepo","monorepo","javascript","typescript","système de construction","cache de tâches","tâches en parallèle","graphique de dépendances","outils de développement"],"de":["turborepo","monorepo","javascript","typescript","build-system","task-cache","parallel-tasks","abhängigkeitsgraph","entwicklungstools"],"pt":["Turborepo","monorepo","JavaScript","TypeScript","otimização","eficiência","desenvolvimento de software","ferramentas de desenvolvimento","guia de configuração"],"ru":["Turborepo","монорепозиторий","JavaScript","TypeScript","оптимизация","эффективность","разработка программного обеспечения","инструменты разработки","руководство по настройке"],"ar":["Turborepo","مونوريبوزиторي","جافاسكريبت","تايبسكريبت","تحسين","كفاءة","تطوير البرمجيات","أدوات التطوير","دليل الإعداد"]}},"owner":"sanity-io","repo":"plugins","repoPath":"sanity-io/plugins","stars":8,"forks":3,"updatedAt":"2026-02-27T09:48:56Z","topics":[],"category":"community","skillMd":{"name":"turborepo","description":"|","version":"2.8.9","bodyPreview":"# Turborepo Skill\n\nBuild system for JavaScript/TypeScript monorepos. Turborepo caches task outputs and runs tasks in parallel based on dependency graph.\n\n## IMPORTANT: Package Tasks, Not Root Tasks\n\n**DO NOT create Root Tasks. ALWAYS create package tasks.**\n\nWhen creating tasks/scripts/pipelines, you MUST:\n\n1. Add the script to each relevant package''s `package.json`\n2. Register the task in root `turbo.json`\n3. Root `package.json` only delegates via `turbo run <task>`\n\n**DO NOT** put task logic i","body":"# Turborepo Skill\n\nBuild system for JavaScript/TypeScript monorepos. Turborepo caches task outputs and runs tasks in parallel based on dependency graph.\n\n## IMPORTANT: Package Tasks, Not Root Tasks\n\n**DO NOT create Root Tasks. ALWAYS create package tasks.**\n\nWhen creating tasks/scripts/pipelines, you MUST:\n\n1. Add the script to each relevant package''s `package.json`\n2. Register the task in root `turbo.json`\n3. Root `package.json` only delegates via `turbo run <task>`\n\n**DO NOT** put task logic in root `package.json`. This defeats Turborepo''s parallelization.\n\n```json\n// DO THIS: Scripts in each package\n// apps/web/package.json\n{ \"scripts\": { \"build\": \"next build\", \"lint\": \"eslint .\", \"test\": \"vitest\" } }\n\n// apps/api/package.json\n{ \"scripts\": { \"build\": \"tsc\", \"lint\": \"eslint .\", \"test\": \"vitest\" } }\n\n// packages/ui/package.json\n{ \"scripts\": { \"build\": \"tsc\", \"lint\": \"eslint .\", \"test\": \"vitest\" } }\n```\n\n```json\n// turbo.json - register tasks\n{\n  \"tasks\": {\n    \"build\": {\"dependsOn\": [\"^build\"], \"outputs\": [\"dist/**\"]},\n    \"lint\": {},\n    \"test\": {\"dependsOn\": [\"build\"]}\n  }\n}\n```\n\n```json\n// Root package.json - ONLY delegates, no task logic\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\",\n    \"lint\": \"turbo run lint\",\n    \"test\": \"turbo run test\"\n  }\n}\n```\n\n```json\n// DO NOT DO THIS - defeats parallelization\n// Root package.json\n{\n  \"scripts\": {\n    \"build\": \"cd apps/web && next build && cd ../api && tsc\",\n    \"lint\": \"eslint apps/ packages/\",\n    \"test\": \"vitest\"\n  }\n}\n```\n\nRoot Tasks (`//#taskname`) are ONLY for tasks that truly cannot exist in packages (rare).\n\n## Secondary Rule: `turbo run` vs `turbo`\n\n**Always use `turbo run` when the command is written into code:**\n\n```json\n// package.json - ALWAYS \"turbo run\"\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\"\n  }\n}\n```\n\n```yaml\n# CI workflows - ALWAYS \"turbo run\"\n- run: turbo run build --affected\n```\n\n**The shorthand `turbo <tasks>` is ONLY for one-off terminal commands** typed directly by humans or agents. Never write `turbo build` into package.json, CI, or scripts.\n\n## Quick Decision Trees\n\n### \"I need to configure a task\"\n\n```\nConfigure a task?\n├─ Define task dependencies → references/configuration/tasks.md\n├─ Lint/check-types (parallel + caching) → Use Transit Nodes pattern (see below)\n├─ Specify build outputs → references/configuration/tasks.md#outputs\n├─ Handle environment variables → references/environment/RULE.md\n├─ Set up dev/watch tasks → references/configuration/tasks.md#persistent\n├─ Package-specific config → references/configuration/RULE.md#package-configurations\n└─ Global settings (cacheDir, daemon) → references/configuration/global-options.md\n```\n\n### \"My cache isn''t working\"\n\n```\nCache problems?\n├─ Tasks run but outputs not restored → Missing `outputs` key\n├─ Cache misses unexpectedly → references/caching/gotchas.md\n├─ Need to debug hash inputs → Use --summarize or --dry\n├─ Want to skip cache entirely → Use --force or cache: false\n├─ Remote cache not working → references/caching/remote-cache.md\n└─ Environment causing misses → references/environment/gotchas.md\n```\n\n### \"I want to run only changed packages\"\n\n```\nRun only what changed?\n├─ Changed packages + dependents (RECOMMENDED) → turbo run build --affected\n├─ Custom base branch → --affected --affected-base=origin/develop\n├─ Manual git comparison → --filter=...[origin/main]\n└─ See all filter options → references/filtering/RULE.md\n```\n\n**`--affected` is the primary way to run only changed packages.** It automatically compares against the default branch and includes dependents.\n\n### \"I want to filter packages\"\n\n```\nFilter packages?\n├─ Only changed packages → --affected (see above)\n├─ By package name → --filter=web\n├─ By directory → --filter=./apps/*\n├─ Package + dependencies → --filter=web...\n├─ Package + dependents → --filter=...web\n└─ Complex combinations → references/filtering/patterns.md\n```\n\n### \"Environment variables aren''t working\"\n\n```\nEnvironment issues?\n├─ Vars not available at runtime → Strict mode filtering (default)\n├─ Cache hits with wrong env → Var not in `env` key\n├─ .env changes not causing rebuilds → .env not in `inputs`\n├─ CI variables missing → references/environment/gotchas.md\n└─ Framework vars (NEXT_PUBLIC_*) → Auto-included via inference\n```\n\n### \"I need to set up CI\"\n\n```\nCI setup?\n├─ GitHub Actions → references/ci/github-actions.md\n├─ Vercel deployment → references/ci/vercel.md\n├─ Remote cache in CI → references/caching/remote-cache.md\n├─ Only build changed packages → --affected flag\n├─ Skip unnecessary builds → turbo-ignore (references/cli/commands.md)\n└─ Skip container setup when no changes → turbo-ignore\n```\n\n### \"I want to watch for changes during development\"\n\n```\nWatch mode?\n├─ Re-run tasks on change → turbo watch (references/watch/RULE.md)\n├─ Dev servers with dependencies → Use `with` key (references/configuration/tasks.md#with)\n├─ Restart dev server on dep change → Use `interruptible: true`\n└─ Persistent dev tasks → Use `persistent: true`\n```\n\n### \"I need to create/structure a package\"\n\n```\nPackage creation/structure?\n├─ Create an internal package → references/best-practices/packages.md\n├─ Repository structure → references/best-practices/structure.md\n├─ Dependency management → references/best-practices/dependencies.md\n├─ Best practices overview → references/best-practices/RULE.md\n├─ JIT vs Compiled packages → references/best-practices/packages.md#compilation-strategies\n└─ Sharing code between apps → references/best-practices/RULE.md#package-types\n```\n\n### \"How should I structure my monorepo?\"\n\n```\nMonorepo structure?\n├─ Standard layout (apps/, packages/) → references/best-practices/RULE.md\n├─ Package types (apps vs libraries) → references/best-practices/RULE.md#package-types\n├─ Creating internal packages → references/best-practices/packages.md\n├─ TypeScript configuration → references/best-practices/structure.md#typescript-configuration\n├─ ESLint configuration → references/best-practices/structure.md#eslint-configuration\n├─ Dependency management → references/best-practices/dependencies.md\n└─ Enforce package boundaries → references/boundaries/RULE.md\n```\n\n### \"I want to enforce architectural boundaries\"\n\n```\nEnforce boundaries?\n├─ Check for violations → turbo boundaries\n├─ Tag packages → references/boundaries/RULE.md#tags\n├─ Restrict which packages can import others → references/boundaries/RULE.md#rule-types\n└─ Prevent cross-package file imports → references/boundaries/RULE.md\n```\n\n## Critical Anti-Patterns\n\n### Using `turbo` Shorthand in Code\n\n**`turbo run` is recommended in package.json scripts and CI pipelines.** The shorthand `turbo <task>` is intended for interactive terminal use.\n\n```json\n// WRONG - using shorthand in package.json\n{\n  \"scripts\": {\n    \"build\": \"turbo build\",\n    \"dev\": \"turbo dev\"\n  }\n}\n\n// CORRECT\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\",\n    \"dev\": \"turbo run dev\"\n  }\n}\n```\n\n```yaml\n# WRONG - using shorthand in CI\n- run: turbo build --affected\n\n# CORRECT\n- run: turbo run build --affected\n```\n\n### Root Scripts Bypassing Turbo\n\nRoot `package.json` scripts MUST delegate to `turbo run`, not run tasks directly.\n\n```json\n// WRONG - bypasses turbo entirely\n{\n  \"scripts\": {\n    \"build\": \"bun build\",\n    \"dev\": \"bun dev\"\n  }\n}\n\n// CORRECT - delegates to turbo\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\",\n    \"dev\": \"turbo run dev\"\n  }\n}\n```\n\n### Using `&&` to Chain Turbo Tasks\n\nDon''t chain turbo tasks with `&&`. Let turbo orchestrate.\n\n```json\n// WRONG - turbo task not using turbo run\n{\n  \"scripts\": {\n    \"changeset:publish\": \"bun build && changeset publish\"\n  }\n}\n\n// CORRECT\n{\n  \"scripts\": {\n    \"changeset:publish\": \"turbo run build && changeset publish\"\n  }\n}\n```\n\n### `prebuild` Scripts That Manually Build Dependencies\n\nScripts like `prebuild` that manually build other packages bypass Turborepo''s dependency graph.\n\n```json\n// WRONG - manually building dependencies\n{\n  \"scripts\": {\n    \"prebuild\": \"cd ../../packages/types && bun run build && cd ../utils && bun run build\",\n    \"build\": \"next build\"\n  }\n}\n```\n\n**However, the fix depends on whether workspace dependencies are declared:**\n\n1. **If dependencies ARE declared** (e.g., `\"@repo/types\": \"workspace:*\"` in package.json), remove the `prebuild` script. Turbo''s `dependsOn: [\"^build\"]` handles this automatically.\n\n2. **If dependencies are NOT declared**, the `prebuild` exists because `^build` won''t trigger without a dependency relationship. The fix is to:\n   - Add the dependency to package.json: `\"@repo/types\": \"workspace:*\"`\n   - Then remove the `prebuild` script\n\n```json\n// CORRECT - declare dependency, let turbo handle build order\n// package.json\n{\n  \"dependencies\": {\n    \"@repo/types\": \"workspace:*\",\n    \"@repo/utils\": \"workspace:*\"\n  },\n  \"scripts\": {\n    \"build\": \"next build\"\n  }\n}\n\n// turbo.json\n{\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"]\n    }\n  }\n}\n```\n\n**Key insight:** `^build` only runs build in packages listed as dependencies. No dependency declaration = no automatic build ordering.\n\n### Overly Broad `globalDependencies`\n\n`globalDependencies` affects ALL tasks in ALL packages. Be specific.\n\n```json\n// WRONG - heavy hammer, affects all hashes\n{\n  \"globalDependencies\": [\"**/.env.*local\"]\n}\n\n// BETTER - move to task-level inputs\n{\n  \"globalDependencies\": [\".env\"],\n  \"tasks\": {\n    \"build\": {\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"],\n      \"outputs\": [\"dist/**\"]\n    }\n  }\n}\n```\n\n### Repetitive Task Configuration\n\nLook for repeated configuration across tasks that can be collapsed. Turborepo supports shared configuration patterns.\n\n```json\n// WRONG - repetitive env and inputs across tasks\n{\n  \"tasks\": {\n    \"build\": {\n      \"env\": [\"API_URL\", \"DATABASE_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"]\n    },\n    \"test\": {\n      \"env\": [\"API_URL\", \"DATABASE_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"]\n    },\n    \"dev\": {\n      \"env\": [\"API_URL\", \"DATABASE_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"],\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n\n// BETTER - use globalEnv and globalDependencies for shared config\n{\n  \"globalEnv\": [\"API_URL\", \"DATABASE_URL\"],\n  \"globalDependencies\": [\".env*\"],\n  \"tasks\": {\n    \"build\": {},\n    \"test\": {},\n    \"dev\": {\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n```\n\n**When to use global vs task-level:**\n\n- `globalEnv` / `globalDependencies` - affects ALL tasks, use for truly shared config\n- Task-level `env` / `inputs` - use when only specific tasks need it\n\n### NOT an Anti-Pattern: Large `env` Arrays\n\nA large `env` array (even 50+ variables) is **not** a problem. It usually means the user was thorough about declaring their build''s environment dependencies. Do not flag this as an issue.\n\n### Using `--parallel` Flag\n\nThe `--parallel` flag bypasses Turborepo''s dependency graph. If tasks need parallel execution, configure `dependsOn` correctly instead.\n\n```bash\n# WRONG - bypasses dependency graph\nturbo run lint --parallel\n\n# CORRECT - configure tasks to allow parallel execution\n# In turbo.json, set dependsOn appropriately (or use transit nodes)\nturbo run lint\n```\n\n### Package-Specific Task Overrides in Root turbo.json\n\nWhen multiple packages need different task configurations, use **Package Configurations** (`turbo.json` in each package) instead of cluttering root `turbo.json` with `package#task` overrides.\n\n```json\n// WRONG - root turbo.json with many package-specific overrides\n{\n  \"tasks\": {\n    \"test\": { \"dependsOn\": [\"build\"] },\n    \"@repo/web#test\": { \"outputs\": [\"coverage/**\"] },\n    \"@repo/api#test\": { \"outputs\": [\"coverage/**\"] },\n    \"@repo/utils#test\": { \"outputs\": [] },\n    \"@repo/cli#test\": { \"outputs\": [] },\n    \"@repo/core#test\": { \"outputs\": [] }\n  }\n}\n\n// CORRECT - use Package Configurations\n// Root turbo.json - base config only\n{\n  \"tasks\": {\n    \"test\": { \"dependsOn\": [\"build\"] }\n  }\n}\n\n// packages/web/turbo.json - package-specific override\n{\n  \"extends\": [\"//\"],\n  \"tasks\": {\n    \"test\": { \"outputs\": [\"coverage/**\"] }\n  }\n}\n\n// packages/api/turbo.json\n{\n  \"extends\": [\"//\"],\n  \"tasks\": {\n    \"test\": { \"outputs\": [\"coverage/**\"] }\n  }\n}\n```\n\n**Benefits of Package Configurations:**\n\n- Keeps configuration close to the code it affects\n- Root turbo.json stays clean and focused on base patterns\n- Easier to understand what''s special about each package\n- Works with `$TURBO_EXTENDS$` to inherit + extend arrays\n\n**When to use `package#task` in root:**\n\n- Single package needs a unique dependency (e.g., `\"deploy\": { \"dependsOn\": [\"web#build\"] }`)\n- Temporary override while migrating\n\nSee `references/configuration/RULE.md#package-configurations` for full details.\n\n### Using `../` to Traverse Out of Package in `inputs`\n\nDon''t use relative paths like `../` to reference files outside the package. Use `$TURBO_ROOT$` instead.\n\n```json\n// WRONG - traversing out of package\n{\n  \"tasks\": {\n    \"build\": {\n      \"inputs\": [\"$TURBO_DEFAULT$\", \"../shared-config.json\"]\n    }\n  }\n}\n\n// CORRECT - use $TURBO_ROOT$ for repo root\n{\n  \"tasks\": {\n    \"build\": {\n      \"inputs\": [\"$TURBO_DEFAULT$\", \"$TURBO_ROOT$/shared-config.json\"]\n    }\n  }\n}\n```\n\n### Missing `outputs` for File-Producing Tasks\n\n**Before flagging missing `outputs`, check what the task actually produces:**\n\n1. Read the package''s script (e.g., `\"build\": \"tsc\"`, `\"test\": \"vitest\"`)\n2. Determine if it writes files to disk or only outputs to stdout\n3. Only flag if the task produces files that should be cached\n\n```json\n// WRONG: build produces files but they''re not cached\n{\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"]\n    }\n  }\n}\n\n// CORRECT: build outputs are cached\n{\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"],\n      \"outputs\": [\"dist/**\"]\n    }\n  }\n}\n```\n\nCommon outputs by framework:\n\n- Next.js: `[\".next/**\", \"!.next/cache/**\"]`\n- Vite/Rollup: `[\"dist/**\"]`\n- tsc: `[\"dist/**\"]` or custom `outDir`\n\n**TypeScript `--noEmit` can still produce cache files:**\n\nWhen `incremental: true` in tsconfig.json, `tsc --noEmit` writes `.tsbuildinfo` files even without emitting JS. Check the tsconfig before assuming no outputs:\n\n```json\n// If tsconfig has incremental: true, tsc --noEmit produces cache files\n{\n  \"tasks\": {\n    \"typecheck\": {\n      \"outputs\": [\"node_modules/.cache/tsbuildinfo.json\"] // or wherever tsBuildInfoFile points\n    }\n  }\n}\n```\n\nTo determine correct outputs for TypeScript tasks:\n\n1. Check if `incremental` or `composite` is enabled in tsconfig\n2. Check `tsBuildInfoFile` for custom cache location (default: alongside `outDir` or in project root)\n3. If no incremental mode, `tsc --noEmit` produces no files\n\n### `^build` vs `build` Confusion\n\n```json\n{\n  \"tasks\": {\n    // ^build = run build in DEPENDENCIES first (other packages this one imports)\n    \"build\": {\n      \"dependsOn\": [\"^build\"]\n    },\n    // build (no ^) = run build in SAME PACKAGE first\n    \"test\": {\n      \"dependsOn\": [\"build\"]\n    },\n    // pkg#task = specific package''s task\n    \"deploy\": {\n      \"dependsOn\": [\"web#build\"]\n    }\n  }\n}\n```\n\n### Environment Variables Not Hashed\n\n```json\n// WRONG: API_URL changes won''t cause rebuilds\n{\n  \"tasks\": {\n    \"build\": {\n      \"outputs\": [\"dist/**\"]\n    }\n  }\n}\n\n// CORRECT: API_URL changes invalidate cache\n{\n  \"tasks\": {\n    \"build\": {\n      \"outputs\": [\"dist/**\"],\n      \"env\": [\"API_URL\", \"API_KEY\"]\n    }\n  }\n}\n```\n\n### `.env` Files Not in Inputs\n\nTurbo does NOT load `.env` files - your framework does. But Turbo needs to know about changes:\n\n```json\n// WRONG: .env changes don''t invalidate cache\n{\n  \"tasks\": {\n    \"build\": {\n      \"env\": [\"API_URL\"]\n    }\n  }\n}\n\n// CORRECT: .env file changes invalidate cache\n{\n  \"tasks\": {\n    \"build\": {\n      \"env\": [\"API_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env\", \".env.*\"]\n    }\n  }\n}\n```\n\n### Root `.env` File in Monorepo\n\nA `.env` file at the repo root is an anti-pattern — even for small monorepos or starter templates. It creates implicit coupling between packages and makes it unclear which packages depend on which variables.\n\n```\n// WRONG - root .env affects all packages implicitly\nmy-monorepo/\n├── .env              # Which packages use this?\n├── apps/\n│   ├── web/\n│   └── api/\n└── packages/\n\n// CORRECT - .env files in packages that need them\nmy-monorepo/\n├── apps/\n│   ├── web/\n│   │   └── .env      # Clear: web needs DATABASE_URL\n│   └── api/\n│       └── .env      # Clear: api needs API_KEY\n└── packages/\n```\n\n**Problems with root `.env`:**\n\n- Unclear which packages consume which variables\n- All packages get all variables (even ones they don''t need)\n- Cache invalidation is coarse-grained (root .env change invalidates everything)\n- Security risk: packages may accidentally access sensitive vars meant for others\n- Bad habits start small — starter templates should model correct patterns\n\n**If you must share variables**, use `globalEnv` to be explicit about what''s shared, and document why.\n\n### Strict Mode Filtering CI Variables\n\nBy default, Turborepo filters environment variables to only those in `env`/`globalEnv`. CI variables may be missing:\n\n```json\n// If CI scripts need GITHUB_TOKEN but it''s not in env:\n{\n  \"globalPassThroughEnv\": [\"GITHUB_TOKEN\", \"CI\"],\n  \"tasks\": { ... }\n}\n```\n\nOr use `--env-mode=loose` (not recommended for production).\n\n### Shared Code in Apps (Should Be a Package)\n\n```\n// WRONG: Shared code inside an app\napps/\n  web/\n    shared/          # This breaks monorepo principles!\n      utils.ts\n\n// CORRECT: Extract to a package\npackages/\n  utils/\n    src/utils.ts\n```\n\n### Accessing Files Across Package Boundaries\n\n```typescript\n// WRONG: Reaching into another package''s internals\nimport {Button} from ''../../packages/ui/src/button''\n\n// CORRECT: Install and import properly\nimport {Button} from ''@repo/ui/button''\n```\n\n### Too Many Root Dependencies\n\n```json\n// WRONG: App dependencies in root\n{\n  \"dependencies\": {\n    \"react\": \"^18\",\n    \"next\": \"^14\"\n  }\n}\n\n// CORRECT: Only repo tools in root\n{\n  \"devDependencies\": {\n    \"turbo\": \"latest\"\n  }\n}\n```\n\n## Common Task Configurations\n\n### Standard Build Pipeline\n\n```json\n{\n  \"$schema\": \"https://turborepo.dev/schema.v2.json\",\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"],\n      \"outputs\": [\"dist/**\", \".next/**\", \"!.next/cache/**\"]\n    },\n    \"dev\": {\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n```\n\nAdd a `transit` task if you have tasks that need parallel execution with cache invalidation (see below).\n\n### Dev Task with `^dev` Pattern (for `turbo watch`)\n\nA `dev` task with `dependsOn: [\"^dev\"]` and `persistent: false` in root turbo.json may look unusual but is **correct for `turbo watch` workflows**:\n\n```json\n// Root turbo.json\n{\n  \"tasks\": {\n    \"dev\": {\n      \"dependsOn\": [\"^dev\"],\n      \"cache\": false,\n      \"persistent\": false  // Packages have one-shot dev scripts\n    }\n  }\n}\n\n// Package turbo.json (apps/web/turbo.json)\n{\n  \"extends\": [\"//\"],\n  \"tasks\": {\n    \"dev\": {\n      \"persistent\": true  // Apps run long-running dev servers\n    }\n  }\n}\n```\n\n**Why this works:**\n\n- **Packages** (e.g., `@acme/db`, `@acme/validators`) have `\"dev\": \"tsc\"` — one-shot type generation that completes quickly\n- **Apps** override with `persistent: true` for actual dev servers (Next.js, etc.)\n- **`turbo watch`** re-runs the one-shot package `dev` scripts when source files change, keeping types in sync\n\n**Intended usage:** Run `turbo watch dev` (not `turbo run dev`). Watch mode re-executes one-shot tasks on file changes while keeping persistent tasks running.\n\n**Alternative pattern:** Use a separate task name like `prepare` or `generate` for one-shot dependency builds to make the intent clearer:\n\n```json\n{\n  \"tasks\": {\n    \"prepare\": {\n      \"dependsOn\": [\"^prepare\"],\n      \"outputs\": [\"dist/**\"]\n    },\n    \"dev\": {\n      \"dependsOn\": [\"prepare\"],\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n```\n\n### Transit Nodes for Parallel Tasks with Cache Invalidation\n\nSome tasks can run in parallel (don''t need built output from dependencies) but must invalidate cache when dependency source code changes.\n\n**The problem with `dependsOn: [\"^taskname\"]`:**\n\n- Forces sequential execution (slow)\n\n**The problem with `dependsOn: []` (no dependencies):**\n\n- Allows parallel execution (fast)\n- But cache is INCORRECT - changing dependency source won''t invalidate cache\n\n**Transit Nodes solve both:**\n\n```json\n{\n  \"tasks\": {\n    \"transit\": {\"dependsOn\": [\"^transit\"]},\n    \"my-task\": {\"dependsOn\": [\"transit\"]}\n  }\n}\n```\n\nThe `transit` task creates dependency relationships without matching any actual script, so tasks run in parallel with correct cache invalidation.\n\n**How to identify tasks that need this pattern:** Look for tasks that read source files from dependencies but don''t need their build outputs.\n\n### With Environment Variables\n\n```json\n{\n  \"globalEnv\": [\"NODE_ENV\"],\n  \"globalDependencies\": [\".env\"],\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"],\n      \"outputs\": [\"dist/**\"],\n      \"env\": [\"API_URL\", \"DATABASE_URL\"]\n    }\n  }\n}\n```\n\n## Reference Index\n\n### Configuration\n\n| File                                                                            | Purpose                                                  |\n| ------------------------------------------------------------------------------- | -------------------------------------------------------- |\n| [configuration/RULE.md](./references/configuration/RULE.md)                     | turbo.json overview, Package Configurations              |\n| [configuration/tasks.md](./references/configuration/tasks.md)                   | dependsOn, outputs, inputs, env, cache, persistent       |\n| [configuration/global-options.md](./references/configuration/global-options.md) | globalEnv, globalDependencies, cacheDir, daemon, envMode |\n| [configuration/gotchas.md](./references/configuration/gotchas.md)               | Common configuration mistakes                            |\n\n### Caching\n\n| File                                                            | Purpose                                      |\n| --------------------------------------------------------------- | -------------------------------------------- |\n| [caching/RULE.md](./references/caching/RULE.md)                 | How caching works, hash inputs               |\n| [caching/remote-cache.md](./references/caching/remote-cache.md) | Vercel Remote Cache, self-hosted, login/link |\n| [caching/gotchas.md](./references/caching/gotchas.md)           | Debugging cache misses, --summarize, --dry   |\n\n### Environment Variables\n\n| File                                                          | Purpose                                   |\n| ------------------------------------------------------------- | ----------------------------------------- |\n| [environment/RULE.md](./references/environment/RULE.md)       | env, globalEnv, passThroughEnv            |\n| [environment/modes.md](./references/environment/modes.md)     | Strict vs Loose mode, framework inference |\n| [environment/gotchas.md](./references/environment/gotchas.md) | .env files, CI issues                     |\n\n### Filtering\n\n| File                                                        | Purpose                  |\n| ----------------------------------------------------------- | ------------------------ |\n| [filtering/RULE.md](./references/filtering/RULE.md)         | --filter syntax overview |\n| [filtering/patterns.md](./references/filtering/patterns.md) | Common filter patterns   |\n\n### CI/CD\n\n| File                                                      | Purpose                         |\n| --------------------------------------------------------- | ------------------------------- |\n| [ci/RULE.md](./references/ci/RULE.md)                     | General CI principles           |\n| [ci/github-actions.md](./references/ci/github-actions.md) | Complete GitHub Actions setup   |\n| [ci/vercel.md](./references/ci/vercel.md)                 | Vercel deployment, turbo-ignore |\n| [ci/patterns.md](./references/ci/patterns.md)             | --affected, caching strategies  |\n\n### CLI\n\n| File                                            | Purpose                                       |\n| ----------------------------------------------- | --------------------------------------------- |\n| [cli/RULE.md](./references/cli/RULE.md)         | turbo run basics                              |\n| [cli/commands.md](./references/cli/commands.md) | turbo run flags, turbo-ignore, other commands |\n\n### Best Practices\n\n| File                                                                          | Purpose                                                         |\n| ----------------------------------------------------------------------------- | --------------------------------------------------------------- |\n| [best-practices/RULE.md](./references/best-practices/RULE.md)                 | Monorepo best practices overview                                |\n| [best-practices/structure.md](./references/best-practices/structure.md)       | Repository structure, workspace config, TypeScript/ESLint setup |\n| [best-practices/packages.md](./references/best-practices/packages.md)         | Creating internal packages, JIT vs Compiled, exports            |\n| [best-practices/dependencies.md](./references/best-practices/dependencies.md) | Dependency management, installing, version sync                 |\n\n### Watch Mode\n\n| File                                        | Purpose                                         |\n| ------------------------------------------- | ----------------------------------------------- |\n| [watch/RULE.md](./references/watch/RULE.md) | turbo watch, interruptible tasks, dev workflows |\n\n### Boundaries (Experimental)\n\n| File                                                  | Purpose                                               |\n| ----------------------------------------------------- | ----------------------------------------------------- |\n| [boundaries/RULE.md](./references/boundaries/RULE.md) | Enforce package isolation, tag-based dependency rules |\n\n## Source Documentation\n\nThis skill is based on the official Turborepo documentation at:\n\n- Source: `apps/docs/content/docs/` in the Turborepo repository\n- Live: https://turborepo.dev/docs\n"},"lastSynced":"2026-03-06T13:04:11.998Z","agentAnalysis":{"suitability":{"en":"Ideal for JavaScript/TypeScript Developer Agents seeking to optimize monorepo build processes with advanced caching and parallel task execution.","zh":"适用于JavaScript/TypeScript开发者代理，旨在优化monorepo构建过程，采用高级缓存和并行任务执行。","ja":"JavaScript/TypeScriptデベロッパーエージェント向けに、モノレポのビルドプロセスを最適化するための高度なキャッシングと並列タスク実行を提供します。","ko":"JavaScript/TypeScript 개발자 에이전트를 위한 모노리포 빌드 프로세스 최적화에 적합하며, 고급 캐싱 및 병렬 작업 실행을 제공합니다.","es":"Ideal para Agentes de Desarrollo de JavaScript/TypeScript que buscan optimizar los procesos de compilación de monorepo con almacenamiento en caché avanzado y ejecución de tareas paralelas.","fr":"Idéal pour les agents de développement JavaScript/TypeScript qui cherchent à optimiser les processus de build de monorepo avec un cache avancé et une exécution de tâches parallèles.","de":"Ideal für JavaScript/TypeScript-Entwicklungsagenten, die Monorepo-Build-Prozesse mit erweitertem Caching und paralleler Aufgabenausführung optimieren möchten.","pt":"Ideal para Agentes de Desenvolvedores JavaScript/TypeScript que buscam otimizar processos de compilação de monorepo com cache avançado e execução paralela de tarefas.","ru":"Идеально для Агентов-разработчиков JavaScript/TypeScript, стремящихся оптимизировать процессы сборки монореpo с помощью продвинутого кэширования и параллельного выполнения задач.","ar":"مثالي لعميل وكلاء JavaScript/TypeScript الذين يبتغون تحسين عمليات بناء مونوريبو مع ذاكرة مؤقتة متقدمة وتنفيذ مهام متوازي."},"recommendation":{"en":"Empowers agents to accelerate development workflows by caching task outputs and running tasks in parallel based on dependency graphs, leveraging turbo.json configurations and package.json scripts for seamless monorepo management.","zh":"赋予代理加速开发工作流的能力，通过缓存任务输出和基于依赖关系图并行运行任务，利用turbo.json配置和package.json脚本实现无缝的monorepo管理。","ja":"エージェントに、タスク出力をキャッシュし、依存関係グラフに基づいてタスクを並列実行することで、開発ワークフローを加速させる能力を提供します。turbo.json構成とpackage.jsonスクリプトを利用して、モノレポ管理を無縫に行うことができます。","ko":"에이전트가 개발 워크플ロー를 가속화할 수 있는 기능을 제공하며, 작업 출력을 캐싱하고 종속성 그래프를 기반으로 작업을 병렬로 실행하여 터보.json 구성 및 패키지.json 스크립트를 사용하여 모노리포 관리를无缝하게 수행할 수 있습니다.","es":"Permite a los agentes acelerar los flujos de trabajo de desarrollo almacenando en caché las salidas de las tareas y ejecutando tareas en paralelo en función de los gráficos de dependencias, aprovechando las configuraciones de turbo.json y los scripts de package.json para una gestión de monorepo sin problemas.","fr":"Permet aux agents d''accélérer les flux de travail de développement en stockant en cache les sorties des tâches et en exécutant des tâches en parallèle en fonction des graphiques de dépendances, en exploitant les configurations de turbo.json et les scripts de package.json pour une gestion de monorepo sans problème.","de":"Ermöglicht es Agenten, die Entwicklungsworkflows durch das Zwischenspeichern von Task-Ausgaben und das parallele Ausführen von Tasks basierend auf Abhängigkeitsgraphen zu beschleunigen, wobei die Konfigurationen von turbo.json und package.json für eine reibungslose Monorepo-Verwaltung genutzt werden.","pt":"Habilita os agentes a acelerar fluxos de trabalho de desenvolvimento, armazenando em cache as saídas de tarefas e executando tarefas em paralelo com base em gráficos de dependência, aproveitando configurações turbo.json e scripts package.json para gerenciamento de monorepo sem problemas.","ru":"Позволяет агентам ускорить рабочие процессы разработки, кэшируя выходные данные задач и выполняя задачи параллельно на основе графиков зависимостей, используя конфигурации turbo.json и скрипты package.json для бесперебойного управления монореpo.","ar":"يمكن للعميل تعزيز وكلاء لتعجيل سير العمل التطوير من خلال تخزين المخرجات المهام في ذاكرة مؤقتة وتنفيذ المهام بالتوازي بالاعتماد على رسوم بيانية للاتصال، واستغلال Configurações turbo.json والبرامج النصية package.json لإدارة مونوريبو دون مشاكل."},"useCases":{"en":["Automating build pipelines for JavaScript/TypeScript monorepos","Optimizing task execution with dependency-based parallelism","Streamlining plugin development and publishing"],"zh":["为JavaScript/TypeScript monorepo自动化构建流水线","使用依赖关系并行优化任务执行","简化插件开发和发布"],"ja":["JavaScript/TypeScriptモノレポのビルドパイプラインを自動化する","依存関係に基づく並列性を使用してタスク実行を最適化する","プラグインの開発と公開を簡素化する"],"ko":["JavaScript/TypeScript 모노리포를 위한 빌드 파이프라인 자동화","종속성 기반 병렬성을 사용하여 작업 실행 최적화","플러그인 개발 및 发布를 단순화"],"es":["Automatización de pipelines de compilación para monorepos de JavaScript/TypeScript","Optimización de la ejecución de tareas con paralelismo basado en dependencias","Optimización del desarrollo y publicación de plugins"],"fr":["Automatisation des pipelines de build pour les monorepos JavaScript/TypeScript","Optimisation de l''exécution des tâches avec un parallélisme basé sur les dépendances","Optimisation du développement et de la publication de plugins"],"de":["Automatisierung von Build-Pipelines für JavaScript/TypeScript-Monorepos","Optimierung der Aufgabenausführung mit abhängigkeitsbasiertem Parallelismus","Optimierung der Plugin-Entwicklung und -Veröffentlichung"],"pt":["Automatizar pipelines de compilação para monorepos JavaScript/TypeScript","Otimizar execução de tarefas com paralelismo baseado em dependência","Simplificar desenvolvimento e publicação de plugins"],"ru":["Автоматизировать конвейеры сборки для монореpo JavaScript/TypeScript","Оптимизировать выполнение задач с параллелизмом на основе зависимостей","Упростить разработку и публикацию плагинов"],"ar":["أتمتة خطوط أنابيب البناء لمونوريبو JavaScript/TypeScript","تحسين تنفيذ المهام بالتوازي بالاعتماد على الاتصال","تبسيط تطوير ونشر الإضافات"]},"limitations":{"en":["Requires JavaScript/TypeScript monorepo setup","Must create package tasks, not root tasks","Dependent on turbo.json and package.json configurations"],"zh":["需要JavaScript/TypeScript monorepo设置","必须创建包任务，而不是根任务","依赖于turbo.json和package.json配置"],"ja":["JavaScript/TypeScriptモノレポの設定が必要","ルートタスクではなくパッケージタスクを作成する必要がある","turbo.jsonとpackage.jsonの構成に依存する"],"ko":["JavaScript/TypeScript 모노리포 설정이 필요","루트 작업이 아닌 패키지 작업을 생성해야 함","터보.json 및 패키지.json 구성에 의존"],"es":["Requiere configuración de monorepo de JavaScript/TypeScript","Deben crearse tareas de paquete, no tareas de raíz","Dependiente de las configuraciones de turbo.json y package.json"],"fr":["Nécessite une configuration de monorepo JavaScript/TypeScript","Doivent créer des tâches de package, pas des tâches de racine","Dépend des configurations de turbo.json et package.json"],"de":["Benötigt eine JavaScript/TypeScript-Monorepo-Konfiguration","Müssen Paketaufgaben erstellen, keine Root-Aufgaben","Abhängig von den Konfigurationen von turbo.json und package.json"],"pt":["Exige configuração de monorepo JavaScript/TypeScript","Deve criar tarefas de pacote, não tarefas de raiz","Depende de configurações turbo.json e package.json"],"ru":["Требует настройки монореpo JavaScript/TypeScript","Должно создавать задачи пакета, а не задачи корня","Зависит от конфигураций turbo.json и package.json"],"ar":["يتطلب إعداد مونوريبو JavaScript/TypeScript","يجب أن يخلق مهام الحزمة، وليس مهام الجذر","يعتمد على Configurações turbo.json والبرامج النصية package.json"]},"version":4},"contentHash":"d7e4295a4ce6a5de509742e501a20c9989e55592d532347459b441be890f6ef1","qualityScore":50}');
