INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sanity-io/plugins/turborepo', 'turborepo', 'sanity-io', 'plugins', 'community', 'turborepo sanity-io plugins community Turborepo is a build system for JavaScript/TypeScript monorepos, providing a centralized place for developing, testing, and publishing plugins. It benefits developers by caching task outputs and running tasks in parallel based on dependency graphs. Turborepo 是一个 JavaScript/TypeScript 项目的构建系统，能够缓存任务输出并基于依赖图运行任务。 Turborepo は JavaScript/TypeScript プロジェクトのビルドシステムであり、タスクの出力をキャッシュし、依存関係グラフに基づいてタスクを実行します。 Turborepo는 JavaScript/TypeScript 프로젝트의 빌드 시스템으로, 태스크 출력을 캐시하고 의존성 그래프를 기반으로 태스크를 실행합니다. Turborepo es un sistema de compilación para monorepos de JavaScript/TypeScript que almacena en caché las salidas de las tareas y ejecuta tareas en paralelo según el grafo de dependencias. Turborepo est un système de construction pour les monorepos JavaScript/TypeScript qui met en cache les sorties des tâches et exécute les tâches en parallèle en fonction du graphique de dépendances. Turborepo ist ein Build-System für JavaScript/TypeScript-Monorepos, das Task-Ausgaben zwischenspeichert und Tasks parallel basierend auf der Abhängigkeitsgraph ausführt. O Turborepo é um sistema de construção para monorepos JavaScript/TypeScript que melhora a eficiência ao armazenar em cache as saídas das tarefas e executar tarefas em paralelo com base no gráfico de dependências Turborepo — это система сборки для монорепозиториев JavaScript/TypeScript, которая улучшает эффективность путем кэширования выходных данных задач и запуска задач параллельно на основе графа зависимостей Turborepo هو نظام بناء لمونوريبوزиторي جافاسكريبت/تايبسكريبت الذي يحسن الكفاءة من خلال تخزين النتائج المؤقتة للمهام وتنفيذ المهام بالتوازي بناءً على مخطط الاعتماديات how to use turborepo turborepo setup guide turborepo vs lerna turborepo install what is turborepo turborepo alternative turborepo tutorial turborepo best practices turborepo for developers Turborepo JavaScript TypeScript monorepo 构建系统 AIエージェント 缓存任务输出 并行任务执行 Caches task outputs for improved performance Runs tasks in parallel based on dependency graphs Supports package tasks via `package.json` files Registers tasks in root `turbo.json` file Delegates tasks via `turbo run <task>` command Optimizes workflow by avoiding root tasks Turborepo is a build system for JavaScript/TypeScript monorepos that caches task outputs and runs tasks in parallel based on dependency graphs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JanuaryLabs/deepagents/openspec-bulk-archive-change', 'community', 'JanuaryLabs', 'deepagents', 'JanuaryLabs/deepagents', 'openspec-bulk-archive-change', 4, 0, 50, '2026-02-25T11:16:42Z', '2026-03-06T06:57:29.199Z', 'f42ab9c99f56c5646d109e7fe94407c25e847ea12c8b43facc8ea42ddc488c72', '{"id":"JanuaryLabs/deepagents/openspec-bulk-archive-change","name":"openspec-bulk-archive-change","description":{"en":"The openspec-bulk-archive-change skill allows developers to archive multiple completed changes in a single operation, handling spec conflicts by checking the codebase. This skill benefits developers working with large codebases.","zh":"openspec-bulk-archive-change 是一种批量归档更改的技能，智能处理规格冲突。它允许您批量归档更改，检查代码库以确定实际实现的内容","ja":"openspec-bulk-archive-change はバッチ変更のアーカイブを可能にするスキルで、スマートな仕様の衝突を解決します。コードベースをチェックして実際に実装された内容を判断します","ko":"openspec-bulk-archive-change는 배치 변경 아카이브를 가능하게 하는 스킬로 스마트한 사양 충돌을 해결합니다. 코드베이스를 확인하여 실제로 구현된 내용을 판단합니다","es":"openspec-bulk-archive-change permite archivar múltiples cambios en una sola operación, manejando conflictos de especificaciones de forma inteligente","fr":"openspec-bulk-archive-change vous permet d''archiver plusieurs changements en une seule opération, en gérant de manière intelligente les conflits de spécifications","de":"openspec-bulk-archive-change ermöglicht das Archivieren mehrerer Änderungen in einer einzigen Operation, indem es Spezifikationskonflikte intelligent handhabt","pt":"O openspec-bulk-archive-change é uma habilidade que permite arquivar várias mudanças concluídas em uma única operação, lidando com conflitos de especificação de forma inteligente","ru":"openspec-bulk-archive-change - это навык, который позволяет архивировать несколько завершенных изменений в одну операцию, обрабатывая конфликты спецификаций интеллектуально","ar":"openspec-bulk-archive-change هو مهارة تسمح بتحديث عدة تغييرات مكتملة في عملية واحدة، وتتعامل مع конфликات المواصفات بذكاء"},"seo":{"title":{"en":"openspec-bulk-archive-change: Bulk Archive Setup Guide | ...","zh":"openspec-bulk-archive-change 设置指南","ja":"openspec-bulk-archive-change 導入ガイド","ko":"openspec-bulk-archive-change 설정 가이드","es":"Guía de configuración de openspec-bulk-archive-change par...","fr":"Guide de mise en place d''openspec-bulk-archive-change pou...","de":"Einrichtungsleitfaden für openspec-bulk-archive-change in...","pt":"Guia de Configuração do openspec-bulk-archive-change","ru":"Настройка openspec-bulk-archive-change: ИИ Агенты для Раз...","ar":"إعداد openspec-bulk-archive-change: أدوات ذكاء اصطناعي لل..."},"description":{"en":"Discover how openspec-bulk-archive-change simplifies batch archiving with intelligent spec conflict handling - try it now and streamline your workflow!","zh":"了解 openspec-bulk-archive-change 的功能和优点，包括批量归档更改和智能处理规格冲突","ja":"openspec-bulk-archive-change の機能と利点を紹介します。バッチ変更のアーカイブとスマートな仕様の衝突の解決を含みます","ko":"openspec-bulk-archive-change의 기능과 이점을 알아보세요. 배치 변경 아카이브 및 스마트한 사양 충돌 해결 포함","es":"Aprende a archivar cambios múltiples con openspec-bulk-archive-change. Descubre cómo funciona esta habilidad de agente de IA para mejorar tu flujo de trabajo","fr":"Découvrez comment archiver plusieurs changements avec openspec-bulk-archive-change. Améliorez votre flux de travail avec cet outil d''IA","de":"Erfahren Sie, wie Sie mehrere Änderungen mit openspec-bulk-archive-change archivieren. Verbessern Sie Ihren Arbeitsablauf mit diesem KI-Tool","pt":"Aprenda a usar o openspec-bulk-archive-change para arquivar mudanças em lote de forma inteligente, resolvendo conflitos de especificação","ru":"Узнайте, как использовать openspec-bulk-archive-change для архивации изменений в пакете, решая конфликты спецификаций с помощью ИИ Агентов","ar":"تعرف على كيفية استخدام openspec-bulk-archive-change لتحديث التغييرات بالجملة بذكاء، وحل конфликات المواصفات"},"definition":{"en":"openspec-bulk-archive-change is a skill that enables batch archiving of completed changes, intelligently resolving spec conflicts by analyzing the codebase.","zh":"openspec-bulk-archive-change 是一种 AI 工具，用于批量归档更改和智能处理规格冲突","ja":"openspec-bulk-archive-change は、バッチ変更のアーカイブとスマートな仕様の衝突を解決するための AI エージェントです","ko":"openspec-bulk-archive-change는 배치 변경 아카이브 및 스마트한 사양 충돌을 해결하는 AI 도구입니다","es":"openspec-bulk-archive-change es una habilidad de agente de IA que archiva cambios múltiples","fr":"openspec-bulk-archive-change est une fonctionnalité d''outil d''IA qui archive plusieurs changements","de":"openspec-bulk-archive-change ist eine Fähigkeit von KI-Tools, die mehrere Änderungen archiviert","pt":"O que é openspec-bulk-archive-change? É uma habilidade de AI que arquiva mudanças em lote, resolvendo conflitos de especificação","ru":"Что такое openspec-bulk-archive-change? Это навык ИИ, который архивирует изменения в пакете, решая конфликты спецификаций","ar":"ما هو openspec-bulk-archive-change؟ هو مهارة ذكاء اصطناعي لتحديث التغييرات بالجملة، وحل конфликات المواصفات"},"features":{"en":["Runs `openspec list --json` to retrieve all active changes","Utilizes AskUserQuestion tool for multi-select change selection","Checks the codebase to determine implemented changes","Handles spec conflicts intelligently","Prompts user for change selection with no required input","Supports batch archiving of multiple completed changes"],"zh":["批量归档更改","智能处理规格冲突","使用 openspec list --json 获取活跃的更改","使用 AskUserQuestion 工具进行更改选择","检查代码库以确定实际实现的内容"],"ja":["バッチ変更のアーカイブ","スマートな仕様の衝突を解決","openspec list --json を使用してアクティブな変更を取得","AskUserQuestion ツールを使用して変更を選択","コードベースをチェックして実際に実装された内容を判断"],"ko":["배치 변경 아카이브","스마트한 사양 충돌을 해결","openspec list --json을 사용하여 활성 변경을 가져옴","AskUserQuestion 도구를 사용하여 변경을 선택","코드베이스를 확인하여 실제로 구현된 내용을 판단"],"es":["Archivar cambios múltiples en una sola operación","Gestión inteligente de conflictos de especificaciones","Uso de la herramienta AskUserQuestion para la selección de cambios","Ejecución de `openspec list --json` para obtener cambios activos","Compatibilidad con operaciones por lotes"],"fr":["Archiver plusieurs changements en une seule opération","Gestion intelligente des conflits de spécifications","Utilisation de l''outil AskUserQuestion pour la sélection de changements","Exécution de `openspec list --json` pour obtenir les changements actifs","Compatibilité avec les opérations par lots"],"de":["Mehrere Änderungen in einer einzigen Operation archivieren","Intelligente Handhabung von Spezifikationskonflikten","Verwendung des AskUserQuestion-Tools für die Änderungsauswahl","Ausführung von `openspec list --json` zur Abrufung von aktiven Änderungen","Unterstützung von Batch-Operationen"],"pt":["Arquivamento em lote de mudanças concluídas","Resolução inteligente de conflitos de especificação","Utilização do comando `openspec list --json`","Integração com a ferramenta AskUserQuestion","Seleção multipla de mudanças para arquivamento","Verificação da base de código para determinar o que está implementado"],"ru":["Архивация изменений в пакете","Интеллектуальное решение конфликтов спецификаций","Использование команды `openspec list --json`","Интеграция с инструментом AskUserQuestion","Множественный выбор изменений для архивации","Проверка кодовой базы для определения того, что реализовано"],"ar":["تحديث التغييرات بالجملة","حل ذكي لконفликات المواصفات","استخدام الأمر `openspec list --json`","التكامل مع أداة AskUserQuestion","اختيار متعدد للتغييرات لتحديثها","فحص قاعدة الشفرة لتحديد ما تم تنفيذه"]},"keywords":{"en":["how to use openspec-bulk-archive-change","openspec-bulk-archive-change setup guide","openspec-bulk-archive-change alternative","what is openspec-bulk-archive-change","openspec-bulk-archive-change install","batch archiving with openspec-bulk-archive-change","openspec-bulk-archive-change vs manual archiving","openspec-bulk-archive-change tutorial","openspec-bulk-archive-change benefits for developers"],"zh":["openspec-bulk-archive-change","AI 工具","批量归档更改","智能处理规格冲突","openspec list --json","AskUserQuestion","代码库检查"],"ja":["openspec-bulk-archive-change","AI エージェント","バッチ変更のアーカイブ","スマートな仕様の衝突を解決","openspec list --json","AskUserQuestion","コードベースのチェック"],"ko":["openspec-bulk-archive-change","AI 도구","배치 변경 아카이브","스마트한 사양 충돌을 해결","openspec list --json","AskUserQuestion","코드베이스 확인"],"es":["agentes de IA","openspec-bulk-archive-change","archivar cambios","gestión de conflictos","AskUserQuestion","operaciones por lotes","desarrollo de software","herramientas de desarrollo"],"fr":["outils d''IA","openspec-bulk-archive-change","archiver des changements","gestion de conflits","AskUserQuestion","opérations par lots","développement de logiciels","outils de développement"],"de":["KI-Tools","openspec-bulk-archive-change","Änderungen archivieren","Konfliktlösung","AskUserQuestion","Batch-Operationen","Software-Entwicklung","Entwicklertools"],"pt":["openspec-bulk-archive-change","arquivamento em lote","resolução de conflitos de especificação","ferramentas de AI para desenvolvedores","CLI para arquivamento de mudanças","AskUserQuestion","openspec list --json","desenvolvimento de software"],"ru":["openspec-bulk-archive-change","архивация изменений в пакете","решение конфликтов спецификаций","ИИ Агенты для разработчиков","CLI для архивации изменений","AskUserQuestion","openspec list --json","разработка программного обеспечения"],"ar":["openspec-bulk-archive-change","تحديث التغييرات بالجملة","حل конфликات المواصفات","أدوات ذكاء اصطناعي للبرمجة","سطر الأوامر لتحديث التغييرات","AskUserQuestion","openspec list --json","برمجة التطبيقات"]}},"owner":"JanuaryLabs","repo":"deepagents","repoPath":"JanuaryLabs/deepagents","stars":4,"forks":0,"updatedAt":"2026-02-25T11:16:42Z","topics":[],"category":"community","skillMd":{"name":"openspec-bulk-archive-change","description":"Archive multiple completed changes at once. Use when archiving several parallel changes.","version":"1.0","bodyPreview":"Archive multiple completed changes in a single operation.\n\nThis skill allows you to batch-archive changes, handling spec conflicts intelligently by checking the codebase to determine what''s actually implemented.\n\n**Input**: None required (prompts for selection)\n\n**Steps**\n\n1. **Get active changes**\n\n   Run `openspec list --json` to get all active changes.\n\n   If no active changes exist, inform user and stop.\n\n2. **Prompt for change selection**\n\n   Use **AskUserQuestion tool** with multi-select t","body":"Archive multiple completed changes in a single operation.\n\nThis skill allows you to batch-archive changes, handling spec conflicts intelligently by checking the codebase to determine what''s actually implemented.\n\n**Input**: None required (prompts for selection)\n\n**Steps**\n\n1. **Get active changes**\n\n   Run `openspec list --json` to get all active changes.\n\n   If no active changes exist, inform user and stop.\n\n2. **Prompt for change selection**\n\n   Use **AskUserQuestion tool** with multi-select to let user choose changes:\n   - Show each change with its schema\n   - Include an option for \"All changes\"\n   - Allow any number of selections (1+ works, 2+ is the typical use case)\n\n   **IMPORTANT**: Do NOT auto-select. Always let the user choose.\n\n3. **Batch validation - gather status for all selected changes**\n\n   For each selected change, collect:\n\n   a. **Artifact status** - Run `openspec status --change \"<name>\" --json`\n   - Parse `schemaName` and `artifacts` list\n   - Note which artifacts are `done` vs other states\n\n   b. **Task completion** - Read `openspec/changes/<name>/tasks.md`\n   - Count `- [ ]` (incomplete) vs `- [x]` (complete)\n   - If no tasks file exists, note as \"No tasks\"\n\n   c. **Delta specs** - Check `openspec/changes/<name>/specs/` directory\n   - List which capability specs exist\n   - For each, extract requirement names (lines matching `### Requirement: <name>`)\n\n4. **Detect spec conflicts**\n\n   Build a map of `capability -> [changes that touch it]`:\n\n   ```\n   auth -> [change-a, change-b]  <- CONFLICT (2+ changes)\n   api  -> [change-c]            <- OK (only 1 change)\n   ```\n\n   A conflict exists when 2+ selected changes have delta specs for the same capability.\n\n5. **Resolve conflicts agentically**\n\n   **For each conflict**, investigate the codebase:\n\n   a. **Read the delta specs** from each conflicting change to understand what each claims to add/modify\n\n   b. **Search the codebase** for implementation evidence:\n   - Look for code implementing requirements from each delta spec\n   - Check for related files, functions, or tests\n\n   c. **Determine resolution**:\n   - If only one change is actually implemented -> sync that one''s specs\n   - If both implemented -> apply in chronological order (older first, newer overwrites)\n   - If neither implemented -> skip spec sync, warn user\n\n   d. **Record resolution** for each conflict:\n   - Which change''s specs to apply\n   - In what order (if both)\n   - Rationale (what was found in codebase)\n\n6. **Show consolidated status table**\n\n   Display a table summarizing all changes:\n\n   ```\n   | Change               | Artifacts | Tasks | Specs   | Conflicts | Status |\n   |---------------------|-----------|-------|---------|-----------|--------|\n   | schema-management   | Done      | 5/5   | 2 delta | None      | Ready  |\n   | project-config      | Done      | 3/3   | 1 delta | None      | Ready  |\n   | add-oauth           | Done      | 4/4   | 1 delta | auth (!)  | Ready* |\n   | add-verify-skill    | 1 left    | 2/5   | None    | None      | Warn   |\n   ```\n\n   For conflicts, show the resolution:\n\n   ```\n   * Conflict resolution:\n     - auth spec: Will apply add-oauth then add-jwt (both implemented, chronological order)\n   ```\n\n   For incomplete changes, show warnings:\n\n   ```\n   Warnings:\n   - add-verify-skill: 1 incomplete artifact, 3 incomplete tasks\n   ```\n\n7. **Confirm batch operation**\n\n   Use **AskUserQuestion tool** with a single confirmation:\n   - \"Archive N changes?\" with options based on status\n   - Options might include:\n     - \"Archive all N changes\"\n     - \"Archive only N ready changes (skip incomplete)\"\n     - \"Cancel\"\n\n   If there are incomplete changes, make clear they''ll be archived with warnings.\n\n8. **Execute archive for each confirmed change**\n\n   Process changes in the determined order (respecting conflict resolution):\n\n   a. **Sync specs** if delta specs exist:\n   - Use the openspec-sync-specs approach (agent-driven intelligent merge)\n   - For conflicts, apply in resolved order\n   - Track if sync was done\n\n   b. **Perform the archive**:\n\n   ```bash\n   mkdir -p openspec/changes/archive\n   mv openspec/changes/<name> openspec/changes/archive/YYYY-MM-DD-<name>\n   ```\n\n   c. **Track outcome** for each change:\n   - Success: archived successfully\n   - Failed: error during archive (record error)\n   - Skipped: user chose not to archive (if applicable)\n\n9. **Display summary**\n\n   Show final results:\n\n   ```\n   ## Bulk Archive Complete\n\n   Archived 3 changes:\n   - schema-management-cli -> archive/2026-01-19-schema-management-cli/\n   - project-config -> archive/2026-01-19-project-config/\n   - add-oauth -> archive/2026-01-19-add-oauth/\n\n   Skipped 1 change:\n   - add-verify-skill (user chose not to archive incomplete)\n\n   Spec sync summary:\n   - 4 delta specs synced to main specs\n   - 1 conflict resolved (auth: applied both in chronological order)\n   ```\n\n   If any failures:\n\n   ```\n   Failed 1 change:\n   - some-change: Archive directory already exists\n   ```\n\n**Conflict Resolution Examples**\n\nExample 1: Only one implemented\n\n```\nConflict: specs/auth/spec.md touched by [add-oauth, add-jwt]\n\nChecking add-oauth:\n- Delta adds \"OAuth Provider Integration\" requirement\n- Searching codebase... found src/auth/oauth.ts implementing OAuth flow\n\nChecking add-jwt:\n- Delta adds \"JWT Token Handling\" requirement\n- Searching codebase... no JWT implementation found\n\nResolution: Only add-oauth is implemented. Will sync add-oauth specs only.\n```\n\nExample 2: Both implemented\n\n```\nConflict: specs/api/spec.md touched by [add-rest-api, add-graphql]\n\nChecking add-rest-api (created 2026-01-10):\n- Delta adds \"REST Endpoints\" requirement\n- Searching codebase... found src/api/rest.ts\n\nChecking add-graphql (created 2026-01-15):\n- Delta adds \"GraphQL Schema\" requirement\n- Searching codebase... found src/api/graphql.ts\n\nResolution: Both implemented. Will apply add-rest-api specs first,\nthen add-graphql specs (chronological order, newer takes precedence).\n```\n\n**Output On Success**\n\n```\n## Bulk Archive Complete\n\nArchived N changes:\n- <change-1> -> archive/YYYY-MM-DD-<change-1>/\n- <change-2> -> archive/YYYY-MM-DD-<change-2>/\n\nSpec sync summary:\n- N delta specs synced to main specs\n- No conflicts (or: M conflicts resolved)\n```\n\n**Output On Partial Success**\n\n```\n## Bulk Archive Complete (partial)\n\nArchived N changes:\n- <change-1> -> archive/YYYY-MM-DD-<change-1>/\n\nSkipped M changes:\n- <change-2> (user chose not to archive incomplete)\n\nFailed K changes:\n- <change-3>: Archive directory already exists\n```\n\n**Output When No Changes**\n\n```\n## No Changes to Archive\n\nNo active changes found. Use `/opsx:new` to create a new change.\n```\n\n**Guardrails**\n\n- Allow any number of changes (1+ is fine, 2+ is the typical use case)\n- Always prompt for selection, never auto-select\n- Detect spec conflicts early and resolve by checking codebase\n- When both changes are implemented, apply specs in chronological order\n- Skip spec sync only when implementation is missing (warn user)\n- Show clear per-change status before confirming\n- Use single confirmation for entire batch\n- Track and report all outcomes (success/skip/fail)\n- Preserve .openspec.yaml when moving to archive\n- Archive directory target uses current date: YYYY-MM-DD-<name>\n- If archive target exists, fail that change but continue with others\n"},"lastSynced":"2026-03-06T06:57:29.199Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Management Agents needing efficient bulk archiving of completed changes.","zh":"Perfect for Code Management Agents 需要高效的批量归档已完成的更改。","ja":"Code Management Agents が効率的に完了した変更をバルクでアーカイブする必要がある場合に最適です。","ko":"코드 관리 에이전트가 완료된 변경 사항을 효율적으로 일괄적으로 아카이브해야 하는 경우에 적합합니다.","es":"Perfecto para agentes de gestión de código que necesitan un archivo de cambios completados de forma eficiente.","fr":"Parfait pour les agents de gestion de code nécessitant un archivage efficace des modifications terminées.","de":"Perfekt für Code-Management-Agents, die ein effizientes Massenarchivieren abgeschlossener Änderungen benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Código que necessitam de arquivamento em massa eficiente de alterações concluídas.","ru":"Идеально для агентов управления кодом, которым требуется эффективное массовое архивирование завершенных изменений.","ar":"مثالي للوكلاء إدارة الشفرة الذين يحتاجون إلى أرشفة كتلة فعالة للتغييرات المكتملة."},"recommendation":{"en":"Empowers agents to batch-archive changes, handling spec conflicts intelligently by checking the codebase using `openspec list --json`, providing a seamless way to manage large codebases with intelligent conflict resolution.","zh":"赋予代理批量归档更改的能力，通过使用 `openspec list --json` 检查代码库来智能地处理规范冲突，提供一种无缝的方式来管理大型代码库和智能冲突解决。","ja":"エージェントにバッチで変更をアーカイブする能力を与え、`openspec list --json` を使用してコードベースをチェックすることで、仕様の衝突を智能的に処理することで、大規模なコードベースを管理し、智能的な衝突解決を提供するためのシームレスな方法を提供します。","ko":"에이전트에게 일괄적으로 변경 사항을 아카이브하는 능력을 부여하고, `openspec list --json`을 사용하여 코드베이스를 확인함으로써 규격 충돌을 지능적으로 처리하여, 대규모 코드베이스를 관리하고 지능적인 충돌 해결을 제공하는 무결점의 방법을 제공합니다.","es":"Habilita a los agentes a archivar por lotes los cambios, manejando conflictos de especificaciones de forma inteligente verificando el código base con `openspec list --json`, proporcionando una forma fluida de gestionar grandes bases de código con resolución de conflictos inteligente.","fr":"Permet aux agents d''archiver par lots les modifications, en gérant de manière intelligente les conflits de spécifications en vérifiant la base de code à l''aide de `openspec list --json`, offrant un moyen fluide de gérer les grandes bases de code avec une résolution de conflits intelligente.","de":"Ermächtigt Agenten, Änderungen in Chargen zu archivieren, spezifikationsübergreifende Konflikte intelligent durch Überprüfung des Codebasis mit `openspec list --json` zu verwalten, bietet eine nahtlose Möglichkeit, große Codebasen mit intelligenter Konfliktlösung zu verwalten.","pt":"Habilita os agentes a fazerem o arquivamento em lote de alterações, lidando com conflitos de especificação de forma inteligente, verificando o código-fonte usando `openspec list --json`, proporcionando uma maneira sem interrupções de gerenciar grandes bases de código com resolução de conflitos inteligente.","ru":"Наделяет агентов возможностью пакетного архивирования изменений, интеллектуально обрабатывая конфликты спецификаций путем проверки кодовой базы с помощью `openspec list --json`, обеспечивая бесперебойный способ управления большими кодовыми базами с интеллектуальной решением конфликтов.","ar":"يمنح الوكلاء القدرة على أرشفة التغييرات بشكل متوازي، والتعامل مع تضارب المواصفات بذكاء عن طريق فحص قاعدة الشفرة باستخدام `openspec list --json`، وتقديم وسيلة سلسة لإدارة قواعد الشفرة الكبيرة مع حل تضارب ذكي."},"useCases":{"en":["Archiving multiple completed changes in a single operation","Resolving spec conflicts by checking the codebase","Streamlining code management for large codebases"],"zh":["一次性操作中归档多个已完成的更改","通过检查代码库来解决规范冲突","简化大型代码库的代码管理"],"ja":["1 回の操作で複数の完了した変更をアーカイブする","コードベースをチェックすることで仕様の冲突を解決する","大規模なコードベースのコード管理を効率化する"],"ko":["한 번의 작업으로 여러 개의 완료된 변경 사항을 아카이브하는 것","코드베이스를 확인하여 규격 충돌을 해결하는 것","대규모 코드베이스의 코드 관리를 간소화하는 것"],"es":["Archivo de varios cambios completados en una sola operación","Resolución de conflictos de especificaciones verificando la base de código","Optimización de la gestión de código para grandes bases de código"],"fr":["Archivage de plusieurs modifications terminées en une seule opération","Résolution de conflits de spécifications en vérifiant la base de code","Optimisation de la gestion de code pour les grandes bases de code"],"de":["Archivieren mehrerer abgeschlossener Änderungen in einer einzigen Operation","Auflösung von Spezifikationskonflikten durch Überprüfung der Codebasis","Optimierung der Codeverwaltung für große Codebasen"],"pt":["Arquivar várias alterações concluídas em uma única operação","Resolver conflitos de especificação verificando a base de código","Otimizar a gestão de código para grandes bases de código"],"ru":["Архивировать несколько завершенных изменений в одной операции","Разрешить конфликты спецификаций, проверив кодовую базу","Оптимизировать управление кодом для крупных кодовых баз"],"ar":["أرشفة عدة تغييرات مكتملة في عملية واحدة","حل تضارب المواصفات من خلال فحص قاعدة الشفرة","تبسيط إدارة الشفرة لقواعد الشفرة الكبيرة"]},"limitations":{"en":["Requires `openspec` command-line tool","No active changes exist, stops the archiving process"],"zh":["需要 `openspec` 命令行工具","如果没有活动的更改，则停止归档过程"],"ja":["`openspec` コマンドラインツールが必要","アクティブな変更がない場合、アーカイブ処理を停止する"],"ko":["`openspec` 명령줄 도구가 필요함","활성 변경 사항이 없으면 아카이브 처리를 중단함"],"es":["Requiere la herramienta de línea de comandos `openspec`","No existen cambios activos, se detiene el proceso de archivado"],"fr":["Nécessite l''outil de ligne de commande `openspec`","Aucun changement actif n''existe, le processus d''archivage s''arrête"],"de":["Benötigt das `openspec`-Kommandozeilen-Tool","Es gibt keine aktiven Änderungen, der Archivierungsprozess wird gestoppt"],"pt":["Requer a ferramenta de linha de comando `openspec`","Não existem alterações ativas, para o processo de arquivamento"],"ru":["Требуется утилита командной строки `openspec`","Не существует активных изменений, останавливает процесс архивирования"],"ar":["يتطلب أداة سطر الأوامر `openspec`","لا توجد تغييرات نشطة، يتوقف عملية الأرشفة"]},"version":4},"contentHash":"f42ab9c99f56c5646d109e7fe94407c25e847ea12c8b43facc8ea42ddc488c72","qualityScore":50}');
