INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ElementsAI-Dev/Cognia/convex', 'convex', 'ElementsAI-Dev', 'Cognia', 'community', 'convex ElementsAI-Dev Cognia community Convex is a development skill for building scalable applications. It benefits developers by providing a robust framework for core development, including functions, schema validation, and realtime capabilities. Convex 是一个用于构建实时应用的开发平台，提供函数、模式、实时和 HTTP 动作等核心开发技能 Convex はリアクティブなアプリケーションを構築するための開発プラットフォームで、関数、スキーマ、リアルタイム、HTTP アクションなどのコア開発スキルを提供します Convex는 실시간 애플리케이션을 개발하기 위한 플랫폼으로 함수, 스키마, 실시간 및 HTTP 액션 등의 핵심 개발 기술을 제공합니다 Convex es un conjunto de habilidades para el desarrollo de aplicaciones reactivas, incluyendo funciones, esquemas y tiempo real Convex est un ensemble de compétences pour le développement d''applications réactives, y compris des fonctions, des schémas et du temps réel Convex ist eine Sammlung von Fähigkeiten für die Entwicklung reaktiver Anwendungen, einschließlich Funktionen, Schemata und Echtzeit O Convex é uma plataforma para desenvolver aplicações reativas. Use functions, schema, realtime e HTTP actions para criar soluções personalizadas. Convex — это платформа для разработки реактивных приложений. Используйте функции, схему, реалтайм и HTTP-действия для создания индивидуальных решений. Convex هي منصة لتطوير التطبيقات الردة الفعالة. استخدم Functions و Schema و Realtime و HTTP Actions لإنشاء حلول مخصصة. how to use convex convex development guide convex alternative convex vs graphql convex install convex setup guide what is convex convex core development convex schema validation Convex 开发 实时应用 函数开发 模式定义 HTTP 动作 Convex 教程 AI エージェント Writing queries, mutations, and actions using `/convex-functions` command Defining database schemas and validators with `/convex-schema-validator` Building reactive subscriptions using `/convex-realtime` Creating webhooks and HTTP endpoints with `/convex-http-actions` Convex is a development framework that enables developers to build scalable applications using specific skills for detailed guidance, including core development, schema validation, and realtime capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fkoschi/grind-it/openspec-continue-change', 'community', 'fkoschi', 'grind-it', 'fkoschi/grind-it', 'openspec-continue-change', 2, 0, 50, '2026-02-24T12:05:19Z', '2026-03-07T01:53:40.065Z', 'd0fbc067936de6bea93e611b962d6fa0fd58bcd47b1fe8ee529fa0c97c1afd9d', '{"id":"fkoschi/grind-it/openspec-continue-change","name":"openspec-continue-change","description":{"en":"The openspec-continue-change skill allows developers to continue working on a change by creating the next artifact, streamlining their workflow. It benefits developers by providing an efficient way to manage changes.","zh":"openspec-continue-change 技术允许您继续更改工作流，使用 openspec list 和 AskUserQuestion 工具","ja":"openspec-continue-change 技術は、openspec list と AskUserQuestion ツールを使用して変更を続行することができます","ko":"openspec-continue-change 기술을 사용하여 openspec list 및 AskUserQuestion 도구로 변경을 계속할 수 있습니다","es":"openspec-continue-change permite a los desarrolladores continuar trabajando en cambios mediante la creación de artefactos. Utiliza la herramienta AskUserQuestion para seleccionar cambios.","fr":"openspec-continue-change permet aux développeurs de poursuivre le travail sur les modifications en créant des artefacts. Il utilise l''outil AskUserQuestion pour sélectionner les modifications.","de":"openspec-continue-change ermöglicht es Entwicklern, Änderungen fortzusetzen, indem sie Artefakte erstellen. Es verwendet das AskUserQuestion-Tool, um Änderungen auszuwählen.","pt":"O openspec-continue-change é uma ferramenta que permite criar artefatos facilmente. Ele usa comandos CLI e ferramentas de usuário para melhorar a produtividade.","ru":"openspec-continue-change — это инструмент, который позволяет создавать артефакты легко. Он использует команды CLI и инструменты пользователя для повышения производительности.","ar":"openspec-continue-change هو أداة تمكنك من إنشاء الملفات المطلوبة بسهولة. يستخدم أوامر CLI وأدوات المستخدم لتحسين الإنتاجية."},"seo":{"title":{"en":"openspec-continue-change: Streamline Change Management | ...","zh":"openspec-continue-change 设置指南：继续更改工作流","ja":"openspec-continue-change のベストプラクティス：変更の続行","ko":"openspec-continue-change 설정 가이드: 변경 계속 작업","es":"Guía de configuración de openspec-continue-change para de...","fr":"Configurer openspec-continue-change : Guide pour les déve...","de":"Einrichtungsanleitung für openspec-continue-change: Entwi...","pt":"Guia de Configuração do openspec-continue-change para Des...","ru":"Настройка openspec-continue-change: Руководство для разра...","ar":"دليل إعداد openspec-continue-change لل مطورين باستخدام أد..."},"description":{"en":"Discover how openspec-continue-change simplifies workflow by creating the next artifact in a change. Learn how to use it now and boost your development effic...","zh":"了解 openspec-continue-change 技术，使用 openspec list 和 AskUserQuestion 工具继续更改工作流","ja":"openspec-continue-change 技術を使用して、openspec list と AskUserQuestion ツールで変更を続行する方法","ko":"openspec-continue-change 기술을 사용하여 openspec list 및 AskUserQuestion 도구로 변경을 계속하는 방법","es":"Aprende a utilizar openspec-continue-change para continuar trabajando en cambios con facilidad. Descubre cómo crear artefactos y seleccionar cambios con la h...","fr":"Découvrez comment utiliser openspec-continue-change pour poursuivre le travail sur les modifications avec facilité. Apprenez à créer des artefacts et à sélec...","de":"Erfahren Sie, wie Sie openspec-continue-change verwenden, um Änderungen fortzusetzen. Entdecken Sie, wie Sie Artefakte erstellen und Änderungen mit dem AskUs...","pt":"Aprenda a usar o openspec-continue-change para criar artefatos com facilidade. Descubra como integrar comandos CLI e ferramentas de usuário para melhorar a p...","ru":"Узнайте, как использовать openspec-continue-change для создания артефактов. Откройте для себя, как интегрировать команды CLI и инструменты пользователя для п...","ar":"تعلم كيفية استخدام openspec-continue-change لإنشاء الملفات المطلوبة بسهولة. اكتشف كيفية دمج أوامر CLI وأدوات المستخدم لتحسين الإنتاجية باستخدام أدوات الذكاء ..."},"definition":{"en":"openspec-continue-change is a skill that enables developers to continue working on a change by creating the next artifact, using commands like openspec list --json to get available changes.","zh":"openspec-continue-change 是一种技术，允许您继续更改工作流","ja":"openspec-continue-change は、変更を続行するための技術です","ko":"openspec-continue-change 는 변경을 계속하는 기술입니다","es":"openspec-continue-change es una habilidad que permite a los desarrolladores continuar trabajando en cambios mediante la creación de artefactos.","fr":"openspec-continue-change est une compétence qui permet aux développeurs de poursuivre le travail sur les modifications en créant des artefacts.","de":"openspec-continue-change ist eine Fähigkeit, die es Entwicklern ermöglicht, Änderungen fortzusetzen, indem sie Artefakte erstellen.","pt":"O openspec-continue-change é uma ferramenta de linha de comando que permite continuar trabalhando em uma alteração.","ru":"openspec-continue-change — это команда CLI, которая позволяет продолжить работу над изменением.","ar":"openspec-continue-change هو أمر سطر أوامر يسمح بمواصلة العمل على تغيير معين."},"features":{"en":["Runs openspec list --json to get available changes sorted by most recently modified","Utilizes the AskUserQuestion tool to let users select which change to work on","Presents the top 3-5 available changes for user selection","Optionally accepts a change name as input","Infers the change name from conversation context if not provided","Prompts for selection if the change name is vague or ambiguous"],"zh":["使用 openspec list 获取可用更改","使用 AskUserQuestion 工具让用户选择要继续的更改","支持对最近修改的更改进行排序","可选地指定更改名称","如果未指定更改名称，则会提示用户选择"],"ja":["openspec list を使用して利用可能な変更を取得","AskUserQuestion ツールを使用してユーザーに続行する変更を選択させる","最近変更された変更の並び替えをサポート","変更名をオプションで指定","変更名が指定されていない場合、ユーザーに選択を促す"],"ko":["openspec list를 사용하여 사용 가능한 변경을 가져옴","AskUserQuestion 도구를 사용하여 사용자가 계속할 변경을 선택하도록 함","최근 수정된 변경의 정렬을 지원","변경 이름을 선택적으로 지정","변경 이름이 지정되지 않은 경우 사용자에게 선택을 요청"],"es":["Creación de artefactos para continuar trabajando en cambios","Utiliza la herramienta AskUserQuestion para seleccionar cambios","Ejecuta el comando `openspec list --json` para obtener cambios disponibles","Presenta los 3 cambios más recientes modificados","Permite a los desarrolladores seleccionar el cambio en el que trabajar","Integra con la línea de comandos (CLI) para una mayor flexibilidad"],"fr":["Création d''artefacts pour poursuivre le travail sur les modifications","Utilise l''outil AskUserQuestion pour sélectionner les modifications","Exécute la commande `openspec list --json` pour obtenir les modifications disponibles","Présente les 3 modifications les plus récemment modifiées","Permet aux développeurs de sélectionner la modification sur laquelle travailler","Intègre avec la ligne de commande (CLI) pour une plus grande flexibilité"],"de":["Erstellung von Artefakten, um Änderungen fortzusetzen","Verwenden des AskUserQuestion-Tools, um Änderungen auszuwählen","Ausführen des Befehls `openspec list --json`, um verfügbare Änderungen zu erhalten","Präsentiert die 3 zuletzt geänderten Änderungen","Ermöglicht es Entwicklern, die Änderung auszuwählen, an der sie arbeiten","Integriert mit der Befehlszeile (CLI) für eine größere Flexibilität"],"pt":["Criação de artefatos facilmente","Integração com comandos CLI","Uso da ferramenta AskUserQuestion para seleção de alterações","Listagem de alterações recentes com openspec list --json","Suporte à seleção de alterações por nome ou contexto de conversa"],"ru":["Создание артефактов легко","Интеграция с командами CLI","Использование инструмента AskUserQuestion для выбора изменений","Список недавних изменений с openspec list --json","Поддержка выбора изменений по имени или контексту разговора с помощью ИИ Агентов"],"ar":["إنشاء الملفات المطلوبة بسهولة","دمج أوامر CLI","استخدام أداة AskUserQuestion لاختيار التغييرات","قائمة التغييرات الأخيرة مع openspec list --json","دعم اختيار التغييرات حسب الاسم أو سياق المحادثة باستخدام أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use openspec-continue-change","openspec-continue-change setup guide","openspec-continue-change alternative","openspec-continue-change vs git","openspec-continue-change install","what is openspec-continue-change","openspec-continue-change tutorial","openspec-continue-change best practices"],"zh":["openspec-continue-change","AIエージェント","openspec list","AskUserQuestion","继续更改工作流","CLI 技术"],"ja":["openspec-continue-change","AIエージェント","openspec list","AskUserQuestion","変更を続行する","CLI 技術"],"ko":["openspec-continue-change","AI 에이전트","openspec list","AskUserQuestion","변경을 계속하는 방법","CLI 기술"],"es":["openspec-continue-change","desarrollo de software","herramientas de desarrollo","AskUserQuestion","CLI","creación de artefactos","selección de cambios","openspec list --json","desarrolladores de software"],"fr":["openspec-continue-change","développement de logiciels","outils de développement","AskUserQuestion","CLI","création d''artefacts","sélection de modifications","openspec list --json","développeurs de logiciels"],"de":["openspec-continue-change","Softwareentwicklung","Entwicklungstools","AskUserQuestion","CLI","Erstellung von Artefakten","Auswahl von Änderungen","openspec list --json","Softwareentwickler"],"pt":["openspec-continue-change","CLI","ferramentas de desenvolvimento","produtividade para desenvolvedores","guias de configuração","comandos de linha de comando","ferramentas de usuário","AskUserQuestion"],"ru":["openspec-continue-change","CLI","инструменты разработки","производительность для разработчиков","руководства по настройке","команды командной строки","инструменты пользователя","AskUserQuestion","ИИ Агенты"],"ar":["openspec-continue-change","CLI","أدوات التطوير","الإنتاجية للمطورين","دلائل الإعداد","أوامر سطر الأوامر","أدوات المستخدم","AskUserQuestion","أدوات الذكاء الاصطناعي"]}},"owner":"fkoschi","repo":"grind-it","repoPath":"fkoschi/grind-it","stars":2,"forks":0,"updatedAt":"2026-02-24T12:05:19Z","topics":[],"category":"community","skillMd":{"name":"openspec-continue-change","description":"Continue working on an OpenSpec change by creating the next artifact. Use when the user wants to progress their change, create the next artifact, or continue their workflow.","version":"1.0","bodyPreview":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-","body":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-4 most recently modified changes as options, showing:\n   - Change name\n   - Schema (from `schema` field if present, otherwise \"spec-driven\")\n   - Status (e.g., \"0/5 tasks\", \"complete\", \"no tasks\")\n   - How recently it was modified (from `lastModified` field)\n\n   Mark the most recently modified change as \"(Recommended)\" since it''s likely what the user wants to continue.\n\n   **IMPORTANT**: Do NOT guess or auto-select a change. Always let the user choose.\n\n2. **Check current status**\n\n   ```bash\n   openspec status --change \"<name>\" --json\n   ```\n\n   Parse the JSON to understand current state. The response includes:\n   - `schemaName`: The workflow schema being used (e.g., \"spec-driven\")\n   - `artifacts`: Array of artifacts with their status (\"done\", \"ready\", \"blocked\")\n   - `isComplete`: Boolean indicating if all artifacts are complete\n\n3. **Act based on status**:\n\n   ***\n\n   **If all artifacts are complete (`isComplete: true`)**:\n   - Congratulate the user\n   - Show final status including the schema used\n   - Suggest: \"All artifacts created! You can now implement this change or archive it.\"\n   - STOP\n\n   ***\n\n   **If artifacts are ready to create** (status shows artifacts with `status: \"ready\"`):\n   - Pick the FIRST artifact with `status: \"ready\"` from the status output\n   - Get its instructions:\n     ```bash\n     openspec instructions <artifact-id> --change \"<name>\" --json\n     ```\n   - Parse the JSON. The key fields are:\n     - `context`: Project background (constraints for you - do NOT include in output)\n     - `rules`: Artifact-specific rules (constraints for you - do NOT include in output)\n     - `template`: The structure to use for your output file\n     - `instruction`: Schema-specific guidance\n     - `outputPath`: Where to write the artifact\n     - `dependencies`: Completed artifacts to read for context\n   - **Create the artifact file**:\n     - Read any completed dependency files for context\n     - Use `template` as the structure - fill in its sections\n     - Apply `context` and `rules` as constraints when writing - but do NOT copy them into the file\n     - Write to the output path specified in instructions\n   - Show what was created and what''s now unlocked\n   - STOP after creating ONE artifact\n\n   ***\n\n   **If no artifacts are ready (all blocked)**:\n   - This shouldn''t happen with a valid schema\n   - Show status and suggest checking for issues\n\n4. **After creating an artifact, show progress**\n   ```bash\n   openspec status --change \"<name>\"\n   ```\n\n**Output**\n\nAfter each invocation, show:\n\n- Which artifact was created\n- Schema workflow being used\n- Current progress (N/M complete)\n- What artifacts are now unlocked\n- Prompt: \"Want to continue? Just ask me to continue or tell me what to do next.\"\n\n**Artifact Creation Guidelines**\n\nThe artifact types and their purpose depend on the schema. Use the `instruction` field from the instructions output to understand what to create.\n\nCommon artifact patterns:\n\n**spec-driven schema** (proposal → specs → design → tasks):\n\n- **proposal.md**: Ask user about the change if not clear. Fill in Why, What Changes, Capabilities, Impact.\n  - The Capabilities section is critical - each capability listed will need a spec file.\n- **specs/<capability>/spec.md**: Create one spec per capability listed in the proposal''s Capabilities section (use the capability name, not the change name).\n- **design.md**: Document technical decisions, architecture, and implementation approach.\n- **tasks.md**: Break down implementation into checkboxed tasks.\n\nFor other schemas, follow the `instruction` field from the CLI output.\n\n**Guardrails**\n\n- Create ONE artifact per invocation\n- Always read dependency artifacts before creating a new one\n- Never skip artifacts or create out of order\n- If context is unclear, ask the user before creating\n- Verify the artifact file exists after writing before marking progress\n- Use the schema''s artifact sequence, don''t assume specific artifact names\n- **IMPORTANT**: `context` and `rules` are constraints for YOU, not content for the file\n  - Do NOT copy `<context>`, `<rules>`, `<project_context>` blocks into the artifact\n  - These guide what you write, but should never appear in the output\n"},"lastSynced":"2026-03-07T01:53:40.065Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined change management and workflow automation.","zh":"非常适合需要简化变更管理和工作流自动化的开发代理。","ja":"開発エージェントが変更管理とワークフロー自動化を効率化する必要がある場合に最適です。","ko":"변경 관리와 워크플로 자동화를 단순화해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión de cambios y automatización de flujos de trabajo simplificada.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion des changements et d''une automation des flux de travail simplifiées.","de":"Perfekt für Entwicklungsmittel, die eine vereinfachte Änderungsverwaltung und Workflow-Automatisierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de alterações e automação de fluxo de trabalho simplificados.","ru":"Идеально подходит для агентов разработки, которым необходим упрощенный менеджмент изменений и автоматизация рабочих процессов.","ar":"مثالي لعمليات التطوير التي تحتاج إلى إدارة مُبسّرة للتغييرات وتوضيح سير العمل."},"recommendation":{"en":"Empowers agents to efficiently manage changes by creating the next artifact, utilizing the `openspec list --json` command and the AskUserQuestion tool for seamless user interaction, and supporting JSON data formats for robust integration.","zh":"通过创建下一个工件、使用 `openspec list --json` 命令和 AskUserQuestion 工具进行无缝的用户交互以及支持 JSON 数据格式以实现强大的集成，从而使代理能够高效地管理更改。","ja":"次のアーティファクトを作成し、`openspec list --json` コマンドと AskUserQuestion ツールを使用してシームレスなユーザーインタラクションを行い、JSON データ形式をサポートして堅牢な統合を実現することで、エージェントが効率的に変更を管理できるようにします。","ko":"다음 아티팩트를 생성하고 `openspec list --json` 명령어와 AskUserQuestion 툴을 이용하여 무결점의 사용자 상호작용을 제공하며 JSON 데이터 형식을 지원하여 강력한 통합을 제공함으로써 에이전트가 효율적으로 변경을 관리할 수 있도록 합니다.","es":"Habilita a los agentes a gestionar eficientemente los cambios creando el próximo artefacto, utilizando el comando `openspec list --json` y la herramienta AskUserQuestion para una interacción del usuario sin problemas, y admitiendo formatos de datos JSON para una integración robusta.","fr":"Permet aux agents de gérer efficacement les changements en créant l''artefact suivant, en utilisant la commande `openspec list --json` et l''outil AskUserQuestion pour une interaction utilisateur transparente, et en prenant en charge les formats de données JSON pour une intégration robuste.","de":"Ermöglicht es Agenten, Änderungen effizient zu verwalten, indem sie das nächste Artefakt erstellen, den Befehl `openspec list --json` und das Tool AskUserQuestion für eine nahtlose Benutzerinteraktion verwenden und JSON-Datenformate für eine robuste Integration unterstützen.","pt":"Habilita os agentes a gerenciar alterações de forma eficiente, criando o próximo artefato, utilizando o comando `openspec list --json` e a ferramenta AskUserQuestion para interação do usuário sem interrupções, e suportando formatos de dados JSON para integração robusta.","ru":"Наделяет агентов возможностью эффективно управлять изменениями, создавая следующий артефакт, используя команду `openspec list --json` и инструмент AskUserQuestion для бесперебойного взаимодействия с пользователем, и поддерживая форматы данных JSON для прочной интеграции.","ar":"تمكّن الوكلاء من إدارة التغييرات بفعالية من خلال إنشاء الملف القادم، واستخدام الأمر `openspec list --json` وأداة AskUserQuestion من أجل تفاعل مستخدم بدون انقطاع، ودعم تنسيقات بيانات JSON من أجل التكامل القوي."},"useCases":{"en":["Continuing work on a specific change by creating the next artifact","Automating change management workflows using the `openspec` command","Streamlining developer workflows by inferring change names from conversation context"],"zh":["通过创建下一个工件继续特定更改的工作","使用 `openspec` 命令自动化更改管理工作流","通过从对话上下文推断更改名称来简化开发者工作流"],"ja":["次のアーティファクトを作成して特定の変更の作業を続ける","`openspec` コマンドを使用して変更管理ワークフローを自動化する","会話のコンテキストから変更名を推測して開発者のワークフローを最適化する"],"ko":["다음 아티팩트를 생성하여 특정 변경의 작업을 계속하는こと","`openspec` 명령어를 사용하여 변경 관리 워크플ロー 자동화","대화의 맥락에서 변경 이름을 추론하여 개발자의 워크플ロー 최적화"],"es":["Continuar trabajando en un cambio específico creando el próximo artefacto","Automatizar flujos de trabajo de gestión de cambios utilizando el comando `openspec`","Optimizar flujos de trabajo de desarrolladores inferiendo nombres de cambios del contexto de conversación"],"fr":["Poursuivre un travail sur un changement spécifique en créant l''artefact suivant","Automatiser les flux de travail de gestion des changements en utilisant la commande `openspec`","Optimiser les flux de travail des développeurs en déduisant les noms de changements du contexte de conversation"],"de":["Weiterarbeit an einem bestimmten Change durch Erstellung des nächsten Artefakts","Automatisierung von Änderungsverwaltungs-Workflows mit dem `openspec`-Befehl","Optimierung von Entwickler-Workflows durch Ableitung von Änderungsnamen aus dem Konversationskontext"],"pt":["Continuar o trabalho em uma alteração específica, criando o próximo artefato","Automatizar fluxos de trabalho de gerenciamento de alterações usando o comando `openspec`","Simplificar fluxos de trabalho de desenvolvedores, inferindo nomes de alterações do contexto da conversa"],"ru":["Продолжить работу над конкретным изменением, создав следующий артефакт","Автоматизировать рабочие процессы управления изменениями, используя команду `openspec`","Упростить рабочие процессы разработчиков, выводя имена изменений из контекста разговора"],"ar":["متابعة العمل على تغيير محدد من خلال إنشاء الملف التالي","توفير سير عمل إدارة التغييرات باستخدام الأمر `openspec`","تبسيط سير عمل المطورين من خلال استنتاج أسماء التغييرات من سياق المحادثة"]},"limitations":{"en":["Requires `openspec` command-line tool installation","Needs access to conversation context for change name inference","Limited to selecting from available changes sorted by most recently modified"],"zh":["需要安装 `openspec` 命令行工具","需要访问对话上下文以推断更改名称","仅限从最近修改的更改中选择"],"ja":["`openspec` コマンドラインツールのインストールが必要","変更名の推測に会話のコンテキストへのアクセスが必要","最も最近変更された変更から選択することのみ"],"ko":["`openspec` 명령줄 툴 설치가 필요","변경 이름 추론을 위해 대화 맥락에 대한 접근이 필요","최근 수정된 변경에서 선택하는 것만限함"],"es":["Requiere la instalación de la herramienta de línea de comandos `openspec`","Necesita acceso al contexto de conversación para inferir el nombre del cambio","Limitado a la selección de cambios disponibles ordenados por más recientemente modificados"],"fr":["Nécessite l''installation de l''outil de ligne de commande `openspec`","A besoin d''un accès au contexte de conversation pour déduire le nom du changement","Limité à la sélection des changements disponibles triés par les plus récemment modifiés"],"de":["Benötigt die Installation des `openspec`-Befehlszeilen-Tools","Benötigt Zugriff auf den Konversationskontext, um den Änderungsnamen abzuleiten","Begrenzt auf die Auswahl verfügbarer Änderungen, sortiert nach zuletzt geändert"],"pt":["Requer instalação da ferramenta de linha de comando `openspec`","Necessita acesso ao contexto da conversa para inferência do nome da alteração","Limitado à seleção de alterações disponíveis, classificadas por mais recentemente modificadas"],"ru":["Требует установки командной строки инструмента `openspec`","Требует доступа к контексту разговора для вывода имени изменения","Ограничен выбором доступных изменений, отсортированных по наиболее недавно измененным"],"ar":["يتطلب تثبيت أداة سطر الأوامر `openspec`","يحتاج إلى الوصول إلى سياق المحادثة لاستنتاج اسم التغيير","محدود بالاختيار من التغييرات المتاحة، المصنفة حسب أحدث تعديلات"]},"version":4},"contentHash":"d0fbc067936de6bea93e611b962d6fa0fd58bcd47b1fe8ee529fa0c97c1afd9d","qualityScore":50}');
