INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ngocsangyem/ngocsangyem.dev/ck:skill-creator', 'ck:skill-creator', 'ngocsangyem', 'ngocsangyem.dev', 'community', 'ck:skill-creator ngocsangyem ngocsangyem.dev community gem html jekyll ruby The ck:skill-creator skill enables developers to create effective, benchmark-optimized Claude skills using practical instructions and progressive disclosure. It benefits developers working with Ruby, HTML, and Jekyll. CK:SKILL-CREATOR是一个用于创建高效AI技能的工具，使用Ruby、Jekyll和进阶披露技术 CK:SKILL-CREATORは、高性能のAIエージェントを作成するためのツールです CK:SKILL-CREATOR는 루비, Jekyll 및 진행식 공개 기술을 사용하여 최적화된 AI 스킬을 생성하는 도구입니다 ck:skill-creator es una habilidad para crear instrucciones prácticas para agentes de IA, utilizando tecnologías como Ruby, Jekyll y HTML ck:skill-creator est une compétence pour créer des instructions pratiques pour les outils d''IA, en utilisant des technologies telles que Ruby, Jekyll et HTML ck:skill-creator ist eine Fähigkeit, um praktische Anweisungen für KI-Tools zu erstellen, indem Sie Technologien wie Ruby, Jekyll und HTML verwenden O ck:skill-creator é uma ferramenta para criar habilidades práticas e otimizadas para Claude, utilizando progressive disclosure e recursos embutidos ck:skill-creator - это инструмент для создания практических и оптимизированных навыков для Claude, используя прогрессивное раскрытие и встроенные ресурсы для ИИ Агентов _ck:skill-creator هو أداة لإنشاء مهارات عملية ومحسنة لبرنامج Claude، باستخدام الكشف التدريجي والموارد المضمنة لأدوات الذكاء الاصطناعي how to use ck:skill-creator ck:skill-creator setup guide ck:skill-creator alternative ck:skill-creator vs Jekyll what is ck:skill-creator ck:skill-creator install ck:skill-creator for Ruby developers progressive disclosure in AI agents benchmark-optimized Claude skills ck:skill-creator documentation CK:SKILL-CREATOR AI技能创建 Ruby Jekyll 进阶披露 Gem HTML SKILL.md AI工具 AI开发 Utilizes progressive disclosure for efficient skill development Supports metadata quality-based automatic skill activation Teaches Claude how to perform tasks using practical instructions Works with Ruby, HTML, and Jekyll for versatile development Employs SKILL.md and bundled resources for comprehensive skill creation Enforces character limits for descriptions, such as <200 characters ck:skill-creator is a skill that facilitates the creation of effective Claude skills using progressive disclosure, focusing on practical instructions rather than documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ruan-cat/11comm/openspec-continue-change', 'community', 'ruan-cat', '11comm', 'ruan-cat/11comm', 'openspec-continue-change', 2, 0, 50, '2026-02-28T13:36:52Z', '2026-03-07T01:53:37.103Z', 'd0fbc067936de6bea93e611b962d6fa0fd58bcd47b1fe8ee529fa0c97c1afd9d', '{"id":"ruan-cat/11comm/openspec-continue-change","name":"openspec-continue-change","description":{"en":"The openspec-continue-change skill enables AI agents to continue working on a change by creating the next artifact, optionally specifying a change name or inferring it from conversation context. This skill benefits developers working on complex projects.","zh":"openspec-continue-change是一个用于继续工作的改变，通过创建下一个工件。它支持通过运行openspec list --json来获取可用改变，并使用AskUserQuestion工具让用户选择要工作的改变","ja":"openspec-continue-changeは、次のアーティファクトを作成することで変更を続けるために使用されます。openspec list --jsonを実行して利用可能な変更を取得し、AskUserQuestionツールを使用してユーザーが作業する変更を選択することをサポート","ko":"openspec-continue-change는 다음 아티팩트를 생성하여 변경을 계속하는 데 사용됩니다. openspec list --json을 실행하여 사용 가능한 변경을 가져오고, AskUserQuestion 도구를 사용하여 사용자가 작업할 변경을 선택","es":"openspec-continue-change es una habilidad que permite a los desarrolladores continuar trabajando en cambios mediante la creación del siguiente artefacto","fr":"openspec-continue-change est une compétence qui permet aux développeurs de continuer à travailler sur des changements en créant le prochain artefact","de":"openspec-continue-change ist eine Fähigkeit, die es Entwicklern ermöglicht, an Änderungen weiterzuarbeiten, indem sie das nächste Artefakt erstellen","pt":"O openspec-continue-change é uma ferramenta que permite criar o próximo artefato de mudança de forma eficiente, com recursos como a lista de mudanças recentes e a seleção de mudanças por meio da ferramenta AskUserQuestion.","ru":"Openspec-continue-change - это инструмент, который позволяет создавать следующий артефакт изменений эффективно, с функциями, такими как список最近их изменений и выбор изменений с помощью инструмента AskUserQuestion.","ar":"openspec-continue-change هو أداة تمكنك من إنشاء الملف المرفق التالي للتغيير بفعالية، مع ميزات مثل قائمة التغييرات الأخيرة واختيار التغييرات بواسطة أداة AskUserQuestion."},"seo":{"title":{"en":"openspec-continue-change: Streamlined Change Management f...","zh":"openspec-continue-change Setup Guide - AI智能工具","ja":"openspec-continue-change セットアップガイド - AIエージェント","ko":"openspec-continue-change 설정 가이드 - AI 에이전트","es":"Guía de configuración de openspec-continue-change para de...","fr":"Configurer openspec-continue-change : Guide pour les déve...","de":"Einrichtungsanleitung für openspec-continue-change: Entwi...","pt":"Guia de Configuração do openspec-continue-change para Des...","ru":"Настройка openspec-continue-change: Руководство для Разра...","ar":"إعداد openspec-continue-change للاستخدام مع أدوات الإي ال..."},"description":{"en":"Discover how openspec-continue-change simplifies change management. Learn to create the next artifact with ease and explore its features now!","zh":"了解openspec-continue-change的技术细节和设置步骤，实现智能社区项目的开发","ja":"openspec-continue-changeの技術的詳細と設定手順を学び、スマートコミュニティプロジェクトの開発を実現","ko":"openspec-continue-change의 기술적 세부 사항과 설정 단계를 알아보고, 지능형 커뮤니티 프로젝트의 개발을 구현","es":"Aprende a utilizar openspec-continue-change para continuar trabajando en cambios con herramientas como AskUserQuestion y CLI","fr":"Découvrez comment utiliser openspec-continue-change pour continuer à travailler sur des changements avec des outils comme AskUserQuestion et CLI","de":"Erfahren Sie, wie Sie openspec-continue-change verwenden, um an Änderungen mit Tools wie AskUserQuestion und CLI weiterzuarbeiten","pt":"Aprenda a usar o openspec-continue-change para criar artefatos de mudança de forma eficiente, com dicas e práticas recomendadas para desenvolvedores","ru":"Узнайте, как использовать openspec-continue-change для создания артефактов изменений, с советами и рекомендациями для разработчиков ИИ Агентов","ar":"تعرف على كيفية استخدام openspec-continue-change لإنشاء الملفات المرفقة للتغيير بفعالية، مع نصائح وأفضل الممارسات لمطوري أدوات الإي الأجنت"},"definition":{"en":"openspec-continue-change is a skill that allows AI agents to manage changes efficiently by creating subsequent artifacts, utilizing commands like openspec list --json and tools like AskUserQuestion.","zh":"openspec-continue-change是一个AI智能工具，用于继续工作的改变","ja":"openspec-continue-changeは、変更を続けるために使用されるAIエージェント","ko":"openspec-continue-change는 변경을 계속하는 데 사용되는 AI 에이전트","es":"openspec-continue-change es una herramienta de AI que permite a los desarrolladores continuar trabajando en cambios","fr":"openspec-continue-change est un outil d''IA qui permet aux développeurs de continuer à travailler sur des changements","de":"openspec-continue-change ist ein AI-Tool, das es Entwicklern ermöglicht, an Änderungen weiterzuarbeiten","pt":"O openspec-continue-change é uma ferramenta de linha de comando que permite continuar trabalhando em uma mudança criando o próximo artefato","ru":"Openspec-continue-change - это инструмент командной строки, который позволяет продолжать работу над изменением, создавая следующий артефакт","ar":"openspec-continue-change هو أداة سطر الأوامر التي تمكنك من الاستمرار في العمل على تغيير من خلال إنشاء الملف المرفق التالي"},"features":{"en":["Runs openspec list --json to retrieve available changes sorted by most recently modified","Utilizes the AskUserQuestion tool for user selection of changes","Presents the top 3-5 changes for user selection","Optionally accepts a change name as input","Infers change name from conversation context if omitted","Prompts for selection if change name is vague or ambiguous"],"zh":["支持通过运行openspec list --json来获取可用改变","使用AskUserQuestion工具让用户选择要工作的改变","创建下一个工件","支持对话上下文推断改变名称","如果改变名称不明确，会提示用户选择"],"ja":["openspec list --jsonを実行して利用可能な変更を取得","AskUserQuestionツールを使用してユーザーが作業する変更を選択","次のアーティファクトを作成","会話のコンテキストから変更名を推測","変更名が不明確な場合、ユーザーに選択を促す"],"ko":["openspec list --json을 실행하여 사용 가능한 변경을 가져옴","AskUserQuestion 도구를 사용하여 사용자가 작업할 변경을 선택","다음 아티팩트를 생성","대화 상텍스트에서 변경 이름을 추론","변경 이름이 불분명한 경우 사용자에게 선택을 요청"],"es":["Utiliza la herramienta AskUserQuestion para seleccionar cambios","Ejecuta el comando `openspec list --json` para obtener cambios disponibles","Permite a los desarrolladores continuar trabajando en cambios mediante la creación del siguiente artefacto","Soporta la inferencia de cambios desde el contexto de la conversación","Presenta los cambios más recientemente modificados","Utiliza la CLI para interactuar con los cambios"],"fr":["Utilise l''outil AskUserQuestion pour sélectionner des changements","Exécute la commande `openspec list --json` pour obtenir des changements disponibles","Permet aux développeurs de continuer à travailler sur des changements en créant le prochain artefact","Prend en charge l''inférence de changements depuis le contexte de la conversation","Présente les changements les plus récemment modifiés","Utilise la CLI pour interagir avec les changements"],"de":["Verwenden Sie das Tool AskUserQuestion, um Änderungen auszuwählen","Führen Sie den Befehl `openspec list --json` aus, um verfügbare Änderungen zu erhalten","Ermöglicht es Entwicklern, an Änderungen weiterzuarbeiten, indem sie das nächste Artefakt erstellen","Unterstützt die Ableitung von Änderungen aus dem Konversationskontext","Stellt die zuletzt geänderten Änderungen dar","Verwenden Sie die CLI, um mit den Änderungen zu interagieren"],"pt":["Criação de artefatos de mudança de forma eficiente","Lista de mudanças recentes com ordenação por data de modificação","Seleção de mudanças por meio da ferramenta AskUserQuestion","Suporte à execução de comandos CLI, como ''openspec list --json''","Integração com a ferramenta AskUserQuestion para seleção de mudanças","Suporte à inferência de nomes de mudanças a partir do contexto da conversa"],"ru":["Эффективное создание артефактов изменений","Список最近их изменений с сортировкой по дате модификации","Выбор изменений с помощью инструмента AskUserQuestion","Поддержка выполнения команд CLI, таких как ''openspec list --json''","Интеграция с инструментом AskUserQuestion для выбора изменений","Поддержка вывода имен изменений из контекста разговора"],"ar":["إنشاء الملفات المرفقة للتغيير بفعالية","قائمة التغييرات الأخيرة مع ترتيب حسب تاريخ التعديل","اختيار التغييرات بواسطة أداة AskUserQuestion","دعم تشغيل أوامر سطر الأوامر، مثل ''openspec list --json''","التكامل مع أداة AskUserQuestion لاختيار التغييرات","دعم استنتاج أسماء التغييرات من سياق المحادثة"]},"keywords":{"en":["how to use openspec-continue-change","openspec-continue-change setup guide","openspec-continue-change alternative","what is openspec-continue-change","openspec-continue-change vs other change management tools","openspec-continue-change install","openspec-continue-change for AI agents","change management with openspec-continue-change","openspec-continue-change best practices"],"zh":["openspec-continue-change","AI智能工具","openspec list --json","AskUserQuestion工具","智能社区项目","改变管理","AI开发工具"],"ja":["openspec-continue-change","AIエージェント","openspec list --json","AskUserQuestionツール","スマートコミュニティプロジェクト","変更管理","AI開発ツール"],"ko":["openspec-continue-change","AI 에이전트","openspec list --json","AskUserQuestion 도구","지능형 커뮤니티 프로젝트","변경 관리","AI 개발 도구"],"es":["openspec-continue-change","desarrollo de software","herramientas de AI","AskUserQuestion","CLI","gestión de cambios","desarrolladores","programación","integración de herramientas"],"fr":["openspec-continue-change","développement de logiciels","outils d''IA","AskUserQuestion","CLI","gestion de changements","développeurs","programmation","intégration d''outils"],"de":["openspec-continue-change","Softwareentwicklung","AI-Tools","AskUserQuestion","CLI","Änderungsmanagement","Entwickler","Programmierung","Toolintegration"],"pt":["openspec-continue-change","ferramenta de linha de comando","criação de artefatos de mudança","lista de mudanças recentes","seleção de mudanças","AskUserQuestion","CLI","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["openspec-continue-change","инструмент командной строки","создание артефактов изменений","список最近их изменений","выбор изменений","AskUserQuestion","CLI","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["openspec-continue-change","أداة سطر الأوامر","إنشاء الملفات المرفقة للتغيير","قائمة التغييرات الأخيرة","اختيار التغييرات","AskUserQuestion","CLI","تطوير البرمجيات","أدوات التطوير","أدوات الإي الأجنت"]}},"owner":"ruan-cat","repo":"11comm","repoPath":"ruan-cat/11comm","stars":2,"forks":0,"updatedAt":"2026-02-28T13:36:52Z","topics":[],"category":"community","skillMd":{"name":"openspec-continue-change","description":"Continue working on an OpenSpec change by creating the next artifact. Use when the user wants to progress their change, create the next artifact, or continue their workflow.","version":"1.0","bodyPreview":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-","body":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-4 most recently modified changes as options, showing:\n   - Change name\n   - Schema (from `schema` field if present, otherwise \"spec-driven\")\n   - Status (e.g., \"0/5 tasks\", \"complete\", \"no tasks\")\n   - How recently it was modified (from `lastModified` field)\n\n   Mark the most recently modified change as \"(Recommended)\" since it''s likely what the user wants to continue.\n\n   **IMPORTANT**: Do NOT guess or auto-select a change. Always let the user choose.\n\n2. **Check current status**\n\n   ```bash\n   openspec status --change \"<name>\" --json\n   ```\n\n   Parse the JSON to understand current state. The response includes:\n   - `schemaName`: The workflow schema being used (e.g., \"spec-driven\")\n   - `artifacts`: Array of artifacts with their status (\"done\", \"ready\", \"blocked\")\n   - `isComplete`: Boolean indicating if all artifacts are complete\n\n3. **Act based on status**:\n\n   ***\n\n   **If all artifacts are complete (`isComplete: true`)**:\n   - Congratulate the user\n   - Show final status including the schema used\n   - Suggest: \"All artifacts created! You can now implement this change or archive it.\"\n   - STOP\n\n   ***\n\n   **If artifacts are ready to create** (status shows artifacts with `status: \"ready\"`):\n   - Pick the FIRST artifact with `status: \"ready\"` from the status output\n   - Get its instructions:\n     ```bash\n     openspec instructions <artifact-id> --change \"<name>\" --json\n     ```\n   - Parse the JSON. The key fields are:\n     - `context`: Project background (constraints for you - do NOT include in output)\n     - `rules`: Artifact-specific rules (constraints for you - do NOT include in output)\n     - `template`: The structure to use for your output file\n     - `instruction`: Schema-specific guidance\n     - `outputPath`: Where to write the artifact\n     - `dependencies`: Completed artifacts to read for context\n   - **Create the artifact file**:\n     - Read any completed dependency files for context\n     - Use `template` as the structure - fill in its sections\n     - Apply `context` and `rules` as constraints when writing - but do NOT copy them into the file\n     - Write to the output path specified in instructions\n   - Show what was created and what''s now unlocked\n   - STOP after creating ONE artifact\n\n   ***\n\n   **If no artifacts are ready (all blocked)**:\n   - This shouldn''t happen with a valid schema\n   - Show status and suggest checking for issues\n\n4. **After creating an artifact, show progress**\n   ```bash\n   openspec status --change \"<name>\"\n   ```\n\n**Output**\n\nAfter each invocation, show:\n\n- Which artifact was created\n- Schema workflow being used\n- Current progress (N/M complete)\n- What artifacts are now unlocked\n- Prompt: \"Want to continue? Just ask me to continue or tell me what to do next.\"\n\n**Artifact Creation Guidelines**\n\nThe artifact types and their purpose depend on the schema. Use the `instruction` field from the instructions output to understand what to create.\n\nCommon artifact patterns:\n\n**spec-driven schema** (proposal → specs → design → tasks):\n\n- **proposal.md**: Ask user about the change if not clear. Fill in Why, What Changes, Capabilities, Impact.\n  - The Capabilities section is critical - each capability listed will need a spec file.\n- **specs/<capability>/spec.md**: Create one spec per capability listed in the proposal''s Capabilities section (use the capability name, not the change name).\n- **design.md**: Document technical decisions, architecture, and implementation approach.\n- **tasks.md**: Break down implementation into checkboxed tasks.\n\nFor other schemas, follow the `instruction` field from the CLI output.\n\n**Guardrails**\n\n- Create ONE artifact per invocation\n- Always read dependency artifacts before creating a new one\n- Never skip artifacts or create out of order\n- If context is unclear, ask the user before creating\n- Verify the artifact file exists after writing before marking progress\n- Use the schema''s artifact sequence, don''t assume specific artifact names\n- **IMPORTANT**: `context` and `rules` are constraints for YOU, not content for the file\n  - Do NOT copy `<context>`, `<rules>`, `<project_context>` blocks into the artifact\n  - These guide what you write, but should never appear in the output\n"},"lastSynced":"2026-03-07T01:53:37.103Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring seamless project workflow integration, such as Cursor, Windsurf, or Claude Code, to continue working on complex changes","zh":"适用于需要无缝项目工作流集成的开发代理，例如Cursor、Windsurf或Claude Code，以继续处理复杂的更改","ja":"Cursor、Windsurf、またはClaude Codeなどの複雑な変更を続けて作業できる開発エージェントに適しています","ko":"Cursor, Windsurf 또는 Claude Code와 같은 개발 에이전트에게 적합하며, 복잡한 변경 사항에 대한 작업을 계속할 수 있습니다","es":"Ideal para agentes de desarrollo que requieren una integración de flujo de trabajo de proyecto sin problemas, como Cursor, Windsurf o Claude Code, para continuar trabajando en cambios complejos","fr":"Idéal pour les agents de développement nécessitant une intégration du flux de travail de projet sans heurts, tels que Cursor, Windsurf ou Claude Code, pour continuer à travailler sur des changements complexes","de":"Ideal für Entwicklungssagenten, die eine nahtlose Projekt-Workflow-Integration benötigen, wie z. B. Cursor, Windsurf oder Claude Code, um an komplexen Änderungen weiterzuarbeiten","pt":"Ideal para Agentes de Desenvolvimento que requerem integração de fluxo de trabalho de projeto sem interrupções, como Cursor, Windsurf ou Claude Code, para continuar trabalhando em alterações complexas","ru":"Идеально для агентов разработки, требующих бесшовной интеграции рабочего процесса проекта, таких как Cursor, Windsurf или Claude Code, для продолжения работы над сложными изменениями","ar":"مثالي للوكلاء الإنمائيين الذين يحتاجون إلى تكامل سير عمل المشروع بدون انقطاع، مثل Cursor و Windsurf أو Claude Code، لمواصلة العمل على التغييرات المعقدة"},"recommendation":{"en":"Empowers agents to efficiently continue working on changes by creating the next artifact, utilizing the openspec list command and optionally specifying a change name or inferring it from conversation context, all while leveraging tools like AskUserQuestion for user selection","zh":"通过创建下一个工件、利用openspec list命令并可选地指定更改名称或从对话上下文推断它来赋予代理高效地继续处理更改的能力，同时利用AskUserQuestion等工具进行用户选择","ja":"openspec listコマンドを使用し、変更名を指定するか会話のコンテキストから推論し、AskUserQuestionなどのツールを使用してユーザー選択を行うことで、エージェントが効率的に変更を続けることができるようにします","ko":"openspec list 명령을 사용하여 다음 아티팩트를 생성하고, 변경 이름을 지정하거나 대화 contexto에서 추론하며, AskUserQuestion과 같은 도구를 사용하여 사용자 선택을 수행함으로써 에이전트가 변경 사항을 효율적으로 계속 처리할 수 있도록 합니다","es":"Habilita a los agentes a continuar trabajando de forma eficiente en los cambios creando el próximo artifacto, utilizando el comando openspec list y opcionalmente especificando un nombre de cambio o infiriéndolo del contexto de la conversación, todo mientras aprovecha herramientas como AskUserQuestion para la selección del usuario","fr":"Permet aux agents de continuer à travailler de manière efficace sur les changements en créant le prochain artifact, en utilisant la commande openspec list et en spécifiant éventuellement un nom de changement ou en le déduisant du contexte de la conversation, le tout en exploitant des outils comme AskUserQuestion pour la sélection de l''utilisateur","de":"Ermöglicht es den Agenten, effizient an Änderungen weiterzuarbeiten, indem sie das nächste Artifact erstellen, den Befehl openspec list verwenden und optional einen Änderungsnamen angeben oder ihn aus dem Konversationskontext ableiten, während sie Tools wie AskUserQuestion für die Benutzerauswahl nutzen","pt":"Habilita os agentes a continuar trabalhando de forma eficiente nas alterações, criando o próximo artifact, utilizando o comando openspec list e opcionalmente especificando um nome de alteração ou inferindo-o do contexto da conversa, aproveitando ferramentas como AskUserQuestion para seleção do usuário","ru":"Наделяет агентов возможностью эффективно продолжать работу над изменениями, создавая следующий артефакт, используя команду openspec list и опционально указывая имя изменения или выводя его из контекста разговора, используя инструменты типа AskUserQuestion для выбора пользователя","ar":"يمنح الوكلاء القدرة على الاستمرار في العمل بفعالية على التغييرات من خلال إنشاء الملف القادم، واستخدام أمر openspec list وختياراً تحديد اسم التغيير أو استخلاصه من سياق المحادثة، مع الاستفادة من أدوات مثل AskUserQuestion لاختيار المستخدم"},"useCases":{"en":["Continuing development on a recently modified change","Automating the creation of the next project artifact","Inferring and selecting the relevant change from conversation context"],"zh":["在最近修改的更改上继续开发","自动创建下一个项目工件","从对话上下文推断和选择相关更改"],"ja":["最近変更された変更を続けて開発する","次のプロジェクト・アーティファクトを自動的に作成する","会話のコンテキストから関連する変更を推論して選択する"],"ko":["最近 수정된 변경 사항에 대한 개발을 계속하는 것","다음 프로젝트 아티팩트를 자동으로 생성하는 것","대화 contexto에서 관련 변경 사항을 추론하고 선택하는 것"],"es":["Continuar el desarrollo en un cambio recientemente modificado","Automatizar la creación del próximo artifacto del proyecto","Inferir y seleccionar el cambio relevante del contexto de la conversación"],"fr":["Continuer le développement sur un changement récemment modifié","Automatiser la création du prochain artifact du projet","Deduire et sélectionner le changement pertinent du contexte de la conversation"],"de":["Weiterentwicklung an einem kürzlich geänderten Änderung","Automatisierung der Erstellung des nächsten Projekt-Artifacts","Ableiten und Auswählen der relevanten Änderung aus dem Konversationskontext"],"pt":["Continuar o desenvolvimento em uma alteração recentemente modificada","Automatizar a criação do próximo artifact do projeto","Inferir e selecionar a alteração relevante do contexto da conversa"],"ru":["Продолжить разработку недавно измененного изменения","Автоматизировать создание следующего артефакта проекта","Вывести и выбрать соответствующее изменение из контекста разговора"],"ar":["مواصلة التطوير على تغيير تم تعديله مؤخرًا","تأتمة إنشاء الملف التالي للمشروع","استخلاص واختيار التغيير ذي الصلة من سياق المحادثة"]},"limitations":{"en":["Requires openspec list command functionality","Needs access to conversation context for change inference","Must prompt user for selection if change name is vague or ambiguous"],"zh":["需要openspec list命令功能","需要访问对话上下文以进行更改推断","如果更改名称不明确或模糊，则必须提示用户选择"],"ja":["openspec listコマンドの機能が必要","会話のコンテキストへのアクセスが変更の推論に必要","変更名があいまいまたは曖昧な場合は、ユーザーに選択を求める必要がある"],"ko":["openspec list 명령의 기능이 필요함","대화 contexto에 대한 액세스가 변경 사항 추론에 필요함","변경 이름이 모호하거나 불명확한 경우 사용자에게 선택을 요청해야 함"],"es":["Requiere la funcionalidad del comando openspec list","Necesita acceso al contexto de la conversación para la inferencia de cambios","Debe solicitar al usuario la selección si el nombre del cambio es vago o ambiguo"],"fr":["Nécessite la fonctionnalité de la commande openspec list","A besoin d''un accès au contexte de la conversation pour la déduction des changements","Doit solliciter la sélection de l''utilisateur si le nom du changement est vague ou ambigu"],"de":["Benötigt die Funktionalität des Befehls openspec list","Benötigt Zugriff auf den Konversationskontext für die Ableitung von Änderungen","Muss den Benutzer zur Auswahl auffordern, wenn der Änderungsname vage oder mehrdeutig ist"],"pt":["Requer funcionalidade do comando openspec list","Necessita acesso ao contexto da conversa para inferência da alteração","Deve solicitar ao usuário a seleção se o nome da alteração for vago ou ambíguo"],"ru":["Требует функциональности команды openspec list","Требует доступа к контексту разговора для вывода изменения","Должен запрашивать у пользователя выбор, если имя изменения неоднозначно или двусмысленно"],"ar":["يتطلب وظيفة أمر openspec list","يحتاج إلى الوصول إلى سياق المحادثة لاستخلاص التغيير","يجب أن يطلب من المستخدم الاختيار إذا كان اسم التغيير غامض أو غير واضح"]},"version":4},"contentHash":"d0fbc067936de6bea93e611b962d6fa0fd58bcd47b1fe8ee529fa0c97c1afd9d","qualityScore":50}');
