INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ruan-cat/11comm/openspec-continue-change', 'openspec-continue-change', 'ruan-cat', '11comm', 'community', 'openspec-continue-change ruan-cat 11comm community The openspec-continue-change skill enables AI agents to continue working on a change by creating the next artifact, optionally specifying a change name or inferring it from conversation context. This skill benefits developers working on complex projects. openspec-continue-change是一个用于继续工作的改变，通过创建下一个工件。它支持通过运行openspec list --json来获取可用改变，并使用AskUserQuestion工具让用户选择要工作的改变 openspec-continue-changeは、次のアーティファクトを作成することで変更を続けるために使用されます。openspec list --jsonを実行して利用可能な変更を取得し、AskUserQuestionツールを使用してユーザーが作業する変更を選択することをサポート openspec-continue-change는 다음 아티팩트를 생성하여 변경을 계속하는 데 사용됩니다. openspec list --json을 실행하여 사용 가능한 변경을 가져오고, AskUserQuestion 도구를 사용하여 사용자가 작업할 변경을 선택 openspec-continue-change es una habilidad que permite a los desarrolladores continuar trabajando en cambios mediante la creación del siguiente artefacto openspec-continue-change est une compétence qui permet aux développeurs de continuer à travailler sur des changements en créant le prochain artefact openspec-continue-change ist eine Fähigkeit, die es Entwicklern ermöglicht, an Änderungen weiterzuarbeiten, indem sie das nächste Artefakt erstellen O openspec-continue-change é uma ferramenta que permite criar o próximo artefato de mudança de forma eficiente, com recursos como a lista de mudanças recentes e a seleção de mudanças por meio da ferramenta AskUserQuestion. Openspec-continue-change - это инструмент, который позволяет создавать следующий артефакт изменений эффективно, с функциями, такими как список最近их изменений и выбор изменений с помощью инструмента AskUserQuestion. openspec-continue-change هو أداة تمكنك من إنشاء الملف المرفق التالي للتغيير بفعالية، مع ميزات مثل قائمة التغييرات الأخيرة واختيار التغييرات بواسطة أداة AskUserQuestion. how to use openspec-continue-change openspec-continue-change setup guide openspec-continue-change alternative what is openspec-continue-change openspec-continue-change vs other change management tools openspec-continue-change install openspec-continue-change for AI agents change management with openspec-continue-change openspec-continue-change best practices openspec-continue-change AI智能工具 openspec list --json AskUserQuestion工具 智能社区项目 改变管理 AI开发工具 Runs openspec list --json to retrieve available changes sorted by most recently modified Utilizes the AskUserQuestion tool for user selection of changes Presents the top 3-5 changes for user selection Optionally accepts a change name as input Infers change name from conversation context if omitted Prompts for selection if change name is vague or ambiguous openspec-continue-change is a skill that allows AI agents to manage changes efficiently by creating subsequent artifacts, utilizing commands like openspec list --json and tools like AskUserQuestion.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AristidesAI/VisionEmoji/fastapi-templates', 'community', 'AristidesAI', 'VisionEmoji', 'AristidesAI/VisionEmoji', 'fastapi-templates', 1, 0, 50, '2026-02-24T11:10:20Z', '2026-03-06T07:10:38.997Z', '281d79d7bb9e8cbd1cbae1411e80a143b4dc253b02a5284d2a29bb2fa7a176f7', '{"id":"AristidesAI/VisionEmoji/fastapi-templates","name":"fastapi-templates","description":{"en":"fastapi-templates provides production-ready FastAPI project structures for building high-performance APIs. It benefits developers starting new projects from scratch or implementing async REST APIs with Python.","zh":"FastAPI 模板提供了生产就绪的项目结构，支持异步模式、依赖注入和中间件，适用于构建高性能 API","ja":"FastAPI テンプレートは、プロダクションレディのプロジェクト構造を提供し、非同期パターン、依存性の注入、ミドルウェアをサポートします","ko":"FastAPI 템플릿은 프로덕션 준비된 프로젝트 구조를 제공하며 비동기 패턴, 의존성 주입 및 미들웨어를 지원합니다","es":"FastAPI-templates ofrece estructuras de proyecto listas para la producción con patrones asíncronos y mejores prácticas para construir APIs de alto rendimiento","fr":"FastAPI-templates propose des structures de projet prêtes pour la production avec des modèles asynchrones et les meilleures pratiques pour construire des API de haute performance","de":"FastAPI-Vorlagen bietet produktionsreife Projektstrukturen mit asynchronen Mustern und Best Practices für den Bau von Hochleistungs-APIs","pt":"O FastAPI-Templates fornece estruturas de projetos de API prontas para produção com padrões assíncronos e boas práticas para construir APIs de alta performance","ru":"FastAPI-Шаблоны предоставляет производственные структуры проектов API с асинхронными шаблонами и лучшими практиками для построения высокопроизводительных API","ar":"يوفر FastAPI-Templates هياكل مشروع واجهة برمجة تطبيقات جاهزة للإنتاج مع أنماط متزامنة وأفضل الممارسات لإنشاء واجهات برمجة تطبيقات عالية الأداء"},"seo":{"title":{"en":"fastapi-templates: Production-Ready FastAPI Project S