INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AristidesAI/VisionEmoji/fastapi-templates', 'fastapi-templates', 'AristidesAI', 'VisionEmoji', 'community', 'fastapi-templates AristidesAI VisionEmoji community coreml detection-model emoji ios-app swift vision yolo26 fastapi-templates provides production-ready FastAPI project structures for building high-performance APIs. It benefits developers starting new projects from scratch or implementing async REST APIs with Python. FastAPI 模板提供了生产就绪的项目结构，支持异步模式、依赖注入和中间件，适用于构建高性能 API FastAPI テンプレートは、プロダクションレディのプロジェクト構造を提供し、非同期パターン、依存性の注入、ミドルウェアをサポートします FastAPI 템플릿은 프로덕션 준비된 프로젝트 구조를 제공하며 비동기 패턴, 의존성 주입 및 미들웨어를 지원합니다 FastAPI-templates ofrece estructuras de proyecto listas para la producción con patrones asíncronos y mejores prácticas para construir APIs de alto rendimiento FastAPI-templates propose des structures de projet prêtes pour la production avec des modèles asynchrones et les meilleures pratiques pour construire des API de haute performance FastAPI-Vorlagen bietet produktionsreife Projektstrukturen mit asynchronen Mustern und Best Practices für den Bau von Hochleistungs-APIs O FastAPI-Templates fornece estruturas de projetos de API prontas para produção com padrões assíncronos e boas práticas para construir APIs de alta performance FastAPI-Шаблоны предоставляет производственные структуры проектов API с асинхронными шаблонами и лучшими практиками для построения высокопроизводительных API يوفر FastAPI-Templates هياكل مشروع واجهة برمجة تطبيقات جاهزة للإنتاج مع أنماط متزامنة وأفضل الممارسات لإنشاء واجهات برمجة تطبيقات عالية الأداء how to use fastapi-templates fastapi-templates setup guide fastapi-templates alternative fastapi-templates vs Flask fastapi-templates install what is fastapi-templates fastapi-templates for AI agents fastapi-templates with Python fastapi-templates and PostgreSQL fastapi-templates tutorial FastAPI 模板 高性能 API 异步 REST API 依赖注入 中间件 PostgreSQL MongoDB AI 工具 Provides async patterns for building high-performance APIs Includes dependency injection for efficient resource management Supports middleware for enhanced request and response handling Allows for building async applications with PostgreSQL and MongoDB Offers proper structure and testing setup for API projects fastapi-templates is a collection of production-ready FastAPI project structures with async patterns, dependency injection, middleware, and best practices for building high-performance APIs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('emaarco/easy-zeebe/automate-process', 'community', 'emaarco', 'easy-zeebe', 'emaarco/easy-zeebe', 'automate-process', 1, 0, 50, '2026-02-26T07:29:30Z', '2026-03-06T07:13:20.728Z', 'd14e88d4a1648c100e0ac5200840a34364cad5ab9187d1757e386ee9012cbbdb', '{"id":"emaarco/easy-zeebe/automate-process","name":"automate-process","description":{"en":"The automate-process skill generates full hexagonal-architecture glue-code for automating Zeebe BPMN processes, benefiting developers using Spring Boot and Kotlin. It creates job workers, process out-adapters, and application service stubs.","zh":"automate-process 技能生成全面的 hexagonal-architecture 粘合代码，用于自动化 Zeebe BPMN 流程。使用 Spring Boot 和 Kotlin 实现","ja":"automate-process スキルは、Zeebe BPMN プロセスの自動化に必要な hexagonal-architecture 粘合コードを生成します。Spring Boot と Kotlin を使用して実現します","ko":"automate-process 스킬은 Zeebe BPMN 프로세스의 자동화를 위한 완전한 hexagonal-architecture胶合 코드를 생성합니다. Spring Boot 및 Kotlin을 사용하여 구현합니다","es":"El skill automate-process genera código de arquitectura hexagonal para automatizar procesos Zeebe BPMN con Kotlin y Spring Boot","fr":"Le skill automate-process génère du code d''architecture hexagonale pour automatiser des processus Zeebe BPMN avec Kotlin et Spring Boot","de":"Das Skill automate-process generiert Code für hexagonale Architektur, um Zeebe-BPMN-Prozesse mit Kotlin und Spring Boot zu automatisieren","pt":"O Automate-Process é um serviço de exemplo que utiliza Zeebe para orquestração de processos, desenvolvido com Kotlin e Spring Boot","ru":"Автоматизация Процессов - это пример сервиса, использующего Zeebe для оркестровки процессов, разработанный на Kotlin и Spring Boot","ar":"ال Automate-Process هو خدمة مثال تستخدم Zeebe لتنسيق العمليات، تم تطويرها باستخدام Kotlin و Spring Boot"},"seo":{"title":{"en":"automate-process: Zeebe BPMN Process Automation Setup Gui...","zh":"