INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('emaarco/easy-zeebe/automate-process', 'automate-process', 'emaarco', 'easy-zeebe', 'community', 'automate-process emaarco easy-zeebe community bpmn kotlin spring zeebe The automate-process skill generates full hexagonal-architecture glue-code for automating Zeebe BPMN processes, benefiting developers using Spring Boot and Kotlin. It creates job workers, process out-adapters, and application service stubs. automate-process 技能生成全面的 hexagonal-architecture 粘合代码，用于自动化 Zeebe BPMN 流程。使用 Spring Boot 和 Kotlin 实现 automate-process スキルは、Zeebe BPMN プロセスの自動化に必要な hexagonal-architecture 粘合コードを生成します。Spring Boot と Kotlin を使用して実現します automate-process 스킬은 Zeebe BPMN 프로세스의 자동화를 위한 완전한 hexagonal-architecture胶合 코드를 생성합니다. Spring Boot 및 Kotlin을 사용하여 구현합니다 El skill automate-process genera código de arquitectura hexagonal para automatizar procesos Zeebe BPMN con Kotlin y Spring Boot Le skill automate-process génère du code d''architecture hexagonale pour automatiser des processus Zeebe BPMN avec Kotlin et Spring Boot Das Skill automate-process generiert Code für hexagonale Architektur, um Zeebe-BPMN-Prozesse mit Kotlin und Spring Boot zu automatisieren O Automate-Process é um serviço de exemplo que utiliza Zeebe para orquestração de processos, desenvolvido com Kotlin e Spring Boot Автоматизация Процессов - это пример сервиса, использующего Zeebe для оркестровки процессов, разработанный на Kotlin и Spring Boot ال Automate-Process هو خدمة مثال تستخدم Zeebe لتنسيق العمليات، تم تطويرها باستخدام Kotlin و Spring Boot how to use automate-process what is automate-process automate-process alternative automate-process vs Camunda automate-process install automate-process setup guide Zeebe BPMN process automation Spring Boot automate-process Kotlin automate-process example automate-process workflow automation automate-process Zeebe Kotlin Spring Boot hexagonal-architecture BPMN 流程自动化 AIエージェント Zeebe BPMN Generates job workers stored in `adapter/inbound/zeebe` with one `@JobWorker` per serviceTask Creates process out-adapter and inbound/outbound port interfaces Supports application service stubs generation Utilizes Zeebe for process orchestration Built with Spring Boot and Kotlin for seamless integration Follows hexagonal-architecture principles for maintainable code automate-process is a Spring Boot and Kotlin example service using Zeebe for process orchestration, generating necessary code for automating BPMN processes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OttawaCloudConsulting/agentic-ai/skill-refactor', 'community', 'OttawaCloudConsulting', 'agentic-ai', 'OttawaCloudConsulting/agentic-ai', 'skill-refactor', 1, 0, 50, '2026-02-28T16:01:42Z', '2026-03-06T07:14:43.728Z', '450d34a75a390f1bb00a05e300b3d44c8ead6452e5d308cea7b40ca596b9a572', '{"id":"OttawaCloudConsulting/agentic-ai/skill-refactor","name":"skill-refactor","description":{"en":"The skill-refactor skill provides a standalone refactor review for existing skills, compiling a review summary and gating changes behind user approval. It benefits AI agent developers by streamlining the refactoring process.","zh":"skill-refactor 是一个用于代码重构的工具，利用 AIエージェント 来分析和改进代码","ja":"skill-refactor は、AIエージェントを使用してコードを分析し、改良するコードリファクタリングツールです","ko":"skill-refactor는 코드를 리팩토링하는 도구로, AI 에이전트를 사용하여 코드를 분석하고 개선합니다","es":"El skill-refactor es una herramienta para revisar y refactorizar habilidades de Agentes de IA de manera eficiente, utilizando técnicas de critique y red-team","fr":"Le skill-refactor est un outil pour revoir et refactoriser des compétences d''Outils d''IA de manière efficace, en utilisant des techniques de critique et de red-team","de":"Der skill-refactor ist ein Werkzeug zur Überprüfung und Refaktorisierung von KI-Agents-Fähigkeiten, das Critique- und Red-Team-Techniken verwendet","pt":"O Skill Refactor é uma ferramenta de revisão de habilidades de IA que executa críticas e testes de segurança em paralelo","ru":"Skill Refactor - это инструмент рефакторинга ИИ навыков, который выполняет критику и тесты безопасности в параллели","ar":"Skill Refactor هو أداة لاستعراض مهارات الذكاء الاصطناعي التي تنفذ الانتقادات واختبارات الأمان بالتوازي"},"seo":{"title":{"en":"skill-refactor: Refactor Review for AI Agents | AI Agent ...","zh":"skill-refactor 设置指南：AIエージェント代码重构工具","ja":"skill-refactor セットアップガイド：AIエージェントを使用したコードリファクタリング","ko":"skill-refactor 설정 가이드: AI 에이전트 코드 리팩토링 도구","es":"Guía de Configuración de skill-refactor para Agentes de IA","fr":"Guide de Configuration de skill-refactor pour Outils d''IA","de":"Einrichtungsleitfaden für skill-refactor bei KI-Agents","pt":"Guia de Configuração do Skill Refactor para Ferramentas d...","ru":"Настройка Skill Refactor для ИИ Агентов: Руководство","ar":"دليل إعداد Skill Refactor لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to streamline AI agent development with skill-refactor. Learn how to refactor existing skills and improve performance - get started now!","zh":"了解 skill-refactor 的功能和特点，发现如何使用 AIエージェント 来重构代码，提高开发效率","ja":"skill-refactor の機能と特徴を紹介します。AIエージェントを使用してコードをリファクタリングし、開発効率を向上させます","ko":"skill-refactor의 기능과 특징을 알아보세요. AI 에이전트를 사용하여 코드를 리팩토링하고 개발 효율성을 높일 수 있습니다","es":"Aprende a configurar skill-refactor para revisar y refactorizar habilidades de Agentes de IA de manera eficiente","fr":"Découvrez comment configurer skill-refactor pour revoir et refactoriser des compétences d''Outils d''IA de manière efficace","de":"Erfahren Sie, wie Sie skill-refactor für die Überprüfung und Refaktorisierung von KI-Agents-Fähigkeiten einrichten","pt":"Aprenda a configurar o Skill Refactor para revisar e melhorar suas habilidades de IA de forma eficaz","ru":"Узнайте, как настроить Skill Refactor для эффективного рефакторинга ваших ИИ навыков","ar":"تعرف على كيفية إعداد Skill Refactor لاستعراض وتحسين مهارات الذكاء الاصطناعي الخاصة بك"},"definition":{"en":"skill-refactor is a development tool that runs critique and red-team agents in parallel to refactor existing AI agent skills.","zh":"skill-refactor 是一个代码重构工具，使用 AIエージェント 来分析和改进代码结构","ja":"skill-refactor は、コードを分析し、改良するために AIエージェントを使用するコードリファクタリングツールです","ko":"skill-refactor는 코드를 분석하고 개선하는 데 AI 에이전트를 사용하는 코드 리팩토링 도구입니다","es":"El skill-refactor es una herramienta de refactorización para habilidades de Agentes de IA que compila resúmenes de revisión y requiere aprobación explícita del usuario","fr":"Le skill-refactor est un outil de refactorisation pour les compétences d''Outils d''IA qui compile des résumés de révision et nécessite une approbation explicite de l''utilisateur","de":"Der skill-refactor ist ein Refaktorisierungstool für KI-Agents-Fähigkeiten, das Überprüfungsresümees compiliert und eine explizite Benutzerbestätigung erfordert","pt":"O que é Skill Refactor? É uma ferramenta de revisão de habilidades de IA que melhora a qualidade do código","ru":"Что такое Skill Refactor? Это инструмент рефакторинга ИИ навыков, который улучшает качество кода","ar":"ما هو Skill Refactor؟ هو أداة لاستعراض مهارات الذكاء الاصطناعي التي تحسن جودة الكود"},"features":{"en":["Accepts project-bound paths (.claude/skills/<skill-name>/) for refactoring","Supports template paths (skills/<skill-name>/) for skill development","Compiles a review summary for user approval","Gates all changes behind explicit user approval","Runs critique and red-team agents in parallel for efficient refactoring","Confirms directory existence and contains SKILL.md before launching"],"zh":["并行运行批评和红队代理","编译审查摘要","所有更改都需要显式用户批准","支持项目绑定路径和模板路径","检查目录是否存在和包含 SKILL.md 文件"],"ja":["並列に批判とレッドチームエージェントを実行","レビューサマリーをコンパイル","すべての変更は明示的なユーザー承認が必要","プロジェクトバインドパスとテンプレートパスのサポート","ディレクトリの存在と SKILL.md ファイルの含有を確認"],"ko":["평행으로 비평과 적색 팀 에이전트를 실행","리뷰 요약을 컴파일","모든 변경은 명시적인 사용자 승인이 필요","프로젝트 바인드 경로와 템플릿 경로 지원","디렉토리의 존재와 SKILL.md 파일의 포함을 확인"],"es":["Revisión de habilidades de Agentes de IA utilizando técnicas de critique y red-team","Compilación de resúmenes de revisión para habilidades de Agentes de IA","Requiere aprobación explícita del usuario para cambios en habilidades de Agentes de IA","Compatibilidad con rutas de proyecto y plantillas para habilidades de Agentes de IA","Verificación de la existencia de directorios y archivos SKILL.md para habilidades de Agentes de IA"],"fr":["Révision de compétences d''Outils d''IA en utilisant des techniques de critique et de red-team","Compilation de résumés de révision pour les compétences d''Outils d''IA","Nécessite une approbation explicite de l''utilisateur pour les modifications de compétences d''Outils d''IA","Compatibilité avec les chemins de projet et les modèles pour les compétences d''Outils d''IA","Vérification de l''existence de répertoires et de fichiers SKILL.md pour les compétences d''Outils d''IA"],"de":["Überprüfung von KI-Agents-Fähigkeiten mithilfe von Critique- und Red-Team-Techniken","Compilation von Überprüfungsresümees für KI-Agents-Fähigkeiten","Erfordert explizite Benutzerbestätigung für Änderungen an KI-Agents-Fähigkeiten","Kompatibilität mit Projektpfaden und Vorlagen für KI-Agents-Fähigkeiten","Überprüfung der Existenz von Verzeichnissen und SKILL.md-Dateien für KI-Agents-Fähigkeiten"],"pt":["Executa críticas e testes de segurança em paralelo","Compila um resumo de revisão","Exige aprovação explícita do usuário para todas as alterações","Aceita caminhos de projeto ou modelos","Confirma a existência do diretório e do arquivo SKILL.md"],"ru":["Выполняет критику и тесты безопасности в параллели","Собирает отчет о рефакторинге","Требует явного одобрения пользователя для всех изменений","Принимает пути проекта или шаблоны","Подтверждает существование директории и файла SKILL.md"],"ar":["تنفذ الانتقادات واختبارات الأمان بالتوازي","تجمع تقريرًا عن الاستعراض","تتطلب موافقة صريحة من المستخدم لجميع التغييرات","تقبل مسارات المشروع أو النماذج","تؤكد وجود الدليل والملف SKILL.md"]},"keywords":{"en":["how to use skill-refactor","skill-refactor setup guide","what is skill-refactor","skill-refactor alternative","skill-refactor vs agentic ai","skill-refactor install","refactor existing skills","ai agent development tools","skill-refactor tutorial"],"zh":["skill-refactor","AIエージェント","代码重构","代码分析","代码改进","开发工具","代码质量","代码安全"],"ja":["skill-refactor","AIエージェント","コードリファクタリング","コード分析","コード改良","開発ツール","コード品質","コードセキュリティ"],"ko":["skill-refactor","AI 에이전트","코드 리팩토링","코드 분석","코드 개선","개발 도구","코드 품질","코드 보안"],"es":["skill-refactor","Agentes de IA","refactorización de habilidades","critique y red-team","compilación de resúmenes de revisión","aprobación explícita del usuario","rutas de proyecto y plantillas","verificación de directorios y archivos SKILL.md"],"fr":["skill-refactor","Outils d''IA","refactorisation de compétences","critique et red-team","compilation de résumés de révision","approbation explicite de l''utilisateur","chemins de projet et modèles","vérification de répertoires et de fichiers SKILL.md"],"de":["skill-refactor","KI-Agents","Refaktorisierung von Fähigkeiten","Critique- und Red-Team-Techniken","Compilation von Überprüfungsresümees","explizite Benutzerbestätigung","Projektpfade und Vorlagen","Überprüfung von Verzeichnissen und SKILL.md-Dateien"],"pt":["Skill Refactor","Ferramentas de IA","Revisão de habilidades de IA","Revisão de código","Segurança de IA","Desenvolvimento de IA","Revisão de projeto","SKILL.md"],"ru":["Skill Refactor","ИИ Агенты","Рефакторинг ИИ навыков","Код рефакторинга","Безопасность ИИ","Разработка ИИ","Проверка проекта","SKILL.md"],"ar":["Skill Refactor","أدوات الذكاء الاصطناعي","استعراض مهارات الذكاء الاصطناعي","استعراض الكود","أمان الذكاء الاصطناعي","تطوير الذكاء الاصطناعي","استعراض المشروع","SKILL.md"]}},"owner":"OttawaCloudConsulting","repo":"agentic-ai","repoPath":"OttawaCloudConsulting/agentic-ai","stars":1,"forks":0,"updatedAt":"2026-02-28T16:01:42Z","topics":[],"category":"community","skillMd":{"name":"skill-refactor","description":"Reviews and refactors an existing skill against quality standards. Use when asked to review, audit, improve, or refactor a skill. Triggers on phrases like refactor this skill, review my skill, improve skill quality, audit skill-name, clean up my skill. Do NOT use to create a new skill from scratch.","bodyPreview":"# Skill Refactor\n\nStandalone refactor review for existing skills. Runs critique and red-team agents in parallel, compiles a review summary, and gates all changes behind explicit user approval.\n\n## Input\n\nAccept one of:\n\n- Project-bound path: `.claude/skills/<skill-name>/`\n- Template path: `skills/<skill-name>/` (or any other project-relative path)\n\nIf the user does not provide a path, ask which skill to refactor before proceeding.\n\nConfirm the directory exists and contains `SKILL.md` before laun","body":"# Skill Refactor\n\nStandalone refactor review for existing skills. Runs critique and red-team agents in parallel, compiles a review summary, and gates all changes behind explicit user approval.\n\n## Input\n\nAccept one of:\n\n- Project-bound path: `.claude/skills/<skill-name>/`\n- Template path: `skills/<skill-name>/` (or any other project-relative path)\n\nIf the user does not provide a path, ask which skill to refactor before proceeding.\n\nConfirm the directory exists and contains `SKILL.md` before launching sub-agents.\n\n## Workflow\n\nSee `references/refactor-protocol.md` for full sub-agent prompt templates, output formats, and AskUserQuestion schemas.\n\n### 1. Locate skill\n\nResolve the skill path. Read all files in the directory. If `SKILL.md` is missing, stop and report.\n\n### 2. Launch parallel sub-agents\n\nLaunch both simultaneously:\n\n- **Critique agent** — evaluates against internal quality standards (conciseness, degrees of freedom, progressive disclosure, structure, forbidden files). Read `references/refactor-protocol.md` for the prompt template.\n- **Red-team agent** — evaluates against `references/anthropic-best-practices.md` (naming, frontmatter, trigger quality, instruction quality, error handling, file conventions). Read `references/refactor-protocol.md` for the prompt template.\n\nWrite outputs to:\n\n- `temp/<skill-name>/critique/feedback.md`\n- `temp/<skill-name>/red-team/feedback.md`\n\n### 3. Compile review summary\n\nMerge both feedback files into `temp/<skill-name>/refactor/review-summary.md`. Present the path to the user and ask them to review it before proceeding.\n\n### 4. Approval gate\n\nUse AskUserQuestion. Options: proceed with refactor, keep as-is, defer. If declined or deferred, log to `decisions.md` and stop.\n\n### 5. Requirements gathering\n\nUse AskUserQuestion (up to 3 questions): which change categories to apply, any new requirements, refactor depth (targeted vs full rewrite). Log all answers to `temp/<skill-name>/refactor/decisions.md`.\n\n### 6. Refactor agent\n\nApply approved changes in-place to the skill files. Preserve sections not flagged for change in targeted refactors. Log implementation notes to `decisions.md`. Read `references/refactor-protocol.md` for the prompt template.\n\n## Constraints\n\n- Never modify skill files without explicit user approval\n- Write all intermediate artifacts to `temp/<skill-name>/` before any approval gate\n- Log all user decisions and implementation choices to `decisions.md`\n"},"lastSynced":"2026-03-06T07:14:43.728Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing streamlined skill refactoring and review processes.","zh":"适合需要简化技能重构和审查流程的AI代理开发人员。","ja":"AIエージェント開発者がストリームライン化されたスキルリファクタリングとレビュー処理が必要な場合に適しています。","ko":"AI 에이전트 개발자가 스트림 라인화 된 스킬 리팩터링 및 리뷰 프로세스가 필요한 경우에 적합합니다.","es":"Perfecto para desarrolladores de Agentes de IA que necesitan procesos de refactorización y revisión de habilidades simplificados.","fr":"Idéal pour les développeurs d''Agents IA ayant besoin de processus de refactorisation et de révision de compétences simplifiés.","de":"Perfekt für AI-Agent-Entwickler, die vereinfachte Prozesse für die Refaktorierung und Überprüfung von Fähigkeiten benötigen.","pt":"Perfeito para desenvolvedores de Agentes de IA que necessitam de processos de refatoração e revisão de habilidades otimizados.","ru":"Идеально подходит для разработчиков агентов ИИ, которым необходимы оптимизированные процессы рефакторинга и обзора навыков.","ar":"مثالي لمنطقيو وكلاء الذكاء الاصطناعي الذين يحتاجون إلى عمليات إعادة هيكلة واستعراض مهارات مدروزة."},"recommendation":{"en":"Empowers agents to run critique and red-team agents in parallel, compiling review summaries and gating changes behind explicit user approval, utilizing project-bound paths and template paths for seamless integration.","zh":"使代理能够并行运行批评和红队代理，编译审查摘要，并在显式用户批准后对更改进行门控，利用项目绑定路径和模板路径实现无缝集成。","ja":"エージェントが批判とレッドチームエージェントを並行して実行し、レビューサマリーをコンパイルし、変更を明示的なユーザー承認の後でゲートすることを可能にし、プロジェクトバウンドパスとテンプレートパスを使用してシームレスに統合します。","ko":"에이전트가 병렬로 비판과 적군 에이전트를 실행하고 리뷰 요약을 컴파일하며 사용자 승인 후에 변경을 게이트하는 것을 가능하게 하고 프로젝트 바운드 경로와 템플릿 경로를 사용하여 무결점 통합을 구현합니다.","es":"Habilita a los agentes a ejecutar críticas y agentes de red en paralelo, compilar resúmenes de revisión y bloquear cambios detrás de la aprobación explícita del usuario, utilizando rutas vinculadas al proyecto y rutas de plantillas para una integración sin problemas, utilizando CLI, API y frameworks como React y Python.","fr":"Permet aux agents d''exécuter des critiques et des agents de red en parallèle, de compiler des résumés de révision et de bloquer les modifications derrière l''approbation explicite de l''utilisateur, en utilisant des chemins liés au projet et des chemins de modèles pour une intégration sans problème, en utilisant CLI, API et des frameworks tels que React et Python.","de":"Ermächtigt Agenten, Kritik und rote Teams parallel auszuführen, Prüfungsübersichten zu erstellen und Änderungen hinter der ausdrücklichen Benutzerzustimmung zu sperren, indem Projektpfade und Template-Pfade für eine nahtlose Integration verwendet werden, unter Verwendung von CLI, API und Frameworks wie React und Python.","pt":"Habilita agentes a executar críticas e agentes de equipe vermelha em paralelo, compilar resumos de revisão e controlar alterações atrás da aprovação explícita do usuário, utilizando caminhos vinculados ao projeto e caminhos de modelo para integração sem problemas.","ru":"Позволяет агентам выполнять критику и команды красной команды параллельно, компилировать сводки обзора и блокировать изменения за явным одобрением пользователя, используя пути, привязанные к проекту, и пути шаблона для бесшовной интеграции.","ar":"تمكّن الوكلاء من تشغيل الانتقادات وفرق الحمر في متوازي، واختبار تلخيصات المراجعة وحجب التغييرات خلف الموافقة الصريحة للمستخدم، باستخدام مسارات مرتبطة بمشروع وقوالب مسارات من أجل التكامل دون مشاكل."},"useCases":{"en":["Refactoring existing skills for improved performance","Automating review summaries for skill updates","Gating changes behind user approval for secure skill development"],"zh":["重构现有的技能以提高性能","自动化技能更新的审查摘要","在用户批准后对更改进行门控以实现安全的技能开发"],"ja":["パフォーマンスの向上のために既存のスキルをリファクタリングする","スキル更新のレビューサマリーを自動化する","セキュアなスキル開発のためにユーザー承認の後で変更をゲートする"],"ko":["성능 향상을 위해 기존의 스킬을 리팩터링하는 것","스킬 업데이트 리뷰 요약을 자동화하는 것","안전한 스킬 개발을 위해 사용자 승인 후에 변경을 게이트하는 것"],"es":["Reestructuración de habilidades existentes para mejorar el rendimiento","Automatización de resúmenes de revisión para actualizaciones de habilidades","Bloqueo de cambios detrás de la aprobación del usuario para un desarrollo de habilidades seguro"],"fr":["Réorganisation de compétences existantes pour améliorer les performances","Automatisation des résumés de révision pour les mises à jour de compétences","Verrouillage des modifications derrière l''approbation de l''utilisateur pour un développement de compétences sécurisé"],"de":["Umstrukturierung bestehender Fähigkeiten für eine verbesserte Leistung","Automatisierung von Prüfungsübersichten für Fähigkeitsaktualisierungen","Sperren von Änderungen hinter der Benutzerzustimmung für eine sichere Fähigkeitsentwicklung"],"pt":["Reestruturação de habilidades existentes para melhorar o desempenho","Automatização de resumos de revisão para atualizações de habilidades","Controle de alterações atrás da aprovação do usuário para desenvolvimento de habilidades seguro"],"ru":["Рефакторинг существующих навыков для улучшения производительности","Автоматизация сводок обзора для обновлений навыков","Блокировка изменений за одобрением пользователя для безопасного развития навыков"],"ar":["إعادة هيكلة المهارات الحالية لتحسين الأداء","تأتمة تلخيصات المراجعة لتحديثات المهارات","حجب التغييرات خلف موافقة المستخدم لتطوير مهارات آمن"]},"limitations":{"en":["Requires explicit user approval for changes","Needs directory existence and SKILL.md presence for initialization"],"zh":["需要显式用户批准才能进行更改","需要目录存在和SKILL.md存在以初始化"],"ja":["変更を行うには明示的なユーザー承認が必要","初期化にはディレクトリの存在とSKILL.mdの存在が必要"],"ko":["변경을 하기 위해 명시적인 사용자 승인이 필요하다","초기화를 위해 디렉토리의 존재와 SKILL.md의 존재가 필요하다"],"es":["Requiere aprobación explícita del usuario para los cambios","Necesita la existencia de directorios y la presencia de SKILL.md para la inicialización"],"fr":["Nécessite l''approbation explicite de l''utilisateur pour les modifications","Nécessite l''existence de répertoires et la présence de SKILL.md pour l''initialisation"],"de":["Benötigt ausdrückliche Benutzerzustimmung für Änderungen","Benötigt die Existenz von Verzeichnissen und die Anwesenheit von SKILL.md für die Initialisierung"],"pt":["Exige aprovação explícita do usuário para alterações","Necessita da existência do diretório e da presença de SKILL.md para inicialização"],"ru":["Требует явного одобрения пользователя для изменений","Требует наличия директории и присутствия SKILL.md для инициализации"],"ar":["يتطلب موافقة صريحة للمستخدم للتغييرات","يحتاج إلى وجود الدليل وحضور SKILL.md للتأسيس"]},"version":4},"contentHash":"450d34a75a390f1bb00a05e300b3d44c8ead6452e5d308cea7b40ca596b9a572","qualityScore":50}');
