INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OttawaCloudConsulting/agentic-ai/skill-refactor', 'skill-refactor', 'OttawaCloudConsulting', 'agentic-ai', 'community', 'skill-refactor OttawaCloudConsulting agentic-ai community The skill-refactor skill provides a standalone refactor review for existing skills, compiling a review summary and gating changes behind user approval. It benefits AI agent developers by streamlining the refactoring process. skill-refactor 是一个用于代码重构的工具，利用 AIエージェント 来分析和改进代码 skill-refactor は、AIエージェントを使用してコードを分析し、改良するコードリファクタリングツールです skill-refactor는 코드를 리팩토링하는 도구로, AI 에이전트를 사용하여 코드를 분석하고 개선합니다 El skill-refactor es una herramienta para revisar y refactorizar habilidades de Agentes de IA de manera eficiente, utilizando técnicas de critique y red-team Le skill-refactor est un outil pour revoir et refactoriser des compétences d''Outils d''IA de manière efficace, en utilisant des techniques de critique et de red-team Der skill-refactor ist ein Werkzeug zur Überprüfung und Refaktorisierung von KI-Agents-Fähigkeiten, das Critique- und Red-Team-Techniken verwendet O Skill Refactor é uma ferramenta de revisão de habilidades de IA que executa críticas e testes de segurança em paralelo Skill Refactor - это инструмент рефакторинга ИИ навыков, который выполняет критику и тесты безопасности в параллели Skill Refactor هو أداة لاستعراض مهارات الذكاء الاصطناعي التي تنفذ الانتقادات واختبارات الأمان بالتوازي how to use skill-refactor skill-refactor setup guide what is skill-refactor skill-refactor alternative skill-refactor vs agentic ai skill-refactor install refactor existing skills ai agent development tools skill-refactor tutorial skill-refactor AIエージェント 代码重构 代码分析 代码改进 开发工具 代码质量 代码安全 Accepts project-bound paths (.claude/skills/<skill-name>/) for refactoring Supports template paths (skills/<skill-name>/) for skill development Compiles a review summary for user approval Gates all changes behind explicit user approval Runs critique and red-team agents in parallel for efficient refactoring Confirms directory existence and contains SKILL.md before launching skill-refactor is a development tool that runs critique and red-team agents in parallel to refactor existing AI agent skills.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('netbarros/psique/c-pro', 'community', 'netbarros', 'psique', 'netbarros/psique', 'c-pro', 1, 0, 50, '2026-03-06T02:38:17Z', '2026-03-06T13:12:39.407Z', '287ea2a55c4112eb266216ff91d15e0469c0cac34666de87cda22ea3d05347e0', '{"id":"netbarros/psique/c-pro","name":"c-pro","description":{"en":"The c-pro skill provides guidance and best practices for working on c-pro tasks and workflows, helping developers and clinicians optimize their workflows","zh":"C-Pro 是一个使用 AI 和 Telegram 实现工作流自动化的平台，提供了工作流自动化和数据分析的功能","ja":"C-Pro は、AI と Telegram を使用してワークフローの自動化を行うプラットフォームです。ワークフローの自動化とデータ分析の機能を提供します","ko":"C-Pro는 AI 및 Telegram을 사용하여 워크플로 자동화를 구현하는 플랫폼으로, 워크플로 자동화 및 데이터 분석 기능을 제공합니다","es":"c-pro es una plataforma que utiliza la IA para entender la psicanálisis y mejorar la gestión de tu clínica","fr":"c-pro est une plateforme qui utilise l''IA pour comprendre la psychanalyse et améliorer la gestion de votre clinique","de":"c-pro ist eine Plattform, die die KI nutzt, um die Psychoanalyse zu verstehen und die Verwaltung Ihrer Klinik zu verbessern","pt":"O c-pro é uma plataforma que combina IA com psicanálise para melhorar a gestão da sua clínica. Saiba como configurá-lo para obter melhores resultados.","ru":"c-pro - это платформа, которая сочетает ИИ с психоанализом для улучшения управления вашей клиникой. Узнайте, как настроить его для достижения лучших результатов.","ar":"برنامج c-pro هو منصة التي تجمع بين الذكاء الاصطناعي والتحليل النفسي لتحسين إدارة عيادتك. تعلم كيفية ضبطه للحصول على نتائج أفضل."},"seo":{"title":{"en":"c-pro: Setup Guide for AI Agents","zh":"C-Pro 设置指南：使用 AI 和 Telegram 实现工作流自动化","ja":"C-Pro セットアップガイド：AI と Telegram を使用したワークフローの自動化","ko":"C-Pro 설정 가이드: AI 및 Telegram을 사용한 워크플로 자동화","es":"Guía de configuración de c-pro con IA y bot de Telegram","fr":"Guide de mise en place de c-pro avec IA et bot Telegram","de