INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('netbarros/psique/c-pro', 'c-pro', 'netbarros', 'psique', 'community', 'c-pro netbarros psique community The c-pro skill provides guidance and best practices for working on c-pro tasks and workflows, helping developers and clinicians optimize their workflows C-Pro 是一个使用 AI 和 Telegram 实现工作流自动化的平台，提供了工作流自动化和数据分析的功能 C-Pro は、AI と Telegram を使用してワークフローの自動化を行うプラットフォームです。ワークフローの自動化とデータ分析の機能を提供します C-Pro는 AI 및 Telegram을 사용하여 워크플로 자동화를 구현하는 플랫폼으로, 워크플로 자동화 및 데이터 분석 기능을 제공합니다 c-pro es una plataforma que utiliza la IA para entender la psicanálisis y mejorar la gestión de tu clínica c-pro est une plateforme qui utilise l''IA pour comprendre la psychanalyse et améliorer la gestion de votre clinique c-pro ist eine Plattform, die die KI nutzt, um die Psychoanalyse zu verstehen und die Verwaltung Ihrer Klinik zu verbessern O c-pro é uma plataforma que combina IA com psicanálise para melhorar a gestão da sua clínica. Saiba como configurá-lo para obter melhores resultados. c-pro - это платформа, которая сочетает ИИ с психоанализом для улучшения управления вашей клиникой. Узнайте, как настроить его для достижения лучших результатов. برنامج c-pro هو منصة التي تجمع بين الذكاء الاصطناعي والتحليل النفسي لتحسين إدارة عيادتك. تعلم كيفية ضبطه للحصول على نتائج أفضل. how to use c-pro what is c-pro c-pro alternative c-pro vs other platforms c-pro install c-pro setup guide c-pro workflow optimization c-pro best practices c-pro Telegram bot c-pro data analysis C-Pro AI 工作流自动化 Telegram 机器人 数据分析 工作流自动化 最佳实践 实现步骤 验证 详细例子 资源 Provides guidance on c-pro tasks and workflows Offers best practices and checklists for c-pro Validates outcomes and provides actionable steps Includes a Telegram bot for automated scheduling Analyzes data to reveal clinic needs References implementation details in resources/implementation-playbook.md c-pro is a platform that utilizes AI to understand psicanálise, featuring a Telegram bot for automated scheduling and data analysis for clinics');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('valuecodes/agentic-monorepo-starter/frontend-ui', 'community', 'valuecodes', 'agentic-monorepo-starter', 'valuecodes/agentic-monorepo-starter', 'frontend-ui', 0, 0, 50, '2026-03-06T12:59:22.262Z', '2026-03-06T14:58:20.704Z', '61d90d0dafed9f0ff6a300ead885ed187734f730122f29fa3128b0f51f3525e0', '{"id":"valuecodes/agentic-monorepo-starter/frontend-ui","name":"frontend-ui","description":{"en":"The frontend-ui skill provides a monorepo template for agent-assisted development, enabling developers to design and implement app UI/UX with consistent patterns, accessibility, and performance. It benefits developers working on app development projects.","zh":"前端UI开发模板提供了一个可重用的包，严格的TypeScript和CI检查，帮助开发者创建高性能和可访问的应用程序界面","ja":"フロントエンドUI開発テンプレートは、再利用可能なパッケージ、厳格なTypeScript、CIチェックを提供し、開発者が高速でアクセス可能なアプリケーションインターフェースを作成するのに役立ちます","ko":"프론트엔드 UI 개발 템플릿은 재사용 가능한 패키지, 엄격한 TypeScript 및 CI 검사를 제공하여 개발자가高速 및 접근 가능한 애플리케이션 인터페이스를 쉽게 생성할 수 있도록 도와줍니다","es":"El frontend-ui es un monorepo de plantilla para desarrollo asistido por agentes con paquetes reutilizables, TypeScript estricto y flujos de trabajo de CI","fr":"Le frontend-ui est un modèle de monorepo pour le développement assisté par des agents avec des packages réutilisables, TypeScript strict et flux de travail CI","de":"Das frontend-ui ist eine Monorepo-Vorlage für agentenunterstützte Entwicklung mit wiederverwendbaren Paketen, strengem TypeScript und CI-Workflows","pt":"O template frontend-ui fornece uma base para desenvolver interfaces de usuário consistentes e acessíveis com TypeScript e CI checks.","ru":"Шаблон frontend-ui предоставляет основу для разработки консистентных и доступных интерфейсов пользователя с помощью TypeScript и CI проверок.","ar":"قالب frontend-ui يقدم أساسًا لإنشاء واجهات مستخدم متسقة وقابلة للوصول مع TypeScript و CI checks."},"seo":{"title":{"en":"frontend-ui: Monorepo Template Setup Guide | AI Agent Skill","zh":"前端UI开发模板设置指南 - AIエージェント","ja":"フロントエンドUI開発テンプレート設定ガイド - AIエージェント","ko":"프론트엔드 UI 개발 템플릿 설정 가이드 - AI 에이전트","es":"Guía de configuración de frontend-ui para agentes de inte...","fr":"Guide de mise en place de frontend-ui pour les outils d''i...","de":"Einrichtungsleitfaden für frontend-ui bei künstlicher Int...","pt":"Guia de Configuração de Frontend UI com Ferramentas de AI","ru":"Настройка шаблона Frontend UI с помощью ИИ Агентов","ar":"دليل إعداد واجهة المستخدم الأمامية مع أدوات الإيجاد الإصط..."},"description":{"en":"Discover how to design and implement app UI/UX with consistency and performance using frontend-ui. Learn how to reuse shared components and follow App Router...","zh":"使用前端UI开发模板，轻松创建高性能、可访问的应用程序界面，遵循严格的TypeScript和CI检查","ja":"フロントエンドUI開発テンプレートを使用して、高速でアクセス可能なアプリケーションインターフェースを作成します。厳格なTypeScriptとCIチェックを遵守","ko":"프론트엔드 UI 개발 템플릿을 사용하여高速 및 접근 가능한 애플리케이션 인터페이스를 쉽게 생성합니다. 엄격한 TypeScript 및 CI 검사를 따름","es":"Aprende a diseñar e implementar interfaz de usuario con patrones consistentes, accesibilidad y rendimiento en frontend-ui","fr":"Découvrez comment concevoir et mettre en œuvre une interface utilisateur avec des modèles cohérents, accessibilité et performances dans frontend-ui","de":"Erfahren Sie, wie Sie eine Benutzeroberfläche mit konsistenten Mustern, Barrierefreiheit und Leistung in frontend-ui entwerfen und implementieren","pt":"Aprenda a criar interfaces de usuário consistentes e acessíveis com o template de monorepo frontend-ui e ferramentas de AI","ru":"Создайте консистентный и доступный интерфейс пользователя с помощью шаблона monorepo frontend-ui и ИИ Агентов","ar":"اقرأ كيفية إنشاء واجهات مستخدم متسقة وقابلة للوصول مع قالب مونوربو frontend-ui وأدوات الإيجاد الإصطناعي"},"definition":{"en":"frontend-ui is a monorepo template for agent-assisted development, providing reusable packages, strict TypeScript, CI checks, and agent workflows for designing and implementing app UI/UX.","zh":"前端UI开发模板是一种用于创建高性能和可访问的应用程序界面的开发工具，具有严格的TypeScript和CI检查","ja":"フロントエンドUI開発テンプレートは、高速でアクセス可能なアプリケーションインターフェースを作成するための開発ツールであり、厳格なTypeScriptとCIチェックを備えています","ko":"프론트엔드 UI 개발 템플릿은高速 및 접근 가능한 애플리케이션 인터페이스를 생성하기 위한 개발 도구로 엄격한 TypeScript 및 CI 검사를 제공합니다","es":"El frontend-ui es una plantilla de monorepo para desarrollo asistido por agentes de inteligencia artificial","fr":"Le frontend-ui est un modèle de monorepo pour le développement assisté par les outils d''intelligence artificielle","de":"Das frontend-ui ist eine Monorepo-Vorlage für die Entwicklung mit künstlicher Intelligenz","pt":"Frontend UI é um template de monorepo para desenvolvimento assistido por agentes de IA","ru":"Frontend UI - это шаблон monorepo для разработки с помощью ИИ Агентов","ar":"واجهة المستخدم الأمامية هي قالب مونوربو لتنمية مساعدة من قبل أدوات الإيجاد الإصطناعي"},"features":{"en":["Provides reusable packages from @repo/ui for consistent UI/UX","Enforces strict TypeScript for robust code quality","Includes CI checks for automated testing and validation","Follows App Router conventions for standardized routing","Allows app-specific UI components under apps/web/src/components","Supports importing UI components via subpaths"],"zh":["使用严格的TypeScript进行开发","提供可重用的包","支持CI检查","遵循App Router约定","提供共享的UI组件"],"ja":["厳格なTypeScriptを使用した開発","再利用可能なパッケージを提供","CIチェックをサポート","App Routerの規約に従った開発","共有のUIコンポーネントを提供"],"ko":["엄격한 TypeScript를 사용한 개발","재사용 가능한 패키지를 제공","CI 검사를 지원","App Router 규약을 따르는 개발","공유의 UI 컴포넌트를 제공"],"es":["Diseño de interfaz de usuario con patrones consistentes","Implementación de accesibilidad y rendimiento","Uso de paquetes reutilizables de @repo/ui","Seguimiento de convenciones de App Router","Integración con flujos de trabajo de CI"],"fr":["Conception d''interface utilisateur avec des modèles cohérents","Mise en œuvre d''accessibilité et de performances","Utilisation de packages réutilisables de @repo/ui","Suivi des conventions de App Router","Intégration avec des flux de travail CI"],"de":["Entwurf von Benutzeroberflächen mit konsistenten Mustern","Implementierung von Barrierefreiheit und Leistung","Verwendung von wiederverwendbaren Paketen von @repo/ui","Einhaltung von App-Router-Konventionen","Integration mit CI-Workflows"],"pt":["Reutilização de componentes compartilhados de @repo/ui","Manutenção de páginas de destino leves","Seguimento de convenções de App Router","Uso de TypeScript estrito","Verificação de CI"],"ru":["Переиспользование общих компонентов из @repo/ui","Сохранение легких целевых страниц","Следование конвенциям App Router","Использование строгого TypeScript","Проверка CI"],"ar":["إعادة استخدام المكونات المشتركة من @repo/ui","الحفاظ على صفحات الوجهة الخفيفة","متابعة اتفاقيات توجيه التطبيق","استخدام TypeScript صارم","فحص CI"]},"keywords":{"en":["how to use frontend-ui","frontend-ui monorepo template","app UI/UX design with frontend-ui","frontend-ui vs other monorepo templates","frontend-ui setup guide","installing frontend-ui for app development","frontend-ui alternative for agent-assisted development","what is frontend-ui","frontend-ui benefits for developers"],"zh":["前端UI开发","AIエージェント","TypeScript","CI检查","App Router","可重用的包","共享的UI组件"],"ja":["フロントエンドUI開発","AIエージェント","TypeScript","CIチェック","App Router","再利用可能なパッケージ","共有のUIコンポーネント"],"ko":["프론트엔드 UI 개발","AI 에이전트","TypeScript","CI 검사","App Router","재사용 가능한 패키지","공유의 UI 컴포넌트"],"es":["frontend-ui","agentes de inteligencia artificial","desarrollo asistido por agentes","monorepo","TypeScript","CI","interfaz de usuario","accesibilidad","rendimiento"],"fr":["frontend-ui","outils d''intelligence artificielle","développement assisté par des agents","monorepo","TypeScript","CI","interface utilisateur","accessibilité","performances"],"de":["frontend-ui","künstliche Intelligenz","Entwicklung mit künstlicher Intelligenz","Monorepo","TypeScript","CI","Benutzeroberfläche","Barrierefreiheit","Leistung"],"pt":["ferramentas de AI para desenvolvimento web","template frontend-ui","desenvolvimento de interfaces de usuário","TypeScript","CI checks","monorepo","desenvolvimento assistido por agentes de IA"],"ru":["ИИ Агенты для веб-разработки","шаблон frontend-ui","разработка интерфейсов пользователя","TypeScript","CI проверки","monorepo","разработка с помощью ИИ Агентов"],"ar":["أدوات الإيجاد الإصطناعي لتنمية الويب","قالب واجهة المستخدم الأمامية","تنمية واجهات المستخدم","TypeScript","فحص CI","monorepo","تنمية مساعدة من قبل أدوات الإيجاد الإصطناعي"]}},"owner":"valuecodes","repo":"agentic-monorepo-starter","repoPath":"valuecodes/agentic-monorepo-starter","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.262Z","topics":[],"category":"community","skillMd":{"name":"frontend-ui","description":"UI/UX guidelines for app development in this Turborepo (apps/web and future apps). Use when designing or implementing app pages, layouts, navigation, or interactions with Tailwind and @repo/ui components.","bodyPreview":"# Frontend UI (Apps)\n\n## Overview\n\nDesign and implement app UI/UX with consistent patterns, accessibility, and performance. Reuse shared components from `@repo/ui`, keep the landing page lightweight, and follow App Router conventions.\n\n## Scope and Boundaries\n\n- Apps may import packages; packages must not import apps.\n- Prefer shared UI in `packages/ui` to avoid duplication across apps.\n- App-specific UI belongs under the app (for web: `apps/web/src/components`).\n- Import UI components via subpa","body":"# Frontend UI (Apps)\n\n## Overview\n\nDesign and implement app UI/UX with consistent patterns, accessibility, and performance. Reuse shared components from `@repo/ui`, keep the landing page lightweight, and follow App Router conventions.\n\n## Scope and Boundaries\n\n- Apps may import packages; packages must not import apps.\n- Prefer shared UI in `packages/ui` to avoid duplication across apps.\n- App-specific UI belongs under the app (for web: `apps/web/src/components`).\n- Import UI components via subpath exports (no barrel imports).\n\n## Workflow\n\n1. Scan existing app layouts/components to preserve established patterns.\n2. Decide whether the UI should be shared (packages/ui) or app-specific.\n3. Build the UI using `@repo/ui` components and Tailwind utilities.\n4. Add or update local app components using the `~/` path alias.\n5. Validate UX details: hierarchy, spacing, responsive behavior, states, and a11y.\n6. Keep changes minimal and avoid new dependencies unless required; ask first.\n\n## UI/UX Guidelines\n\n- Layout: establish clear hierarchy with headings and section spacing; keep pages lightweight.\n- Typography: use the existing Geist Sans/Mono setup unless explicitly asked to change.\n- Color: rely on the UI theme tokens and CSS variables; avoid ad-hoc palettes.\n- States: include hover/focus/active/disabled plus empty, loading, and error states.\n- Responsiveness: design mobile-first and avoid horizontal scroll.\n- Motion: use subtle, purposeful motion only when it improves clarity.\n\n## Implementation Rules\n\n- App Router only: routes live in `apps/web/src/app` (use `page.tsx` and `layout.tsx`).\n- Use `~/` for local imports (e.g., `~/components/...`).\n- Do not duplicate global CSS imports already defined in `apps/web/src/app/globals.css`.\n\n## Accessibility and Semantics\n\n- Use semantic elements (`header`, `nav`, `main`, `footer`) and proper heading order.\n- Ensure keyboard access and visible focus states.\n- Use buttons for actions and links for navigation.\n- Provide labels or ARIA attributes where needed.\n\n## Client Component Guidance\n\n- Default to Server Components in apps.\n- Add `\"use client\"` only when needed (hooks, browser APIs, event handlers).\n- Isolate client components to the smallest subtree.\n\n## Output Format (PR-ready)\n\n- Follow the repo response format: Plan, Edits, Review Notes, Validation.\n- In Review Notes, include a PR summary (what/why), risks, and follow-ups.\n\n## Validation Commands\n\n- `pnpm --filter web lint`\n- `pnpm --filter web typecheck`\n- `pnpm --filter web build`\n- `pnpm --filter web format`\n- Use repo-wide `pnpm lint` / `pnpm typecheck` when required.\n"},"lastSynced":"2026-03-06T14:58:20.704Z","agentAnalysis":{"suitability":{"en":"Perfect for UI-focused Agents needing consistent app UI/UX patterns with accessibility and performance optimization.","zh":"适合需要一致的应用程序 UI/UX 模式、可访问性和性能优化的 UI 集中型 Agents。","ja":"UI に焦点を当てたエージェントが、一貫したアプリの UI/UX パターンと、アクセシビリティおよびパフォーマンスの最適化を必要とする場合に最適です。","ko":"일관된 애플리케이션 UI/UX 패턴 및 접근성 및 성능 최적화를 필요로 하는 UI 중심 에이전트에게 적합합니다.","es":"Ideal para agentes centrados en la interfaz de usuario que necesitan patrones de interfaz de usuario/aplicación coherentes con optimización de accesibilidad y rendimiento.","fr":"Parfait pour les agents axés sur l''interface utilisateur nécessitant des modèles d''interface utilisateur/application cohérents avec une optimisation de l''accessibilité et des performances.","de":"Perfekt für benutzeroberflächenorientierte Agenten, die konsistente App-Benutzeroberflächen-/Benutzererfahrungsmuster mit Barrierefreiheits- und Leistungsoptimierung benötigen.","pt":"Perfeito para Agentes focados em UI que necessitam de padrões de UI/UX de aplicativos consistentes com otimização de acessibilidade e desempenho.","ru":"Идеально подходит для агентов, ориентированных на UI, которым необходимы последовательные шаблоны UI/UX приложений с оптимизацией доступности и производительности.","ar":"مثالي للوكلاء الذين يركزون على واجهة المستخدم و الذين يحتاجون إلى أنماط واجهة مستخدم و تجربة مستخدم متسقة مع تحسين إمكانية الوصول والأداء."},"recommendation":{"en":"Empowers agents to design and implement reusable UI components via @repo/ui, following App Router conventions and ensuring lightweight landing pages with shared components, all while maintaining accessibility and performance standards using protocols like subpa imports.","zh":"赋予代理设计和实现可重用 UI 组件的能力，通过 @repo/ui 实现，遵循应用路由器约定，确保轻量级着陆页和共享组件，同时保持可访问性和性能标准，使用诸如子包导入等协议。","ja":"エージェントに、@repo/ui を介して再利用可能な UI コンポーネントを設計および実装する能力を与え、アプリ ルーターの規約に従い、軽量のランディング ページと共有コンポーネントを確保し、アクセシビリティとパフォーマンスの標準を維持する、サブパ インポートなどのプロトコルを使用する。","ko":"에이전트에게 @repo/ui를 통해 재사용 가능한 UI 컴포넌트를 설계 및 구현할 수 있는 능력을 부여하여, 애플리케이션 라우터 규약을 따르며, 가벼운 랜딩 페이지와 공유 컴포넌트를 보장하고, 서브 패키지 가져오기와 같은 프로토콜을 사용하여 접근성 및 성능 표준을 유지합니다.","es":"Habilita a los agentes a diseñar e implementar componentes de interfaz de usuario reutilizables a través de @repo/ui, siguiendo las convenciones del enrutador de aplicaciones y garantizando páginas de aterrizaje ligeras con componentes compartidos, todo mientras mantiene los estándares de accesibilidad y rendimiento utilizando protocolos como las importaciones de subpa.","fr":"Permet aux agents de concevoir et de mettre en œuvre des composants d''interface utilisateur réutilisables via @repo/ui, en suivant les conventions du routeur d''applications et en garantissant des pages d''atterrissage légères avec des composants partagés, le tout en maintenant les normes d''accessibilité et de performances en utilisant des protocoles tels que les imports de subpa.","de":"Ermächtigt Agenten, wiederverwendbare Benutzeroberflächenkomponenten über @repo/ui zu entwerfen und zu implementieren, indem sie den Konventionen des App-Routers folgen und leichte Landingpages mit gemeinsam genutzten Komponenten sicherstellen, während sie die Standards für Barrierefreiheit und Leistung mithilfe von Protokollen wie Subpa-Importen aufrechterhält.","pt":"Habilita os agentes a projetar e implementar componentes de UI reutilizáveis via @repo/ui, seguindo as convenções do App Router e garantindo páginas de destino leves com componentes compartilhados, mantendo sempre os padrões de acessibilidade e desempenho usando protocolos como subpa imports.","ru":"Наделяет агентов возможностью проектировать и реализовывать повторно используемые компоненты UI через @repo/ui, следуя конвенциям App Router и гарантируя легкие страницы назначения с общими компонентами, сохраняя при этом стандарты доступности и производительности с использованием протоколов, таких как subpa imports.","ar":"تمكّن الوكلاء من تصميم وتنفيذ مكونات واجهة المستخدم القابلة لإعادة الاستخدام عبر @repo/ui، متبعةً اتفاقيات App Router وضمان صفحات وصول خفيفة مع مكونات مشتركة، مع الحفاظ على معايير إمكانية الوصول والأداء باستخدام بروتوكولات مثل استيراد subpa."},"useCases":{"en":["Implementing consistent UI patterns across apps","Optimizing app performance through lightweight landing pages","Ensuring accessibility in app design"],"zh":["在应用程序中实现一致的 UI 模式","通过轻量级着陆页优化应用程序性能","确保应用程序设计中的可访问性"],"ja":["アプリケーション全体で一貫した UI パターンを実現する","軽量のランディング ページを通じてアプリケーションのパフォーマンスを最適化する","アプリケーション設計におけるアクセシビリティを確保する"],"ko":["애플리케이션에서 일관된 UI 패턴을 구현하는 것","가벼운 랜딩 페이지를 통해 애플리케이션 성능을 최적화하는 것","애플리케이션 디자인에서 접근성을 보장하는 것"],"es":["Implementar patrones de interfaz de usuario coherentes en aplicaciones","Optimizar el rendimiento de la aplicación a través de páginas de aterrizaje ligeras","Garantizar la accesibilidad en el diseño de aplicaciones"],"fr":["Mettre en œuvre des modèles d''interface utilisateur cohérents dans les applications","Optimiser les performances de l''application via des pages d''atterrissage légères","Assurer l''accessibilité dans la conception d''applications"],"de":["Konsistente Benutzeroberflächenmuster über Apps hinweg implementieren","Die Leistung von Apps durch leichte Landingpages optimieren","Barrierefreiheit im App-Design sicherstellen"],"pt":["Implementar padrões de UI consistentes em aplicativos","Otimizar o desempenho do aplicativo por meio de páginas de destino leves","Garantir a acessibilidade no design do aplicativo"],"ru":["Реализация последовательных шаблонов UI в приложениях","Оптимизация производительности приложения за счет легких страниц назначения","Обеспечение доступности в дизайне приложения"],"ar":["تنفيذ أنماط واجهة مستخدم متسقة عبر التطبيقات","تحسين أداء التطبيق من خلال صفحات الوصول الخفيفة","ضمان إمكانية الوصول في تصميم التطبيق"]},"limitations":{"en":["Apps may not import packages, only vice versa","Requires adherence to App Router conventions"],"zh":["应用程序可能无法导入包，只能导出","需要遵循应用路由器约定"],"ja":["アプリケーションはパッケージをインポートできない、逆のみ","アプリ ルーターの規約に従う必要がある"],"ko":["애플리케이션이 패키지를 가져올 수 없고, 반대로만 가능","애플리케이션 라우터 규약을 따라야 함"],"es":["Las aplicaciones pueden no importar paquetes, solo viceversa","Requiere adherirse a las convenciones del enrutador de aplicaciones"],"fr":["Les applications peuvent ne pas importer des packages, mais seulement vice versa","Nécessite de se conformer aux conventions du routeur d''applications"],"de":["Apps können keine Pakete importieren, nur umgekehrt","Erfordert die Einhaltung der Konventionen des App-Routers"],"pt":["Os aplicativos podem não importar pacotes, apenas vice-versa","Requer aderência às convenções do App Router"],"ru":["Приложения могут не импортировать пакеты, только наоборот","Требует соблюдения конвенций App Router"],"ar":["البرامج قد لا تستورد حزم البرامج، بل العكس","يتطلب الالتزام باتفاقيات App Router"]},"version":4},"contentHash":"61d90d0dafed9f0ff6a300ead885ed187734f730122f29fa3128b0f51f3525e0","qualityScore":50}');
