INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('valuecodes/agentic-monorepo-starter/frontend-ui', 'frontend-ui', 'valuecodes', 'agentic-monorepo-starter', 'community', 'frontend-ui valuecodes agentic-monorepo-starter community The frontend-ui skill provides a monorepo template for agent-assisted development, enabling developers to design and implement app UI/UX with consistent patterns, accessibility, and performance. It benefits developers working on app development projects. 前端UI开发模板提供了一个可重用的包，严格的TypeScript和CI检查，帮助开发者创建高性能和可访问的应用程序界面 フロントエンドUI開発テンプレートは、再利用可能なパッケージ、厳格なTypeScript、CIチェックを提供し、開発者が高速でアクセス可能なアプリケーションインターフェースを作成するのに役立ちます 프론트엔드 UI 개발 템플릿은 재사용 가능한 패키지, 엄격한 TypeScript 및 CI 검사를 제공하여 개발자가高速 및 접근 가능한 애플리케이션 인터페이스를 쉽게 생성할 수 있도록 도와줍니다 El frontend-ui es un monorepo de plantilla para desarrollo asistido por agentes con paquetes reutilizables, TypeScript estricto y flujos de trabajo de CI Le frontend-ui est un modèle de monorepo pour le développement assisté par des agents avec des packages réutilisables, TypeScript strict et flux de travail CI Das frontend-ui ist eine Monorepo-Vorlage für agentenunterstützte Entwicklung mit wiederverwendbaren Paketen, strengem TypeScript und CI-Workflows O template frontend-ui fornece uma base para desenvolver interfaces de usuário consistentes e acessíveis com TypeScript e CI checks. Шаблон frontend-ui предоставляет основу для разработки консистентных и доступных интерфейсов пользователя с помощью TypeScript и CI проверок. قالب frontend-ui يقدم أساسًا لإنشاء واجهات مستخدم متسقة وقابلة للوصول مع TypeScript و CI checks. how to use frontend-ui frontend-ui monorepo template app UI/UX design with frontend-ui frontend-ui vs other monorepo templates frontend-ui setup guide installing frontend-ui for app development frontend-ui alternative for agent-assisted development what is frontend-ui frontend-ui benefits for developers 前端UI开发 AIエージェント TypeScript CI检查 App Router 可重用的包 共享的UI组件 Provides reusable packages from @repo/ui for consistent UI/UX Enforces strict TypeScript for robust code quality Includes CI checks for automated testing and validation Follows App Router conventions for standardized routing Allows app-specific UI components under apps/web/src/components Supports importing UI components via subpaths frontend-ui is a monorepo template for agent-assisted development, providing reusable packages, strict TypeScript, CI checks, and agent workflows for designing and implementing app UI/UX.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('valuecodes/cli-agent-sandbox/docs-sync', 'community', 'valuecodes', 'cli-agent-sandbox', 'valuecodes/cli-agent-sandbox', 'docs-sync', 0, 0, 50, '2026-02-07T11:51:54Z', '2026-03-07T03:48:58.096Z', 'd416984991727151b8aad46f9fcd66521249362156d7f4bd1eed2fac4fcbc158', '{"id":"valuecodes/cli-agent-sandbox/docs-sync","name":"docs-sync","description":{"en":"docs-sync is a CLI sandbox for experimenting with LLM agents, tool-calling, and evals, benefiting developers who need to keep documentation consistent. It updates commands, paths, and tool behavior across relevant doc files.","zh":"docs-sync 是一个用于保持文档同步的 CLI 工具，支持 LLM 代理和工具调用。","ja":"docs-sync は AIエージェントと工具呼び出しのドキュメントを最新に保つための CLI ツールです。","ko":"docs-sync는 문서를 동기화하여 LLM 에이전트와 툴 호출을 지원하는 CLI 도구입니다.","es":"docs-sync es una herramienta de línea de comandos para mantener la documentación actualizada y consistente en un repositorio de paquetes único","fr":"docs-sync est un outil en ligne de commande pour maintenir la documentation à jour et cohérente dans un référentiel de packages unique","de":"docs-sync ist ein Befehlszeilen-Tool, um die Dokumentation aktuell und konsistent in einem einzigartigen Paket-Repository zu halten","pt":"A ferramenta docs-sync é uma CLI sandbox para experimentar com agentes LLM, chamadas de ferramentas e avaliações, mantendo a documentação consistente","ru":"Инструмент docs-sync представляет собой CLI sandbox для экспериментов с агентами LLM, вызовами инструментов и оценками, поддерживающий согласованность документации","ar":"أداة docs-sync هي مشغل CLI لتجربة وحدات الذكاء الاصطناعي، واستدعاء الأدوات وتقييمها، مع الحفاظ على توافق الوثائق"},"seo":{"title":{"en":"docs-sync: CLI Sandbox Setup Guide for AI Agents","zh":"docs-sync 设置指南：保持文档同步","ja":"docs-sync セットアップガイド：AIエージェントのドキュメントを最新に保つ","ko":"docs-sync 설정 가이드: 문서 일관성을 유지하다","es":"Guía de configuración de docs-sync para Agentes de IA","fr":"Guide de mise en place de docs-sync pour les Outils d''IA","de":"Einrichtungsleitfaden für docs-sync in KI-Agenten","pt":"Guia de Configuração docs-sync: Ferramenta de Sincronizaç...","ru":"Настройка docs-sync: Инструмент для Синхронизации Докумен...","ar":"دليل إعداد docs-sync: أداة مزامنة الوثائق لآلات الذكاء ال..."},"description":{"en":"Discover how to keep documentation up-to-date with docs-sync. Learn to propagate changes to README.md, AGENTS.md, and .codex/** files with ease. Get started ...","zh":"docs-sync 是一个 CLI 沙箱，用于实验 LLM 代理、工具调用和评估。保持文档同步，避免过时引用。","ja":"docs-sync は AIエージェントのドキュメントを最新に保つための CLI サンドボックスです。README.md、AGENTS.md、Codex エージェント構成などを更新します。","ko":"docs-sync는 LLM 에이전트, 툴 호출 및 평가를 실험하기 위한 CLI 샌드박스입니다. 문서를 동기화하여 오래된 참조를 피합니다.","es":"Mantén la documentación actualizada con docs-sync, una herramienta de línea de comandos para experimentar con agentes de lenguaje y evaluaciones","fr":"Gardez votre documentation à jour avec docs-sync, un outil en ligne de commande pour expérimenter avec les agents de langage et les évaluations","de":"Halten Sie Ihre Dokumentation mit docs-sync aktuell, einem Befehlszeilen-Tool für die Experimentierung mit KI-Agenten und Bewertungen","pt":"Aprenda a utilizar a ferramenta docs-sync para manter a documentação atualizada e consistente em seu repositório","ru":"Узнайте, как использовать docs-sync для поддержания актуальной и согласованной документации в вашем репозитории ИИ Агентов","ar":"تعرف على كيفية استخدام أداة docs-sync لتحديث الوثائق وتوحيدها في مستودعك لآلات الذكاء الاصطناعي"},"definition":{"en":"docs-sync is a command-line interface tool for maintaining consistent documentation across multiple files, including README.md, AGENTS.md, and .codex/** configurations.","zh":"docs-sync 是一个用于保持文档同步的 CLI 工具，用于实验 LLM 代理和工具调用。","ja":"docs-sync は AIエージェントのドキュメントを最新に保つための CLI サンドボックスです。","ko":"docs-sync는 문서를 동기화하여 LLM 에이전트와 툴 호출을 지원하는 CLI 도구입니다.","es":"docs-sync es una herramienta de línea de comandos para mantener la documentación de Agentes de IA actualizada","fr":"docs-sync est un outil en ligne de commande pour maintenir la documentation des Outils d''IA à jour","de":"docs-sync ist ein Befehlszeilen-Tool, um die Dokumentation von KI-Agenten aktuell zu halten","pt":"docs-sync é uma ferramenta de sincronização de documentação para manter a documentação atualizada e consistente","ru":"docs-sync - это инструмент для синхронизации документации, обеспечивающий актуальность и согласованность документов","ar":"docs-sync هي أداة مزامنة الوثائق للحفاظ على تحديث وتوافق الوثائق"},"features":{"en":["Scans for documentation files including README.md, AGENTS.md, and .codex/**","Propagates changes to all relevant doc files to avoid stale references","Updates commands, paths, and tool behavior across multiple files","Supports Markdown file formats for easy documentation editing","Includes a workflow for finding and updating doc files"],"zh":["支持 LLM 代理和工具调用","自动更新 README.md、AGENTS.md 和 Codex エージェント構成","扫描和更新文档文件","避免过时引用"],"ja":["AIエージェントと工具呼び出しのサポート","README.md、AGENTS.md、Codex エージェント構成の自動更新","ドキュメント ファイルのスキャンと更新","古い参照の回避"],"ko":["LLM 에이전트와 툴 호출 지원","README.md, AGENTS.md, Codex 에이전트 구성 자동 업데이트","문서 파일 스캔 및 업데이트","오래된 참조 피하기"],"es":["Mantiene la documentación actualizada en archivos como README.md y AGENTS.md","Propaga cambios a archivos de documentación relevantes","Soporta la configuración de agentes de lenguaje en la carpeta .codex","Permite la experimentación con agentes de lenguaje y evaluaciones","Mantiene la consistencia en la documentación de un repositorio de paquetes único"],"fr":["Maintient la documentation à jour dans des fichiers tels que README.md et AGENTS.md","Propage les modifications aux fichiers de documentation pertinents","Prend en charge la configuration des agents de langage dans le dossier .codex","Permet l''expérimentation avec les agents de langage et les évaluations","Maintient la cohérence dans la documentation d''un référentiel de packages unique"],"de":["Hält die Dokumentation in Dateien wie README.md und AGENTS.md aktuell","Verbreitet Änderungen an relevanten Dokumentationsdateien","Unterstützt die Konfiguration von KI-Agenten im Verzeichnis .codex","Ermöglicht die Experimentierung mit KI-Agenten und Bewertungen","Hält die Konsistenz in der Dokumentation eines einzigartigen Paket-Repositorys aufrecht"],"pt":["CLI sandbox para experimentar com agentes LLM","Chamadas de ferramentas e avaliações","Manutenção da documentação consistente em arquivos como README.md e AGENTS.md","Suporte a configurações de agentes Codex","Atualização automática de referências em documentos"],"ru":["CLI sandbox для экспериментов с агентами LLM","Вызовы инструментов и оценки","Поддержание согласованности документации в файлах seperti README.md и AGENTS.md","Поддержка конфигураций агентов Codex","Автоматическое обновление ссылок в документах"],"ar":["مشغل CLI لتجربة وحدات الذكاء الاصطناعي","استدعاء الأدوات وتقييمها","الحفاظ على توافق الوثائق في الملفات مثل README.md و AGENTS.md","دعم تكوين وحدات Codex","تحديث تلقائي للمراجع في الوثائق"]},"keywords":{"en":["how to use docs-sync","docs-sync setup guide","docs-sync alternative","docs-sync vs other CLI tools","docs-sync install","what is docs-sync","docs-sync for AI agents","docs-sync for LLM agents","CLI sandbox for documentation"],"zh":["docs-sync","LLM 代理","工具调用","CLI 沙箱","文档同步","README.md","AGENTS.md","Codex エージェント構成"],"ja":["docs-sync","AIエージェント","工具呼び出し","CLI サンドボックス","ドキュメント同期","README.md","AGENTS.md","Codex エージェント構成"],"ko":["docs-sync","LLM 에이전트","툴 호출","CLI 샌드박스","문서 동기화","README.md","AGENTS.md","Codex 에이전트 구성"],"es":["docs-sync","Agentes de IA","herramientas de línea de comandos","documentación de software","configuración de agentes de lenguaje","evaluaciones de lenguaje","desarrollo de software","mantenimiento de documentación"],"fr":["docs-sync","Outils d''IA","outils en ligne de commande","documentation de logiciel","configuration des agents de langage","évaluations de langage","développement de logiciel","maintenance de documentation"],"de":["docs-sync","KI-Agenten","Befehlszeilen-Tools","Software-Dokumentation","Konfiguration von KI-Agenten","Sprachbewertungen","Software-Entwicklung","Dokumentationspflege"],"pt":["docs-sync","ferramenta de sincronização de documentação","CLI sandbox","agentes LLM","chamadas de ferramentas","avaliações","documentação consistente","configurações de agentes Codex"],"ru":["docs-sync","инструмент синхронизации документации","CLI sandbox","агенты LLM","вызовы инструментов","оценки","согласованность документации","конфигурации агентов Codex","ИИ Агенты"],"ar":["docs-sync","أداة مزامنة الوثائق","مشغل CLI","وحدات الذكاء الاصطناعي","استدعاء الأدوات","تقييمات","توافق الوثائق","تكوين وحدات Codex","آلات الذكاء الاصطناعي"]}},"owner":"valuecodes","repo":"cli-agent-sandbox","repoPath":"valuecodes/cli-agent-sandbox","stars":0,"forks":0,"updatedAt":"2026-02-07T11:51:54Z","topics":[],"category":"community","skillMd":{"name":"docs-sync","description":"Keep documentation consistent in this repo. Use when you need to update or propagate changes across README/AGENTS/CLAUDE/.codex docs.","bodyPreview":"# Docs Sync\n\nKeep documentation consistent and up-to-date for this single-package repo. When updating commands, paths, or tool behavior, propagate changes to all relevant doc files to avoid stale references.\n\n## Scope\n\nDocumentation files to consider:\n\n- `README.md`\n- `AGENTS.md`\n- `CLAUDE.md` (symlink to `AGENTS.md`, do not edit directly)\n- `.codex/**` (Codex agent configs and skills)\n- Any new doc-like Markdown files added later\n\n## Workflow\n\n1. **Find doc files**: Scan for all documentation f","body":"# Docs Sync\n\nKeep documentation consistent and up-to-date for this single-package repo. When updating commands, paths, or tool behavior, propagate changes to all relevant doc files to avoid stale references.\n\n## Scope\n\nDocumentation files to consider:\n\n- `README.md`\n- `AGENTS.md`\n- `CLAUDE.md` (symlink to `AGENTS.md`, do not edit directly)\n- `.codex/**` (Codex agent configs and skills)\n- Any new doc-like Markdown files added later\n\n## Workflow\n\n1. **Find doc files**: Scan for all documentation files listed in Scope.\n2. **Update references consistently**: When changing a command, path, or pattern, update ALL occurrences across all doc files. Never partially update.\n3. **Add/update explanations**: When changing a command or config, add or update a short explanation of what it does and why.\n4. **Run formatter**: Execute `pnpm format` if you touched Markdown or config files that are formatted.\n5. **Run validation (if needed)**: If documentation changes include code or tooling changes, run `pnpm lint`, `pnpm typecheck`, and `pnpm test`. Skip these when edits are doc-only.\n6. **Summarize changes**: Report files changed and flag anything that needs human review.\n\n## Guidelines\n\n- Keep docs concise and scannable\n- Use consistent terminology across all files\n- Prefer examples over lengthy explanations\n- Update version numbers/dates if present\n- Remove obsolete sections rather than leaving stale content\n- When adding new commands, include both the command and a brief explanation\n- Do not introduce instructions that conflict with `AGENTS.md`\n- Do not edit `CLAUDE.md` directly; update `AGENTS.md` instead\n- Mermaid: wrap node text in quotes like `A[\"Label\"]` and `B{\"Question?\"}` to avoid parse issues with punctuation\n\n## Output Requirements\n\nAlways finish with a summary:\n\n- **Files changed**: List of documentation files modified\n- **What to review**: Any changes that need human verification (e.g., explanations that may need refinement, removed sections)\n- **Validation status**: Commands run, or explicitly note what was skipped\n"},"lastSynced":"2026-03-07T03:48:58.096Z","agentAnalysis":{"suitability":{"en":"Perfect for CLI Agents needing automated documentation synchronization across Markdown files","zh":"适用于需要在 Markdown 文件中自动同步文档的 CLI 代理","ja":"CLI エージェントが Markdown ファイルをまたいだ自動ドキュメント同期が必要な場合に適しています","ko":"CLI 에이전트가 Markdown 파일에 걸쳐 자동 문서同步이 필요할 때 적합합니다","es":"Perfecto para agentes de CLI que necesitan una sincronización automática de documentación a través de archivos Markdown","fr":"Parfait pour les agents CLI nécessitant une synchronisation automatique de documentation à travers les fichiers Markdown","de":"Perfekt für CLI-Agents, die eine automatisierte Dokumentationssynchronisierung über Markdown-Dateien benötigen","pt":"Perfeito para Agentes CLI que necessitam de sincronização automática de documentação em arquivos Markdown","ru":"Идеально подходит для агентов CLI, требующих автоматической синхронизации документации в файлах Markdown","ar":"مثالي للوكلاء CLI الذين يحتاجون إلى تنسيق وثائق آلي عبر ملفات Markdown"},"recommendation":{"en":"Empowers agents to maintain consistent documentation by updating commands, paths, and tool behavior across relevant doc files, including README.md, AGENTS.md, and .codex/** directories, using Markdown file formats","zh":"使代理能够通过更新命令、路径和工具行为来维护文档的一致性，包括 README.md、AGENTS.md 和 .codex/** 目录，使用 Markdown 文件格式","ja":"エージェントが README.md、AGENTS.md、および .codex/** ディレクトリを含む関連ドキュメントファイル全体でコマンド、パス、ツールの動作を更新することでドキュメントの一貫性を維持できるようにします。Markdown ファイル形式を使用します","ko":"README.md, AGENTS.md 및 .codex/** 디렉토리를 포함한 관련 문서 파일 전체에 걸쳐 명령, 경로 및 도구 동작을 업데이트하여 에이전트가 문서 일관성을 유지할 수 있도록 합니다. Markdown 파일 형식을 사용합니다","es":"Permite a los agentes mantener una documentación coherente actualizando comandos, rutas y comportamiento de herramientas en los archivos de documentación relevantes, incluidos README.md, AGENTS.md y directorios .codex/, utilizando formatos de archivo Markdown","fr":"Permet aux agents de maintenir une documentation cohérente en mettant à jour les commandes, les chemins et le comportement des outils dans les fichiers de documentation pertinents, y compris README.md, AGENTS.md et répertoires .codex/, en utilisant des formats de fichier Markdown","de":"Ermöglicht es den Agents, eine konsistente Dokumentation durch Aktualisieren von Befehlen, Pfaden und Tool-Verhalten in den relevanten Dokumentationsdateien zu erhalten, einschließlich README.md, AGENTS.md und .codex/-Verzeichnissen, unter Verwendung von Markdown-Dateiformaten","pt":"Habilita os agentes a manter documentação consistente atualizando comandos, caminhos e comportamento de ferramentas em arquivos de documentação relevantes, incluindo README.md, AGENTS.md e diretórios .codex/, usando formatos de arquivo Markdown","ru":"Позволяет агентам поддерживать согласованную документацию, обновляя команды, пути и поведение инструментов в соответствующих файлах документации, включая README.md, AGENTS.md и директории .codex/, используя форматы файлов Markdown","ar":"تمكّن الوكلاء من الحفاظ على توثيق متسق عن طريق تحديث الأوامر ومسارات وسلوك الأدوات عبر ملفات الوثائق ذات الصلة، بما في ذلك README.md و AGENTS.md ومجلدات .codex/، باستخدام تنسيقات ملفات Markdown"},"useCases":{"en":["Automating documentation updates for CLI tools","Synchronizing agent configurations across doc files","Updating tool behavior references in README.md and AGENTS.md"],"zh":["自动更新 CLI 工具的文档","在文档文件中同步代理配置","在 README.md 和 AGENTS.md 中更新工具行为引用"],"ja":["CLI ツールのドキュメントを自動更新する","ドキュメントファイル全体でエージェントの構成を同期する","README.md および AGENTS.md でツールの動作を参照することを更新する"],"ko":["CLI 도구의 문서를 자동으로 업데이트하는 것","문서 파일에서 에이전트 구성同步","README.md 및 AGENTS.md에서 도구 동작 참조 업데이트하는 것"],"es":["Automatización de actualizaciones de documentación para herramientas de CLI","Sincronización de configuraciones de agentes en archivos de documentación","Actualización de referencias de comportamiento de herramientas en README.md y AGENTS.md"],"fr":["Automatisation des mises à jour de documentation pour les outils CLI","Synchronisation des configurations d''agents dans les fichiers de documentation","Mise à jour des références de comportement d''outils dans README.md et AGENTS.md"],"de":["Automatisierung von Dokumentationsupdates für CLI-Tools","Synchronisierung von Agentenkonfigurationen in Dokumentationsdateien","Aktualisierung von Tool-Verhaltensreferenzen in README.md und AGENTS.md"],"pt":["Automatizar atualizações de documentação para ferramentas CLI","Sincronizar configurações de agentes em arquivos de documentação","Atualizar referências de comportamento de ferramentas em README.md e AGENTS.md"],"ru":["Автоматизировать обновления документации для инструментов CLI","Синхронизировать конфигурации агентов в файлах документации","Обновлять ссылки на поведение инструментов в README.md и AGENTS.md"],"ar":["تأتمة تحديثات الوثائق لأدوات CLI","تنسيق-configurations الوكلاء عبر ملفات الوثائق","تحديث مراجع سلوك الأدوات في README.md و AGENTS.md"]},"limitations":{"en":["Requires CLI sandbox environment","Limited to Markdown file formats","Single-package repository only"],"zh":["需要 CLI 沙盒环境","仅限 Markdown 文件格式","仅支持单包仓库"],"ja":["CLI サンドボックス環境が必要","Markdown ファイル形式に限られる","シングルパッケージリポジトリのみ"],"ko":["CLI 샌드박스 환경이 필요함","Markdown 파일 형식으로만 제한됨","단일 패키지 저장소만 지원"],"es":["Requiere un entorno de sandbox de CLI","Limitado a formatos de archivo Markdown","Solo repositorio de paquetes único"],"fr":["Nécessite un environnement de sandbox de CLI","Limité aux formats de fichier Markdown","Seulement un référentiel de paquets unique"],"de":["Benötigt eine CLI-Sandbox-Umgebung","Begrenzt auf Markdown-Dateiformate","Nur ein einzelnes Paket-Repository"],"pt":["Requer ambiente de sandbox CLI","Limitado a formatos de arquivo Markdown","Repositório de pacote único apenas"],"ru":["Требует среды песочницы CLI","Ограничен форматами файлов Markdown","Только один репозиторий пакета"],"ar":["يتطلب بيئة sandbox CLI","محدود بتنسيقات ملفات Markdown","مخزن حزمة واحد فقط"]},"version":4},"contentHash":"d416984991727151b8aad46f9fcd66521249362156d7f4bd1eed2fac4fcbc158","qualityScore":50}');
