INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('valuecodes/cli-agent-sandbox/docs-sync', 'docs-sync', 'valuecodes', 'cli-agent-sandbox', 'community', 'docs-sync valuecodes cli-agent-sandbox community docs-sync is a CLI sandbox for experimenting with LLM agents, tool-calling, and evals, benefiting developers who need to keep documentation consistent. It updates commands, paths, and tool behavior across relevant doc files. docs-sync 是一个用于保持文档同步的 CLI 工具，支持 LLM 代理和工具调用。 docs-sync は AIエージェントと工具呼び出しのドキュメントを最新に保つための CLI ツールです。 docs-sync는 문서를 동기화하여 LLM 에이전트와 툴 호출을 지원하는 CLI 도구입니다. docs-sync es una herramienta de línea de comandos para mantener la documentación actualizada y consistente en un repositorio de paquetes único docs-sync est un outil en ligne de commande pour maintenir la documentation à jour et cohérente dans un référentiel de packages unique docs-sync ist ein Befehlszeilen-Tool, um die Dokumentation aktuell und konsistent in einem einzigartigen Paket-Repository zu halten A ferramenta docs-sync é uma CLI sandbox para experimentar com agentes LLM, chamadas de ferramentas e avaliações, mantendo a documentação consistente Инструмент docs-sync представляет собой CLI sandbox для экспериментов с агентами LLM, вызовами инструментов и оценками, поддерживающий согласованность документации أداة docs-sync هي مشغل CLI لتجربة وحدات الذكاء الاصطناعي، واستدعاء الأدوات وتقييمها، مع الحفاظ على توافق الوثائق how to use docs-sync docs-sync setup guide docs-sync alternative docs-sync vs other CLI tools docs-sync install what is docs-sync docs-sync for AI agents docs-sync for LLM agents CLI sandbox for documentation docs-sync LLM 代理 工具调用 CLI 沙箱 文档同步 README.md AGENTS.md Codex エージェント構成 Scans for documentation files including README.md, AGENTS.md, and .codex/** Propagates changes to all relevant doc files to avoid stale references Updates commands, paths, and tool behavior across multiple files Supports Markdown file formats for easy documentation editing Includes a workflow for finding and updating doc files docs-sync is a command-line interface tool for maintaining consistent documentation across multiple files, including README.md, AGENTS.md, and .codex/** configurations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('davidkelley/searchlite/bug-hunting', 'community', 'davidkelley', 'searchlite', 'davidkelley/searchlite', 'bug-hunting', 0, 0, 50, '2026-03-07T01:49:01.563Z', '2026-03-07T02:06:44.571Z', '660c80c3b1fd791f588f35f79368ec5d2096b44b8b23f77c53a0392ea06b7d36', '{"id":"davidkelley/searchlite/bug-hunting","name":"bug-hunting","description":{"en":"The bug-hunting skill enables AI agents to efficiently detect and correct bugs in their implementation, prioritizing correctness and durability. It benefits developers by providing a structured approach to bug detection and resolution.","zh":"Searchlite 的 Bug Hunting 工作流程强调正确性和复现，使用 Rust API 和 CLI 进行快速全文搜索","ja":"Searchlite のバグハンティング ワークフローは、正しさと再現を重視し、Rust API と CLI を使用して高速な全文検索を行う","ko":"Searchlite 의 버그 헌팅 워크플로우는 정확성과 재현을 강조하며 Rust API와 CLI를 사용하여 빠른 전체 텍스트 검색을 수행","es":"El Bug Hunting con Searchlite utiliza BM25 con coincidencia de frases y filtros para una búsqueda de texto completo rápida","fr":"Le Bug Hunting avec Searchlite utilise BM25 avec correspondance de phrases et des filtres pour une recherche de texte complet rapide","de":"Das Bug Hunting mit Searchlite nutzt BM25 mit Phrasenübereinstimmung und Filtern für eine schnelle Volltextsuche","pt":"O Searchlite é um mecanismo de busca embutido que oferece recursos avançados para bug hunting, incluindo BM25 e filtragem","ru":"Searchlite - это встроенный поисковый движок, который предлагает продвинутые функции для поиска багов, включая BM25 и фильтрацию","ar":"Searchlite هو محرك بحث مدمج يقدم ميزات متقدمة لتحديد الأخطاء، بما في ذلك BM25 والترشيح"},"seo":{"title":{"en":"bug-hunting: Effective Bug Detection for AI Agents | AI A...","zh":"Bug Hunting 工作流程指南 - Searchlite 集成搜索引擎","ja":"バグハンティング ワークフロー チュートリアル - Searchlite AIエージェント","ko":"버그 헌팅 워크플로우 설정 가이드 - Searchlite 임베디드 검색 엔진","es":"Guía de configuración de Bug Hunting con Searchlite","fr":"Mise en place de Bug Hunting avec Searchlite","de":"Einrichtungsleitfaden für Bug Hunting mit Searchlite","pt":"Guia de Configuração de Bug Hunting com Searchlite","ru":"Настройка ИИ Агентов для Bug Hunting с Searchlite","ar":"إعداد مرشح بحث عن الأخطاء مع Searchlite"},"description":{"en":"Learn how to utilize bug-hunting for efficient bug detection and correction. Get started with our guide and improve your AI agent''s performance today!","zh":"Searchlite 集成搜索引擎的 Bug Hunting 工作流程，强调正确性、复现和最小化修复，使用 Rust API、CLI 和 C/WASM 绑定","ja":"Searchlite AIエージェントのバグハンティング ワークフローは、正しさ、再現、最小限の修復を重視し、Rust API、CLI、C/WASM バインディングを使用","ko":"Searchlite 임베디드 검색 엔진의 버그 헌팅 워크플로우는 정확성과 재현을 강조하며 Rust API, CLI 및 C/WASM 바인딩을 지원","es":"Aprende a encontrar errores reales con Searchlite, un motor de búsqueda embebido con API de Rust y compatibilidad con CLI","fr":"Découvrez comment trouver des erreurs réelles avec Searchlite, un moteur de recherche intégré avec API Rust et prise en charge CLI","de":"Erfahren Sie, wie Sie mit Searchlite, einer eingebetteten Suchmaschine mit Rust-API und CLI-Unterstützung, echte Fehler finden","pt":"Aprenda a configurar o Searchlite para encontrar bugs de forma eficaz, com recursos como BM25 e filtragem","ru":"Узнайте, как настроить Searchlite для эффективного поиска багов с помощью BM25 и фильтрации","ar":"تعلم كيفية إعداد Searchlite لتحديد الأخطاء بفعالية باستخدام BM25 والترشيح"},"definition":{"en":"bug-hunting is a systematic approach to detecting and correcting bugs in software implementation, emphasizing reproducibility and minimal fixes.","zh":"Bug Hunting 是一种强调正确性、复现和最小化修复的软件测试方法","ja":"バグハンティングとは、正しさ、再現、最小限の修復を重視するソフトウェア テスト方法","ko":"버그 헌팅은 정확성과 재현을 강조하며 최소한의 수정을 수행하는 소프트웨어 테스트 방법","es":"Bug Hunting es una técnica de detección de errores que utiliza un motor de búsqueda embebido como Searchlite","fr":"Le Bug Hunting est une technique de détection d''erreurs qui utilise un moteur de recherche intégré comme Searchlite","de":"Bug Hunting ist eine Technik zur Fehlererkennung, die eine eingebettete Suchmaschine wie Searchlite verwendet","pt":"Bug hunting é o processo de encontrar e identificar bugs em um sistema, utilizando ferramentas como o Searchlite","ru":"Поиск багов - это процесс обнаружения и идентификации ошибок в системе, используя инструменты como Searchlite","ar":"مرشح البحث عن الأخطاء هو عملية تحديد وتصحيح الأخطاء في النظام، باستخدام أدوات مثل Searchlite"},"features":{"en":["Utilizes BM25 with phrase matching for efficient full-text search","Supports filters and aggregations for narrowing down bug scope","Provides stored fields and highlighting for easier bug identification","Offers optional vector and GPU stubs for fast schema-driven search","Enforces a discovery phase with clear reproduction and minimal fix requirements","Ensures durability and correctness through non-negotiable rules"],"zh":["BM25 与短语匹配","Rust API 和 CLI","C/WASM 绑定","快速全文搜索","最小化修复和回归测试"],"ja":["BM25 とフレーズ マッチング","Rust API と CLI","C/WASM バインディング","高速な全文検索","最小限の修復と回帰テスト"],"ko":["BM25 및 구문 일치","Rust API 및 CLI","C/WASM 바인딩","빠른 전체 텍스트 검색","최소한의 수정 및 회귀 테스트"],"es":["Motor de búsqueda embebido con API de Rust","Compatibilidad con CLI y bindings de C/WASM","BM25 con coincidencia de frases y filtros","Búsqueda de texto completo rápida con vectores y GPU","Reproducción minimalista y pruebas de regresión"],"fr":["Moteur de recherche intégré avec API Rust","Prise en charge de CLI et de bindings C/WASM","BM25 avec correspondance de phrases et des filtres","Recherche de texte complet rapide avec des vecteurs et GPU","Reproduction minimaliste et tests de régression"],"de":["Eingebettete Suchmaschine mit Rust-API","Unterstützung für CLI und C/WASM-Bindings","BM25 mit Phrasenübereinstimmung und Filtern","Schnelle Volltextsuche mit Vektoren und GPU","Minimalistische Reproduktion und RegressionsTests"],"pt":["Suporte a BM25 com correspondência de frases","Filtragem e agregação de campos","Campos armazenados e realce de resultados","Compatibilidade com Rust, CLI e C/WASM"],"ru":["Поддержка BM25 с фразовой соответствием","Фильтрация и агрегация полей","Хранимые поля и выделение результатов","Совместимость с Rust, CLI и C/WASM"],"ar":["دعم BM25 مع مطابقة الجمل","الترشيح والتجميع للحقول","الحقول المخزنة وتأكيد النتائج","التوافق مع Rust و CLI و C/WASM"]},"keywords":{"en":["how to use bug-hunting","what is bug-hunting","bug-hunting alternative","bug-hunting vs debugging","bug-hunting install guide","bug-hunting setup for AI agents","effective bug detection techniques","AI agent bug correction","bug-hunting workflow optimization"],"zh":["Bug Hunting","Searchlite","集成搜索引擎","Rust API","CLI","C/WASM 绑定","全文搜索","软件测试"],"ja":["バグハンティング","Searchlite","AIエージェント","Rust API","CLI","C/WASM バインディング","全文検索","ソフトウェア テスト"],"ko":["버그 헌팅","Searchlite","임베디드 검색 엔진","Rust API","CLI","C/WASM 바인딩","전체 텍스트 검색","소프트웨어 테스트"],"es":["Herramientas de AI para desarrolladores","Bug Hunting con Searchlite","Búsqueda de texto completo en Rust","CLI para búsqueda de errores","BM25 y coincidencia de frases","Desarrollo de software con Searchlite"],"fr":["Outils d''IA pour les développeurs","Bug Hunting avec Searchlite","Recherche de texte complet en Rust","CLI pour la recherche d''erreurs","BM25 et correspondance de phrases","Développement de logiciels avec Searchlite"],"de":["AI-Tools für Entwickler","Bug Hunting mit Searchlite","Volltextsuche in Rust","CLI für FehlerSuche","BM25 und Phrasenübereinstimmung","Software-Entwicklung mit Searchlite"],"pt":["bug hunting","Searchlite","BM25","filtragem de bugs","desenvolvimento de software","testes de software","rust","CLI","C/WASM"],"ru":["поиск багов","ИИ Агенты","Searchlite","BM25","фильтрация багов","разработка программного обеспечения","тестирование программного обеспечения","rust","CLI","C/WASM"],"ar":["مرشح البحث عن الأخطاء","أدوات الذكاء الاصطناعي","Searchlite","BM25","ترشيح الأخطاء","تطوير البرمجيات","اختبار البرمجيات","rust","CLI","C/WASM"]}},"owner":"davidkelley","repo":"searchlite","repoPath":"davidkelley/searchlite","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.563Z","topics":[],"category":"community","skillMd":{"name":"bug-hunting","description":"Structured workflow for discovering, reproducing, and fixing bugs in Searchlite by inspecting real code paths (CLI/HTTP/core), validating durability invariants, and producing regression tests; use when investigating incorrect results, crashes, data loss risks, or “it sometimes fails” reports.","bodyPreview":"# Bug Hunting Workflow\n\n## Intent\n\nThis skill is for **finding real bugs in the implementation**, not guessing. It forces a discovery phase (build a mental model, reproduce, narrow scope) before making changes.\n\nYou must prioritize:\n\n1. correctness and durability\n2. clear reproduction\n3. minimal fix + regression test\n\n---\n\n## Non-negotiable rules\n\n- **No fix without a reproduction** (a failing test, a minimal repro program, or a deterministic HTTP/CLI script).\n- **No durability regressions**: do","body":"# Bug Hunting Workflow\n\n## Intent\n\nThis skill is for **finding real bugs in the implementation**, not guessing. It forces a discovery phase (build a mental model, reproduce, narrow scope) before making changes.\n\nYou must prioritize:\n\n1. correctness and durability\n2. clear reproduction\n3. minimal fix + regression test\n\n---\n\n## Non-negotiable rules\n\n- **No fix without a reproduction** (a failing test, a minimal repro program, or a deterministic HTTP/CLI script).\n- **No durability regressions**: do not weaken WAL/manifest/atomic rename/fsync ordering.\n- **No “drive-by refactors”** while bug hunting; keep patches tight and reviewable.\n- After changes, you must run the full quality suite from `code-quality`.\n\n---\n\n## Discovery phase (required)\n\n### 0) Establish the boundaries\n\nBefore opening files, answer (in notes) these questions:\n\n- Which surface is affected? **CLI**, **HTTP**, **embedded API**, **wasm**, or **ffi**?\n- Is it a **correctness** issue (wrong results), **durability** issue (lost/duplicated data), or **stability** issue (panic/hang)?\n- Does it require a specific feature flag (`vectors`, `zstd`, `gpu`, wasm/IndexedDB, ffi)?\n- Is the failure deterministic or intermittent?\n\n### 1) Baseline the repo (don’t trust your local state)\n\nRun in workspace root:\n\n- `cargo fmt --all`\n- `cargo clippy --all --all-features --all-targets -- -D warnings`\n- `cargo test --all --all-features`\n\nIf anything fails here, you may be chasing a known failure; fix/resolve that first.\n\n### 2) Map the architecture you’re about to debug\n\nCreate a quick map in notes (1–2 minutes):\n\n- `searchlite-core`: schema, indexing, WAL/manifest, segments, query execution, filters/aggs, vectors\n- `searchlite-cli`: user-facing commands and JSON output formatting\n- `searchlite-http`: endpoints (/init, /add, /bulk, /delete, /commit, /refresh, /search, /inspect, /stats, /compact), limits/timeouts/concurrency\n- `searchlite-wasm`: bindings + IndexedDB storage semantics (no fsync)\n- `searchlite-ffi`: C ABI / safety edges\n\nThis map guides where you look first.\n\n### 3) Reproduce the bug with the smallest possible corpus\n\nProduce a “minimal reproducible case” artifact set:\n\n- a schema JSON (small)\n- a small NDJSON/doc list (5–50 docs)\n- one request (HTTP JSON or CLI command) that fails\n\nFor HTTP:\n\n- include the server flags/env (bind addr, index path, max-body-bytes, max-concurrency, request-timeout, refresh-on-commit)\n\nFor CLI:\n\n- include exact commands and any flags\n\n**Goal:** a script a teammate can run in <60 seconds.\n\n### 4) Turn on observability (don’t add prints yet)\n\nUse existing debugging features first:\n\n- For search correctness: add `explain: true` to the request.\n- For performance/odd slowdowns while reproducing: add `profile: true`.\n- For server behavior: run with `RUST_LOG=debug` (or more targeted module filters) and capture the relevant lines.\n\nIf your issue is “writes not visible,” verify lifecycle:\n\n- you must `commit`\n- you may need `/refresh` in HTTP depending on config\n\n### 5) Narrow the fault line by bisecting the pipeline\n\nPick one axis at a time:\n\n**Correctness axis**\n\n- Does the doc get ingested successfully?\n- Does it appear in `/stats` documents?\n- Does `/inspect` show a new segment after commit?\n- Does the query match in bm25 mode vs wand/bmw mode?\n\n**Durability axis**\n\n- Is WAL appended correctly?\n- Is manifest updated atomically?\n- Is WAL truncated only after manifest persistence?\n- After restart, does replay do the expected thing?\n\n**HTTP axis**\n\n- Is the request being rejected due to max body / timeouts / concurrency?\n- Is NDJSON streaming partial and rolling back?\n- Are errors correctly surfaced as `{\"error\":{\"type\",\"reason\"}}`?\n\n### 6) Perform a targeted static sweep of the suspected modules\n\nOnce you know the rough area, do a deliberate scan for bug smells:\n\nSearch patterns to grep/ripgrep for in the relevant crate:\n\n- panics: `unwrap()`, `expect(`, `panic!`, `unreachable!`, `todo!`\n- suspicious error handling: `map_err(|_|`, `ok()?` in non-optional contexts, silent `let _ =`\n- integer edge cases: casts (`as usize`), underflow (`- 1`), unchecked indexing\n- concurrency hazards: `Mutex`/`RwLock` lock ordering, `.await` while holding locks, channels without bounds\n- IO hazards: missing `fsync`, non-atomic file replace, partial writes not handled, directory fsync omissions\n- schema mismatch hazards: stringly-typed field lookups, analyzer lookup defaults, missing nested path validation\n- vector hazards: dimension mismatch, normalization assumptions, unchecked candidate sizing, `NaN` propagation\n\nYou are not “fixing” in this step—just identifying suspects.\n\n### 7) Dynamic bug probes by subsystem (choose what fits)\n\n#### A) WAL / manifest / commit / rollback\n\nIf you suspect commit/durability issues:\n\n- Reproduce a crash-window scenario:\n  1. ingest docs\n  2. start commit\n  3. force termination mid-way (or simulate via test hooks if present)\n  4. restart and observe replay\n- Validate the invariants:\n  - manifest atomic update (rename) and directory sync\n  - WAL truncation happens after manifest sync\n  - rollback cleans new segment artifacts\n\nIf you can’t safely crash in tests, create a unit test around writer/commit phases and validate state.\n\n#### B) Segment lifecycle / compaction / cleanup\n\nIf you see duplicates, ghosts, or bloat:\n\n- Inspect segments via `inspect` and compare to `stats`\n- Run compaction and verify:\n  - live docs preserved\n  - deleted/tombstoned dropped\n  - old segment files removed (or expected to remain until cleanup)\n\n#### C) Query execution modes\n\nIf you suspect scoring/pruning bugs:\n\n- Run the same query with `execution=bm25`, `execution=wand`, `execution=bmw`\n- Results should match for deterministic corpora (unless the contract explicitly says otherwise)\n- If they diverge, you likely have a pruning-bound bug or block-max metadata mismatch\n\n#### D) Filters/aggs/nested correctness\n\nIf filters/aggs are wrong:\n\n- Verify required fields are `fast: true`\n- For nested, verify the filter uses a `Nested` block and that clauses bind to the same object instance\n- Add a repro doc with two nested objects that would catch “cross-object” leakage\n\n#### E) Vectors (feature `vectors`)\n\nIf vector behavior is wrong:\n\n- Check dimension mismatch handling\n- Check cosine normalization expectations\n- Confirm ANN parameters (`candidate_size`, `ef_search`) don’t overflow or accept nonsensical values\n- Verify hybrid search doesn’t double-count or drop vector scores\n\n---\n\n## Fix phase (required)\n\n### 1) Write the failing regression test first\n\n- Prefer a unit test in the most local crate if possible.\n- If the bug is surface-level behavior (HTTP contract, CLI output), add an integration test.\n- Make it deterministic and small.\n- Assert on structure, not strings (parse JSON output).\n\n### 2) Implement the minimal fix\n\n- Tight patch, minimal diff.\n- Keep durability semantics intact.\n- Avoid introducing allocations/locks in hot paths unless justified.\n\n### 3) Prove it\n\nRun:\n\n- `cargo test --all --all-features`\n- Any relevant examples (e.g. pruning example if you touched pruning logic)\n- If the bug touched performance-sensitive code, run the relevant bench before/after.\n\n### 4) Add a “root cause” note\n\nIn the PR description or internal notes, include:\n\n- symptom\n- root cause\n- why the fix is correct\n- what test prevents regressions\n\n---\n\n## Output format (what Codex should produce)\n\nWhen using this skill, produce:\n\n1. **Repro artifact** (schema + docs + request/command)\n2. **Fault localization** (files + functions involved)\n3. **Root cause analysis**\n4. **Fix plan** (minimal changes)\n5. **Regression test** (where it lives and what it asserts)\n6. **Validation commands run** (from code-quality)\n"},"lastSynced":"2026-03-07T02:06:44.571Z","agentAnalysis":{"suitability":{"en":"Perfect for Debugging Agents needing efficient bug detection and correction capabilities.","zh":"非常适合需要高效的错误检测和纠正能力的调试代理。","ja":"デバッグエージェントが効率的なバグ検出および修正機能を必要とする場合に最適です。","ko":"효율적인 버그 탐지 및 수정 기능이 필요한 디버깅 에이전트에 적합합니다.","es":"Perfecto para agentes de depuración que necesitan capacidades de detección y corrección de errores eficientes.","fr":"Parfait pour les agents de débogage ayant besoin de capacités de détection et de correction de bogues efficaces.","de":"Perfekt für Debugging-Agents, die effiziente Fehlersuch- und Korrekturfunktionen benötigen.","pt":"Perfeito para agentes de depuração que precisam de capacidades de detecção e correção de bugs eficientes.","ru":"Идеально подходит для агентов отладки, которым требуются эффективные возможности обнаружения и исправления ошибок.","ar":"مثالي لعمليات التكشف عن الأخطاء التي تحتاج إلى كفاءة في كشف الأخطاء وتصحيحها."},"recommendation":{"en":"Empowers agents to systematically detect and correct bugs using a structured approach, prioritizing correctness and durability through clear reproduction, minimal fixes, and regression testing, ensuring no durability regressions and enforcing rules like no fix without a reproduction.","zh":"赋予代理以系统地检测和纠正错误的能力，通过清晰的再现、最小修复和回归测试，确保正确性和耐用性，不会出现耐用性回归，并强制执行无再现就无修复的规则。","ja":"エージェントに、再現の明確さ、最小限の修正、回帰テストを優先して、バグを体系的に検出して修正する能力を付与し、正しさと耐久性を確保し、耐久性の回帰が発生せず、再現なければ修正しないというルールを強制します。","ko":"에이전트가 체계적으로 버그를 탐지하고 수정할 수 있는 기능을 제공하여, 명확한 재현, 최소한의 수정, 회귀 테스트를 통해 정확성과 내구성을 우선시하고, 내구성의 회귀가 발생하지 않도록하며, 재현 없이는 수정하지 않는 규칙을 강제합니다.","es":"Habilita a los agentes a detectar y corregir sistemáticamente los errores utilizando un enfoque estructurado, priorizando la corrección y la durabilidad a través de una reproducción clara, reparaciones mínimas y pruebas de regresión, asegurando que no haya regresiones de durabilidad y haciendo cumplir reglas como no reparar sin una reproducción.","fr":"Permet aux agents de détecter et de corriger systématiquement les bogues en utilisant une approche structurée, en donnant la priorité à la correction et à la durabilité grâce à une reproduction claire, des corrections minimales et des tests de régression, en garantissant qu''il n''y a pas de régression de durabilité et en faisant respecter des règles comme pas de correction sans reproduction.","de":"Ermöglicht es den Agenten, Fehler systematisch zu erkennen und zu korrigieren, indem sie einen strukturierten Ansatz verwenden, der Korrektheit und Haltbarkeit durch klare Reproduktion, minimale Korrekturen und Regressionsprüfungen priorisiert, um sicherzustellen, dass es keine Haltbarkeitsrückschritte gibt und Regeln wie keine Korrektur ohne Reproduktion durchsetzt.","pt":"Habilita os agentes a detectar e corrigir bugs de forma sistemática, utilizando uma abordagem estruturada, priorizando a correção e a durabilidade por meio de reprodução clara, correções mínimas e testes de regressão, garantindo que não haja regressões de durabilidade e aplicando regras como não aplicar correção sem reprodução.","ru":"Наделяет агентов возможностью систематически обнаруживать и исправлять ошибки, используя структурированный подход, отдающий приоритет правильности и долговечности посредством четкого воспроизведения, минимальных исправлений и тестирования регрессии, гарантируя, что не произойдут регрессии долговечности и обеспечивая соблюдение правил, таких как не исправлять без воспроизведения.","ar":"يمنح الوكلاء القدرة على كشف الأخطاء وتصحيحها بطريقة منهجية، باستخدام نهج منظم، واعطاء الأولوية للتصحيح والمتانة من خلال إعادة إنتاج واضحة وتصحيح أخف واختبارات انحدار، مما يضمن عدم حدوث انحدارات في المتانة وتنفيذ قواعد مثل عدم إصلاح بدون إعادة إنتاج."},"useCases":{"en":["Automating bug detection in implementation","Generating minimal repro programs for bug reproduction","Debugging code with a focus on correctness and durability"],"zh":["实现中的自动化错误检测","生成最小重现程序用于错误再现","注重正确性和耐用性的代码调试"],"ja":["実装における自動バグ検出","バグ再現のための最小再現プログラムの生成","正しさと耐久性に焦点を当てたコードのデバッグ"],"ko":["구현에서의 자동화 버그 탐지","버그 재현을 위한 최소 재현 프로그램 생성","정확성과 내구성에 중점을 둔 코드 디버깅"],"es":["Automatización de la detección de errores en la implementación","Generación de programas de reproducción mínimos para la reproducción de errores","Depuración de código con enfoque en la corrección y la durabilidad"],"fr":["Automatisation de la détection de bogues dans la mise en œuvre","Génération de programmes de reproduction minimaux pour la reproduction de bogues","Débogage de code avec un focus sur la correction et la durabilité"],"de":["Automatisierung der Fehlersuche in der Implementierung","Generierung von minimalen Reproduktionsprogrammen für die Fehlerreproduktion","Fehlersuche im Code mit Fokus auf Korrektheit und Haltbarkeit"],"pt":["Automatizar a detecção de bugs na implementação","Gerar programas de reprodução mínimos para reprodução de bugs","Depurar código com foco na correção e durabilidade"],"ru":["Автоматизация обнаружения ошибок в реализации","Генерация минимальных программ воспроизведения для воспроизведения ошибок","Отладка кода с учетом правильности и долговечности"],"ar":["تحسين الكشف التلقائي عن الأخطاء في التنفيذ","إنتاج برامج إعادة الإنتاج الأقل للكشف عن الأخطاء","تصحيح الأكواد مع التركيز على الصحة والمتانة"]},"limitations":{"en":["Requires a discovery phase before making changes","No fix without a reproduction","Must prioritize correctness and durability"],"zh":["需要在进行更改之前进行发现阶段","无再现则无修复","必须优先考虑正确性和耐用性"],"ja":["変更を加える前に検出段階を実行する必要がある","再現がなければ修正しない","正しさと耐久性を優先する必要がある"],"ko":["변경을 가하기 전에 발견 단계를 수행해야함","재현 없이는 수정하지 않음","정확성과 내구성을 우선시해야함"],"es":["Requiere una fase de descubrimiento antes de realizar cambios","No hay reparación sin reproducción","Debe priorizar la corrección y la durabilidad"],"fr":["Nécessite une phase de découverte avant d''apporter des modifications","Pas de correction sans reproduction","Doit donner la priorité à la correction et à la durabilité"],"de":["Erfordert eine Entdeckungsphase, bevor Änderungen vorgenommen werden","Keine Korrektur ohne Reproduktion","Muss Korrektheit und Haltbarkeit priorisieren"],"pt":["Requer uma fase de descoberta antes de fazer alterações","Não há correção sem reprodução","Deve priorizar a correção e a durabilidade"],"ru":["Требует фазы обнаружения перед внесением изменений","Не исправлять без воспроизведения","Должно отдавать приоритет правильности и долговечности"],"ar":["يتطلب مرحلة اكتشاف قبل إجراء التغييرات","لا يوجد تصحيح بدون إعادة الإنتاج","يجب أن تعطي الأولوية للتصحيح والمتانة"]},"version":4},"contentHash":"660c80c3b1fd791f588f35f79368ec5d2096b44b8b23f77c53a0392ea06b7d36","qualityScore":50}');
