INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('davidkelley/searchlite/bug-hunting', 'bug-hunting', 'davidkelley', 'searchlite', 'community', 'bug-hunting davidkelley searchlite community The bug-hunting skill enables AI agents to efficiently detect and correct bugs in their implementation, prioritizing correctness and durability. It benefits developers by providing a structured approach to bug detection and resolution. Searchlite 的 Bug Hunting 工作流程强调正确性和复现，使用 Rust API 和 CLI 进行快速全文搜索 Searchlite のバグハンティング ワークフローは、正しさと再現を重視し、Rust API と CLI を使用して高速な全文検索を行う Searchlite 의 버그 헌팅 워크플로우는 정확성과 재현을 강조하며 Rust API와 CLI를 사용하여 빠른 전체 텍스트 검색을 수행 El Bug Hunting con Searchlite utiliza BM25 con coincidencia de frases y filtros para una búsqueda de texto completo rápida Le Bug Hunting avec Searchlite utilise BM25 avec correspondance de phrases et des filtres pour une recherche de texte complet rapide Das Bug Hunting mit Searchlite nutzt BM25 mit Phrasenübereinstimmung und Filtern für eine schnelle Volltextsuche O Searchlite é um mecanismo de busca embutido que oferece recursos avançados para bug hunting, incluindo BM25 e filtragem Searchlite - это встроенный поисковый движок, который предлагает продвинутые функции для поиска багов, включая BM25 и фильтрацию Searchlite هو محرك بحث مدمج يقدم ميزات متقدمة لتحديد الأخطاء، بما في ذلك BM25 والترشيح how to use bug-hunting what is bug-hunting bug-hunting alternative bug-hunting vs debugging bug-hunting install guide bug-hunting setup for AI agents effective bug detection techniques AI agent bug correction bug-hunting workflow optimization Bug Hunting Searchlite 集成搜索引擎 Rust API CLI C/WASM 绑定 全文搜索 软件测试 Utilizes BM25 with phrase matching for efficient full-text search Supports filters and aggregations for narrowing down bug scope Provides stored fields and highlighting for easier bug identification Offers optional vector and GPU stubs for fast schema-driven search Enforces a discovery phase with clear reproduction and minimal fix requirements Ensures durability and correctness through non-negotiable rules bug-hunting is a systematic approach to detecting and correcting bugs in software implementation, emphasizing reproducibility and minimal fixes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cmcp0/credit-applications-hub/compile-agents-context', 'community', 'cmcp0', 'credit-applications-hub', 'cmcp0/credit-applications-hub', 'compile-agents-context', 0, 0, 50, '2026-02-18T06:44:21Z', '2026-03-07T13:07:05.400Z', '7c539e313f567ab4944bd5ac1208b92088a0d4a659bce09572a497b8dc73ebc3', '{"id":"cmcp0/credit-applications-hub/compile-agents-context","name":"compile-agents-context","description":{"en":"The compile-agents-context skill runs the old init command workflow as a Codex-native skill, standardizing AGENTS discovery and regeneration. It benefits developers by providing explicit options for customization.","zh":"编译代理上下文是一种Codex-native技能，用于标准化代理发现和再生，支持扫描深度、依赖关系和自动监视等功能","ja":"Compile Agents Contextは、代理の発見と再生成を標準化するCodex-nativeスキルで、スキャン深度、依存関係、自動監視などの機能をサポートしています","ko":"컴파일 에이전트 컨텍스트는 에이전트 발견 및 재생성을 표준화하는 코덱스 네이티브 스킬로扫描 깊이, 종속성 및 자동 감시 등 기능을 지원합니다","es":"Compile-agents-context es una habilidad que estandariza la descubierta y regeneración de AGENTS con opciones explícitas, como scan_depth y include_dependencies.","fr":"Compile-agents-context est une compétence qui standardise la découverte et la régénération d''AGENTS avec des options explicites, comme scan_depth et include_dependencies.","de":"Compile-agents-context ist eine Fähigkeit, die die Entdeckung und Regenerierung von AGENTS mit expliziten Optionen wie scan_depth und include_dependencies standardisiert.","pt":"O Compile Agents Context é uma habilidade Codex-native que standardiza a descoberta e regeneração de AGENTS com opções explícitas. Ela melhora a eficiência do seu projeto lendo arquivos de projeto raiz e scanneando dependências","ru":"Compile Agents Context — это навык Codex-native, который стандартизирует обнаружение и регенерацию AGENTS с явными параметрами. Он улучшает эффективность вашего проекта, читая файлы корневого проекта и 