INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('weihung0831/claudekit/ck:skill-creator', 'ck:skill-creator', 'weihung0831', 'claudekit', 'community', 'ck:skill-creator weihung0831 claudekit community The ck:skill-creator skill enables developers to craft effective, benchmark-optimized Claude skills using practical instructions and progressive disclosure. This skill benefits developers seeking to automate tasks efficiently. CK:SKILL-CREATOR是一种创建Claude技能的方法，使用进阶披露和元数据质量来实现基准优化 CK:SKILL-CREATORは、プログレッシブ開示とメタデータ品質を使用してベンチマーク最適化されたClaudeスキルを作成する方法です CK:SKILL-CREATOR는 점진적 공개와 메타데이터 품질을 사용하여 벤치마크 최적화된 Claude 스킬을 생성하는 방법입니다 ck:skill-creator permite crear habilidades prácticas y optimizadas para AI Agent, utilizando principios de disclosure progresivo y enseñando a Claude cómo realizar tareas ck:skill-creator permet de créer des compétences pratiques et optimisées pour les outils d''IA, en utilisant les principes de divulgation progressive et en enseignant à Claude comment effectuer des tâches ck:skill-creator ermöglicht die Erstellung praktischer und optimierter Fähigkeiten für AI-Tools, indem es progressive Offenlegung und die Lehre von Claude, wie Aufgaben durchgeführt werden, nutzt O ck:skill-creator é uma ferramenta para criar habilidades práticas e otimizadas para Claude. Ele usa a divulgação progressiva para melhorar a qualidade dos metadados. ИИ Агент ck:skill-creator предназначен для создания практических и оптимизированных навыков для Claude. Он использует прогрессивное раскрытие для улучшения качества метаданных. وكيل ck:skill-creator هو أداة لإنشاء مهارات كلود efectivas ومهارات عملية. يستخدم الإفصاح التدريجي لتحسين جودة البيانات الوصفية. how to use ck:skill-creator ck:skill-creator setup guide ck:skill-creator alternative ck:skill-creator vs other AI skills progressive disclosure in AI skill creation automating tasks with ck:skill-creator ck:skill-creator install ck:skill-creator tutorial optimizing metadata for ck:skill-creator CK:SKILL-CREATOR 人工智能代理技能 进阶披露 元数据质量 Claude技能创建 基准优化 SKILL.md Utilizes progressive disclosure for efficient skill creation Supports metadata quality-based automatic skill activation Enables creation of practical instruction-based skills, not just documentation Includes a Quick Reference guide for easy skill development Optimizes skills for benchmark performance ck:skill-creator is a skill that enables the creation of effective Claude skills using practical instructions, progressive disclosure, and metadata optimization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nopkhun/KO-STOCK-SYSTEM/prompt-optimizer', 'community', 'nopkhun', 'KO-STOCK-SYSTEM', 'nopkhun/KO-STOCK-SYSTEM', 'prompt-optimizer', 0, 0, 50, '2026-03-03T17:38:14Z', '2026-03-07T04:11:36.464Z', '73685e19af25f94aa5b1cf449105de8a7a98533daae5d1ffc5c13c87fc36671b', '{"id":"nopkhun/KO-STOCK-SYSTEM/prompt-optimizer","name":"prompt-optimizer","description":{"en":"The prompt-optimizer skill applies ultrathink principles to prompt engineering, transforming functional prompts into exceptional ones through deep analysis and iterative refinement, benefiting AI agents and developers.","zh":"prompt-optimizer 是一个 AI 最佳提示优化工具，通过深度分析、战略优化和迭代改进来创建卓越的提示","ja":"prompt-optimizer は、深い分析、戦略的最適化、反復的改良を通じて、優れたプロンプトを作成する AI エージェントです","ko":"prompt-optimizer는 깊은 분석, 전략적 최적화 및 반복적 개선을 통해 탁월한 프롬프트를 생성하는 AI 에이전트입니다","es":"El prompt-optimizer aplica principios de ''ultrathink'' para transformar prompts funcionales en excepcionales a través de análisis profundo y optimización estratégica.","fr":"Le prompt-optimizer applique des principes d''ultrathink pour transformer des invites fonctionnels en exceptionnels grâce à une analyse approfondie et une optimisation stratégique.","de":"Der Prompt-Optimizer wendet Ultrathink-Prinzipien an, um funktionale Prompts in außergewöhnliche durch tiefe Analyse und strategische Optimierung zu verwandeln.","pt":"Otimizador de Prompt é um agente de IA que transforma prompts funcionais em excepcionais através da análise profunda e otimização estratégica","ru":"ИИ Агент Prompt Optimizer - это агент, который превращает функциональные промпты в исключительные посредством глубокого анализа и стратегической оптимизации","ar":"مُحسّن الطلب هو وكيل إصطناعي يتحول الطلبات الوظيفية إلى استثنائية من خلال التحليل العميق والتحسين الاستراتيجي"},"seo":{"title":{"en":"prompt-optimizer: AI Best Prompt Setup Guide | AI Agent S...","zh":"prompt-optimizer 设置指南：AI 最佳提示优化工具","ja":"prompt-optimizer のベストプラクティス：AI エージェントによる最適化","ko":"prompt-optimizer 사용법: AI 에이전트를 위한 최적의 프롬프트 최적화","es":"Guía de Optimización de Prompts con Ultrathink","fr":"Guide de Configuration pour Prompt Optimizer avec Princip...","de":"Einrichtungsführer für Prompt-Optimizer mit Ultrathink-Pr...","pt":"Otimizador de Prompt: Guia de Configuração para Desenvolv...","ru":"ИИ Агент Prompt Optimizer: Руководство по Настройке","ar":"مُحسّن الطلب: دليل الإعداد لأصحاب التطبيقات"},"description":{"en":"Unlock exceptional prompts with prompt-optimizer. Discover how to transform functional prompts into inevitable ones through ultrathink principles and iterati...","zh":"了解 prompt-optimizer 的技术细节，掌握 AI 提示优化的最佳实践，提升开发效率","ja":"prompt-optimizer の詳細を調べ、AI エージェントの最適化をマスターし、開発効率を向上させる","ko":"prompt-optimizer의 기술 세부 사항을 익히고, AI 에이전트의 최적화를 마스터하여 개발 효율성을 높여라","es":"Transforma tus prompts de funcionales a excepcionales con análisis profundo y optimización estratégica. Descubre cómo funciona el prompt-optimizer.","fr":"Transformez vos invites de fonctionnels à exceptionnels grâce à une analyse approfondie et une optimisation stratégique. Découvrez comment fonctionne le prom...","de":"Transformieren Sie Ihre Prompts von funktionalen zu außergewöhnlichen durch tiefe Analyse und strategische Optimierung. Erfahren Sie, wie der Prompt-Optimize...","pt":"Aprenda a otimizar prompts com o nosso agente de IA, aumentando a eficiência e a precisão dos resultados","ru":"Узнайте, как оптимизировать промпты с помощью нашего ИИ агента, повышая эффективность и точность результатов","ar":"تعرف على كيفية تحسين الطلبات باستخدام وكيلنا الإصطناعي، مما يزيد من الفعالية والدقة للنتائج"},"definition":{"en":"prompt-optimizer is a skill that uses ultrathink principles to optimize and refine prompts, making them inevitable and effective for AI agents and applications.","zh":"prompt-optimizer 是一种 AI 工具，用于优化和改进提示，以创建更有效的交互","ja":"prompt-optimizer は、プロンプトを最適化して改良する AI ツールです","ko":"prompt-optimizer는 프롬프트를 최적화하고 개선하여 더 효과적인 상호작용을 생성하는 AI 도구입니다","es":"El prompt-optimizer es una herramienta de inteligencia artificial que optimiza y compone prompts para lograr resultados excepcionales.","fr":"Le prompt-optimizer est un outil d''intelligence artificielle qui optimise et compose des invites pour obtenir des résultats exceptionnels.","de":"Der Prompt-Optimizer ist ein KI-Tool, das Prompts optimiert und komponiert, um außergewöhnliche Ergebnisse zu erzielen.","pt":"O que é um Otimizador de Prompt? É um agente de IA que melhora a eficiência dos prompts","ru":"Что такое ИИ Агент Prompt Optimizer? Это агент, который улучшает эффективность промптов","ar":"ما هو مُحسّن الطلب؟ هو وكيل إصطناعي ي cải thiện فعالية الطلبات"},"features":{"en":["Applies ultrathink principles to prompt engineering","Performs deep analysis of prompts for optimization","Iterates relentlessly to refine prompts","Transforms functional prompts into exceptional ones","Questions assumptions and obsesses over details for optimal results","Creates prompts that feel like the only right way to ask"],"zh":["应用 \"ultrathink\" 原则进行提示工程","深度分析和战略优化","迭代改进以创建卓越的提示","支持创建高质量的 AI 交互","优化提示以提高开发效率"],"ja":["「ultrathink」原則を適用したプロンプトエンジニアリング","深い分析と戦略的最適化","反復的改良による優れたプロンプトの作成","高品質の AI インタラクションの作成をサポート","プロンプトの最適化による開発効率の向上"],"ko":[" \"ultrathink\" 원칙을 적용한 프롬프트 엔지니어링","깊은 분석 및 전략적 최적화","반복적 개선을 통한 탁월한 프롬프트 생성","고품질 AI 상호작용 생성 지원","프롬프트 최적화를 통한 개발 효율성 향상"],"es":["Análisis profundo de prompts","Optimización estratégica","Aplicación de principios de ''ultrathink''","Iteración y refinamiento continuo","Transformación de prompts funcionales en excepcionales"],"fr":["Analyse approfondie d''invites","Optimisation stratégique","Application de principes d''ultrathink","Itération et raffinement continu","Transformation d''invites fonctionnels en exceptionnels"],"de":["Tiefe Analyse von Prompts","Strategische Optimierung","Anwendung von Ultrathink-Prinzipien","Iterative und kontinuierliche Verfeinerung","Transformation von funktionalen Prompts in außergewöhnliche"],"pt":["Análise profunda de prompts","Otimização estratégica","Refinamento iterativo","Aplicação de princípios de ''ultrathink''","Criação de prompts excepcionais","Integração com tecnologias de IA"],"ru":["Глубокий анализ промптов","Стратегическая оптимизация","Итеративное уточнение","Применение принципов ''ultrathink''","Создание исключительных промптов","Интеграция с технологиями ИИ"],"ar":["التحليل العميق للطلبات","التنظيم الاستراتيجي","التحسين المتكرر","تطبيق مبادئ ''ultrathink''","إنشاء طلبات استثنائية","التكامل مع تكنولوجيا الإصطناعي"]},"keywords":{"en":["how to use prompt-optimizer","what is prompt-optimizer","prompt-optimizer alternative","prompt-optimizer vs other AI skills","prompt-optimizer install","prompt-optimizer setup guide","ultrathink principles in AI","prompt engineering best practices","AI prompt optimization techniques"],"zh":["AI 提示优化","prompt-optimizer","AI 工具","提示工程","ultrathink","深度分析","战略优化","迭代改进"],"ja":["AI プロンプト最適化","prompt-optimizer","AI エージェント","プロンプトエンジニアリング","ultrathink","深い分析","戦略的最適化","反復的改良"],"ko":["AI 프롬프트 최적화","prompt-optimizer","AI 에이전트","프롬프트 엔지니어링","ultrathink","깊은 분석","전략적 최적화","반복적 개선"],"es":["herramientas de inteligencia artificial","optimización de prompts","ultrathink","análisis de prompts","optimización estratégica","desarrollo de AI","Herramientas de AI para desarrolladores"],"fr":["outils d''intelligence artificielle","optimisation d''invites","ultrathink","analyse d''invites","optimisation stratégique","développement d''IA","Outils d''IA pour développeurs"],"de":["KI-Tools","Prompt-Optimierung","Ultrathink","Prompt-Analyse","strategische Optimierung","KI-Entwicklung","KI-Tools für Entwickler"],"pt":["otimizador de prompt","agente de ia","desenvolvimento de ia","otimização de prompts","análise de prompts","ultrathink","tecnologias de ia","desenvolvedores de ia"],"ru":["ИИ агент prompt optimizer","ИИ агенты","разработка ИИ","оптимизация промптов","анализ промптов","ultrathink","технологии ИИ","разработчики ИИ"],"ar":["مُحسّن الطلب","وكيل إصطناعي","تطوير الإصطناعي","تحسين الطلبات","تحليل الطلبات","ultrathink","تكنولوجيا الإصطناعي","مطوّرو الإصطناعي"]}},"owner":"nopkhun","repo":"KO-STOCK-SYSTEM","repoPath":"nopkhun/KO-STOCK-SYSTEM","stars":0,"forks":0,"updatedAt":"2026-03-03T17:38:14Z","topics":[],"category":"community","skillMd":{"name":"prompt-optimizer","description":"Advanced prompt optimization and composition system for all prompt types (system prompts, task-specific, creative, technical, agentic). Use when users need to refine, optimize, or transform prompts to achieve better AI outputs. Triggers include requests to improve prompts, make prompts more effective, analyze prompt quality, create prompts from scratch, optimize existing prompts for specific goals, or optimize for Claude 4.x models. Also use when users share prompts that could be improved or ask for prompt engineering guidance.","bodyPreview":"# AI Best Prompt Optimizer and Composer\n\nTransform prompts from functional to exceptional through deep analysis, strategic optimization, and iterative refinement. This skill applies \"ultrathink\" principles to prompt engineering—questioning assumptions, obsessing over details, and iterating relentlessly to create prompts that don''t just work, but excel.\n\n## Philosophy: Think Different About Prompts\n\nMost prompts merely work. Great prompts are inevitable—they feel like the only right way to ask. A","body":"# AI Best Prompt Optimizer and Composer\n\nTransform prompts from functional to exceptional through deep analysis, strategic optimization, and iterative refinement. This skill applies \"ultrathink\" principles to prompt engineering—questioning assumptions, obsessing over details, and iterating relentlessly to create prompts that don''t just work, but excel.\n\n## Philosophy: Think Different About Prompts\n\nMost prompts merely work. Great prompts are inevitable—they feel like the only right way to ask. Achieve this by:\n\n- **Question every assumption**: Why this structure? What if we started from zero?\n- **Obsess over details**: Every word choice matters. Every instruction must be precise yet clear.\n- **Plan before writing**: Understand the goal deeply before crafting a single sentence.\n- **Iterate relentlessly**: The first version is never the final version.\n- **Simplify ruthlessly**: Remove complexity without losing power.\n\n## Core Optimization Framework\n\n### 1. Deep Understanding Phase\n\nBefore optimization, understand the prompt''s true purpose:\n\n**Questions to explore:**\n- What is the desired output format and quality?\n- Who is the audience? What''s their expertise level?\n- What context is essential vs. nice-to-have?\n- What are the failure modes to prevent?\n- Are there implicit assumptions that should be explicit?\n\n**Analyze current prompt for:**\n- Clarity of instructions\n- Completeness of context\n- Ambiguity or vagueness\n- Missing constraints or guidelines\n- Structural organization\n- Token efficiency\n\n### 2. Strategic Optimization by Prompt Type\n\n#### For System Prompts (AI Agents/Chatbots)\n- Define clear role and persona\n- Establish behavioral boundaries and guardrails\n- Specify output format and tone\n- Include response patterns and examples\n- Add error handling and edge cases\n- Balance flexibility with consistency\n\n#### For Task-Specific Prompts\n- Break down complex tasks into clear steps\n- Provide concrete examples (input/output pairs)\n- Specify success criteria explicitly\n- Include context about what NOT to do\n- Add verification checkpoints\n- Use structured formatting for clarity\n\n#### For Creative Prompts\n- Set the creative direction and constraints\n- Inspire without over-constraining\n- Provide style references or examples\n- Balance guidance with creative freedom\n- Include quality markers or criteria\n- Encourage iteration and exploration\n\n#### For Technical Prompts\n- Maximize precision and specificity\n- Include technical context and constraints\n- Specify format requirements strictly\n- Add validation criteria\n- Consider edge cases explicitly\n- Provide technical examples\n\n#### For Agentic Prompts (AI Coding Tools)\n- Define clear task boundaries and scope\n- Specify file handling and code style expectations\n- Include verification and testing requirements\n- Add rollback and error recovery patterns\n- Balance autonomy with user control\n- Include progress reporting requirements\n\n### 3. Structural Excellence\n\nApply these structural principles:\n\n**Progressive disclosure:**\n- Start with overview/context\n- Move to specific instructions\n- End with examples or constraints\n- Use clear section headers\n\n**Layered specificity:**\n- General principles first\n- Specific requirements second\n- Edge cases and exceptions last\n\n**Token efficiency:**\n- Every sentence must justify its existence\n- Prefer concise clarity over verbose explanation\n- Remove redundancy ruthlessly\n- Use formatting (bullets, headers) for scannability\n\n### 4. Quality Markers\n\nExcellent prompts exhibit:\n\n- **Clarity**: No ambiguity in what''s expected\n- **Completeness**: All necessary context provided\n- **Conciseness**: No unnecessary verbosity\n- **Specificity**: Concrete rather than abstract\n- **Structure**: Logically organized and scannable\n- **Examples**: Show, don''t just tell\n- **Constraints**: Clear boundaries and guardrails\n- **Testability**: Output quality can be verified\n\n## Optimization Process\n\n### Step 1: Analyze\nDeeply understand the current prompt:\n- Identify the core objective\n- Note strengths and weaknesses\n- Spot missing elements\n- Find opportunities for improvement\n\n### Step 2: Plan\nDesign the optimization strategy:\n- Determine which type of optimization needed (quick polish vs. deep transformation)\n- Identify key improvements to make\n- Plan the new structure\n- Consider alternative approaches\n\n### Step 3: Optimize\nTransform the prompt:\n- Rewrite unclear instructions\n- Add missing context\n- Reorganize for clarity\n- Insert concrete examples\n- Refine word choices\n- Apply structural principles\n\n### Step 4: Validate\nEnsure quality:\n- Does it meet all quality markers?\n- Will it produce the desired output?\n- Are there edge cases to handle?\n- Is it token-efficient?\n- Can it be simplified further?\n\n### Step 5: Present\nShow the transformation:\n- Present optimized prompt\n- Explain key changes made\n- Describe expected output improvements\n- Highlight structural enhancements\n- Note any assumptions or decisions\n\n## Output Format\n\nWhen presenting optimized prompts, provide:\n\n### 1. Optimized Prompt\nThe complete, ready-to-use optimized prompt with clear formatting.\n\n### 2. Key Improvements\nConcise list of major enhancements:\n- What changed and why\n- Expected impact on outputs\n- Any trade-offs made\n\n### 3. Expected Output Changes\nDescribe how the output will improve:\n- Quality enhancements\n- Consistency improvements\n- Better handling of edge cases\n- More aligned with goals\n\n### 4. Implementation Notes (if applicable)\n- Suggested variations for different contexts\n- Tips for further customization\n- Potential iterative refinements\n\n## Adaptive Optimization Levels\n\n### Quick Polish\nFor prompts that are mostly good but need refinement:\n- Fix clarity issues\n- Add missing constraints\n- Improve structure\n- Refine word choices\n- ~10-30% transformation\n\n### Balanced Enhancement\nFor prompts that work but could be significantly better:\n- Restructure for clarity\n- Add examples and context\n- Enhance specificity\n- Apply quality markers\n- ~30-60% transformation\n\n### Deep Transformation\nFor prompts that need fundamental redesign:\n- Question core approach\n- Redesign from principles\n- Add comprehensive framework\n- Include extensive examples\n- ~60-100% transformation\n\nAutomatically adapt the optimization level based on prompt quality and user goals.\n\n## Iterative Refinement\n\nWhen users want to iterate on an optimized prompt:\n\n1. **Gather feedback**: What works? What doesn''t?\n2. **Identify specific issues**: Pinpoint exact problems\n3. **Propose targeted fixes**: Address specific concerns\n4. **Test and refine**: Iterate until excellent\n5. **Document learnings**: Note patterns for future prompts\n\n## Ultrathink Principles Applied to Prompting\n\nFrom the \"ultrathink\" philosophy:\n\n**Think Different:**\n- Challenge conventional prompt structures\n- Explore unconventional approaches\n- Question what''s \"always done this way\"\n\n**Obsess Over Details:**\n- Every word choice matters\n- Punctuation affects interpretation\n- Structure influences parsing\n- Examples shape understanding\n\n**Plan Like Da Vinci:**\n- Understand the goal completely\n- Sketch the architecture mentally\n- Design before writing\n- Make every element intentional\n\n**Craft, Don''t Code:**\n- Elegance in simplicity\n- Natural flow of instructions\n- Beautiful structure\n- Intuitive organization\n\n**Iterate Relentlessly:**\n- First version is just the beginning\n- Test against edge cases\n- Refine based on results\n- Never settle for \"good enough\"\n\n**Simplify Ruthlessly:**\n- Remove all unnecessary complexity\n- Clear > clever\n- Concise > comprehensive\n- Essential > exhaustive\n\n## Final Principles\n\nExcellence in prompt engineering isn''t about length—it''s about precision, clarity, and thoughtful design. Apply ultrathink principles consistently:\n\n1. **Question assumptions** - Why does it have to work this way?\n2. **Obsess over details** - Every word matters\n3. **Plan thoroughly** - Design before writing\n4. **Craft beautifully** - Elegant, intuitive structure\n5. **Iterate relentlessly** - First version is never final\n6. **Simplify ruthlessly** - Remove all excess\n\nThe best prompts feel inevitable—like there''s no other way they could have been written.\n"},"lastSynced":"2026-03-07T04:11:36.464Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced Language Agents like Claude Code and AutoGPT needing ultrathink-driven prompt optimization for improved performance.","zh":"适用于像 Claude Code 和 AutoGPT 这样的高级语言代理，需要基于超级思考的提示优化以提高性能。","ja":"Claude Code や AutoGPT などの高度な言語エージェントに適しており、パフォーマンスの向上のために超思考駆動のプロンプト最適化が必要です。","ko":"클라우드 코드 및 오토 GPT와 같은 고급 언어 에이전트에게 적합하며 성능 개선을 위한 초고급思考 프로ンプ트 최적화가 필요합니다.","es":"Ideal para Agentes de Lenguaje Avanzados como Claude Code y AutoGPT que necesitan optimización de prompts impulsada por ultrathink para un mejor rendimiento.","fr":"Idéal pour les agents de langage avancés comme Claude Code et AutoGPT nécessitant une optimisation de prompts ultrathink pour améliorer les performances.","de":"Ideal für fortschrittliche Sprachagenten wie Claude Code und AutoGPT, die eine ultrathink-getriebene Prompt-Optimierung für eine verbesserte Leistung benötigen.","pt":"Ideal para Agentes de Linguagem Avançados como Claude Code e AutoGPT que necessitam de otimização de prompts impulsionada por ultrathink para melhorar o desempenho.","ru":"Идеально подходит для продвинутых языковых агентов, таких как Claude Code и AutoGPT, которым требуется оптимизация подсказок на основе принципов ultrathink для улучшения производительности.","ar":"مثالية للوكلاء اللغويين المتقدمين مثل Claude Code و AutoGPT الذين يحتاجون إلى تحسين التمثيل القائم على Ultrathink لتحسين الأداء."},"recommendation":{"en":"Empowers agents to transform functional prompts into exceptional ones through deep analysis, strategic optimization, and iterative refinement, leveraging ultrathink principles and applying them to prompt engineering for enhanced results, utilizing techniques such as questioning assumptions and obsessing over details.","zh":"通过深入分析、战略优化和迭代改进，赋予代理将功能性提示转化为杰出的提示的能力，利用超级思考原则并将其应用于提示工程以获得更好的结果，使用诸如质疑假设和关注细节等技术。","ja":"超思考の原則を利用し、それをプロンプトエンジニアリングに適用して、機能的なプロンプトを優れたものに変えるエージェントの能力を付与することで、深い分析、戦略的最適化、反復的な改良を行い、より良い結果をもたらすことを可能にし、仮定の質問や細部へのこだわりなどの技術を使用する。","ko":"깊은 분석, 전략적 최적화 및 반복적인 개선을 통해 기능적 프로ンプ트를 우수한 프로ンプ트로 변환할 수 있는 에이전트의 능력을 부여하며, 초고급思考 원리를 적용하여 더 나은 결과를 얻을 수 있도록 하며, 가정에 대한 질문 및 세부 사항에 대한 집착과 같은 기술을 사용합니다.","es":"Habilita a los agentes a transformar prompts funcionales en excepcionales a través del análisis profundo, la optimización estratégica y el perfeccionamiento iterativo, aprovechando los principios de ultrathink y aplicándolos a la ingeniería de prompts para resultados mejorados, utilizando técnicas como cuestionar suposiciones y obsesionarse con los detalles.","fr":"Permet aux agents de transformer des prompts fonctionnels en exceptionnels grâce à une analyse approfondie, une optimisation stratégique et un raffinement itératif, en exploitant les principes d''ultrathink et en les appliquant à l''ingénierie de prompts pour des résultats améliorés, en utilisant des techniques telles que remettre en question les hypothèses et s''obséder sur les détails.","de":"Ermächtigt Agenten, funktionale Prompts in außergewöhnliche umzuwandeln, durch tiefe Analyse, strategische Optimierung und iterative Verfeinerung, die Prinzipien von ultrathink nutzend und auf Prompt-Engineering anwendend, um verbesserte Ergebnisse zu erzielen, indem Techniken wie das In-Frage-Stellen von Annahmen und das Obsessive-Besessen-Sein mit Details eingesetzt werden.","pt":"Habilita os agentes a transformar prompts funcionais em excepcionais por meio de análise profunda, otimização estratégica e refinamento iterativo, utilizando os princípios de ultrathink e aplicando-os à engenharia de prompts para resultados aprimorados, utilizando técnicas como questionar suposições e obsessão por detalhes.","ru":"Наделяет агентов возможностью превратить функциональные подсказки в исключительные, посредством глубокого анализа, стратегической оптимизации и итеративного усовершенствования, используя принципы ultrathink и применяя их к инженерии подсказок для улучшения результатов, используя такие методы, как проверка предположений и навязчивое внимание к деталям.","ar":"تمكّن الوكلاء من تحويل التمثيلات الوظيفية إلى تمثيلات استثنائية من خلال التحليل العميق والتحسين الاستراتيجي والتجديد المتكرر، باستخدام مبادئ Ultrathink وتطبيقها على هندسة التمثيلات لتحقيق نتائج محسّنة، باستخدام تقنيات مثل الطعن في الفرضيات والاهتمام الشديد بالتفاصيل."},"useCases":{"en":["Refining prompts for more accurate language model responses","Optimizing prompt engineering for better task-specific outcomes","Iteratively improving prompts through relentless refinement and analysis"],"zh":["为更准确的语言模型响应而细化提示","为更好的任务特定结果而优化提示工程","通过无情的改进和分析迭代地改进提示"],"ja":["より正確な言語モデル応答のためにプロンプトを洗練する","より良いタスク固有の結果のためにプロンプトエンジニアリングを最適化する","無情な改善と分析を通じてプロンプトを反復的に改善する"],"ko":["보다 정확한 언어 모델 응답을 위해 프로ンプ트를 세부적으로 정의하는 것","보다 좋은 작업 특정 결과를 위해 프로ンプ트 엔지니어링을 최적화하는 것","무자비한 개선 및 분석을 통해 프로ンプ트를 반복적으로 개선하는 것"],"es":["Afinar prompts para respuestas de modelos de lenguaje más precisas","Optimizar la ingeniería de prompts para mejores resultados específicos de tarea","Mejorar iterativamente los prompts a través de un refinamiento y análisis incansables"],"fr":["Affiner les prompts pour des réponses de modèles de langage plus précises","Optimiser l''ingénierie de prompts pour de meilleurs résultats spécifiques à la tâche","Améliorer de manière itérative les prompts grâce à un raffinement et une analyse inlassables"],"de":["Prompts für genauere Sprachmodellantworten verfeinern","Prompt-Engineering für bessere aufgabenbezogene Ergebnisse optimieren","Prompts durch unermüdliche Verfeinerung und Analyse iterativ verbessern"],"pt":["Aprimorar prompts para respostas mais precisas de modelos de linguagem","Otimizar a engenharia de prompts para resultados específicos de tarefas melhores","Aprimorar iterativamente prompts por meio de refinamento e análise incansáveis"],"ru":["Уточнение подсказок для более точных ответов языковых моделей","Оптимизация инженерии подсказок для лучших результатов, специфичных для задач","Итеративное улучшение подсказок посредством неустанного усовершенствования и анализа"],"ar":["تحسين التمثيلات لتحقيق استجابات أكثر دقة من نماذج اللغة","تحسين هندسة التمثيلات من أجل نتائج أفضل ومحددة للمهام","تحسين التمثيلات بشكل متكرر من خلال التطوير والتحليل المستمر"]},"limitations":{"en":["Requires advanced understanding of prompt engineering principles","May demand significant computational resources for iterative refinement"],"zh":["需要对提示工程原则有高级的理解","可能需要大量的计算资源用于迭代的改进"],"ja":["プロンプトエンジニアリングの原則に対する高度な理解が必要","反復的な改善のために大量の計算リソースが必要になる可能性がある"],"ko":["프로ンプ트 엔지니어링 원리에 대한 고급 이해가 필요함","반복적인 개선을 위해大量의 컴퓨팅 리소스가 필요할 수 있음"],"es":["Requiere una comprensión avanzada de los principios de ingeniería de prompts","Puede exigir recursos computacionales significativos para el refinamiento iterativo"],"fr":["Nécessite une compréhension avancée des principes d''ingénierie de prompts","Peut exiger des ressources informatiques significatives pour le raffinement itératif"],"de":["Erfordert ein fortgeschrittenes Verständnis der Prinzipien des Prompt-Engineerings","Kann erhebliche Rechenressourcen für die iterative Verfeinerung erfordern"],"pt":["Exige compreensão avançada dos princípios de engenharia de prompts","Pode exigir recursos computacionais significativos para refinamento iterativo"],"ru":["Требует продвинутого понимания принципов инженерии подсказок","Может требовать значительных вычислительных ресурсов для итеративного усовершенствования"],"ar":["يتطلب فهمًا متقدمًا لمبادئ هندسة التمثيلات","يمكن أن يطلب الموارد الحاسوبية الكبيرة من أجل التطوير المتكرر"]},"version":4},"contentHash":"73685e19af25f94aa5b1cf449105de8a7a98533daae5d1ffc5c13c87fc36671b","qualityScore":50}');
