INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nopkhun/KO-STOCK-SYSTEM/prompt-optimizer', 'prompt-optimizer', 'nopkhun', 'KO-STOCK-SYSTEM', 'community', 'prompt-optimizer nopkhun KO-STOCK-SYSTEM community The prompt-optimizer skill applies ultrathink principles to prompt engineering, transforming functional prompts into exceptional ones through deep analysis and iterative refinement, benefiting AI agents and developers. prompt-optimizer 是一个 AI 最佳提示优化工具，通过深度分析、战略优化和迭代改进来创建卓越的提示 prompt-optimizer は、深い分析、戦略的最適化、反復的改良を通じて、優れたプロンプトを作成する AI エージェントです prompt-optimizer는 깊은 분석, 전략적 최적화 및 반복적 개선을 통해 탁월한 프롬프트를 생성하는 AI 에이전트입니다 El prompt-optimizer aplica principios de ''ultrathink'' para transformar prompts funcionales en excepcionales a través de análisis profundo y optimización estratégica. Le prompt-optimizer applique des principes d''ultrathink pour transformer des invites fonctionnels en exceptionnels grâce à une analyse approfondie et une optimisation stratégique. Der Prompt-Optimizer wendet Ultrathink-Prinzipien an, um funktionale Prompts in außergewöhnliche durch tiefe Analyse und strategische Optimierung zu verwandeln. Otimizador de Prompt é um agente de IA que transforma prompts funcionais em excepcionais através da análise profunda e otimização estratégica ИИ Агент Prompt Optimizer - это агент, который превращает функциональные промпты в исключительные посредством глубокого анализа и стратегической оптимизации مُحسّن الطلب هو وكيل إصطناعي يتحول الطلبات الوظيفية إلى استثنائية من خلال التحليل العميق والتحسين الاستراتيجي how to use prompt-optimizer what is prompt-optimizer prompt-optimizer alternative prompt-optimizer vs other AI skills prompt-optimizer install prompt-optimizer setup guide ultrathink principles in AI prompt engineering best practices AI prompt optimization techniques AI 提示优化 prompt-optimizer AI 工具 提示工程 ultrathink 深度分析 战略优化 迭代改进 Applies ultrathink principles to prompt engineering Performs deep analysis of prompts for optimization Iterates relentlessly to refine prompts Transforms functional prompts into exceptional ones Questions assumptions and obsesses over details for optimal results Creates prompts that feel like the only right way to ask prompt-optimizer is a skill that uses ultrathink principles to optimize and refine prompts, making them inevitable and effective for AI agents and applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bluewaves-creations/website-foundation/media-generation', 'community', 'bluewaves-creations', 'website-foundation', 'bluewaves-creations/website-foundation', 'media-generation', 0, 0, 50, '2026-03-04T15:15:35Z', '2026-03-07T04:15:10.468Z', '3c3beb253055c430d880fb30f9b6671da6d07a94ff865a568ebe2b0ea62041c9', '{"id":"bluewaves-creations/website-foundation/media-generation","name":"media-generation","description":{"en":"The media-generation skill generates images and videos through Cloudflare AI Gateway, utilizing fal.ai for processing. This technology benefits developers by handling authentication and providing a seamless integration.","zh":"媒体生成使用Cloudflare AI Gateway生成图片和视频，支持Seedream v4.5模型，图片大小为2048x2048，成本约为$0.04每张图片","ja":"メディア生成はCloudflare AI Gatewayを使用して画像と動画を生成し、Seedream v4.5モデルをサポートします。画像サイズは2048x2048で、コストは約$0.04毎の画像です","ko":"미디어 생성은 Cloudflare AI Gateway를 사용하여 이미지 및 비디오를 생성하며 Seedream v4.5 모델을 지원합니다. 이미지 크기는 2048x2048이고 비용은 약 $0.04의 이미지입니다","es":"La generación de medios permite crear imágenes y videos a través de Cloudflare AI Gateway, utilizando la plantilla de Website Foundation. No se requiere clave de API en el código de la aplicación.","fr":"La génération de médias permet de créer des images et des vidéos via Cloudflare AI Gateway, en utilisant le modèle de Website Foundation. Aucune clé d''API n''est requise dans le code de l''application.","de":"Die Mediengenerierung ermöglicht die Erstellung von Bildern und Videos über Cloudflare AI Gateway, unter Verwendung der Website Foundation-Vorlage. Kein API-Schlüssel ist im Anwendungscode erforderlich.","pt":"A geração de mídia permite criar imagens e vídeos personalizados com o Cloudflare AI Gateway e a biblioteca media.ts","ru":"Генерация медиа позволяет создавать индивидуальные изображения и видео с помощью Cloudflare AI Gateway и библиотеки media.ts","ar":"تتيح توليد الوسائط إنشاء صور وفيديوهات مخصصة باستخدام Cloudflare AI Gateway ومكتبة media.ts"},"seo":{"title":{"en":"media-generation: Cloudflare AI Gateway Setup Guide | AI ...","zh":"媒体生成Setup Guide - 基于Cloudflare AI Gateway的图片和视频生成","ja":"メディア生成Setup Guide - Cloudflare AI Gatewayを使用した画像と動画生成","ko":"미디어 생성 Setup Guide - Cloudflare AI Gateway를 사용한 이미지 및 비디오 생성","es":"Generación de Medios: Guía de Configuración con Cloudflar...","fr":"Génération de Médias: Meilleures Pratiques avec Cloudflar...","de":"Mediengenerierung: Einrichtungsleitfaden mit Cloudflare A...","pt":"Guia de Configuração de Geração de Mídia com Cloudflare A...","ru":"Настройка ИИ Агентов для Генерации Медиа с помощью Cloudf...","ar":"دليل إعداد توليد الوسائط باستخدام Cloudflare AI Gateway"},"description":{"en":"Unlock AI-powered media generation with Cloudflare AI Gateway and fal.ai. Learn how to proxy requests and generate images and videos without API keys.","zh":"了解媒体生成的技术细节，使用Cloudflare AI Gateway和fal.ai生成图片和视频，无需API密钥","ja":"メディア生成の技術的詳細を学び、Cloudflare AI Gatewayとfal.aiを使用して画像と動画を生成します。APIキーは不要です","ko":"미디어 생성의 기술적 세부 사항을 학습하고 Cloudflare AI Gateway와 fal.ai를 사용하여 이미지 및 비디오를 생성합니다. API 키가 필요하지 않습니다","es":"Aprende a generar imágenes y videos con la plantilla de Website Foundation y Cloudflare AI Gateway, sin necesidad de clave de API","fr":"Découvrez comment générer des images et des vidéos avec le modèle de Website Foundation et Cloudflare AI Gateway, sans clé d''API","de":"Erfahren Sie, wie Sie Bilder und Videos mit der Website Foundation-Vorlage und Cloudflare AI Gateway erstellen, ohne API-Schlüssel","pt":"Aprenda a gerar imagens e vídeos com o Cloudflare AI Gateway e a biblioteca media.ts, sem necessidade de chave de API","ru":"Узнайте, как генерировать изображения и видео с помощью Cloudflare AI Gateway и библиотеки media.ts, без необходимости API-ключа","ar":"تعلم كيفية توليد الصور والفيديوهات باستخدام Cloudflare AI Gateway ومكتبة media.ts، دون الحاجة إلى مفتاح API"},"definition":{"en":"media-generation is a skill that utilizes Cloudflare AI Gateway to generate images and videos through fal.ai, handling authentication and providing raw responses with image URLs.","zh":"媒体生成是使用AI技术生成图片和视频的过程，使用Cloudflare AI Gateway和fal.ai实现","ja":"メディア生成は、AI技術を使用して画像と動画を生成するプロセスです。Cloudflare AI Gatewayとfal.aiを使用します","ko":"미디어 생성은 AI 기술을 사용하여 이미지 및 비디오를 생성하는 프로세스입니다. Cloudflare AI Gateway와 fal.ai를 사용합니다","es":"La generación de medios es una función que permite crear imágenes y videos a través de Cloudflare AI Gateway","fr":"La génération de médias est une fonction qui permet de créer des images et des vidéos via Cloudflare AI Gateway","de":"Die Mediengenerierung ist eine Funktion, die die Erstellung von Bildern und Videos über Cloudflare AI Gateway ermöglicht","pt":"Geração de mídia é a capacidade de criar imagens e vídeos automaticamente com o auxílio de inteligência artificial","ru":"Генерация медиа - это возможность создавать изображения и видео автоматически с помощью искусственного интеллекта","ar":"توليد الوسائط هو القدرة على إنشاء الصور والفيديوهات تلقائيًا بمساعدة الذكاء الاصطناعي"},"features":{"en":["Generates images using Seedream v4.5 model from ByteDance","Supports default image size of auto_2K (2048x2048)","Handles authentication through Cloudflare AI Gateway","Returns raw Response from fal.ai with images[].url","Exports library functions through src/lib/media.ts","Provides cost-effective image generation at ~$0.04 per image"],"zh":["使用Cloudflare AI Gateway生成图片和视频","支持Seedream v4.5模型","图片大小为2048x2048","成本约为$0.04每张图片","无需API密钥","使用fal.ai生成图片和视频"],"ja":["Cloudflare AI Gatewayを使用して画像と動画を生成する","Seedream v4.5モデルをサポートする","画像サイズは2048x2048","コストは約$0.04毎の画像","APIキーは不要","fal.aiを使用して画像と動画を生成する"],"ko":["Cloudflare AI Gateway를 사용하여 이미지 및 비디오를 생성한다","Seedream v4.5 모델을 지원한다","이미지 크기는 2048x2048","비용은 약 $0.04의 이미지","API 키가 필요하지 않다","fal.ai를 사용하여 이미지 및 비디오를 생성한다"],"es":["Generación de imágenes y videos a través de Cloudflare AI Gateway","Uso de la plantilla de Website Foundation","No se requiere clave de API en el código de la aplicación","Soporte para el modelo Seedream v4.5 (ByteDance)","Tamaño de imagen predeterminado: auto_2K (2048x2048)","Costo aproximado: $0.04 por imagen"],"fr":["Génération d''images et de vidéos via Cloudflare AI Gateway","Utilisation du modèle de Website Foundation","Aucune clé d''API requise dans le code de l''application","Prise en charge du modèle Seedream v4.5 (ByteDance)","Taille d''image par défaut : auto_2K (2048x2048)","Coût approximatif : $0.04 par image"],"de":["Erstellung von Bildern und Videos über Cloudflare AI Gateway","Verwendung der Website Foundation-Vorlage","Kein API-Schlüssel ist im Anwendungscode erforderlich","Unterstützung für das Seedream v4.5-Modell (ByteDance)","Bildgröße (Standard): auto_2K (2048x2048)","Ungefährer Kosten: $0.04 pro Bild"],"pt":["Geração de imagens com o modelo Seedream v4.5","Tamanho padrão de imagem de 2048x2048","Custo de aproximadamente $0,04 por imagem","Retorno de URL da imagem gerada","Autenticação feita pelo gateway, sem necessidade de chave de API"],"ru":["Генерация изображений с помощью модели Seedream v4.5","Стандартный размер изображения 2048x2048","Стоимость примерно $0,04 за изображение","Возвращаемый URL сгенерированного изображения","Аутентификация осуществляется шлюзом, без необходимости API-ключа"],"ar":["توليد الصور باستخدام نموذج Seedream v4.5","الحجم الافتراضي للصورة 2048x2048","التكلفة حوالي 0.04 دولارًا للصورة","إرجاع عنوان URL للصورة المتولدة","التحقق من خلال البوابة، دون الحاجة إلى مفتاح API"]},"keywords":{"en":["how to use media-generation","media-generation setup guide","Cloudflare AI Gateway alternative","media-generation vs fal.ai","media-generation install","what is media-generation","media-generation tutorial","AI-powered media generation","fal.ai integration"],"zh":["媒体生成","Cloudflare AI Gateway","fal.ai","图片生成","视频生成","AI技术","Seedream v4.5","图片大小","成本","API密钥"],"ja":["メディア生成","Cloudflare AI Gateway","fal.ai","画像生成","動画生成","AI技術","Seedream v4.5","画像サイズ","コスト","APIキー"],"ko":["미디어 생성","Cloudflare AI Gateway","fal.ai","이미지 생성","비디오 생성","AI 기술","Seedream v4.5","이미지 크기","비용","API 키"],"es":["generación de medios","Cloudflare AI Gateway","Website Foundation","Seedream v4.5","ByteDance","imagen auto_2K","costo de imagen","desarrollo de aplicaciones","Herramientas de AI"],"fr":["génération de médias","Cloudflare AI Gateway","Website Foundation","Seedream v4.5","ByteDance","image auto_2K","coût de l''image","développement d''applications","Outils d''IA"],"de":["Mediengenerierung","Cloudflare AI Gateway","Website Foundation","Seedream v4.5","ByteDance","Bildgröße auto_2K","Bildkosten","Anwendungsentwicklung","KI-Tools"],"pt":["geração de mídia","Cloudflare AI Gateway","media.ts","Seedream v4.5","tamanho de imagem","custo de imagem","autenticação","API","desenvolvimento web","inteligência artificial"],"ru":["генерация медиа","Cloudflare AI Gateway","media.ts","Seedream v4.5","размер изображения","стоимость изображения","аутентификация","API","веб-разработка","искусственный интеллект"],"ar":["توليد الوسائط","Cloudflare AI Gateway","media.ts","Seedream v4.5","حجم الصورة","تكلفة الصورة","التحقق","API","تطوير الويب","الذكاء الاصطناعي"]}},"owner":"bluewaves-creations","repo":"website-foundation","repoPath":"bluewaves-creations/website-foundation","stars":0,"forks":0,"updatedAt":"2026-03-04T15:15:35Z","topics":[],"category":"community","skillMd":{"name":"media-generation","description":"Generate images and videos using fal.ai models through Cloudflare AI Gateway — understand the API, craft prompts, and configure options. Use when the user mentions generate an image, generate a video, create media, AI image, AI video, fal.ai, seedream, seedance, or media prompt.","bodyPreview":"# Media Generation\n\nWebsite Foundation generates images and videos through Cloudflare AI Gateway, proxying requests to fal.ai. No API key is needed in the application code — the gateway handles authentication.\n\n## Library Functions\n\n`src/lib/media.ts` exports two functions:\n\n### `generateImage(env, prompt, options?)`\n\n- **Model**: Seedream v4.5 (ByteDance)\n- **Default size**: `auto_2K` (2048x2048)\n- **Cost**: ~$0.04 per image\n- **Returns**: Raw `Response` from fal.ai with `images[].url`\n\n### `ge","body":"# Media Generation\n\nWebsite Foundation generates images and videos through Cloudflare AI Gateway, proxying requests to fal.ai. No API key is needed in the application code — the gateway handles authentication.\n\n## Library Functions\n\n`src/lib/media.ts` exports two functions:\n\n### `generateImage(env, prompt, options?)`\n\n- **Model**: Seedream v4.5 (ByteDance)\n- **Default size**: `auto_2K` (2048x2048)\n- **Cost**: ~$0.04 per image\n- **Returns**: Raw `Response` from fal.ai with `images[].url`\n\n### `generateVideo(env, prompt, options?)`\n\n- **Model**: Seedance 1.5 Pro (ByteDance)\n- **Defaults**: 16:9 aspect ratio, 720p, 5 seconds, with audio\n- **Cost**: ~$0.26 per 5s video\n- **Returns**: Raw `Response` from fal.ai with `video.url`\n\n## API Routes\n\nBoth require Cloudflare Access authentication:\n\n- `POST /api/media/generate-image` — Accepts `{ prompt, imageSize? }`\n- `POST /api/media/generate-video` — Accepts `{ prompt, aspectRatio?, resolution?, duration? }`\n\n## Prompt Tips\n\n- Be specific and descriptive — include subject, setting, lighting, style\n- For text in images, Seedream supports rendered text: include `The text \"...\" should appear`\n- For video, describe action and camera movement; include audio cues for sound generation\n- Keep prompts under 500 characters for best results\n\n## References\n\n- [Seedream API reference](references/seedream-api.md) — Full input/output schema for image generation\n- [Seedance API reference](references/seedance-api.md) — Full input/output schema for video generation\n"},"lastSynced":"2026-03-07T04:15:10.468Z","agentAnalysis":{"suitability":{"en":"Perfect for Visual AI Agents needing advanced image and video generation capabilities through Cloudflare AI Gateway and fal.ai","zh":"非常适合需要通过Cloudflare AI Gateway和fal.ai进行高级图像和视频生成的视觉AI代理","ja":"Cloudflare AI Gatewayとfal.aiを介して高度な画像および動画生成が必要な視覚AIエージェントに最適","ko":"Cloudflare AI Gateway와 fal.ai를 통해 고급 이미지 및 비디오 생성이 필요한 시각 AI 에이전트에 적합","es":"Perfecto para Agentes de Inteligencia Artificial Visuales que necesitan capacidades avanzadas de generación de imágenes y videos a través de Cloudflare AI Gateway y fal.ai","fr":"Parfait pour les Agents d''Intelligence Artificielle Visuels nécessitant des capacités avancées de génération d''images et de vidéos via Cloudflare AI Gateway et fal.ai","de":"Perfekt für visuelle KI-Agents, die erweiterte Bild- und Videogenerierungsfunktionen über Cloudflare AI Gateway und fal.ai benötigen","pt":"Perfeito para Agentes de IA Visuais que necessitam de capacidades avançadas de geração de imagens e vídeos por meio do Cloudflare AI Gateway e fal.ai","ru":"Идеально подходит для визуальных агентов ИИ, которым требуются расширенные возможности генерации изображений и видео через Cloudflare AI Gateway и fal.ai","ar":"مثالي للوكلاء الذكاء الاصطناعي البصري الذين يحتاجون إلى قدرات متقدمة لإنشاء الصور والفيديو من خلال Cloudflare AI Gateway و fal.ai"},"recommendation":{"en":"Empowers agents to generate high-quality images and videos using Seedream v4.5 model, handling authentication seamlessly and providing a cost-effective solution at ~$0.04 per image, with support for proxying requests to fal.ai","zh":"赋予代理生成高质量的图像和视频的能力，使用Seedream v4.5模型，处理身份验证，并提供一种经济有效的解决方案，约每张图片$0.04，支持代理请求到fal.ai","ja":"Seedream v4.5モデルを使用して、高品質の画像や動画を生成できるエージェントを可能にし、認証をシームレスに処理し、画像あたり約$0.04のコスト効率の良いソリューションを提供し、fal.aiへのリクエストのプロキシをサポート","ko":"에이전트가 Seedream v4.5 모델을 사용하여 고해상도의 이미지와 비디오를 생성할 수 있도록 하며, 인증을 무결점으로 처리하고, 이미지당 약 $0.04의 비용 효율적인 솔루션을 제공하며, fal.ai로의 요청 프록시를 지원","es":"Permite a los agentes generar imágenes y videos de alta calidad utilizando el modelo Seedream v4.5, manejando la autenticación de forma segura y proporcionando una solución rentable a ~$0.04 por imagen, con soporte para proxy de solicitudes a fal.ai","fr":"Permet aux agents de générer des images et des vidéos de haute qualité en utilisant le modèle Seedream v4.5, en gérant l''authentification de manière sécurisée et en fournissant une solution rentable à ~$0.04 par image, avec un support pour le proxy de requêtes vers fal.ai","de":"Ermöglicht es den Agents, hochwertige Bilder und Videos mithilfe des Seedream v4.5-Modells zu generieren, Authentifizierung nahtlos zu handhaben und eine kostengünstige Lösung bei ~$0.04 pro Bild bereitzustellen, mit Unterstützung für die Proxy-Anfragen an fal.ai","pt":"Habilita os agentes a gerar imagens e vídeos de alta qualidade usando o modelo Seedream v4.5, lidando com autenticação de forma transparente e fornecendo uma solução rentável a ~$0.04 por imagem, com suporte para proxy de solicitações para fal.ai","ru":"Наделяет агентов возможностью генерировать изображения и видео высокого качества с использованием модели Seedream v4.5, обрабатывая аутентификацию бесшовно и предоставляя экономически эффективное решение за ~$0.04 за изображение, с поддержкой прокси-запросов к fal.ai","ar":"تمكّن الوكلاء من إنشاء صور وفیديوهات عالية الجودة باستخدام نموذج Seedream v4.5 ، وتعامل مع المصادقة بسهولة وتقديم حل экономي يبلغ ~$0.04 لكل صورة ، مع دعم استعلامات الوسيط إلى fal.ai"},"useCases":{"en":["Generating images for web applications","Creating videos for social media platforms","Automating visual content creation for marketing campaigns"],"zh":["为Web应用程序生成图像","为社交媒体平台创建视频","自动化营销活动的视觉内容创建"],"ja":["Webアプリケーションの画像生成","ソーシャルメディアプラットフォームの動画作成","マーケティングキャンペーンの視覚コンテンツの自動生成"],"ko":["웹 애플리케이션을 위한 이미지 생성","소셜 미디어 플랫폼을 위한 비디오 생성","마케팅 캠페인을 위한 시각적 콘텐츠 자동 생성"],"es":["Generación de imágenes para aplicaciones web","Creación de videos para plataformas de redes sociales","Automatización de la creación de contenido visual para campañas de marketing"],"fr":["Génération d''images pour les applications web","Création de vidéos pour les plateformes de réseaux sociaux","Automatisation de la création de contenu visuel pour les campagnes de marketing"],"de":["Generierung von Bildern für Webanwendungen","Erstellung von Videos für soziale Medienplattformen","Automatisierung der Erstellung von visuellem Inhalt für Marketingkampagnen"],"pt":["Geração de imagens para aplicações web","Criação de vídeos para plataformas de mídia social","Automação da criação de conteúdo visual para campanhas de marketing"],"ru":["Генерация изображений для веб-приложений","Создание видео для социальных медиа-платформ","Автоматизация создания визуального контента для маркетинговых кампаний"],"ar":["إنشاء صور للتطبيقات على الويب","إنشاء فيديوهات لمنصات الإعلام الاجتماعي","تأتمة إنشاء المحتوى المرئي للحملات التسويقية"]},"limitations":{"en":["Requires Cloudflare AI Gateway and fal.ai integration","Costs ~$0.04 per image generated","Limited to Seedream v4.5 model"],"zh":["需要Cloudflare AI Gateway和fal.ai集成","每张生成的图片约花费$0.04","仅限Seedream v4.5模型"],"ja":["Cloudflare AI Gatewayとfal.aiの統合が必要","生成される画像ごとに約$0.04のコスト","Seedream v4.5モデルに限定"],"ko":["Cloudflare AI Gateway와 fal.ai 통합이 필요","생성된 이미지당 약 $0.04의 비용","Seedream v4.5 모델로 제한"],"es":["Requiere integración con Cloudflare AI Gateway y fal.ai","Cuesta ~$0.04 por imagen generada","Limitado al modelo Seedream v4.5"],"fr":["Nécessite une intégration avec Cloudflare AI Gateway et fal.ai","Coûte ~$0.04 par image générée","Limité au modèle Seedream v4.5"],"de":["Benötigt Integration mit Cloudflare AI Gateway und fal.ai","Kosten von ~$0.04 pro generiertem Bild","Begrenzt auf das Seedream v4.5-Modell"],"pt":["Requer integração com Cloudflare AI Gateway e fal.ai","Custa ~$0.04 por imagem gerada","Limitado ao modelo Seedream v4.5"],"ru":["Требует интеграции с Cloudflare AI Gateway и fal.ai","Стоит ~$0.04 за сгенерированное изображение","Ограничен моделью Seedream v4.5"],"ar":["يتطلب تكامل مع Cloudflare AI Gateway و fal.ai","يكلف ~$0.04 لكل صورة تم إنشاؤها","محدود بنموذج Seedream v4.5"]},"version":4},"contentHash":"3c3beb253055c430d880fb30f9b6671da6d07a94ff865a568ebe2b0ea62041c9","qualityScore":50}');
