INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bluewaves-creations/website-foundation/media-generation', 'media-generation', 'bluewaves-creations', 'website-foundation', 'community', 'media-generation bluewaves-creations website-foundation community The media-generation skill generates images and videos through Cloudflare AI Gateway, utilizing fal.ai for processing. This technology benefits developers by handling authentication and providing a seamless integration. 媒体生成使用Cloudflare AI Gateway生成图片和视频，支持Seedream v4.5模型，图片大小为2048x2048，成本约为$0.04每张图片 メディア生成はCloudflare AI Gatewayを使用して画像と動画を生成し、Seedream v4.5モデルをサポートします。画像サイズは2048x2048で、コストは約$0.04毎の画像です 미디어 생성은 Cloudflare AI Gateway를 사용하여 이미지 및 비디오를 생성하며 Seedream v4.5 모델을 지원합니다. 이미지 크기는 2048x2048이고 비용은 약 $0.04의 이미지입니다 La generación de medios permite crear imágenes y videos a través de Cloudflare AI Gateway, utilizando la plantilla de Website Foundation. No se requiere clave de API en el código de la aplicación. La génération de médias permet de créer des images et des vidéos via Cloudflare AI Gateway, en utilisant le modèle de Website Foundation. Aucune clé d''API n''est requise dans le code de l''application. Die Mediengenerierung ermöglicht die Erstellung von Bildern und Videos über Cloudflare AI Gateway, unter Verwendung der Website Foundation-Vorlage. Kein API-Schlüssel ist im Anwendungscode erforderlich. A geração de mídia permite criar imagens e vídeos personalizados com o Cloudflare AI Gateway e a biblioteca media.ts Генерация медиа позволяет создавать индивидуальные изображения и видео с помощью Cloudflare AI Gateway и библиотеки media.ts تتيح توليد الوسائط إنشاء صور وفيديوهات مخصصة باستخدام Cloudflare AI Gateway ومكتبة media.ts how to use media-generation media-generation setup guide Cloudflare AI Gateway alternative media-generation vs fal.ai media-generation install what is media-generation media-generation tutorial AI-powered media generation fal.ai integration 媒体生成 Cloudflare AI Gateway fal.ai 图片生成 视频生成 AI技术 Seedream v4.5 图片大小 成本 API密钥 Generates images using Seedream v4.5 model from ByteDance Supports default image size of auto_2K (2048x2048) Handles authentication through Cloudflare AI Gateway Returns raw Response from fal.ai with images[].url Exports library functions through src/lib/media.ts Provides cost-effective image generation at ~$0.04 per image media-generation is a skill that utilizes Cloudflare AI Gateway to generate images and videos through fal.ai, handling authentication and providing raw responses with image URLs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kreuzberg-dev/kreuzberg/kreuzberg', 'community', 'kreuzberg-dev', 'kreuzberg', 'kreuzberg-dev/kreuzberg', 'kreuzberg', 0, 0, 50, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:32.261Z', '4ec8fa91d9dd48bafcb32556b244d2198f6745dfadfad81fe33d33b8b3f8d316', '{"id":"kreuzberg-dev/kreuzberg/kreuzberg","name":"kreuzberg","description":{"en":"Kreuzberg is a polyglot document intelligence framework that extracts text, metadata, and structured information from various file formats, benefiting developers and data analysts. It supports Rust, Python, Ruby, Java, and more.","zh":"Kreuzberg 文档智能框架是一个高性能的文档解析和提取库，支持 75+ 格式。它提供 Rust 核心和原生绑定，适用于多种编程语言","ja":"Kreuzberg ドキュメントインテリジェンスフレームワークは、高性能のドキュメント解析と抽出ライブラリです。75+ の形式をサポートし、Rust コアとネイティブバインディングを提供します","ko":"Kreuzberg 문서 인텔리전스 프레임워크는 높은 성능의 문서 파싱 및 추출 라이브러리입니다. 75+ 형식을 지원하며 Rust 코어 및 네이티브 바인딩을 제공합니다","es":"Kreuzberg es un framework de inteligencia de documentos de alto rendimiento con núcleo de Rust que extrae texto, metadatos y información estructurada de 75+ formatos de archivo.","fr":"Kreuzberg est un framework d''intelligence de documents haute performance à base de Rust qui extrait du texte, des métadonnées et des informations structurées de 75+ formats de fichiers.","de":"Kreuzberg ist ein Hochleistungs-Dokumentenintelligenz-Framework mit Rust-Kern, das Text, Metadaten und strukturierte Informationen aus 75+ Dateiformaten extrahiert.","pt":"O Kreuzberg é uma estrutura de inteligência de documentos de alto desempenho com um núcleo Rust e ligações nativas para Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP e Elixir.","ru":"Kreuzberg - это высокопроизводительная платформа интеллектуального извлечения документов с ядром Rust и родными связями для Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP и Elixir.","ar":"Kreuzberg هو إطار ذكاء المستندات عالي الأداء مع نواة