INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kreuzberg-dev/kreuzberg/kreuzberg', 'kreuzberg', 'kreuzberg-dev', 'kreuzberg', 'community', 'kreuzberg kreuzberg-dev kreuzberg community Kreuzberg is a polyglot document intelligence framework that extracts text, metadata, and structured information from various file formats, benefiting developers and data analysts. It supports Rust, Python, Ruby, Java, and more. Kreuzberg 文档智能框架是一个高性能的文档解析和提取库，支持 75+ 格式。它提供 Rust 核心和原生绑定，适用于多种编程语言 Kreuzberg ドキュメントインテリジェンスフレームワークは、高性能のドキュメント解析と抽出ライブラリです。75+ の形式をサポートし、Rust コアとネイティブバインディングを提供します Kreuzberg 문서 인텔리전스 프레임워크는 높은 성능의 문서 파싱 및 추출 라이브러리입니다. 75+ 형식을 지원하며 Rust 코어 및 네이티브 바인딩을 제공합니다 Kreuzberg es un framework de inteligencia de documentos de alto rendimiento con núcleo de Rust que extrae texto, metadatos y información estructurada de 75+ formatos de archivo. Kreuzberg est un framework d''intelligence de documents haute performance à base de Rust qui extrait du texte, des métadonnées et des informations structurées de 75+ formats de fichiers. Kreuzberg ist ein Hochleistungs-Dokumentenintelligenz-Framework mit Rust-Kern, das Text, Metadaten und strukturierte Informationen aus 75+ Dateiformaten extrahiert. O Kreuzberg é uma estrutura de inteligência de documentos de alto desempenho com um núcleo Rust e ligações nativas para Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP e Elixir. Kreuzberg - это высокопроизводительная платформа интеллектуального извлечения документов с ядром Rust и родными связями для Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP и Elixir. Kreuzberg هو إطار ذكاء المستندات عالي الأداء مع نواة Rust وروابط محلية ل Python و Node.js/TypeScript و Ruby و Go و Java و C# و PHP و Elixir. how to use kreuzberg kreuzberg alternative kreuzberg install document extraction software kreuzberg vs tesseract kreuzberg setup guide polyglot document intelligence rust document extraction kreuzberg python binding Kreuzberg 文档智能框架 文档解析 文档提取 Rust Python Ruby Java AIエージェント 文档智能 Extracts text, tables, metadata, and images from 75+ file formats including PDF, Office documents, and images with OCR Supports native bindings for Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP, and Elixir Performs OCR on scanned documents or images Extracts metadata and structured information from HTML, email, archives, and academic formats Available for use via CLI, REST API, or MCP server Kreuzberg is a high-performance document intelligence library with a Rust core, enabling extraction of text, tables, metadata, and images from multiple file formats.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('boisenoise/skills-collections/fastapi-templates', 'community', 'boisenoise', 'skills-collections', 'boisenoise/skills-collections', 'fastapi-templates', 0, 0, 50, '2026-03-08T01:57:15.279Z', '2026-03-08T02:00:48.769Z', '5e7131af88753376f5aac6b40ec51d93e41c6e89c2ef29cc0507cb1362a3d043', '{"id":"boisenoise/skills-collections/fastapi-templates","name":"fastapi-templates","description":{"en":"fastapi-templates provides production-ready FastAPI project structures for building high-performance APIs. It benefits developers starting new FastAPI projects from scratch.","zh":"FastAPI 项目模板提供生产就绪的项目结构，包括异步模式、依赖注入和中间件","ja":"FastAPI プロジェクトテンプレートは、非同期パターン、依存性注入、ミドルウェアを含むプロダクションレディのプロジェクト構造を提供します","ko":"FastAPI 프로젝트 템플릿은 비동기 패턴, 의존성 주입, 미들웨어를 포함한 프로덕션 레디 프로젝트 구조를 제공합니다","es":"FastAPI-templates ofrece estructuras de proyectos de FastAPI listas para la producción con patrones asíncronos y mejores prácticas","fr":"FastAPI-templates propose des structures de projets FastAPI prêtes pour la production avec des modèles asynchrones et les meilleures pratiques","de":"FastAPI-templates bietet produktionsreife FastAPI-Projektstrukturen mit asynchronen Mustern und Best Practices","pt":"FastAPI Templates fornece estruturas de projeto prontas para produção com padrões assíncronos e boas práticas para construir APIs de alto desempenho","ru":"Шаблоны FastAPI предоставляют производственные проектные структуры с асинхронными шаблонами и лучшими практиками для построения высокопроизводительных API с ИИ Агентами","ar":"قوالب FastAPI توفر هياكل مشروع جاهزة للانتاج مع الأنماط غير المتزامنة وأفضل الممارسات لإنشاء APIs عالية الأداء مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"fastapi-templates: Production-Ready FastAPI Project Setup...","zh":"FastAPI 项目模板设置指南 - 使用异步模式和依赖注入","ja":"FastAPI プロジェクトテンプレートのベストプラクティス - 非同期パターンと依存性注入","ko":"FastAPI 프로젝트 템플릿 설정 가이드 - 비동기 패턴과 의존성 주입","es":"Plantillas de FastAPI: Guía de Configuración para APIs de...","fr":"Modèles de FastAPI: Guide de Mise en Place pour les APIs ...","de":"FastAPI-Vorlagen: Einrichtungsleitfaden für Hochleistungs...","pt":"FastAPI Templates: Guia de Configuração para APIs de Alto...","ru":"Шаблоны FastAPI: Настройка производительных API с ИИ Аген...","ar":"قوالب FastAPI: دليل الإعداد لإنشاء APIs عالية الأداء مع أ..."},"description":{"en":"Discover how to kickstart high-performance APIs with fastapi-templates. Learn to set up async REST APIs, middleware, and dependency injection with ease.","zh":"使用 FastAPI 项目模板构建高性能 API，包括异步 REST API、依赖注入和中间件","ja":"FastAPI プロジェクトテンプレートを使用して、高性能 API を構築します。非同期 REST API、依存性注入、ミドルウェアなど","ko":"FastAPI 프로젝트 템플릿을 사용하여 높은 성능의 API를 구축합니다. 비동기 REST API, 의존성 주입, 미들웨어 등","es":"Aprende a configurar proyectos de FastAPI con patrones asíncronos, inyección de dependencias y mejores prácticas para APIs de alto rendimiento","fr":"Découvrez comment configurer des projets FastAPI avec des modèles asynchrones, injection de dépendances et meilleures pratiques pour les APIs hautes performa...","de":"Erfahren Sie, wie Sie FastAPI-Projekte mit asynchronen Mustern, Abhängigkeitsinjektion und Best Practices für Hochleistungs-APIs einrichten","pt":"Aprenda a criar APIs de alto desempenho com FastAPI Templates, incluindo padrões assíncronos, injeção de dependência e middleware","ru":"Изучите создание производительных API с FastAPI Templates, включая асинхронные шаблоны, внедрение зависимостей и middleware с помощью ИИ Агентов","ar":"تعلم كيفية إنشاء APIs عالية الأداء مع قوالب FastAPI، بما في ذلك الأنماط غير المتزامنة و الحقن التلقائي و وسيط الخدمة باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"fastapi-templates is a collection of production-ready FastAPI project structures with async patterns, dependency injection, and middleware for high-performance APIs.","zh":"FastAPI 项目模板是一种预定义的项目结构，用于构建高性能 API","ja":"FastAPI プロジェクトテンプレートは、高性能 API を構築するために事前に定義されたプロジェクト構造です","ko":"FastAPI 프로젝트 템플릿은 높은 성능의 API를 구축하기 위한 事前に 정의된 프로젝트 구조입니다","es":"FastAPI-templates es un conjunto de plantillas para proyectos de FastAPI que proporcionan estructuras de proyecto asíncronas y de alto rendimiento","fr":"FastAPI-templates est un ensemble de modèles pour les projets FastAPI qui fournissent des structures de projet asynchrones et hautes performances","de":"FastAPI-templates ist eine Sammlung von Vorlagen für FastAPI-Projekte, die asynchrone und hochleistungsstarke Projektstrukturen bereitstellen","pt":"FastAPI Templates são estruturas de projeto prontas para produção que utilizam padrões assíncronos e boas práticas para construir APIs de alto desempenho","ru":"Шаблоны FastAPI - это производственные проектные структуры, использующие асинхронные шаблоны и лучшие практики для построения высокопроизводительных API","ar":"قوالب FastAPI هي هياكل مشروع جاهزة للانتاج التي تستخدم الأنماط غير المتزامنة وأفضل الممارسات لإنشاء APIs عالية الأداء"},"features":{"en":["Production-ready FastAPI project structures with async patterns","Dependency injection for efficient resource management","Middleware support for customized API behavior","Async REST API implementation with Python","Integration with PostgreSQL and MongoDB for database management","Proper project structure and testing setup for high-performance APIs"],"zh":["异步模式支持","依赖注入","中间件支持","PostgreSQL 和 MongoDB 支持","生产就绪的项目结构"],"ja":["非同期パターンのサポート","依存性注入","ミドルウェアのサポート","PostgreSQL と MongoDB のサポート","プロダクションレディのプロジェクト構造"],"ko":["비동기 패턴 지원","의존성 주입","미들웨어 지원","PostgreSQL 및 MongoDB 지원","프로덕션 레디 프로젝트 구조"],"es":["Patrones asíncronos para APIs de alto rendimiento","Inyección de dependencias para una mejor organización del código","Middleware para la gestión de solicitudes y respuestas","Estructuras de proyecto listas para la producción","Compatibilidad con PostgreSQL y MongoDB","Pruebas y depuración integradas"],"fr":["Modèles asynchrones pour les APIs hautes performances","Injection de dépendances pour une meilleure organisation du code","Middleware pour la gestion des requêtes et réponses","Structures de projet prêtes pour la production","Compatibilité avec PostgreSQL et MongoDB","Tests et débogage intégrés"],"de":["Asynchrone Muster für Hochleistungs-APIs","Abhängigkeitsinjektion für eine bessere Codeorganisation","Middleware für die Anfrage- und Antwortverwaltung","Produktionsreife Projektstrukturen","Kompatibilität mit PostgreSQL und MongoDB","Integrierte Tests und Fehlersuche"],"pt":["Padrões assíncronos para APIs de alto desempenho","Injeção de dependência para gerenciamento de dependências","Middleware para tratamento de requisições e respostas","Suporte a PostgreSQL e MongoDB para armazenamento de dados","Estruturas de projeto prontas para produção com testes"],"ru":["Асинхронные шаблоны для высокопроизводительных API","Внедрение зависимостей для управления зависимостями","Middleware для обработки запросов и ответов","Поддержка PostgreSQL и MongoDB для хранения данных","Производственные проектные структуры с тестами"],"ar":["الأنماط غير المتزامنة لإنشاء APIs عالية الأداء","الحقن التلقائي لإدارة التبعيات","وسيط الخدمة لمعالجة الطلبات والاستجابات","دعم PostgreSQL و MongoDB لتخزين البيانات","هياكل مشروع جاهزة للانتاج مع الاختبارات"]},"keywords":{"en":["how to use fastapi-templates","fastapi-templates setup guide","fastapi-templates alternative","fastapi-templates vs Flask","fastapi-templates install","fastapi-templates tutorial","fastapi-templates async REST API","fastapi-templates PostgreSQL integration","fastapi-templates MongoDB setup"],"zh":["FastAPI 项目模板","异步模式","依赖注入","中间件","PostgreSQL","MongoDB","高性能 API","AI エージェント","FastAPI 设置指南"],"ja":["FastAPI プロジェクトテンプレート","非同期パターン","依存性注入","ミドルウェア","PostgreSQL","MongoDB","高性能 API","AI エージェント","FastAPI ベストプラクティス"],"ko":["FastAPI 프로젝트 템플릿","비동기 패턴","의존성 주입","미들웨어","PostgreSQL","MongoDB","높은 성능의 API","AI 에이전트","FastAPI 설정 가이드"],"es":["FastAPI","plantillas de FastAPI","APIs de alto rendimiento","patrones asíncronos","inyección de dependencias","middleware","PostgreSQL","MongoDB","desarrollo de APIs"],"fr":["FastAPI","modèles de FastAPI","APIs hautes performances","modèles asynchrones","injection de dépendances","middleware","PostgreSQL","MongoDB","développement d''APIs"],"de":["FastAPI","FastAPI-Vorlagen","Hochleistungs-APIs","asynchrone Muster","Abhängigkeitsinjektion","Middleware","PostgreSQL","MongoDB","API-Entwicklung"],"pt":["FastAPI Templates","APIs de alto desempenho","Padrões assíncronos","Injeção de dependência","Middleware","PostgreSQL","MongoDB","Desenvolvimento de APIs"],"ru":["Шаблоны FastAPI","Высокопроизводительные API","Асинхронные шаблоны","Внедрение зависимостей","Middleware","PostgreSQL","MongoDB","Разработка API"],"ar":["قوالب FastAPI","APIs عالية الأداء","الأنماط غير المتزامنة","الحقن التلقائي","وسيط الخدمة","PostgreSQL","MongoDB","تطوير APIs"]}},"owner":"boisenoise","repo":"skills-collections","repoPath":"boisenoise/skills-collections","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.279Z","topics":[],"category":"community","skillMd":{"name":"fastapi-templates","description":"Create production-ready FastAPI projects with async patterns, dependency injection, and comprehensive error handling. Use when building new FastAPI applications or setting up backend API projects.","bodyPreview":"# FastAPI Project Templates\n\nProduction-ready FastAPI project structures with async patterns, dependency injection, middleware, and best practices for building high-performance APIs.\n\n## Use this skill when\n\n- Starting new FastAPI projects from scratch\n- Implementing async REST APIs with Python\n- Building high-performance web services and microservices\n- Creating async applications with PostgreSQL, MongoDB\n- Setting up API projects with proper structure and testing\n\n## Do not use this skill when","body":"# FastAPI Project Templates\n\nProduction-ready FastAPI project structures with async patterns, dependency injection, middleware, and best practices for building high-performance APIs.\n\n## Use this skill when\n\n- Starting new FastAPI projects from scratch\n- Implementing async REST APIs with Python\n- Building high-performance web services and microservices\n- Creating async applications with PostgreSQL, MongoDB\n- Setting up API projects with proper structure and testing\n\n## Do not use this skill when\n\n- The task is unrelated to fastapi project templates\n- You need a different domain or tool outside this scope\n\n## Instructions\n\n- Clarify goals, constraints, and required inputs.\n- Apply relevant best practices and validate outcomes.\n- Provide actionable steps and verification.\n- If detailed examples are required, open `resources/implementation-playbook.md`.\n\n## Resources\n\n- `resources/implementation-playbook.md` for detailed patterns and examples.\n"},"lastSynced":"2026-03-08T02:00:48.769Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Web Development Agents needing high-performance API structures with async patterns and dependency injection.","zh":"适合需要高性能API结构、异步模式和依赖注入的Python Web开发代理。","ja":"Python Web開発エージェントが、高性能のAPI構造、非同期パターン、依存性注入を必要とする場合に最適です。","ko":"고성능 API 구조, 비동기 패턴 및 의존성 주입이 필요한 Python 웹 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo Web de Python que necesitan estructuras de API de alto rendimiento con patrones asíncronos e inyección de dependencias.","fr":"Parfait pour les agents de développement Web Python nécessitant des structures d''API haute performance avec des modèles asynchrones et une injection de dépendances.","de":"Perfekt für Python-Web-Entwicklungsagenten, die hochleistungsstarke API-Strukturen mit asynchronen Mustern und Abhängigkeitsinjektion benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Web Python que necessitam de estruturas de API de alto desempenho com padrões assíncronos e injeção de dependência.","ru":"Идеально подходит для агентов веб-разработки Python, которым требуются высокопроизводительные структуры API с асинхронными шаблонами и внедрением зависимостей.","ar":"مثالي للوكلاء الذين يطورون ويب بايثون الذين يحتاجون إلى هياكل واجهة برمجة التطبيقات عالية الأداء مع أنماط غير متزامنة وحقن التبعيات."},"recommendation":{"en":"Empowers agents to build production-ready FastAPI projects with async REST APIs, middleware, and best practices for high-performance web services and microservices using Python, PostgreSQL, and MongoDB.","zh":"赋予代理构建生产就绪的FastAPI项目的能力，具有异步REST API、中间件以及使用Python、PostgreSQL和MongoDB的高性能Web服务和微服务的最佳实践。","ja":"エージェントが、Python、PostgreSQL、MongoDBを使用した高性能のWebサービスとマイクロサービス、および非同期REST API、ミドルウェア、ベストプラクティスを備えたプロダクションレディのFastAPIプロジェクトを構築できる力を与えます。","ko":"에이전트가 Python, PostgreSQL 및 MongoDB를 사용하여 생산 준비가 완료된 FastAPI 프로젝트를 구축할 수 있는 능력을 부여합니다. 비동기 REST API, 미들웨어 및 고성능 웹 서비스와 마이크로 서비스에 대한 모범 사례가 포함됩니다.","es":"Habilita a los agentes a crear proyectos de FastAPI listos para producción con API REST asíncronas, middleware y mejores prácticas para servicios web y microservicios de alto rendimiento que utilizan Python, PostgreSQL y MongoDB.","fr":"Permet aux agents de créer des projets FastAPI prêts pour la production avec des API REST asynchrones, des middleware et des meilleures pratiques pour des services web et des microservices haute performance utilisant Python, PostgreSQL et MongoDB.","de":"Ermächtigt Agenten, produktionsbereite FastAPI-Projekte mit asynchronen REST-APIs, Middleware und Best Practices für hochleistungsstarke Webdienste und Microdienste mit Python, PostgreSQL und MongoDB zu erstellen.","pt":"Permite que os agentes criem projetos FastAPI prontos para produção com APIs REST assíncronas, middleware e melhores práticas para serviços da web e microsserviços de alto desempenho usando Python, PostgreSQL e MongoDB.","ru":"Позволяет агентам создавать проекты FastAPI, готовые к производству, с асинхронными REST API, middleware и лучшими практиками для высокопроизводительных веб-сервисов и микросервисов, использующих Python, PostgreSQL и MongoDB.","ar":"تمكن الوكلاء من إنشاء مشاريع FastAPI جاهزة للإنتاج مع واجهات برمجة التطبيقات REST غير المتزامنة وبرامج الوسائط والأساليب المثلى لخدمات الويب وأداء المايكروسيرفس عالية الأداء باستخدام بايثون وبوستجري إس كيو إل ومونغو دي بي."},"useCases":{"en":["Building high-performance web services with async patterns","Implementing REST APIs with Python and FastAPI","Setting up API projects with proper structure and testing for PostgreSQL and MongoDB"],"zh":["使用异步模式构建高性能Web服务","使用Python和FastAPI实现REST API","为PostgreSQL和MongoDB设置具有适当结构和测试的API项目"],"ja":["非同期パターンを使用した高性能Webサービスの構築","PythonとFastAPIを使用したREST APIの実装","PostgreSQLとMongoDBのための適切な構造とテストを備えたAPIプロジェクトの設定"],"ko":["비동기 패턴을 사용하여 고성능 웹 서비스 구축","Python 및 FastAPI를 사용하여 REST API 구현","PostgreSQL 및 MongoDB를 위한 적절한 구조 및 테스트와 함께 API 프로젝트 설정"],"es":["Creación de servicios web de alto rendimiento con patrones asíncronos","Implementación de API REST con Python y FastAPI","Configuración de proyectos de API con estructura y pruebas adecuadas para PostgreSQL y MongoDB"],"fr":["Création de services web haute performance avec des modèles asynchrones","Mise en œuvre d''API REST avec Python et FastAPI","Configuration de projets d''API avec structure et tests appropriés pour PostgreSQL et MongoDB"],"de":["Erstellung von Webdiensten mit hoher Leistung und asynchronen Mustern","Implementierung von REST-APIs mit Python und FastAPI","Einrichtung von API-Projekten mit geeigneter Struktur und Tests für PostgreSQL und MongoDB"],"pt":["Construir serviços da web de alto desempenho com padrões assíncronos","Implementar APIs REST com Python e FastAPI","Configurar projetos de API com estrutura apropriada e testes para PostgreSQL e MongoDB"],"ru":["Построение высокопроизводительных веб-сервисов с асинхронными шаблонами","Реализация REST API с помощью Python и FastAPI","Настройка проектов API с правильной структурой и тестированием для PostgreSQL и MongoDB"],"ar":["بناء خدمات الويب عالية الأداء مع الأنماط غير المتزامنة","تنفيذ واجهات برمجة التطبيقات REST باستخدام بايثون و Fas