INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('boisenoise/skills-collections/fastapi-templates', 'fastapi-templates', 'boisenoise', 'skills-collections', 'community', 'fastapi-templates boisenoise skills-collections community fastapi-templates provides production-ready FastAPI project structures for building high-performance APIs. It benefits developers starting new FastAPI projects from scratch. FastAPI 项目模板提供生产就绪的项目结构，包括异步模式、依赖注入和中间件 FastAPI プロジェクトテンプレートは、非同期パターン、依存性注入、ミドルウェアを含むプロダクションレディのプロジェクト構造を提供します FastAPI 프로젝트 템플릿은 비동기 패턴, 의존성 주입, 미들웨어를 포함한 프로덕션 레디 프로젝트 구조를 제공합니다 FastAPI-templates ofrece estructuras de proyectos de FastAPI listas para la producción con patrones asíncronos y mejores prácticas FastAPI-templates propose des structures de projets FastAPI prêtes pour la production avec des modèles asynchrones et les meilleures pratiques FastAPI-templates bietet produktionsreife FastAPI-Projektstrukturen mit asynchronen Mustern und Best Practices FastAPI Templates fornece estruturas de projeto prontas para produção com padrões assíncronos e boas práticas para construir APIs de alto desempenho Шаблоны FastAPI предоставляют производственные проектные структуры с асинхронными шаблонами и лучшими практиками для построения высокопроизводительных API с ИИ Агентами قوالب FastAPI توفر هياكل مشروع جاهزة للانتاج مع الأنماط غير المتزامنة وأفضل الممارسات لإنشاء APIs عالية الأداء مع أدوات الذكاء الاصطناعي how to use fastapi-templates fastapi-templates setup guide fastapi-templates alternative fastapi-templates vs Flask fastapi-templates install fastapi-templates tutorial fastapi-templates async REST API fastapi-templates PostgreSQL integration fastapi-templates MongoDB setup FastAPI 项目模板 异步模式 依赖注入 中间件 PostgreSQL MongoDB 高性能 API AI エージェント FastAPI 设置指南 Production-ready FastAPI project structures with async patterns Dependency injection for efficient resource management Middleware support for customized API behavior Async REST API implementation with Python Integration with PostgreSQL and MongoDB for database management Proper project structure and testing setup for high-performance APIs fastapi-templates is a collection of production-ready FastAPI project structures with async patterns, dependency injection, and middleware for high-performance APIs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ehmo/platform-design-skills/ipados-design-guidelines', 'community', 'ehmo', 'platform-design-skills', 'ehmo/platform-design-skills', 'ipados-design-guidelines', 0, 0, 50, '2026-03-08T01:57:15.285Z', '2026-03-08T02:00:56.516Z', 'd44650dc044218c7f41860a75656dfe0f244189d2033f4bcd17a8804b3a8950c', '{"id":"ehmo/platform-design-skills/ipados-design-guidelines","name":"ipados-design-guidelines","description":{"en":"The ipados-design-guidelines skill provides comprehensive rules for building iPad-native apps following Apple''s Human Interface Guidelines, benefiting developers who want to create adaptive layouts and multitasking support.","zh":"iPadOS 设计指南 AI 代理技能提供 300+ 行动规则，帮助开发者构建和评估原生 iPad 应用，遵循 Apple HIG 和 WCAG 2.2","ja":"iPadOS デザインガイドライン AI エージェントスキルは、300以上のアクションルールを提供して、開発者がネイティブ iPad アプリを構築および評価するのに役立ちます。Apple HIG と WCAG 2.2 に準拠しています","ko":"iPadOS 디자인 가이드라인 AI 에이전트 스킬은 300개 이상의 액션 규칙을 제공하여 개발자가 네이티브 iPad 앱을 구축하고 평가하는 데 도움을 주며 Apple HIG 및 WCAG 2.2를 준수합니다","es":"El conjunto de habilidades de diseño de iPadOS proporciona reglas para desarrollar aplicaciones nativas de iPad","fr":"L''ensemble de compétences de conception d''iPadOS fournit des règles pour développer des applications natives iPad","de":"Das iPadOS-Design-Skill-Set bietet Regeln für die Entwicklung von nativen iPad-Apps","pt":"As diretrizes de design do iPadOS fornecem regras para criar aplicativos nativos para iPad, incluindo layouts adaptáveis e interações de ponteiro","ru":"Руководство по дизайну iPadOS предоставляет правила для создания родных приложений для iPad, включая адаптивные макеты и взаимодействия с указателем","ar":"دليل تصميم iPadOS يوفر قواعد لإنشاء تطبيقات أصلية لجهاز iPad، بما في ذلك التصاميم القابلة للتكيف وتفاعلات المؤشر"},"seo":{"title":{"en":"ipados-design-guidelines: Best Practices for AI Agents | ...","zh":"iPadOS 设计指南设置指南 - AIエージェント集成","ja":"iPadOS デザインガイドラインセットアップガイド - AIエージェント","ko":"iPadOS 디자인 가이드ライン 설정 가이드 - AI 에이전트","es":"Guía de configuración para pautas de diseño de iPadOS","fr":"Guide de mise en place des directives de conception d''iPadOS","de":"Einrichtungsleitfaden für iPadOS-Designrichtlinien","pt":"iPadOS Design Guidelines: Guia de Configuração para Desen...","ru":"ИИ Агенты для iPadOS: Руководство по Настройке","ar":"دليل تصميم iPadOS: إرشادات الإعداد للمطورين"},"description":{"en":"Unlock iPad-native app development with 300+ actionable rules from Apple HIG. Get started with ipados-design-guidelines today and optimize your app''s design!","zh":"了解如何使用 iPadOS 设计指南 AI 代理技能构建和评估原生 iPad 应用，包括 300+ 行动规则和 Apple HIG 集成","ja":"iPadOS デザインガイドライン AI エージェントスキルを使用して、ネイティブ iPad アプリを構築および評価する方法について学びます。300以上のアクションルールと Apple HIG を含みます","ko":"iPadOS 디자인 가이드라인 AI 에이전트 스킬을 사용하여 네이티브 iPad 앱을 구축하고 평가하는 방법에 대해 알아보세요. 300개 이상의 액션 규칙과 Apple HIG 통합","es":"Aprende a desarrollar aplicaciones nativas de iPad siguiendo las pautas de diseño de Apple con más de 300 reglas de diseño","fr":"Découvrez comment développer des applications natives iPad en suivant les directives de conception d''Apple avec plus de 300 règles de design","de":"Erfahren Sie, wie Sie native iPad-Apps entwickeln, die die Designrichtlinien von Apple einhalten, mit über 300 Designregeln","pt":"Aprenda a criar aplicativos nativos para iPad com as diretrizes de design oficiais da Apple, incluindo layouts adaptáveis e interações de ponteiro","ru":"Создавайте родные приложения для iPad с помощью официальных руководств по дизайну от Apple, включая адаптивные макеты и взаимодействия с указателем","ar":"تعلم كيفية إنشاء تطبيقات أصلية لجهاز iPad باستخدام إرشادات التصميم الرسمية من Apple، بما في ذلك التصاميم القابلة للتكيف وتفاعلات المؤشر"},"definition":{"en":"ipados-design-guidelines is a set of rules for building and evaluating apps against official design guidelines, including iOS, iPadOS, macOS, watchOS, visionOS, tvOS, Android, and Web.","zh":"iPadOS 设计指南 AI 代理技能是一种用于构建和评估原生 iPad 应用的技术，提供 300+ 行动规则以遵循 Apple HIG 和 WCAG 2.2","ja":"iPadOS デザインガイドライン AI エージェントスキルは、ネイティブ iPad アプリを構築および評価するための技術で、Apple HIG と WCAG 2.2 に準拠する 300以上のアクションルールを提供します","ko":"iPadOS 디자인 가이드라인 AI 에이전트 스킬은 네이티브 iPad 앱을 구축하고 평가하는 기술로 Apple HIG 및 WCAG 2.2를 준수하는 300개 이상의 액션 규칙을 제공합니다","es":"¿Qué es el conjunto de habilidades de diseño de iPadOS? Un conjunto de reglas para desarrollar aplicaciones nativas de iPad","fr":"Qu''est-ce que l''ensemble de compétences de conception d''iPadOS ? Un ensemble de règles pour développer des applications natives iPad","de":"Was ist das iPadOS-Design-Skill-Set? Ein Satz von Regeln für die Entwicklung von nativen iPad-Apps","pt":"O que são as diretrizes de design do iPadOS? São regras para criar aplicativos nativos para iPad, baseadas nas diretrizes de interface humana da Apple","ru":"Что такое руководство по дизайну iPadOS? Это правила для создания родных приложений для iPad, основанные на руководстве по интерфейсу человека от Apple","ar":"ما هي إرشادات التصميم لجهاز iPadOS؟ هي قواعد لإنشاء تطبيقات أصلية لجهاز iPad، تستند إلى إرشادات واجهة الإنسان من Apple"},"features":{"en":["Supports adaptive size classes for responsive layouts","Enables multitasking support and pointer interactions","Provides rules for inter-app drag and drop and keyboard shortcuts","Works with Claude Code, Codex, and any agent that supports the Agent Skills format","Includes 300+ actionable rules distilled from Apple HIG, Material Design 3, and WCAG 2.2"],"zh":["提供 300+ 行动规则以遵循 Apple HIG 和 WCAG 2.2","支持 iPad 原生应用的构建和评估","集成 Claude Code、Codex 和其他支持 Agent Skills 格式的代理","提供响应式布局、多任务处理支持、指针交互、键盘快捷键和应用间拖放等功能","支持 iPadOS、iOS、macOS、watchOS、visionOS、tvOS 和 Android 平台"],"ja":["Apple HIG と WCAG 2.2 に準拠する 300以上のアクションルールを提供","ネイティブ iPad アプリの構築および評価をサポート","Claude Code、Codex、および他の Agent Skills 形式をサポートするエージェントとの統合","レスポンシブ レイアウト、多タスク サポート、ポインターインタラクション、キーボード ショートカット、およびアプリ間のドラッグ アンド ドロップなどの機能を提供","iPadOS、iOS、macOS、watchOS、visionOS、tvOS、および Android プラットフォームをサポート"],"ko":["Apple HIG 및 WCAG 2.2를 준수하는 300개 이상의 액션 규칙 제공","네이티브 iPad 앱의 구축 및 평가를 지원","Claude Code, Codex 및 다른 에이전트 스킬 형식을 지원하는 에이전트와의 통합","응답형 레이아웃, 멀티태스킹 지원, 포인터 상호작용, 키보드 단축키 및 앱 간 드래그 앤 드롭 등의 기능 제공","iPadOS, iOS, macOS, watchOS, visionOS, tvOS 및 Android 플랫폼 지원"],"es":["Más de 300 reglas de diseño para iOS, iPadOS, macOS, watchOS, visionOS, tvOS, Android y Web","Compatibilidad con Claude Code, Codex y cualquier agente que admita el formato de habilidades del agente","Diseño adaptativo con tamaños de clase regulares","Soporte para multitarea y interacciones con punteros","Compatibilidad con intercambio de arrastre y soltar entre aplicaciones"],"fr":["Plus de 300 règles de design pour iOS, iPadOS, macOS, watchOS, visionOS, tvOS, Android et Web","Compatibilité avec Claude Code, Codex et tout agent qui prend en charge le format de compétences de l''agent","Conception adaptative avec des tailles de classe régulières","Prise en charge de la multitâche et des interactions avec des pointeurs","Compatibilité avec le glisser-déposer entre les applications"],"de":["Über 300 Designregeln für iOS, iPadOS, macOS, watchOS, visionOS, tvOS, Android und Web","Kompatibilität mit Claude Code, Codex und jedem Agenten, der das Agent-Skill-Format unterstützt","Adaptives Design mit regulären Größeneinstellungen","Unterstützung für Multitasking und Pointer-Interaktionen","Kompatibilität mit Drag-and-Drop zwischen Apps"],"pt":["Layouts adaptáveis para diferentes tamanhos de tela","Suporte a multitarefa e interações de ponteiro","Atalhos de teclado e arrastar e soltar entre aplicativos","Compatibilidade com Claude Code, Codex e outros agentes","Mais de 300 regras para garantir a conformidade com as diretrizes de design da Apple"],"ru":["Адаптивные макеты для разных размеров экрана","Поддержка многозадачности и взаимодействий с указателем","Клавишные сокращения и перетаскивание между приложениями","Совместимость с Claude Code, Codex и другими агентами","Более 300 правил для обеспечения соответствия руководству по дизайну от Apple"],"ar":["تصاميم قابلة للتكيف لأحجام الشاشة المختلفة","دعم التحكم في عدة مهام وتفاعلات المؤشر","أوامر لوحة المفاتيح والسحب والإفلات بين التطبيقات","التوافق مع Claude Code و Codex والمواضيع الأخرى","أكثر من 300 قاعدة لضمان مطابقة إرشادات التصميم من Apple"]},"keywords":{"en":["how to use ipados-design-guidelines","ipados-design-guidelines setup guide","ipados-design-guidelines alternative","ipados-design-guidelines vs Material Design 3","what is ipados-design-guidelines","ipados-design-guidelines install","ipados-design-guidelines best practices for developers"],"zh":["iPadOS 设计指南","AI 代理技能","Apple HIG","WCAG 2.2","原生 iPad 应用","响应式布局","多任务处理支持","指针交互","键盘快捷键","应用间拖放"],"ja":["iPadOS デザインガイドライン","AI エージェントスキル","Apple HIG","WCAG 2.2","ネイティブ iPad アプリ","レスポンシブ レイアウト","多タスク サポート","ポインターインタラクション","キーボード ショートカット","アプリ間のドラッグ アンド ドロップ"],"ko":["iPadOS 디자인 가이드라인","AI 에이전트 스킬","Apple HIG","WCAG 2.2","네이티브 iPad 앱","응답형 레이아웃","멀티태스킹 지원","포인터 상호작용","키보드 단축키","앱 간 드래그 앤 드롭"],"es":["pautas de diseño de iPadOS","desarrollo de aplicaciones nativas de iPad","reglas de diseño para iOS y iPadOS","diseño adaptativo para iPad","multitarea en iPad","interacciones con punteros en iPad","Herramientas de diseño de UI para iPadOS","Desarrollo de aplicaciones móviles con iPadOS"],"fr":["directives de conception d''iPadOS","développement d''applications natives iPad","règles de design pour iOS et iPadOS","conception adaptative pour iPad","multitâche sur iPad","interactions avec des pointeurs sur iPad","Outils de conception d''interface utilisateur pour iPadOS","Développement d''applications mobiles avec iPadOS"],"de":["Designrichtlinien für iPadOS","Entwicklung von nativen iPad-Apps","Designregeln für iOS und iPadOS","Adaptives Design für iPad","Multitasking auf dem iPad","Pointer-Interaktionen auf dem iPad","UI-Design-Tools für iPadOS","Mobile App-Entwicklung mit iPadOS"],"pt":["iPadOS design guidelines","desenvolvimento de aplicativos para iPad","layout adaptável","interações de ponteiro","multitarefa","atalhos de teclado","arrastar e soltar","Claude Code","Codex"],"ru":["ИИ Агенты для iPadOS","создание приложений для iPad","адаптивный макет","взаимодействия с указателем","многозадачность","клавишные сокращения","перетаскивание","Claude Code","Codex"],"ar":["دليل تصميم iPadOS","تطوير تطبيقات لجهاز iPad","تصميم قابل للتكيف","تفاعلات المؤشر","التحكم في عدة مهام","أوامر لوحة المفاتيح","السحب والإفلات","Claude Code","Codex"]}},"owner":"ehmo","repo":"platform-design-skills","repoPath":"ehmo/platform-design-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.285Z","topics":[],"category":"community","skillMd":{"name":"ipados-design-guidelines","description":"Apple Human Interface Guidelines for iPad. Use when building iPad-optimized interfaces, implementing multitasking, pointer support, keyboard shortcuts, or responsive layouts. Triggers on tasks involving iPad, Split View, Stage Manager, sidebar navigation, or trackpad support.","version":"1.0.0","bodyPreview":"# iPadOS Design Guidelines\n\nComprehensive rules for building iPad-native apps following Apple''s Human Interface Guidelines. iPad is not a big iPhone -- it demands adaptive layouts, multitasking support, pointer interactions, keyboard shortcuts, and inter-app drag and drop. These rules extend iOS patterns for the larger, more capable canvas.\n\n---\n\n## 1. Responsive Layout (CRITICAL)\n\n### 1.1 Use Adaptive Size Classes\n\niPad presents two horizontal size classes: **regular** (full screen, large split","body":"# iPadOS Design Guidelines\n\nComprehensive rules for building iPad-native apps following Apple''s Human Interface Guidelines. iPad is not a big iPhone -- it demands adaptive layouts, multitasking support, pointer interactions, keyboard shortcuts, and inter-app drag and drop. These rules extend iOS patterns for the larger, more capable canvas.\n\n---\n\n## 1. Responsive Layout (CRITICAL)\n\n### 1.1 Use Adaptive Size Classes\n\niPad presents two horizontal size classes: **regular** (full screen, large splits) and **compact** (Slide Over, narrow splits). Design for both. Never hardcode dimensions.\n\n```swift\nstruct AdaptiveView: View {\n    @Environment(\\.horizontalSizeClass) var sizeClass\n\n    var body: some View {\n        if sizeClass == .regular {\n            TwoColumnLayout()\n        } else {\n            StackedLayout()\n        }\n    }\n}\n```\n\n### 1.2 Don''t Scale Up iPhone UI\n\niPad layouts must be purpose-built. Stretching an iPhone layout across a 13\" display wastes space and feels wrong. Use multi-column layouts, master-detail patterns, and increased information density in regular width.\n\n### 1.3 Support All iPad Screen Sizes\n\nDesign for the full range: iPad Mini (8.3\"), iPad (10.9\"), iPad Air (11\"/13\"), and iPad Pro (11\"/13\"). Use flexible layouts that redistribute content rather than simply scaling.\n\n### 1.4 Column-Based Layouts for Regular Width\n\nIn regular width, organize content into columns. Two-column is the most common (sidebar + detail). Three-column works for deep hierarchies (sidebar + list + detail). Avoid single-column full-width layouts on large screens.\n\n```swift\nstruct ThreeColumnLayout: View {\n    var body: some View {\n        NavigationSplitView {\n            SidebarView()\n        } content: {\n            ContentListView()\n        } detail: {\n            DetailView()\n        }\n    }\n}\n```\n\n### 1.5 Respect Safe Areas\n\niPad safe areas differ from iPhone. Older iPads have no home indicator. iPads in landscape have different insets than portrait. Always use `safeAreaInset` and never hardcode padding for notches or indicators.\n\n### 1.6 Support Both Orientations\n\niPad apps must work well in both portrait and landscape. Landscape is the dominant orientation for productivity. Portrait is common for reading. Adapt column counts and layout density to orientation.\n\n---\n\n## 2. Multitasking (CRITICAL)\n\n### 2.1 Support Split View\n\nYour app must function correctly at 1/3, 1/2, and 2/3 screen widths in Split View. At 1/3 width, your app receives compact horizontal size class. Content must remain usable at every split ratio.\n\n### 2.2 Support Slide Over\n\nSlide Over presents your app as a compact-width overlay on the right edge. It behaves like an iPhone-width app. Ensure all functionality remains accessible in this narrow mode.\n\n### 2.3 Handle Stage Manager\n\nStage Manager allows freely resizable windows and multiple windows simultaneously. Your app must:\n- Resize fluidly to arbitrary dimensions\n- Support multiple scenes (windows) showing different content\n- Not assume any fixed size or aspect ratio\n\n```swift\n@main\nstruct MyApp: App {\n    var body: some Scene {\n        WindowGroup {\n            ContentView()\n        }\n        // Support multiple windows\n        WindowGroup(\"Detail\", for: Item.ID.self) { $itemId in\n            DetailView(itemId: itemId)\n        }\n    }\n}\n```\n\n### 2.4 Never Assume Full Screen\n\nThe app may launch directly into Split View or Stage Manager. Do not depend on full-screen dimensions during setup, onboarding, or any flow. Test your app at every possible size.\n\n### 2.5 Handle Size Transitions Gracefully\n\nWhen the user resizes via multitasking, animate layout changes smoothly. Preserve scroll position, selection state, and user context across size transitions. Never reload content on resize.\n\n### 2.6 Support Multiple Scenes\n\nUse `UIScene` / SwiftUI `WindowGroup` to let users open multiple instances of your app showing different content. Each scene is independent. Support `NSUserActivity` for state restoration.\n\n---\n\n## 3. Navigation (HIGH)\n\n### 3.1 Sidebar for Primary Navigation\n\nIn regular width, replace the iPhone tab bar with a sidebar. The sidebar provides more room for navigation items, supports sections, and feels native on iPad.\n\n```swift\nstruct AppNavigation: View {\n    @State private var selection: NavigationItem? = .inbox\n\n    var body: some View {\n        NavigationSplitView {\n            List(selection: $selection) {\n                Section(\"Main\") {\n                    Label(\"Inbox\", systemImage: \"tray\")\n                        .tag(NavigationItem.inbox)\n                    Label(\"Drafts\", systemImage: \"doc\")\n                        .tag(NavigationItem.drafts)\n                    Label(\"Sent\", systemImage: \"paperplane\")\n                        .tag(NavigationItem.sent)\n                }\n                Section(\"Labels\") {\n                    // Dynamic sections\n                }\n            }\n            .navigationTitle(\"Mail\")\n        } detail: {\n            DetailView(for: selection)\n        }\n    }\n}\n```\n\n### 3.2 Automatic Tab-to-Sidebar Conversion\n\nSwiftUI `TabView` with `.sidebarAdaptable` style automatically converts to a sidebar in regular width. Use this for seamless iPhone-to-iPad adaptation.\n\n```swift\nTabView {\n    Tab(\"Home\", systemImage: \"house\") { HomeView() }\n    Tab(\"Search\", systemImage: \"magnifyingglass\") { SearchView() }\n    Tab(\"Profile\", systemImage: \"person\") { ProfileView() }\n}\n.tabViewStyle(.sidebarAdaptable)\n```\n\n### 3.3 Three-Column Layout for Complex Hierarchies\n\nUse `NavigationSplitView` with three columns when your information architecture has three levels: category > list > detail. Examples: mail (accounts > messages > message), file managers, settings.\n\n### 3.4 Toolbar at Top\n\nOn iPad, toolbars live at the top of the screen in the navigation bar area, not at the bottom like iPhone. Place contextual actions in `.toolbar` with appropriate placement.\n\n```swift\n.toolbar {\n    ToolbarItemGroup(placement: .primaryAction) {\n        Button(\"Compose\", systemImage: \"square.and.pencil\") { }\n    }\n    ToolbarItemGroup(placement: .secondaryAction) {\n        Button(\"Archive\", systemImage: \"archivebox\") { }\n        Button(\"Delete\", systemImage: \"trash\") { }\n    }\n}\n```\n\n### 3.5 Detail View Should Never Be Empty\n\nWhen no item is selected in a list/sidebar, show a meaningful empty state in the detail area. Use a placeholder with icon and instruction text, not a blank screen.\n\n---\n\n## 4. Pointer & Trackpad (HIGH)\n\n### 4.1 Add Hover Effects to Interactive Elements\n\nAll tappable elements should respond to pointer hover. The system provides automatic hover effects for standard controls. For custom views, use `.hoverEffect()`.\n\n```swift\nButton(\"Action\") { }\n    .hoverEffect(.highlight)  // Subtle highlight on hover\n\n// Custom hover effect\nMyCustomView()\n    .hoverEffect(.lift)  // Lifts and adds shadow\n```\n\n### 4.2 Pointer Magnetism on Buttons\n\nThe pointer should snap to (be attracted toward) button bounds. Standard UIKit/SwiftUI buttons get this automatically. For custom hit targets, ensure the pointer region matches the tappable area using `.contentShape()`.\n\n### 4.3 Support Right-Click Context Menus\n\nRight-click (secondary click) should present context menus. Use `.contextMenu` which automatically supports both long-press (touch) and right-click (pointer).\n\n```swift\nText(item.title)\n    .contextMenu {\n        Button(\"Copy\", systemImage: \"doc.on.doc\") { }\n        Button(\"Share\", systemImage: \"square.and.arrow.up\") { }\n        Divider()\n        Button(\"Delete\", systemImage: \"trash\", role: .destructive) { }\n    }\n```\n\n### 4.4 Trackpad Scroll Behaviors\n\nSupport two-finger scrolling with momentum. Pinch to zoom where appropriate. Respect scroll direction preferences. For custom scroll views, ensure trackpad gestures feel natural alongside touch gestures.\n\n### 4.5 Customize Cursor for Content Areas\n\nChange cursor appearance based on context. Text areas show I-beam. Links show pointer hand. Resize handles show resize cursors. Draggable items show grab cursor.\n\n### 4.6 Pointer-Driven Drag and Drop\n\nPointer users expect click-and-drag for rearranging, selecting, and moving content. Combine with multi-select via Shift-click and Cmd-click.\n\n---\n\n## 5. Keyboard (HIGH)\n\n### 5.1 Cmd+Key Shortcuts for All Major Actions\n\nEvery primary action must have a keyboard shortcut. Standard shortcuts are mandatory:\n\n| Shortcut | Action |\n|----------|--------|\n| Cmd+N | New item |\n| Cmd+F | Find/Search |\n| Cmd+S | Save |\n| Cmd+Z | Undo |\n| Cmd+Shift+Z | Redo |\n| Cmd+C/V/X | Copy/Paste/Cut |\n| Cmd+A | Select all |\n| Cmd+P | Print |\n| Cmd+W | Close window/tab |\n| Cmd+, | Settings/Preferences |\n| Delete | Delete selected item |\n\n```swift\nButton(\"New Document\") { createDocument() }\n    .keyboardShortcut(\"n\", modifiers: .command)\n```\n\n### 5.2 Discoverability via Cmd-Hold Overlay\n\nWhen the user holds the Cmd key, iPadOS shows a shortcut overlay. Register all shortcuts using `.keyboardShortcut()` so they appear in this overlay. Group related shortcuts logically.\n\n### 5.3 Tab Key Navigation Between Fields\n\nSupport Tab to move forward and Shift+Tab to move backward between form fields and focusable elements. Use `.focusable()` and `@FocusState` to manage keyboard focus order.\n\n```swift\nstruct FormView: View {\n    @FocusState private var focusedField: Field?\n\n    var body: some View {\n        Form {\n            TextField(\"Name\", text: $name)\n                .focused($focusedField, equals: .name)\n            TextField(\"Email\", text: $email)\n                .focused($focusedField, equals: .email)\n            TextField(\"Phone\", text: $phone)\n                .focused($focusedField, equals: .phone)\n        }\n    }\n}\n```\n\n### 5.4 Never Override System Shortcuts\n\nDo not claim shortcuts reserved by the system: Cmd+H (Home), Cmd+Tab (App Switcher), Cmd+Space (Spotlight), Globe key combinations. These will not work and create confusion.\n\n### 5.5 Detect Hardware Keyboard\n\nAdapt UI when a hardware keyboard is connected. Hide the on-screen keyboard shortcut bar. Show keyboard-optimized controls. Use `GCKeyboard` or track keyboard visibility to detect state.\n\n### 5.6 Arrow Key Navigation\n\nSupport arrow keys for navigating lists, grids, and collections. Combine with Shift for multi-selection. This is essential for productivity-focused apps.\n\n---\n\n## 6. Apple Pencil (MEDIUM)\n\n### 6.1 Support Scribble\n\niPadOS converts handwriting to text in any standard text field automatically. Do not disable Scribble. For custom text input, adopt `UIScribbleInteraction`. Test that Scribble works in all text entry points.\n\n### 6.2 Double-Tap Tool Switching\n\nApple Pencil 2 and later supports double-tap to switch tools (e.g., pen to eraser). If your app has drawing tools, implement the `UIPencilInteraction` delegate to handle double-tap.\n\n### 6.3 Pressure and Tilt for Drawing\n\nFor drawing apps, respond to `force` (pressure) and `altitudeAngle`/`azimuthAngle` (tilt) from pencil touch events. Use these for variable line width, opacity, or shading.\n\n### 6.4 Hover Detection (M2+ Pencil)\n\nApple Pencil with hover (M2 iPad Pro and later) provides position data before the pencil touches the screen. Use this for preview effects, tool size indicators, and enhanced precision.\n\n```swift\n// UIKit hover support\noverride func pencilHoverChanged(_ hover: UIHoverGestureRecognizer) {\n    let location = hover.location(in: canvas)\n    showBrushPreview(at: location)\n}\n```\n\n### 6.5 PencilKit Integration\n\nFor note-taking and annotation, use `PKCanvasView` from PencilKit. It provides a full drawing experience with tool picker, undo, and ink recognition out of the box.\n\n```swift\nimport PencilKit\n\nstruct DrawingView: UIViewRepresentable {\n    @Binding var canvasView: PKCanvasView\n\n    func makeUIView(context: Context) -> PKCanvasView {\n        canvasView.tool = PKInkingTool(.pen, color: .black, width: 5)\n        canvasView.drawingPolicy = .anyInput\n        return canvasView\n    }\n}\n```\n\n---\n\n## 7. Drag and Drop (HIGH)\n\n### 7.1 Inter-App Drag and Drop is Expected\n\niPad users expect to drag content between apps. Support dragging content out (as a source) and dropping content in (as a destination). This is a core iPad interaction.\n\n```swift\n// As drag source\nText(item.title)\n    .draggable(item.title)\n\n// As drop destination\nDropTarget()\n    .dropDestination(for: String.self) { items, location in\n        handleDrop(items)\n        return true\n    }\n```\n\n### 7.2 Multi-Item Drag\n\nUsers can pick up one item, then tap additional items to add them to the drag. Support multi-item drag by providing multiple `NSItemProvider` items. Show a badge count on the drag preview.\n\n### 7.3 Spring-Loaded Interactions\n\nWhen dragging over a navigation element (folder, tab, sidebar item), pause briefly to \"spring open\" that destination. Implement spring-loading on navigation containers to enable deep drop targets.\n\n### 7.4 Visual Feedback for Drag and Drop\n\nProvide clear visual states:\n- **Lift**: Item lifts with shadow when drag begins\n- **Move**: Destination highlights when drag hovers over valid target\n- **Drop**: Animate insertion at drop point\n- **Cancel**: Item animates back to origin\n\n### 7.5 Support Universal Control\n\nUniversal Control lets users drag between iPad and Mac. If your app supports drag and drop with standard `NSItemProvider` and UTTypes, Universal Control works automatically.\n\n### 7.6 Drop Delegates for Custom Behavior\n\nUse `DropDelegate` for fine-grained control over drop behavior: validating drop content, reordering within lists, and handling drop position.\n\n```swift\nstruct ReorderDropDelegate: DropDelegate {\n    let item: Item\n    @Binding var items: [Item]\n    @Binding var draggedItem: Item?\n\n    func performDrop(info: DropInfo) -> Bool {\n        draggedItem = nil\n        return true\n    }\n\n    func dropEntered(info: DropInfo) {\n        guard let draggedItem,\n              let fromIndex = items.firstIndex(of: draggedItem),\n              let toIndex = items.firstIndex(of: item) else { return }\n        withAnimation {\n            items.move(fromOffsets: IndexSet(integer: fromIndex),\n                      toOffset: toIndex > fromIndex ? toIndex + 1 : toIndex)\n        }\n    }\n}\n```\n\n---\n\n## 8. External Display (MEDIUM)\n\n### 8.1 Provide Extended Content, Not Just Mirroring\n\nWhen connected to an external display, show complementary content rather than duplicating the iPad screen. Presentations, reference material, or expanded views belong on the external display while controls stay on iPad.\n\n```swift\n@main\nstruct MyApp: App {\n    var body: some Scene {\n        WindowGroup {\n            ContentView()\n        }\n        // Additional scene for external display\n        WindowGroup(id: \"presentation\") {\n            PresentationView()\n        }\n    }\n}\n```\n\n### 8.2 Handle Display Connection and Disconnection\n\nListen for `UIScreen.didConnectNotification` and `UIScreen.didDisconnectNotification`. Transition gracefully -- if the external display disconnects mid-presentation, bring content back to the iPad screen without data loss.\n\n### 8.3 Support Full External Display Resolution\n\nUse the full resolution and aspect ratio of the external display. Do not letterbox or pillarbox your content. Query `UIScreen.bounds` and `UIScreen.scale` for the connected display.\n\n---\n\n## Evaluation Checklist\n\nUse this checklist to verify iPad-readiness:\n\n### Layout & Multitasking\n- [ ] App uses adaptive layout with `horizontalSizeClass`\n- [ ] Tested at all Split View ratios (1/3, 1/2, 2/3)\n- [ ] Tested in Slide Over (compact width)\n- [ ] Stage Manager: resizes fluidly to arbitrary dimensions\n- [ ] Multiple scenes/windows supported\n- [ ] Both orientations (portrait and landscape) work correctly\n- [ ] No content clipped at any size\n- [ ] Safe areas respected on all iPad models\n\n### Navigation\n- [ ] Sidebar visible in regular width\n- [ ] Tab bar used in compact width\n- [ ] Detail view shows placeholder when no selection\n- [ ] Toolbar items placed at top, not bottom\n- [ ] Three-column layout used where appropriate\n\n### Pointer & Trackpad\n- [ ] Hover effects on all interactive elements\n- [ ] Right-click context menus available\n- [ ] Pointer cursor adapts to content (I-beam for text, etc.)\n- [ ] Click-and-drag works for reordering\n\n### Keyboard\n- [ ] Cmd+key shortcuts for all major actions\n- [ ] Shortcuts appear in Cmd-hold overlay\n- [ ] Tab key navigates between form fields\n- [ ] No system shortcut conflicts\n- [ ] Arrow keys navigate lists and grids\n- [ ] Return/Enter activates default action\n\n### Apple Pencil\n- [ ] Scribble works in all text fields\n- [ ] Drawing apps support pressure and tilt\n- [ ] Double-tap interaction handled (if applicable)\n\n### Drag and Drop\n- [ ] Content can be dragged out to other apps\n- [ ] Content can be dropped in from other apps\n- [ ] Multi-item drag supported\n- [ ] Visual feedback for all drag states\n\n### External Display\n- [ ] Extended content shown (not just mirror)\n- [ ] Graceful handling of connect/disconnect\n\n---\n\n## Anti-Patterns\n\n### DO NOT: Scale Up iPhone Layouts\nStretching a single-column iPhone UI to fill an iPad screen wastes space, looks lazy, and provides a poor experience. Always redesign for the larger canvas.\n\n### DO NOT: Disable Multitasking\nNever opt out of multitasking support. Users expect every app to work in Split View and Slide Over. Requiring full screen is hostile to iPad workflows.\n\n### DO NOT: Ignore the Keyboard\nMany iPad users have Magic Keyboard or Smart Keyboard. An app with no keyboard shortcuts forces them to reach for the screen constantly. Provide shortcuts for all frequent actions.\n\n### DO NOT: Use iPhone-Style Bottom Tab Bars in Regular Width\nTab bars at the bottom waste vertical space on iPad and look out of place. Convert to sidebar navigation in regular width. SwiftUI does this automatically with `.sidebarAdaptable`.\n\n### DO NOT: Show Popovers as Full-Screen Sheets\nOn iPad, popovers should anchor to their source element as floating panels. Only use full-screen sheets for immersive content or flows that genuinely need the full screen. Avoid the iPhone pattern of everything being a sheet.\n\n### DO NOT: Ignore Pointer Hover States\nMissing hover effects make the app feel broken when using a trackpad. Users cannot tell what is interactive. Always add hover feedback to custom interactive elements.\n\n### DO NOT: Hardcode Dimensions\nNever hardcode widths, heights, or positions based on a specific iPad model. Use Auto Layout constraints, SwiftUI flexible frames, and `GeometryReader` for dynamic sizing.\n\n### DO NOT: Forget Drag and Drop\nOn iPad, drag and drop between apps is a core workflow. Not supporting it makes your app a dead end for content. At minimum, support dragging text, images, and URLs in and out.\n\n### DO NOT: Override System Keyboard Shortcuts\nClaiming Cmd+H, Cmd+Tab, Cmd+Space, or Globe shortcuts will not work and confuses users who expect system behavior. Check Apple''s reserved shortcuts list before assigning.\n\n### DO NOT: Present Dense Content Without Scrolling\nLarge iPad screens tempt designers to show everything at once. Content should still scroll when it exceeds the visible area. Never truncate content to avoid scrolling.\n"},"lastSynced":"2026-03-08T02:00:56.516Z","agentAnalysis":{"suitability":{"en":"Perfect for UI/UX Agents needing to create adaptive layouts and multitasking support for iPad-native apps","zh":"非常适合需要创建自适应布局和iPad原生应用多任务支持的UI/UX代理","ja":"UI/UXエージェントが適応レイアウトとiPadネイティブアプリのマルチタスク支援を作成する必要がある場合に最適","ko":"UI/UX 에이전트가 적응형 레이아웃과 iPad 네이티브 앱의 멀티태스킹 지원을 생성해야 하는 경우에 완벽함","es":"Perfecto para agentes de UI/UX que necesitan crear diseños de layout adaptables y soporte de multitarea para aplicaciones nativas de iPad","fr":"Parfait pour les agents UI/UX ayant besoin de créer des dispositions de layout adaptatives et un support de multitâche pour les applications natives iPad","de":"Perfekt für UI/UX-Agents, die adaptive Layouts und Multitasking-Unterstützung für iPad-native Apps erstellen müssen","pt":"Perfeito para agentes de UI/UX que precisam criar layouts adaptativos e suporte a multitarefa para aplicativos nativos do iPad","ru":"Идеально для агентов UI/UX, которым необходимо создавать адаптивные макеты и поддержку многозадачности для приложений, родных для iPad","ar":"مثالي لعميل واجهة المستخدم / تجربة المستخدم الذي يحتاج إلى إنشاء تخطيطات متكيفة ودعم تشغيل تطبيقات متعددة للأجهزة الأصلية لآي باد"},"recommendation":{"en":"Empowers agents to design iPad-native apps following Apple''s Human Interface Guidelines, utilizing adaptive size classes, pointer interactions, keyboard shortcuts, and inter-app drag and drop, extending iOS patterns for a larger canvas","zh":"赋予代理设计遵循Apple的人机接口指南的iPad原生应用的能力，利用自适应大小类、指针交互、键盘快捷键和应用程序间拖放，扩展iOS模式以适应更大的画布","ja":"AppleのHuman Interface Guidelinesに従ったiPadネイティブアプリを設計するエージェントの能力を提供し、適応サイズクラス、ポインターインタラクション、キーボードショートカット、およびアプリ間のドラッグアンドドロップを利用して、より大きなキャンバスに対応したiOSパターンを拡張する","ko":"에이전트가 Apple의 Human Interface Guidelines를 따르는 iPad 네이티브 앱을 설계할 수 있는 능력을 부여하여 적응형 크기 클래스, 포인터 상호작용, 키보드 단축키 및 앱 간 드래그 및 드롭을 사용하여 더大的 캔버스에 대한 iOS 패턴을 확장함","es":"Habilita a los agentes a diseñar aplicaciones nativas de iPad siguiendo las Directrices de Interfaz Humana de Apple, utilizando clases de tamaño adaptables, interacciones de puntero, atajos de teclado y arrastre y soltar entre aplicaciones, extendiendo los patrones de iOS para una superficie de trabajo más grande","fr":"Permet aux agents de concevoir des applications natives iPad en suivant les Directives d''Interface Humaine d''Apple, en utilisant des classes de taille adaptatives, des interactions de pointeur, des raccourcis clavier et un glisser-déposer entre applications, en étendant les modèles d''iOS pour un plus grand canvas","de":"Ermächtigt Agenten, iPad-native Apps zu entwerfen, die Apples Human Interface Guidelines folgen, unter Verwendung adaptiver Größeneinstellungen, Pointer-Interaktionen, Tastenkürzel und Drag-and-Drop zwischen Apps, wodurch iOS-Muster für eine größere Arbeitsfläche erweitert werden","pt":"Habilita os agentes a projetar aplicativos nativos do iPad seguindo as Diretrizes de Interface Humana da Apple, utilizando classes de tamanho adaptáveis, interações de ponteiro, atalhos de teclado e arrastar e soltar entre aplicativos, estendendo os padrões do iOS para uma tela maior","ru":"Наделяет агентов возможностью проектировать приложения, родные для iPad, следуя Руководящим принципам интерфейса человека Apple, используя адаптивные размерные классы, взаимодействия указателя, клавиатурные сокращения и перетаскивание между приложениями, расширяя шаблоны iOS для более крупной поверхности","ar":"تمكين العميل من تصميم تطبيقات أصلية لآي باد باتباع إرشادات واجهة المستخدم البشرية من شركة آبل، باستخدام فئات حجم متكيفة وتفاعلات المؤشر واختصارات لوحة المفاتيح وسحب وإفلات بين التطبيقات، وتوسيع نمط iOS لشاشة أكبر"},"useCases":{"en":["Designing responsive layouts for iPad screens","Implementing multitasking support for enhanced user experience","Creating adaptive interfaces with pointer interactions and keyboard shortcuts"],"zh":["为iPad屏幕设计响应式布局","实现多任务支持以增强用户体验","使用指针交互和键盘快捷键创建自适应接口"],"ja":["iPadスクリーン用のレスポンシブルレイアウトを設計する","マルチタスク支援を実装してユーザーエクスペリエンスを強化する","ポインターインタラクションとキーボードショートカットを使用して適応インターフェイスを作成する"],"ko":["iPad 화면을 위한 반응형 레이아웃을 설계함","멀티태스킹 지원을 구현하여 사용자 경험을 향상함","포인터 상호작용 및 키보드 단축키를 사용하여 적응형 인터페이스를 생성함"],"es":["Diseñar diseños de layout responsivos para pantallas de iPad","Implementar soporte de multitarea para una experiencia de usuario mejorada","Crear interfaces adaptables con interacciones de puntero y atajos de teclado"],"fr":["Concevoir des dispositions de layout responsives pour les écrans iPad","Mettre en œuvre un support de multitâche pour une expérience utilisateur améliorée","Créer des interfaces adaptatives avec des interactions de pointeur et des raccourcis clavier"],"de":["Entwerfen responsiver Layouts für iPad-Bildschirme","Implementieren von Multitasking-Unterstützung für eine verbesserte Benutzeroberfläche","Erstellen adaptiver Schnittstellen mit Pointer-Interaktionen und Tastenkürzeln"],"pt":["Projetar layouts responsivos para telas do iPad","Implementar suporte a multitarefa para uma experiência do usuário aprimorada","Criar interfaces adaptativas com interações de ponteiro e atalhos de teclado"],"ru":["Проектировать адаптивные макеты для экранов iPad","Реализовывать поддержку многозадачности для улучшения опыта пользователя","Создавать адаптивные интерфейсы с взаимодействиями указателя и клавиатурными сокращениями"],"ar":["تصميم تخطيطات مستجدة لشاشات آي باد","تنفيذ دعم تشغيل تطبيقات متعددة لتجربة مستخدم محسنة","إنشاء واجهات مستجدة مع تفاعلات المؤشر واختصارات لوحة المفاتيح"]},"limitations":{"en":["Requires knowledge of Apple''s Human Interface Guidelines","Specific to iPadOS design","Demands understanding of adaptive layouts and multitasking support"],"zh":["需要了解Apple的人机接口指南","特定于iPadOS设计","要求了解自适应布局和多任务支持"],"ja":["AppleのHuman Interface Guidelinesの知識が必要","iPadOSデザインに特化","適応レイアウトとマルチタスク支援の理解が求められる"],"ko":["Apple의 Human Interface Guidelines에 대한 지식이 필요함","iPadOS 설계에 특정됨","적응형 레이아웃 및 멀티태스킹 지원에 대한 이해가 필요함"],"es":["Requiere conocimiento de las Directrices de Interfaz Humana de Apple","Específico para el diseño de iPadOS","Exige comprensión de diseños de layout adaptables y soporte de multitarea"],"fr":["Nécessite une connaissance des Directives d''Interface Humaine d''Apple","Spécifique à la conception d''iPadOS","Exige une compréhension des dispositions de layout adaptatives et du support de multitâche"],"de":["Benötigt Kenntnisse der Human Interface Guidelines von Apple","Spezifisch für das Design von iPadOS","Erfordert Verständnis für adaptive Layouts und Multitasking-Unterstützung"],"pt":["Exige conhecimento das Diretrizes de Interface Humana da Apple","Específico para design do iPadOS","Exige compreensão de layouts adaptativos e suporte a multitarefa"],"ru":["Требует знания Руководящих принципов интерфейса человека Apple","Конкретно для дизайна iPadOS","Требует понимания адаптивных макетов и поддержки многозадачности"],"ar":["يتطلب معرفة إرشادات واجهة المستخدم البشرية من شركة آبل","محدد لتصميم آي باد أو إس","يتطلب فهم التخطيطات المتكيفة ودعم تشغيل التطبيقات المتعددة"]},"version":4},"contentHash":"d44650dc044218c7f41860a75656dfe0f244189d2033f4bcd17a8804b3a8950c","qualityScore":50}');
