INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ehmo/platform-design-skills/ipados-design-guidelines', 'ipados-design-guidelines', 'ehmo', 'platform-design-skills', 'community', 'ipados-design-guidelines ehmo platform-design-skills community The ipados-design-guidelines skill provides comprehensive rules for building iPad-native apps following Apple''s Human Interface Guidelines, benefiting developers who want to create adaptive layouts and multitasking support. iPadOS 设计指南 AI 代理技能提供 300+ 行动规则，帮助开发者构建和评估原生 iPad 应用，遵循 Apple HIG 和 WCAG 2.2 iPadOS デザインガイドライン AI エージェントスキルは、300以上のアクションルールを提供して、開発者がネイティブ iPad アプリを構築および評価するのに役立ちます。Apple HIG と WCAG 2.2 に準拠しています iPadOS 디자인 가이드라인 AI 에이전트 스킬은 300개 이상의 액션 규칙을 제공하여 개발자가 네이티브 iPad 앱을 구축하고 평가하는 데 도움을 주며 Apple HIG 및 WCAG 2.2를 준수합니다 El conjunto de habilidades de diseño de iPadOS proporciona reglas para desarrollar aplicaciones nativas de iPad L''ensemble de compétences de conception d''iPadOS fournit des règles pour développer des applications natives iPad Das iPadOS-Design-Skill-Set bietet Regeln für die Entwicklung von nativen iPad-Apps As diretrizes de design do iPadOS fornecem regras para criar aplicativos nativos para iPad, incluindo layouts adaptáveis e interações de ponteiro Руководство по дизайну iPadOS предоставляет правила для создания родных приложений для iPad, включая адаптивные макеты и взаимодействия с указателем دليل تصميم iPadOS يوفر قواعد لإنشاء تطبيقات أصلية لجهاز iPad، بما في ذلك التصاميم القابلة للتكيف وتفاعلات المؤشر how to use ipados-design-guidelines ipados-design-guidelines setup guide ipados-design-guidelines alternative ipados-design-guidelines vs Material Design 3 what is ipados-design-guidelines ipados-design-guidelines install ipados-design-guidelines best practices for developers iPadOS 设计指南 AI 代理技能 Apple HIG WCAG 2.2 原生 iPad 应用 响应式布局 多任务处理支持 指针交互 键盘快捷键 应用间拖放 Supports adaptive size classes for responsive layouts Enables multitasking support and pointer interactions Provides rules for inter-app drag and drop and keyboard shortcuts Works with Claude Code, Codex, and any agent that supports the Agent Skills format Includes 300+ actionable rules distilled from Apple HIG, Material Design 3, and WCAG 2.2 ipados-design-guidelines is a set of rules for building and evaluating apps against official design guidelines, including iOS, iPadOS, macOS, watchOS, visionOS, tvOS, Android, and Web.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gannonh/kata-orchestrator/kata-help', 'community', 'gannonh', 'kata-orchestrator', 'gannonh/kata-orchestrator', 'kata-help', 0, 0, 50, '2026-03-08T01:57:15.286Z', '2026-03-08T02:00:58.541Z', 'a4dd7c68c8722d32e6bbe81e81caec4b8180cd10b9895cc595c484cdebda2346', '{"id":"gannonh/kata-orchestrator/kata-help","name":"kata-help","description":{"en":"kata-help is an agent orchestration framework designed for spec-driven development, benefiting developers who need to streamline their workflow. It provides a structured approach to agent management.","zh":"Kata-Help是用于仕様駆動開発的AIエージェント框架，提供版本信息和安装指南","ja":"Kata-Helpは仕様駆動開発を実現するAIエージェントフレームワークで、バージョン情報とインストールガイドを提供","ko":"Kata-Help는仕様駆動開発을 위한 AI 에이전트 프레임워크로, 버전 정보와 설치 방법을 제공합니다","es":"kata-help es un framework de orquestación de agentes para desarrollo basado en especificaciones. Ofrece una forma eficiente de gestionar y ejecutar tareas.","fr":"kata-help est un framework d''orchestration d''agents pour le développement basé sur des spécifications. Il propose une façon efficace de gérer et d''exécuter des tâches.","de":"kata-help ist ein Framework für die Orchestrierung von Agenten für spezifikationsbasierte Entwicklung. Es bietet eine effiziente Möglichkeit, Aufgaben zu verwalten und auszuführen.","pt":"O kata-help é um framework de orquestração de agentes para desenvolvimento dirigido por especificações. Ele fornece uma forma eficiente de gerenciar e executar tarefas","ru":"kata-help - это фреймворк для оркестровки агентов для спецификационно-ориентированного разработки. Он предоставляет эффективный способ управления и выполнения задач","ar":"kata-help هو إطار عمل لتوجيه الوكلاء لتصميم التوجيه بالمواصفات. يوفر طريقة فعالة لإدارة وتنفيذ المهام"},"seo":{"title":{"en":"kata-help: Agent Orchestration Framework Setup Guide | AI...","zh":"Kata-Help Setup Guide: AIエージェント框架","ja":"Kata-Help ベストプラクティス: AIエージェントを使用した仕様駆動開発","ko":"Kata-Help 사용법: AI 에이전트 프레임워크 및 버전 정보","es":"Guía de Configuración de kata-help: Framework de Orquesta...","fr":"Guide de Configuration de kata-help: Framework d''Orchestr...","de":"Einrichtungsleitfaden für kata-help: Agenten-Orchestrieru...","pt":"Guia de Configuração do kata-help para Desenvolvimento Di...","ru":"Установка и Настройка kata-help для Спецификационно-ориен...","ar":"دليل إعداد kata-help لتصميم التوجيه بالمواصفات"},"description":{"en":"Discover how kata-help simplifies spec-driven development with its agent orchestration framework. Learn how to install and use kata-help with our expert guide.","zh":"了解Kata-Help AIエージェント框架的功能和特点，包括版本信息和安装指南","ja":"Kata-Help AIエージェントの仕様駆動開発機能とベストプラクティスを紹介","ko":"Kata-Help AI 에이전트 프레임워크와 버전 정보를 확인하고 설치 방법을 알아보세요","es":"Aprende a configurar kata-help, un framework de orquestación de agentes para desarrollo basado en especificaciones. Descubre sus características y beneficios.","fr":"Découvrez comment configurer kata-help, un framework d''orchestration d''agents pour le développement basé sur des spécifications. Explorez ses fonctionnalités...","de":"Erfahren Sie, wie Sie kata-help konfigurieren, ein Framework für die Orchestrierung von Agenten für spezifikationsbasierte Entwicklung. Entdecken Sie seine F...","pt":"Aprenda a configurar o kata-help, um framework de orquestração de agentes para desenvolvimento dirigido por especificações. Descubra como integrar essa ferra...","ru":"Узнайте, как настроить kata-help, фреймворк для оркестровки агентов для спецификационно-ориентированного разработки. Откройте для себя, как интегрировать это...","ar":"تعرف على كيفية إعداد kata-help، إطار عمل لتوجيه الوكلاء لتصميم التوجيه بالمواصفات. اكتشف كيفية دمج هذه الأداة في تدفق عملك"},"definition":{"en":"kata-help is an agent orchestration framework for spec-driven development, providing a structured approach to managing agents and workflows.","zh":"Kata-Help是一种AIエージェント框架，用于仕様駆動開発和版本管理","ja":"Kata-HelpはAIエージェントフレームワークの一種で、仕様駆動開発とバージョン管理に使用される","ko":"Kata-Help는仕様駆動開発과 버전 관리를 위한 AI 에이전트 프레임워크입니다","es":"kata-help es un framework de orquestación de agentes que permite el desarrollo basado en especificaciones.","fr":"kata-help est un framework d''orchestration d''agents qui permet le développement basé sur des spécifications.","de":"kata-help ist ein Framework für die Orchestrierung von Agenten, das die spezifikationsbasierte Entwicklung ermöglicht.","pt":"O kata-help é um framework de orquestração de agentes que auxilia no desenvolvimento dirigido por especificações","ru":"kata-help - это фреймворк для оркестровки агентов, помогающий в спецификационно-ориентированном разработки","ar":"kata-help هو إطار عمل لتوجيه الوكلاء الذي يساعد في تصميم التوجيه بالمواصفات"},"features":{"en":["Displays the complete Kata skill reference with version info","Reads the installed version from the VERSION file in the CLAUDE_PLUGIN_ROOT directory","Outputs reference content with the version number inserted at the top","Executes bash commands to retrieve version information","Supports conditional logic to handle unknown version scenarios"],"zh":["提供版本信息","支持仕様駆動開発","包含安装指南","使用Bash脚本","支持CLI命令"],"ja":["バージョン情報の提供","仕様駆動開発のサポート","インストールガイドの含まれる","Bashスクリプトの使用","CLIコマンドのサポート"],"ko":["버전 정보 제공","仕様駆動開発 지원","설치 가이드 포함","Bash 스크립트 사용","CLI 명령어 지원"],"es":["Orquestación de agentes para desarrollo basado en especificaciones","Ejecución de tareas de forma eficiente","Utiliza la línea de comandos (CLI) para la configuración","Soporte para la lectura de versiones instaladas","Generación de contenido de referencia para la documentación"],"fr":["Orchestration d''agents pour le développement basé sur des spécifications","Exécution de tâches de manière efficace","Utilise la ligne de commande (CLI) pour la configuration","Prise en charge de la lecture des versions installées","Génération de contenu de référence pour la documentation"],"de":["Orchestrierung von Agenten für spezifikationsbasierte Entwicklung","Ausführung von Aufgaben auf effiziente Weise","Verwendung der Kommandozeile (CLI) für die Konfiguration","Unterstützung für die Lesung von installierten Versionen","Generierung von Referenzinhalt für die Dokumentation"],"pt":["Suporte a desenvolvimento dirigido por especificações","Orquestração de agentes para automação de tarefas","Leitura de versão instalada via comando bash","Saída de referência com informações de versão"],"ru":["Поддержка спецификационно-ориентированного разработки","Оркестровка агентов для автоматизации задач","Чтение установленной версии через команду bash","Выходная справка с информацией о версии"],"ar":["دعم تصميم التوجيه بالمواصفات","توجيه الوكلاء لتحسين المهام","قراءة الإصدار المثبت عبر أمر bash","إخراج المرجع مع معلومات الإصدار"]},"keywords":{"en":["how to use kata-help","kata-help alternative","kata-help install","what is kata-help","kata-help vs agent orchestration frameworks","kata-help setup guide","spec-driven development with kata-help","kata-help agent management","kata-help workflow automation"],"zh":["Kata-Help","AIエージェント","仕様駆動開発","版本管理","Bash脚本","CLI命令","安装指南"],"ja":["Kata-Help","AIエージェント","仕様駆動開発","バージョン管理","Bashスクリプト","CLIコマンド","インストールガイド"],"ko":["Kata-Help","AI 에이전트","仕様駆動開発","버전 관리","Bash 스크립트","CLI 명령어","설치 가이드"],"es":["kata-help","framework de orquestación de agentes","desarrollo basado en especificaciones","CLI","gestión de tareas","documentación técnica","herramientas de desarrollo","agentes de IA","desarrollo de software"],"fr":["kata-help","framework d''orchestration d''agents","développement basé sur des spécifications","CLI","gestion de tâches","documentation technique","outils de développement","agents d''IA","développement de logiciels"],"de":["kata-help","Framework für die Orchestrierung von Agenten","spezifikationsbasierte Entwicklung","CLI","Aufgabenverwaltung","technische Dokumentation","Entwicklungstools","KI-Agents","Software-Entwicklung"],"pt":["kata-help","desenvolvimento dirigido por especificações","orquestração de agentes","automatização de tarefas","bash","versão instalada","referência técnica"],"ru":["kata-help","спецификационно-ориентированное разработки","оркестровка агентов","автоматизация задач","bash","установленная версия","техническая справка"],"ar":["kata-help","تصميم التوجيه بالمواصفات","توجيه الوكلاء","تحسين المهام","bash","الإصدار المثبت","مرجع تقني"]}},"owner":"gannonh","repo":"kata-orchestrator","repoPath":"gannonh/kata-orchestrator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.286Z","topics":[],"category":"community","skillMd":{"name":"kata-help","description":"Show available Kata skills, displaying the usage guide, explaining skill reference, or when the user asks for help with Kata. Triggers include help, show skills, list skills, what skills, kata skills, and usage guide.","version":"0.1.0","bodyPreview":"<objective>\nDisplay the complete Kata skill reference with version info.\n\nFirst, read the installed version:\n\n```bash\nif [ -n \"$CLAUDE_PLUGIN_ROOT\" ]; then\n  cat \"$CLAUDE_PLUGIN_ROOT/VERSION\" 2>/dev/null\nelse\n  echo \"unknown\"\nfi\n```\n\nThen output the reference content below, inserting the version at the top. Do NOT add:\n\n- Project-specific analysis\n- Git status or file context\n- Next-step suggestions\n- Any commentary beyond the reference\n  </objective>\n\n<reference>\n# Kata Skill Reference\n\n**Versi","body":"<objective>\nDisplay the complete Kata skill reference with version info.\n\nFirst, read the installed version:\n\n```bash\nif [ -n \"$CLAUDE_PLUGIN_ROOT\" ]; then\n  cat \"$CLAUDE_PLUGIN_ROOT/VERSION\" 2>/dev/null\nelse\n  echo \"unknown\"\nfi\n```\n\nThen output the reference content below, inserting the version at the top. Do NOT add:\n\n- Project-specific analysis\n- Git status or file context\n- Next-step suggestions\n- Any commentary beyond the reference\n  </objective>\n\n<reference>\n# Kata Skill Reference\n\n**Version:** {version from bash above}\n\n**Kata** is a spec-driven development framework for Claude Code. It creates hierarchical project plans optimized for agentic development.\n\n## Quick Start\n\n1. `/kata-new-project` - Initialize project (includes research, requirements, roadmap)\n2. `/kata-plan-phase 1` - Create detailed plan for first phase\n3. `/kata-execute-phase 1` - Execute the phase\n\n## Staying Updated\n\nKata evolves fast. Check for updates periodically:\n\n```\n/kata-whats-new\n```\n\nShows what changed since your installed version and how to update.\n\n## Core Workflow\n\n```\n/kata-new-project → /kata-plan-phase → /kata-execute-phase → repeat\n```\n\n### Project Initialization\n\n**`/kata-new-project`**\nInitialize new project through unified flow.\n\nOne skill takes you from idea to ready-for-planning:\n\n- Deep questioning to understand what you''re building\n- Optional domain research (spawns 4 parallel researcher agents)\n- Requirements definition with v1/v2/out-of-scope scoping\n- Roadmap creation with phase breakdown and success criteria\n\nCreates all `.planning/` artifacts:\n\n- `PROJECT.md` — vision and requirements\n- `config.json` — workflow mode (interactive/yolo)\n- `research/` — domain research (if selected)\n- `REQUIREMENTS.md` — scoped requirements with REQ-IDs\n- `ROADMAP.md` — phases mapped to requirements\n- `STATE.md` — project memory\n\nUsage: `/kata-new-project`\n\n**`/kata-map-codebase`**\nMap an existing codebase for brownfield projects.\n\n- Analyzes codebase with parallel Explore agents\n- Creates `.planning/codebase/` with 7 focused documents\n- Covers stack, architecture, structure, conventions, testing, integrations, concerns\n- Use before `/kata-new-project` on existing codebases\n\nUsage: `/kata-map-codebase`\n\n### Phase Planning\n\n**`/kata-discuss-phase <number>`**\nHelp articulate your vision for a phase before planning.\n\n- Captures how you imagine this phase working\n- Creates CONTEXT.md with your vision, essentials, and boundaries\n- Use when you have ideas about how something should look/feel\n\nUsage: `/kata-discuss-phase 2`\n\n**`/kata-research-phase <number>`**\nComprehensive ecosystem research for niche/complex domains.\n\n- Discovers standard stack, architecture patterns, pitfalls\n- Creates RESEARCH.md with \"how experts build this\" knowledge\n- Use for 3D, games, audio, shaders, ML, and other specialized domains\n- Goes beyond \"which library\" to ecosystem knowledge\n\nUsage: `/kata-research-phase 3`\n\n**`/kata-listing-phase-assumptions <number>`**\nSee what Claude is planning to do before it starts.\n\n- Shows Claude''s intended approach for a phase\n- Lets you course-correct if Claude misunderstood your vision\n- No files created - conversational output only\n\nUsage: `/kata-listing-phase-assumptions 3`\n\n**`/kata-plan-phase <number>`**\nCreate detailed execution plan for a specific phase.\n\n- Generates `.planning/phases/pending/XX-phase-name/XX-YY-PLAN.md`\n- Breaks phase into concrete, actionable tasks\n- Includes verification criteria and success measures\n- Multiple plans per phase supported (XX-01, XX-02, etc.)\n\nUsage: `/kata-plan-phase 1`\nResult: Creates `.planning/phases/pending/01-foundation/01-01-PLAN.md`\n\n### Execution\n\n**`/kata-execute-phase <phase-number>`**\nExecute all plans in a phase.\n\n- Moves phase from `pending/` → `active/` → `completed/`\n- Groups plans by wave (from frontmatter), executes waves sequentially\n- Plans within each wave run in parallel via Task tool\n- Verifies phase goal after all plans complete\n- Updates REQUIREMENTS.md, ROADMAP.md, STATE.md\n\nUsage: `/kata-execute-phase 5`\n\n### Quick Mode\n\n**`/kata-execute-quick-task`**\nExecute small, ad-hoc tasks with Kata guarantees but skip optional agents.\n\nQuick mode uses the same system with a shorter path:\n\n- Spawns planner + executor (skips researcher, checker, verifier)\n- Quick tasks live in `.planning/quick/` separate from planned phases\n- Updates STATE.md tracking (not ROADMAP.md)\n\nUse when you know exactly what to do and the task is small enough to not need research or verification.\n\nUsage: `/kata-execute-quick-task`\nResult: Creates `.planning/quick/NNN-slug/PLAN.md`, `.planning/quick/NNN-slug/SUMMARY.md`\n\n### Roadmap Management\n\n**`/kata-add-phase <description>`**\nAdd new phase to end of current milestone.\n\n- Appends to ROADMAP.md\n- Uses next sequential number\n- Creates phase directory in `pending/`\n\nUsage: `/kata-add-phase \"Add admin dashboard\"`\n\n**`/kata-insert-phase <after> <description>`**\nInsert urgent work as decimal phase between existing phases.\n\n- Creates intermediate phase (e.g., 7.1 between 7 and 8)\n- Useful for discovered work that must happen mid-milestone\n- Maintains phase ordering\n\nUsage: `/kata-insert-phase 7 \"Fix critical auth bug\"`\nResult: Creates Phase 7.1\n\n**`/kata-remove-phase <number>`**\nRemove a future phase and renumber subsequent phases.\n\n- Deletes phase directory and all references\n- Renumbers all subsequent phases to close the gap\n- Only works on future (unstarted) phases\n- Git commit preserves historical record\n\nUsage: `/kata-remove-phase 17`\nResult: Phase 17 deleted, phases 18-20 become 17-19\n\n**`/kata-move-phase <phase> <operation>`**\nMove a phase between milestones or reorder within a milestone.\n\n- Cross-milestone: moves phase to target milestone, renumbers both\n- Reorder: changes phase position within milestone, renumbers all\n- Only pending phases can be moved\n\nUsage: `/kata-move-phase 3 to v1.6.0` (cross-milestone)\nUsage: `/kata-move-phase 3 before 1` (reorder within milestone)\n\n### Milestone Management\n\n**`/kata-add-milestone <name>`**\nStart a new milestone through unified flow.\n\n- Deep questioning to understand what you''re building next\n- Optional domain research (spawns 4 parallel researcher agents)\n- Requirements definition with scoping\n- Roadmap creation with phase breakdown\n\nMirrors `/kata-new-project` flow for brownfield projects (existing PROJECT.md).\n\nUsage: `/kata-add-milestone \"v2.0 Features\"`\n\n**`/kata-complete-milestone <version>`**\nArchive completed milestone and prepare for next version.\n\n- Creates MILESTONES.md entry with stats\n- Archives full details to milestones/ directory\n- Creates git tag for the release\n- Prepares workspace for next version\n\nUsage: `/kata-complete-milestone 1.0.0`\n\n### Progress Tracking\n\n**`/kata-track-progress`**\nCheck project status and intelligently route to next action.\n\n- Shows visual progress bar and completion percentage\n- Summarizes recent work from SUMMARY files\n- Displays current position and what''s next\n- Lists key decisions and open issues\n- Offers to execute next plan or create it if missing\n- Detects 100% milestone completion\n\nUsage: `/kata-track-progress`\n\n### Session Management\n\n**`/kata-resume-work`**\nResume work from previous session with full context restoration.\n\n- Reads STATE.md for project context\n- Shows current position and recent progress\n- Offers next actions based on project state\n\nUsage: `/kata-resume-work`\n\n**`/kata-pause-work`**\nCreate context handoff when pausing work mid-phase.\n\n- Creates .continue-here file with current state\n- Updates STATE.md session continuity section\n- Captures in-progress work context\n\nUsage: `/kata-pause-work`\n\n### Debugging\n\n**`/kata-debug [issue description]`**\nSystematic debugging with persistent state across context resets.\n\n- Gathers symptoms through adaptive questioning\n- Creates `.planning/debug/[slug].md` to track investigation\n- Investigates using scientific method (evidence → hypothesis → test)\n- Survives `/clear` — run `/kata-debug` with no args to resume\n- Archives resolved issues to `.planning/debug/resolved/`\n\nUsage: `/kata-debug \"login button doesn''t work\"`\nUsage: `/kata-debug` (resume active session)\n\n### Issue Management\n\n**`/kata-add-issue [description]`**\nCapture idea or task as issue from current conversation.\n\n- Extracts context from conversation (or uses provided description)\n- Creates structured issue file in `.planning/issues/open/`\n- Infers area from file paths for grouping\n- Checks for duplicates before creating\n- Updates STATE.md issue count\n\nUsage: `/kata-add-issue` (infers from conversation)\nUsage: `/kata-add-issue Add auth token refresh`\n\n**`/kata-check-issues [area]`**\nList pending issues and select one to work on.\n\n- Lists all pending issues with title, area, age\n- Optional area filter (e.g., `/kata-check-issues api`)\n- Loads full context for selected issue\n- Routes to appropriate action (work now, add to phase, brainstorm)\n- Moves issue to done/ when work begins\n\nUsage: `/kata-check-issues`\nUsage: `/kata-check-issues api`\n\n### User Acceptance Testing\n\n**`/kata-verify-work [phase]`**\nValidate built features through conversational UAT.\n\n- Extracts testable deliverables from SUMMARY.md files\n- Presents tests one at a time (yes/no responses)\n- Automatically diagnoses failures and creates fix plans\n- Ready for re-execution if issues found\n\nUsage: `/kata-verify-work 3`\n\n### Milestone Auditing\n\n**`/kata-audit-milestone [version]`**\nAudit milestone completion against original intent.\n\n- Reads all phase VERIFICATION.md files\n- Checks requirements coverage\n- Spawns integration checker for cross-phase wiring\n- Creates MILESTONE-AUDIT.md with gaps and tech debt\n\nUsage: `/kata-audit-milestone`\n\n**`/kata-plan-milestone-gaps`**\nCreate phases to close gaps identified by audit.\n\n- Reads MILESTONE-AUDIT.md and groups gaps into phases\n- Prioritizes by requirement priority (must/should/nice)\n- Adds gap closure phases to ROADMAP.md\n- Ready for `/kata-plan-phase` on new phases\n\nUsage: `/kata-plan-milestone-gaps`\n\n### Configuration\n\n**`/kata-customize`**\nManage template overrides for customizing Kata output formats.\n\n- List all customizable templates with override status\n- Copy a default template for local editing\n- Edit an override with conversational changes\n- Validate overrides against required schemas\n\nUsage: `/kata-customize`\nUsage: `/kata-customize list`\nUsage: `/kata-customize copy summary-template.md`\nUsage: `/kata-customize validate`\n\n**`/kata-configure-settings`**\nConfigure workflow toggles and model profile interactively.\n\n- Toggle researcher, plan checker, verifier agents\n- Select model profile (quality/balanced/budget)\n- Updates `.planning/config.json`\n\nUsage: `/kata-configure-settings`\n\n**`/kata-set-profile <profile>`**\nQuick switch model profile for Kata agents.\n\n- `quality` — Opus everywhere except verification\n- `balanced` — Opus for planning, Sonnet for execution (default)\n- `budget` — Sonnet for writing, Haiku for research/verification\n\nUsage: `/kata-set-profile budget`\n\n### Utility Skills\n\n**`/kata-help`**\nShow this skill reference.\n\n**`/kata-whats-new`**\nSee what''s changed since your installed version.\n\n- Shows installed vs latest version comparison\n- Displays changelog entries for versions you''ve missed\n- Highlights breaking changes\n- Provides update instructions when behind\n\nUsage: `/kata-whats-new`\n\n## Files & Structure\n\n```\n.planning/\n├── PROJECT.md            # Project vision\n├── REQUIREMENTS.md       # Scoped requirements with REQ-IDs\n├── ROADMAP.md            # Current phase breakdown\n├── STATE.md              # Project memory & context\n├── MILESTONES.md         # Completed milestone history\n├── config.json           # Workflow mode & gates\n├── templates/            # Template overrides (customized output formats)\n├── research/             # Domain research (from project init)\n├── issues/               # Captured ideas and tasks\n│   ├── open/             # Issues waiting to be worked on\n│   └── done/             # Completed issues\n├── debug/                # Active debug sessions\n│   └── resolved/         # Archived resolved issues\n├── codebase/             # Codebase map (brownfield projects)\n│   ├── STACK.md          # Languages, frameworks, dependencies\n│   ├── ARCHITECTURE.md   # Patterns, layers, data flow\n│   ├── STRUCTURE.md      # Directory layout, key files\n│   ├── CONVENTIONS.md    # Coding standards, naming\n│   ├── TESTING.md        # Test setup, patterns\n│   ├── INTEGRATIONS.md   # External services, APIs\n│   └── CONCERNS.md       # Tech debt, known issues\n├── milestones/           # Archived milestone details\n├── quick/                # Quick task plans and summaries\n│   └── NNN-slug/\n│       ├── PLAN.md\n│       └── SUMMARY.md\n└── phases/\n    ├── pending/          # Phases not yet started\n    │   └── 03-next-phase/\n    │       └── 03-01-PLAN.md\n    ├── active/           # Phase currently being executed\n    │   └── 02-in-progress/\n    │       ├── 02-01-PLAN.md\n    │       └── 02-01-SUMMARY.md\n    └── completed/        # Finished phases\n        └── 01-foundation/\n            ├── 01-01-PLAN.md\n            └── 01-01-SUMMARY.md\n```\n\n## Workflow Modes\n\nSet during `/kata-new-project`:\n\n**Interactive Mode**\n\n- Confirms each major decision\n- Pauses at checkpoints for approval\n- More guidance throughout\n\n**YOLO Mode**\n\n- Auto-approves most decisions\n- Executes plans without confirmation\n- Only stops for critical checkpoints\n\nChange anytime by editing `.planning/config.json`\n\n## Planning Configuration\n\nConfigure how planning artifacts are managed in `.planning/config.json`:\n\n**`planning.commit_docs`** (default: `true`)\n\n- `true`: Planning artifacts committed to git (standard workflow)\n- `false`: Planning artifacts kept local-only, not committed\n\nWhen `commit_docs: false`:\n\n- Add `.planning/` to your `.gitignore`\n- Useful for OSS contributions, client projects, or keeping planning private\n- All planning files still work normally, just not tracked in git\n\n**`planning.search_gitignored`** (default: `false`)\n\n- `true`: Add `--no-ignore` to broad ripgrep searches\n- Only needed when `.planning/` is gitignored and you want project-wide searches to include it\n\nExample config:\n\n```json\n{\n  \"planning\": {\n    \"commit_docs\": false,\n    \"search_gitignored\": true\n  }\n}\n```\n\n## Common Workflows\n\n**Starting a new project:**\n\n```\n/kata-new-project        # Unified flow: questioning → research → requirements → roadmap\n/clear\n/kata-plan-phase 1       # Create plans for first phase\n/clear\n/kata-execute-phase 1    # Execute all plans in phase\n```\n\n**Resuming work after a break:**\n\n```\n/kata-track-progress  # See where you left off and continue\n```\n\n**Adding urgent mid-milestone work:**\n\n```\n/kata-insert-phase 5 \"Critical security fix\"\n/kata-plan-phase 5.1\n/kata-execute-phase 5.1\n```\n\n**Completing a milestone:**\n\n```\n/kata-complete-milestone 1.0.0\n/clear\n/kata-add-milestone  # Start next milestone (questioning → research → requirements → roadmap)\n```\n\n**Capturing ideas during work:**\n\n```\n/kata-add-issue                    # Capture from conversation context\n/kata-add-issue Fix modal z-index  # Capture with explicit description\n/kata-check-issues                 # Review and work on issues\n/kata-check-issues api             # Filter by area\n```\n\n**Debugging an issue:**\n\n```\n/kata-debug \"form submission fails silently\"  # Start debug session\n# ... investigation happens, context fills up ...\n/clear\n/kata-debug                                    # Resume from where you left off\n```\n\n## Getting Help\n\n- Read `.planning/PROJECT.md` for project vision\n- Read `.planning/STATE.md` for current context\n- Check `.planning/ROADMAP.md` for phase status\n- Run `/kata-track-progress` to check where you''re up to\n  </reference>\n"},"lastSynced":"2026-03-08T02:00:58.541Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing structured agent management and spec-driven development capabilities.","zh":"非常适合需要结构化的代理管理和基于规格驱动开发能力的开发者代理。","ja":"構造化されたエージェント管理と仕様駆動開発機能を必要とするデベロッパーエージェントに最適です。","ko":"구조화된 에이전트 관리와 사양 기반 개발 기능을 필요로 하는 개발자 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan gestión de agentes estructurada y capacidades de desarrollo dirigidas por especificaciones.","fr":"Parfait pour les agents de développement nécessitant une gestion d''agents structurée et des capacités de développement pilotées par des spécifications.","de":"Perfekt für Entwickleragenten, die eine strukturierte Agentenverwaltung und spezifikationsgetriebene Entwicklungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de gestão de agente estruturada e capacidades de desenvolvimento baseadas em especificações.","ru":"Идеально подходит для агентов-разработчиков, которым необходима структурированная управление агентами и возможности разработки на основе спецификаций.","ar":"مثالي للوكلاء المطورين الذين يحتاجون إلى إدارة وكلاء منظمّة وقدرات تطوير مدفوعة بالمواصفات."},"recommendation":{"en":"Empowers agents to streamline workflow using a structured approach to agent orchestration, leveraging spec-driven development and providing a comprehensive framework for agent management, including version control and plugin management via CLAUDE_PLUGIN_ROOT and VERSION files.","zh":"赋予代理使用结构化方法流线化工作流程的能力，利用基于规格驱动开发，并提供一个用于代理管理的综合框架，包括通过CLAUDE_PLUGIN_ROOT和VERSION文件的版本控制和插件管理。","ja":"エージェントは、構造化されたアプローチを使用してワークフローをストリームライン化し、仕様駆動開発を活用し、CLAUDE_PLUGIN_ROOTおよびVERSIONファイルによるバージョン管理とプラグイン管理を含むエージェント管理のための包括的なフレームワークを提供する機能を備えています。","ko":"에이전트가 구조화된 접근 방식을 사용하여 워크플ロー 최적화를 가능하게 하며, 사양 기반 개발을 활용하고, CLAUDE_PLUGIN_ROOT 및 VERSION 파일을 통한 버전 관리 및 플러그인 관리를 포함한 에이전트 관리를 위한 포괄적인 프레임워크를 제공합니다.","es":"Habilita a los agentes a optimizar el flujo de trabajo utilizando un enfoque estructurado para la orquestación de agentes, aprovechando el desarrollo dirigido por especificaciones y proporcionando un marco integral para la gestión de agentes, incluyendo control de versiones y administración de complementos a través de CLAUDE_PLUGIN_ROOT y archivos VERSION.","fr":"Permet aux agents de rationaliser le flux de travail en utilisant une approche structurée pour l''orchestration des agents, en exploitant le développement piloté par des spécifications et en fournissant un cadre complet pour la gestion des agents, y compris la gestion de versions et la gestion de plugins via CLAUDE_PLUGIN_ROOT et des fichiers VERSION.","de":"Ermächtigt Agenten, den Arbeitsablauf mithilfe eines strukturierten Ansatzes zur Agentenorchestrierung zu optimieren, indem spezifikationsgetriebene Entwicklung genutzt und ein umfassendes Framework für die Agentenverwaltung bereitgestellt wird, einschließlich Versionskontrolle und Plug-in-Verwaltung über CLAUDE_PLUGIN_ROOT und VERSION-Dateien.","pt":"Habilita os agentes a otimizar o fluxo de trabalho usando uma abordagem estruturada para orquestração de agentes, aproveitando o desenvolvimento baseado em especificações e fornecendo uma estrutura abrangente para gestão de agentes, incluindo controle de versão e gerenciamento de plug-ins via CLAUDE_PLUGIN_ROOT e arquivos VERSION.","ru":"Наделяет агентов возможностью оптимизировать рабочий процесс, используя структурированный подход к оркестровке агентов, используя разработку на основе спецификаций и предоставляя комплексную основу для управления агентами, включая контроль версий и управление плагинами через CLAUDE_PLUGIN_ROOT и файлы VERSION.","ar":"تمكّن الوكلاء من تبسيط سير العمل باستخدام نهج منظم لترتيب الوكلاء، والاستفادة من تطوير مدفوع بالمواصفات وتوفير إطار شامل لإدارة الوكلاء، بما في ذلك التحكم في الإصدارات وإدارة الإضافات عبر CLAUDE_PLUGIN_ROOT وملفات VERSION."},"useCases":{"en":["Streamlining agent workflow","Managing agent versions","Orchestrating spec-driven development"],"zh":["流线化代理工作流程","管理代理版本","编排基于规格驱动开发"],"ja":["エージェントのワークフローを最適化する","エージェントバージョンの管理","仕様駆動開発のオーケストレーション"],"ko":["에이전트 워크플ロー 최적화","에이전트 버전 관리","사양 기반 개발 오케스트레이션"],"es":["Optimización del flujo de trabajo de los agentes","Gestión de versiones de los agentes","Orquestación del desarrollo dirigido por especificaciones"],"fr":["Rationalisation du flux de travail des agents","Gestion des versions des agents","Orchestration du développement piloté par des spécifications"],"de":["Optimierung des Arbeitsablaufs von Agenten","Verwaltung von Agenten-Versionen","Orchestrierung der spezifikationsgetriebenen Entwicklung"],"pt":["Otimização do fluxo de trabalho do agente","Gestão de versões de agente","Orquestração do desenvolvimento baseado em especificações"],"ru":["Оптимизация рабочего процесса агента","Управление версиями агента","Оркестровка разработки на основе спецификаций"],"ar":["تبسيط سير عمل الوكيل","إدارة إصدارات الوكيل","ترتيب تطوير مدفوع بالمواصفات"]},"limitations":{"en":["Requires CLAUDE_PLUGIN_ROOT environment variable","Needs access to VERSION file"],"zh":["需要CLAUDE_PLUGIN_ROOT环境变量","需要访问VERSION文件"],"ja":["CLAUDE_PLUGIN_ROOT環境変数が必要","VERSIONファイルへのアクセスが必要"],"ko":["CLAUDE_PLUGIN_ROOT 환경 변수가 필요합니다","VERSION 파일에 대한 액세스가 필요합니다"],"es":["Requiere la variable de entorno CLAUDE_PLUGIN_ROOT","Necesita acceso al archivo VERSION"],"fr":["Nécessite la variable d''environnement CLAUDE_PLUGIN_ROOT","A besoin d''un accès au fichier VERSION"],"de":["Benötigt die Umgebungsvariable CLAUDE_PLUGIN_ROOT","Benötigt Zugriff auf die VERSION-Datei"],"pt":["Requer a variável de ambiente CLAUDE_PLUGIN_ROOT","Necessita acesso ao arquivo VERSION"],"ru":["Требует переменной среды CLAUDE_PLUGIN_ROOT","Требует доступа к файлу VERSION"],"ar":["يتطلب متغير البيئة CLAUDE_PLUGIN_ROOT","يحتاج إلى الوصول إلى ملف VERSION"]},"version":4},"contentHash":"a4dd7c68c8722d32e6bbe81e81caec4b8180cd10b9895cc595c484cdebda2346","qualityScore":50}');
