INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gannonh/kata-orchestrator/kata-help', 'kata-help', 'gannonh', 'kata-orchestrator', 'community', 'kata-help gannonh kata-orchestrator community kata-help is an agent orchestration framework designed for spec-driven development, benefiting developers who need to streamline their workflow. It provides a structured approach to agent management. Kata-Help是用于仕様駆動開発的AIエージェント框架，提供版本信息和安装指南 Kata-Helpは仕様駆動開発を実現するAIエージェントフレームワークで、バージョン情報とインストールガイドを提供 Kata-Help는仕様駆動開発을 위한 AI 에이전트 프레임워크로, 버전 정보와 설치 방법을 제공합니다 kata-help es un framework de orquestación de agentes para desarrollo basado en especificaciones. Ofrece una forma eficiente de gestionar y ejecutar tareas. kata-help est un framework d''orchestration d''agents pour le développement basé sur des spécifications. Il propose une façon efficace de gérer et d''exécuter des tâches. kata-help ist ein Framework für die Orchestrierung von Agenten für spezifikationsbasierte Entwicklung. Es bietet eine effiziente Möglichkeit, Aufgaben zu verwalten und auszuführen. O kata-help é um framework de orquestração de agentes para desenvolvimento dirigido por especificações. Ele fornece uma forma eficiente de gerenciar e executar tarefas kata-help - это фреймворк для оркестровки агентов для спецификационно-ориентированного разработки. Он предоставляет эффективный способ управления и выполнения задач kata-help هو إطار عمل لتوجيه الوكلاء لتصميم التوجيه بالمواصفات. يوفر طريقة فعالة لإدارة وتنفيذ المهام how to use kata-help kata-help alternative kata-help install what is kata-help kata-help vs agent orchestration frameworks kata-help setup guide spec-driven development with kata-help kata-help agent management kata-help workflow automation Kata-Help AIエージェント 仕様駆動開発 版本管理 Bash脚本 CLI命令 安装指南 Displays the complete Kata skill reference with version info Reads the installed version from the VERSION file in the CLAUDE_PLUGIN_ROOT directory Outputs reference content with the version number inserted at the top Executes bash commands to retrieve version information Supports conditional logic to handle unknown version scenarios kata-help is an agent orchestration framework for spec-driven development, providing a structured approach to managing agents and workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Xilonz/gemini-wordpress-agent-skills/wp-block-development', 'community', 'Xilonz', 'gemini-wordpress-agent-skills', 'Xilonz/gemini-wordpress-agent-skills', 'wp-block-development', 0, 0, 50, '2026-03-08T01:57:15.290Z', '2026-03-08T02:01:00.801Z', '0bb162e63148530991584df1ae8c06fbb33cd4d642c115101ef491e530d6705c', '{"id":"Xilonz/gemini-wordpress-agent-skills/wp-block-development","name":"wp-block-development","description":{"en":"The wp-block-development skill enables developers to efficiently create, update, and manage WordPress blocks, leveraging tools like @wordpress/scripts and wp-env.","zh":"WordPress区块开发技能提供了创建和更新区块、修改block.json和动态渲染的技术支持","ja":"WordPressブロック開発スキルは、ブロックの作成、更新、block.jsonの編集、動的レンダリングをサポートします","ko":"워드프레스 블록 개발 스킬은 블록 생성, 업데이트, block.json 수정, 동적 렌더링을 지원합니다","es":"wp-block-development es una habilidad para crear y personalizar bloques de WordPress, incluyendo renderizado dinámico y herramientas de compilación","fr":"wp-block-development est une compétence pour créer et personnaliser des blocs WordPress, y compris le rendu dynamique et les outils de construction","de":"wp-block-development ist eine Fähigkeit zum Erstellen und Anpassen von WordPress-Blöcken, einschließlich dynamischem Rendering und Build-Tools","pt":"Desenvolva blocos personalizados para WordPress com recursos como `block.json` e renderização dinâmica","ru":"Разработайте пользовательские блоки для WordPress с функциями như `block.json` и динамической отрисовкой с ИИ Агентами","ar":"قم بتطوير كتل مخصصة لشركة WordPress مع ميزات مثل `block.json` وترndering الديناميكي مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"wp-block-development: WordPress Block Setup Guide | AI Ag...","zh":"WordPress区块开发设置指南 - AIエージェント工具","ja":"WordPressブロック開発ベストプラクティス - AIエージェント","ko":"워드프레스 블록 개발 가이드 - AI 에이전트 도구","es":"Guía de configuración de wp-bl