INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Xilonz/gemini-wordpress-agent-skills/wp-block-development', 'wp-block-development', 'Xilonz', 'gemini-wordpress-agent-skills', 'community', 'wp-block-development Xilonz gemini-wordpress-agent-skills community The wp-block-development skill enables developers to efficiently create, update, and manage WordPress blocks, leveraging tools like @wordpress/scripts and wp-env. WordPress区块开发技能提供了创建和更新区块、修改block.json和动态渲染的技术支持 WordPressブロック開発スキルは、ブロックの作成、更新、block.jsonの編集、動的レンダリングをサポートします 워드프레스 블록 개발 스킬은 블록 생성, 업데이트, block.json 수정, 동적 렌더링을 지원합니다 wp-block-development es una habilidad para crear y personalizar bloques de WordPress, incluyendo renderizado dinámico y herramientas de compilación wp-block-development est une compétence pour créer et personnaliser des blocs WordPress, y compris le rendu dynamique et les outils de construction wp-block-development ist eine Fähigkeit zum Erstellen und Anpassen von WordPress-Blöcken, einschließlich dynamischem Rendering und Build-Tools Desenvolva blocos personalizados para WordPress com recursos como `block.json` e renderização dinâmica Разработайте пользовательские блоки для WordPress с функциями như `block.json` и динамической отрисовкой с ИИ Агентами قم بتطوير كتل مخصصة لشركة WordPress مع ميزات مثل `block.json` وترndering الديناميكي مع أدوات الذكاء الاصطناعي how to use wp-block-development wp-block-development setup guide wordpress block development tutorial wp-block-development vs gutenberg wp-block-development install wordpress block creation block.json management wp-env setup WordPress区块开发 AIエージェント工具 block.json修改 动态渲染 WordPress区块创建 WordPress区块更新 @wordpress/scripts @wordpress/create-block Creates and updates WordPress blocks using block.json Supports dynamic rendering with render.php and render_callback Manages block deprecations and migrations using deprecated versions Utilizes build tooling like @wordpress/scripts and @wordpress/create-block Troubleshoots common block issues, such as invalid or unsaved blocks wp-block-development is a specialized skill for building and customizing WordPress blocks, including creating new blocks, updating existing ones, and troubleshooting common issues.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bear2u/my-skills/Prompt Coach', 'community', 'bear2u', 'my-skills', 'bear2u/my-skills', 'Prompt Coach', 0, 0, 50, '2026-03-08T01:57:15.291Z', '2026-03-08T02:01:02.602Z', '79c140c6cb1c2b0280c62203740b9ada5d40da4633f38a342da53a50e530e224', '{"id":"bear2u/my-skills/Prompt Coach","name":"Prompt Coach","description":{"en":"Prompt Coach helps developers become better AI-native engineers by analyzing Claude Code session logs and improving their AI workflow efficiency. It enables developers to build effective AI workflows and leverage AI tools optimally.","zh":"Prompt Coach 是一个 AI 原生工程专家和提示工程专家，帮助开发者优化 AI 工作流程和工具使用效率","ja":"Prompt Coach は、AI エージェントの効率化を支援するエキスパートで、開発者が AI 工作流を最適化するのに役立ちます","ko":"Prompt Coach 는 AI 도구의 사용 효율성을 높이고 개발자들이 더 나은 AI 네이티브 엔지니어가 되도록 지원하는 전문가입니다","es":"Prompt Coach es un experto en ingeniería de promtps y flujos de trabajo de IA que ayuda a los desarrolladores a mejorar sus habilidades","fr":"Prompt Coach est un expert en ingénierie de promtps et de flux de travail IA qui aide les développeurs à améliorer leurs compétences","de":"Prompt Coach ist ein Experte für Prompt-Engineering und IA-Workflows, der Entwicklern hilft, ihre Fähigkeiten zu verbessern","pt":"O Prompt Coach é uma ferramenta de engenharia de IA que ajuda a criar fluxos de trabalho eficazes e promove a eficiência na utilização de ferramentas de IA","ru":"Prompt Coach - это инструмент ИИ инженерии, который помогает создавать эффективные рабочие процессы и оптимизировать использование ИИ инструментов","ar":"Prompt Coach هو أداة هندسية إيمان تساعد على إنشاء تدفقات عمل فعالة وتحسين كفاءة استخدام أدوات الإيمان"},"seo":{"title":{"en":"Prompt Coach: AI Workflows Optimization Guide | AI Agent ...","zh":"Prompt Coach 最佳实践指南 - AI 工具优化","ja":"Prompt Coach 導入ガイド - AI エージェントの効率化","ko":"Prompt Coach 설정 가이드 - AI 도구 최적화","es":"Guía de configu